TEST(the_mouse_selects_text_by_dragging_clicking_and_shift) {
    // As Compose's mouse selection in a text field: a press places the caret (and focuses),
    // dragging selects; two clicks take words, three paragraphs, dragging by them; Shift extends.
    auto value = mutableStateOf(std::string("alpha beta gamma\ndelta"));
    TextEditState ime;
    int shown = 0;  // the input method asked for (before the rule: told as it closes too)
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().height(100));
            TextField(value.get(), [&](std::string v) { value.set(std::move(v)); }, Modifier().fillMaxWidth().testTag("f"));
        });
    }, {400, 800});
    ComposeHost& h = rule.host();
    h.setCallbacks({.textInput = [&](bool active, Rect, const TextEditState&, const ImeOptions&) { shown += active; },
                    .textInputChanged = [&](const TextEditState& e) { ime = e; }});
    auto mouse = ComposeHost::PointerType::Mouse;
    // Where a press puts the caret: one character in from each, on the first line.
    auto caretAt = [&](Offset p) {
        rule.advanceTimeBy(500);  // a click of its own
        h.pointerDown(p, -1, 0, mouse);
        h.pointerUp(p);
        rule.waitForIdle();
        return ime.selectionEnd;
    };
    Rect f = rule.onNodeWithTag("f").bounds();
    float y = f.y + 26;
    auto x = [&](int column) { return f.x + 16 + 8 * float(column) + 2; };
    int c1 = caretAt({x(1), y});
    CHECK(h.focusedNode() != nullptr && ime.selectionStart == c1);  // focused by the press
    int before = shown;
    int c3 = caretAt({x(3), y}), c13 = caretAt({x(13), y});
    CHECK(shown == before + 2);  // a click on the focused field brings back a keyboard dismissed
    CHECK(c1 < c3 && c3 < c13 && c13 < 16);
    // A drag selects from the press.
    rule.advanceTimeBy(500);
    h.pointerDown({x(1), y}, -1, 0, mouse);
    for (int i = 2; i <= 13; ++i) h.pointerMove({x(i), y});
    h.pointerUp({x(13), y});
    rule.waitForIdle();
    CHECK(ime.selectionStart == c1 && ime.selectionEnd == c13);
    // A double click, then dragging: whole words, from "beta" on to the end of "gamma"...
    rule.advanceTimeBy(500);
    h.pointerDown({x(7), y}, -1, 0, mouse);
    h.pointerUp({x(7), y});
    h.pointerDown({x(7), y}, -1, 0, mouse);
    rule.waitForIdle();
    CHECK(ime.selectionStart == 6 && ime.selectionEnd == 10);  // "beta"
    h.pointerMove({x(13), y});
    rule.waitForIdle();
    CHECK(ime.selectionStart == 6 && ime.selectionEnd == 16);
    h.pointerMove({x(1), y});  // ...or back, from the end of "beta" to the start of "alpha"
    h.pointerUp({x(1), y});
    rule.waitForIdle();
    CHECK(ime.selectionStart == 10 && ime.selectionEnd == 0);
    // Three clicks: the paragraph (the first line, without its line break).
    rule.advanceTimeBy(500);
    for (int i = 0; i < 3; ++i) {
        h.pointerDown({x(7), y}, -1, 0, mouse);
        h.pointerUp({x(7), y});
    }
    rule.waitForIdle();
    CHECK(ime.selectionStart == 0 && ime.selectionEnd == 16);
    // Shift and a click: the selection goes from where it started to there.
    caretAt({x(3), y});
    h.setKeyboardModifiers({.shift = true});
    rule.advanceTimeBy(500);
    h.pointerDown({x(13), y}, -1, 0, mouse);
    h.pointerUp({x(13), y});
    h.setKeyboardModifiers({});
    rule.waitForIdle();
    CHECK(ime.selectionStart == c3 && ime.selectionEnd == c13);
    CHECK(value.peek() == "alpha beta gamma\ndelta");  // selecting changes no text
}

TEST(selection_container_mouse_clicks_words_paragraphs_and_shift) {
    std::string clipboard;
    ComposeTestRule rule([&] {
        SelectionContainer(Modifier().fillMaxWidth(), [&] {
            Column([&] {
                Text("alpha beta gamma", Modifier().testTag("first"));
                Text("delta epsilon\nzeta eta", Modifier().testTag("second"));
            });
        });
    }, {400, 800});
    auto& h = rule.host();
    h.setCallbacks({.setClipboard = [&](const std::string& t) { clipboard = t; }});
    auto mouse = ComposeHost::PointerType::Mouse;
    auto at = [&](const char* tag, int index, int line = 0) {  // 8 dp a character, 20 dp a line
        Rect r = rule.onNodeWithTag(tag).bounds();
        return Offset{r.x + 8 * float(index) + 2, r.y + 10 + 20 * float(line)};
    };
    auto copy = [&] {
        clipboard.clear();
        h.keyDown(Key::C, {.ctrl = true});
        return clipboard;
    };
    auto clicks = [&](Offset p, int n) {
        rule.advanceTimeBy(500);
        for (int i = 0; i < n; ++i) {
            h.pointerDown(p, -1, 0, mouse);
            h.pointerUp(p);
        }
        rule.waitForIdle();
    };
    // Two clicks, the second held and dragged on into the next text: word by word.
    rule.advanceTimeBy(500);
    h.pointerDown(at("first", 7), -1, 0, mouse);
    h.pointerUp(at("first", 7));
    h.pointerDown(at("first", 7), -1, 0, mouse);
    rule.waitForIdle();
    CHECK(copy() == "beta");
    h.pointerMove(at("second", 8));
    h.pointerUp(at("second", 8));
    rule.waitForIdle();
    CHECK(copy() == "beta gamma\ndelta epsilon");
    // Back over the anchor: from the end of "beta" to the start of "alpha".
    rule.advanceTimeBy(500);
    h.pointerDown(at("first", 7), -1, 0, mouse);
    h.pointerUp(at("first", 7));
    h.pointerDown(at("first", 7), -1, 0, mouse);
    h.pointerMove(at("first", 1));
    h.pointerUp(at("first", 1));
    rule.waitForIdle();
    CHECK(copy() == "alpha beta");
    // Three clicks: the paragraph, up to the line break.
    clicks(at("second", 2, 1), 3);
    CHECK(copy() == "zeta eta");
    // A click, then Shift and a click: from the first to the second.
    clicks(at("first", 6), 1);
    h.setKeyboardModifiers({.shift = true});
    clicks(at("second", 5), 1);
    h.setKeyboardModifiers({});
    CHECK(copy() == "beta gamma\ndelta");
}

TEST(selection_container_selects_and_copies_text) {
    std::string clipboard;
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().height(200));
            SelectionContainer(Modifier().fillMaxWidth().testTag("container"), [&] {
                Column([&] {
                    Text("merhaba güzel dünya", Modifier().testTag("first"));
                    Text("ikinci satır burada", Modifier().testTag("second"));
                    DisableSelection([&] { Text("seçilmeyen etiket", Modifier().testTag("disabled")); });
                    Box(Modifier().fillMaxWidth().height(100).testTag("space"));
                });
            });
            Text("dışarıda kalan", Modifier().testTag("outside"));
        });
    }, {400, 800});
    auto& host = rule.host();
    host.setCallbacks({.setClipboard = [&](const std::string& s) { clipboard = s; }});
    // FakeTextMeasurer: 8 dp per character, lines 20 dp tall.
    auto at = [&](const char* tag, int index) {
        Rect r = rule.onNodeWithTag(tag).bounds();
        return Offset{r.x + 8 * float(index) + 2, r.y + 10};
    };
    auto longPress = [&](Offset p) {
        host.pointerDown(p);
        rule.advanceTimeBy(500);
        host.pointerUp(p);
        rule.waitForIdle();
    };
    auto tapAt = [&](Offset p) {
        host.pointerDown(p);
        host.pointerUp(p);
        rule.waitForIdle();
    };
    auto drag = [&](Offset from, Offset to, ComposeHost::PointerType type) {
        host.pointerDown(from, -1, 0, type);
        for (int i = 1; i <= 6; ++i) {
            rule.advanceFrame();
            host.pointerMove({from.x + (to.x - from.x) * float(i) / 6, from.y + (to.y - from.y) * float(i) / 6});
        }
        host.pointerUp(to);
        rule.waitForIdle();
    };
    auto copy = [&] {
        clipboard.clear();
        host.keyDown(Key::C, {.ctrl = true});
        rule.waitForIdle();
        return clipboard;
    };
    longPress(at("first", 10));
    CHECK(rule.onNodeWithText("Copy").exists() && rule.onNodeWithText("Select all").exists());
    rule.onNodeWithText("Copy").performClick();
    CHECK(clipboard == "güzel" && !rule.onNodeWithText("Copy").exists());
    // One selection: a word in another text takes the place of the first one; select all takes
    // every selectable text, a line each.
    longPress(at("first", 2));
    longPress(at("second", 2));
    rule.onAllNodesWithText("Copy").assertCountEquals(1);
    rule.onNodeWithText("Select all").performClick();
    rule.onNodeWithText("Copy").performClick();
    CHECK(clipboard == "merhaba güzel dünya\nikinci satır burada");
    rule.onAllNodesWithText("Copy").assertCountEquals(0);
    // The end handle under "merhaba", dragged six characters on and a line down: into the second text.
    longPress(at("first", 3));
    Rect first = rule.onNodeWithTag("first").bounds();
    Offset handle{first.x + 8 * 7 + 11, first.y + 20 + 11};
    drag(handle, {handle.x + 48, handle.y + 20}, ComposeHost::PointerType::Touch);
    rule.onNodeWithText("Copy").performClick();
    CHECK(clipboard == "merhaba güzel dünya\nikinci satır ");
    // ...and back up: the selection shrinks into the first text again.
    longPress(at("first", 3));
    drag(handle, {handle.x + 48, handle.y + 20}, ComposeHost::PointerType::Touch);
    drag({handle.x + 48, handle.y + 20}, {handle.x + 48, handle.y}, ComposeHost::PointerType::Touch);
    rule.onNodeWithText("Copy").performClick();
    CHECK(clipboard == "merhaba güzel");
    // At the very start of the second text the end is the first one's end: the handle stays there.
    longPress(at("first", 3));
    drag(handle, {first.x + 11, first.y + 51}, ComposeHost::PointerType::Touch);
    drag({first.x + 8 * 19 + 11, handle.y}, {first.x + 8 * 12 + 11, handle.y}, ComposeHost::PointerType::Touch);
    rule.onNodeWithText("Copy").assertExists().performClick();
    CHECK(clipboard == "merhaba güze");
    // The start handle can't pass the end one.
    longPress(at("second", 9));
    Rect second = rule.onNodeWithTag("second").bounds();
    drag({second.x + 8 * 7 - 11, second.y + 20 + 11}, {second.x + 8 * 18 - 11, second.y + 20 + 11}, ComposeHost::PointerType::Touch);
    rule.onNodeWithText("Copy").performClick();
    CHECK(clipboard.empty());
    // A press elsewhere in the container clears it; text outside, or in DisableSelection, isn't selectable.
    longPress(at("second", 2));
    tapAt(rule.onNodeWithTag("space").bounds().center());
    CHECK(!rule.onNodeWithText("Copy").exists());
    longPress(at("outside", 2));
    CHECK(!rule.onNodeWithText("Copy").exists());
    longPress(at("disabled", 2));
    CHECK(!rule.onNodeWithText("Copy").exists());
    // The mouse: a drag selects from text to text, without handles; Ctrl+C copies.
    drag(at("first", 8), at("second", 6), ComposeHost::PointerType::Mouse);
    CHECK(!rule.onNodeWithText("Copy").exists());
    CHECK(copy() == "güzel dünya\nikinci");
    // Below the last text (the label in DisableSelection doesn't count): to its end.
    Rect space = rule.onNodeWithTag("space").bounds();
    drag(at("first", 0), {space.x + 2, space.y + 10}, ComposeHost::PointerType::Mouse);
    CHECK(copy() == "merhaba güzel dünya\nikinci satır burada");
    // ...dragged backwards too; a double click takes a word; Escape clears it.
    drag(at("second", 6), at("first", 8), ComposeHost::PointerType::Mouse);
    CHECK(copy() == "güzel dünya\nikinci");
    for (int i = 0; i < 2; ++i) {
        host.pointerDown(at("first", 15), -1, 0, ComposeHost::PointerType::Mouse);
        host.pointerUp(at("first", 15));
        rule.advanceTimeBy(50);
    }
    rule.waitForIdle();
    CHECK(copy() == "dünya");
    host.keyDown(Key::Escape);
    rule.waitForIdle();
    CHECK(copy().empty());
    // A click clears it too; the mouse's long press selects nothing.
    drag(at("first", 0), at("first", 7), ComposeHost::PointerType::Mouse);
    CHECK(copy() == "merhaba");
    host.pointerDown(at("second", 3), -1, 0, ComposeHost::PointerType::Mouse);
    rule.advanceTimeBy(600);
    host.pointerUp(at("second", 3));
    rule.waitForIdle();
    CHECK(copy().empty() && !rule.onNodeWithText("Copy").exists());
}

TEST(app_side_change_resyncs_input_method) {
    auto value = std::make_shared<MutableState<std::string>>(mutableStateOf(""));
    std::vector<std::string> resyncs;  // before the rule: its callbacks run as it goes (the keyboard hidden)
    int shows = 0;
    ComposeTestRule rule([value] {
        TextField(value->get(), [value](std::string v) { value->set(std::move(v)); }, Modifier().testTag("field"),
                  {.singleLine = true, .onSubmit = [value] { value->set(""); }});
    });
    rule.host().setCallbacks({
        .textInput = [&](bool active, Rect, const TextEditState&, const KeyboardOptions&) { shows += active; },
        .textInputChanged = [&](const TextEditState& s) { resyncs.push_back(s.text); },
    });
    rule.onNodeWithTag("field").performClick();
    CHECK(shows == 1);
    rule.host().textEdit({"kalem", 5, 5, 0, 5});
    rule.waitForIdle();
    CHECK(resyncs.empty());  // the IME's own edit is not echoed back
    rule.host().keyDown(Key::Enter);  // onSubmit clears the field
    rule.waitForIdle();
    CHECK((resyncs == std::vector<std::string>{""}));
    rule.onNodeWithTag("field").performClick();  // tapping the focused field brings the keyboard back
    CHECK(shows == 2);
}

