TEST(fling_keeps_scrolling_after_release) {
    auto data = range(5000);
    LazyListState state;
    ComposeTestRule rule(
        [&] {
            LazyColumn(Modifier().fillMaxSize(), {.state = state}, [&](LazyListScope& list) {
                list.items(data, [](int v) { Text("row " + std::to_string(v)); });
            });
        },
        {400, 800});
    rule.swipe({200, 700}, {200, 300}, 5);  // 400dp in 80ms
    int atRelease = state.firstVisibleItemIndex();
    rule.waitForIdle();
    int afterFling = state.firstVisibleItemIndex();
    CHECK(atRelease >= 15);
    CHECK(afterFling > atRelease + 20);
    CHECK(!rule.host().hasPendingWork());  // the fling ended by itself
}

