    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    Color dim = cs.onSurface.copy(0.1f), faint = cs.onSurface.copy(0.38f);
    // Disabled (Compose 1.4's): a filled one on the surface's text at 10%; an outlined one clear,
    // checked or not, its icon (and an unchecked one's outline) in the color around it faded.
    CHECK((canvas.rectColors == std::vector<Color>{dim, colors::Transparent, colors::Transparent, colors::Black}));
    CHECK((canvas.vectorColors == std::vector<Color>{faint, colors::Black.copy(0.38f), colors::Black.copy(0.38f), Color::hex(0xFFEB3B)}));
    CHECK((canvas.strokeColors == std::vector<Color>{colors::Black.copy(0.38f)}));
    rule.onNodeWithTag("renkli").performClick();
    CHECK(!liked.peek());
    testing::RecordingCanvas after;
    rule.host().draw(after);
    CHECK(after.rectColors.size() == 4 && after.rectColors.back() == colors::White && after.vectorColors.back() == Color::hex(0x808080));
