TEST(scaffold_pads_content_by_its_bars_and_insets) {
    PaddingValues seen;
    ComposeTestRule rule(
        [&] {
            CompositionLocalProvider({LocalSystemInsets.provides({.statusBars = {0, 24, 0, 0}, .navigationBars = {0, 0, 0, 16}})}, [&] {
                Scaffold(Modifier().fillMaxSize(),
                         {.topBar = [] { TopAppBar({.title = [] { Text("Başlık"); }}); },
                          .floatingActionButton =
                              [] { FloatingActionButton([] {}, [] { Icon(Icons::Filled::Add, "Ekle"); }); }},
                         [&](PaddingValues padding) {
                             seen = padding;
                             Box(Modifier().fillMaxSize().padding(padding).testTag("content"));
                         });
            });
        },
        {400, 800});
    CHECK(near(seen.top, 64 + 24));  // the top bar includes the status bar
    CHECK(near(seen.bottom, 16));    // no bottom bar: the navigation bar inset
    CHECK(near(rule.onNodeWithTag("content").node()->contentBounds().y, 88));
    Rect fab = rule.onNodeWithText("Ekle").bounds();
    CHECK(near(fab.right(), 400 - 16 - 16) && near(fab.bottom(), 800 - 16 - 16 - 16));  // icon inside a 56dp FAB
}

