TEST(snackbar_queue_action_and_timeout) {
    SnackbarHostState snackbar;
    int undone = 0;
    ComposeTestRule rule([&] { SnackbarHost(snackbar); }, {400, 800});
    snackbar.showSnackbar("birinci", "Geri al", [&] { ++undone; });
    snackbar.showSnackbar("ikinci");
    rule.waitForIdle(0);
    CHECK(rule.onNodeWithText("birinci").exists());
    rule.onNodeWithText("Geri al").performClick();
    CHECK(undone == 1);
    rule.waitForIdle(0);
    CHECK(rule.onNodeWithText("ikinci").exists());  // the queued one follows
    rule.advanceTimeBy(3000);
    CHECK(rule.onNodeWithText("ikinci").exists());
    rule.advanceTimeBy(1200);  // short snackbars last 4 s...
    rule.waitForIdle();        // ...then slide out
    CHECK(!rule.onNodeWithText("ikinci").exists());
    CHECK(!snackbar.current());
}

