namespace {
ImageBitmap testImage(int w, int h) { return ImageBitmap::fromPixels(w, h, std::vector<uint8_t>(size_t(w * h * 4), 255)); }
} // namespace

TEST(image_sizes_follow_the_aspect_ratio) {
    ImageBitmap photo = testImage(640, 400);
    ComposeTestRule rule(
        [&] {
            Column([&] {
                Image(photo, "natural", Modifier().testTag("natural"));
                Image(photo, "wide", Modifier().fillMaxWidth().testTag("wide"));
                Image(photo, "fixed", Modifier().size(100, 100).testTag("fixed"));
            });
        },
        {320, 2000});
    Rect natural = rule.onNodeWithTag("natural").bounds();
    CHECK(near(natural.width, 320) && near(natural.height, 200));  // scaled down to fit, aspect kept
    CHECK(near(rule.onNodeWithTag("wide").bounds().height, 200));
    CHECK(near(rule.onNodeWithTag("fixed").bounds().height, 100));
}

TEST(content_scale_places_the_image) {
    ImageBitmap photo = testImage(200, 100);  // 2:1 into a 100x100 box
    ComposeTestRule rule([&] {
        Row([&] {
            Image(photo, "fit", Modifier().size(100), ContentScale::Fit);
            Image(photo, "crop", Modifier().size(100), ContentScale::Crop);
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(canvas.images.size() == 2);
    Rect fit = canvas.imageDestinations[0], crop = canvas.imageDestinations[1], cropSrc = canvas.imageSources[1];
    CHECK(near(fit.y, 25) && near(fit.height, 50) && near(fit.width, 100));  // letterboxed
    CHECK(near(crop.width, 100) && near(crop.height, 100));                  // fills...
    CHECK(near(cropSrc.x, 50) && near(cropSrc.width, 100));                  // ...showing the middle half
}

