// ---- AnimatedVisibility / AnimatedContent / Crossfade ------------------------------------------

TEST(animated_visibility_expands_then_disposes_on_exit) {
    auto visible = mutableStateOf(false);
    auto log = std::make_shared<std::vector<std::string>>();
    ComposeTestRule rule([&] {
        Column([&] {
            AnimatedVisibility(visible.get(), [&] {
                DisposableEffect(0, [log]() -> std::function<void()> {
                    log->push_back("shown");
                    return [log] { log->push_back("gone"); };
                });
                Box(Modifier().size(100).testTag("panel"));
            });
            Box(Modifier().size(10).testTag("below"));
        });
    });
    CHECK(!rule.onNodeWithTag("panel").exists());
    visible.set(true);
    rule.advanceTimeBy(64);
    float midY = rule.onNodeWithTag("below").bounds().y;
    CHECK(midY > 0 && midY < 100);  // expanding
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("below").bounds().y, 100));
    visible.set(false);
    rule.advanceTimeBy(64);
    CHECK(rule.onNodeWithTag("panel").exists());  // still there while it shrinks
    rule.waitForIdle();
    CHECK(!rule.onNodeWithTag("panel").exists());
    CHECK(near(rule.onNodeWithTag("below").bounds().y, 0));
    CHECK((*log == std::vector<std::string>{"shown", "gone"}));
}

TEST(animated_content_shows_both_while_switching) {
    auto n = mutableStateOf(1);
    ComposeTestRule rule([&] {
        AnimatedContent<int>(n.get(), [](const int& v) { Text("n=" + std::to_string(v)); });
    });
    CHECK(rule.onNodeWithText("n=1").exists());
    n.set(2);
    rule.advanceTimeBy(48);
    CHECK(rule.onNodeWithText("n=1").exists() && rule.onNodeWithText("n=2").exists());
    rule.waitForIdle();
    CHECK(!rule.onNodeWithText("n=1").exists() && rule.onNodeWithText("n=2").exists());
    // Interrupted twice in a row: only the last one stays.
    n.set(3);
    rule.advanceTimeBy(32);
    n.set(4);
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("n=4").exists());
    CHECK(!rule.onNodeWithText("n=3").exists() && !rule.onNodeWithText("n=2").exists());
    CHECK(!rule.host().hasPendingWork());
}

TEST(animated_content_puts_the_entering_content_by_its_z_index) {
    auto n = mutableStateOf(1);
    auto spec = mutableStateOf(0.f);  // the entering content's z-index
    ComposeTestRule rule([&] {
        AnimatedContent<int>(n.get(), [](const AnimatedContentScope&, const int& v) { Text("n=" + std::to_string(v)); }, Modifier(),
                             [&](const int&, const int&) {  // fades both at once (both drawn from the start)
                                 return togetherWith(fadeIn(0, tween(300)), fadeOut(0, tween(300))).withTargetContentZIndex(spec.peek());
                             });
    });
    auto order = [&] {  // which of the two is drawn last (on top)
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        std::string last;
        for (const auto& t : canvas.texts)
            if (t.starts_with("n=")) last = t;
        return last;
    };
    n.set(2);
    rule.advanceTimeBy(48);
    CHECK(order() == "n=2");  // by default the newer content is on top
    rule.waitForIdle();
    spec.set(-1);  // going back: it comes in under the one leaving
    n.set(1);
    rule.advanceTimeBy(48);
    CHECK(rule.onNodeWithText("n=1").exists() && rule.onNodeWithText("n=2").exists() && order() == "n=2");
    rule.waitForIdle();
    CHECK(order() == "n=1");
}

TEST(layout_coordinates_tell_their_parent_and_map_between_nodes) {
    std::optional<LayoutCoordinates> inner, other;
    ComposeTestRule rule([&] {
        Column(Modifier().padding(10), [&] {
            Box(Modifier().size(100, 50));
            Box(Modifier().padding(20, 5, 0, 0).size(40).onGloballyPositioned([&](const LayoutCoordinates& c) { inner = c; }));
            Box(Modifier().size(30).onGloballyPositioned([&](const LayoutCoordinates& c) { other = c; }));
        });
    });
    // inner: past its padding, at (30, 65); in the column's content (from 10, 10) at (20, 55).
    CHECK(inner && near(inner->positionInRoot().x, 30) && near(inner->positionInRoot().y, 65));
    Rect inParent = inner ? inner->boundsInParent() : Rect{};
    CHECK(near(inParent.x, 20) && near(inParent.y, 55) && near(inParent.width, 40) && near(inParent.height, 40));
    // Its parent is the column (120 wide, at the top left), whose parent is the root (no parent).
    auto parent = inner ? inner->parentLayoutCoordinates() : std::nullopt;
    CHECK(parent && near(parent->positionInRoot().x, 0) && near(parent->size().width, 120) && parent->parentLayoutCoordinates() &&
          !parent->parentLayoutCoordinates()->parentLayoutCoordinates());
    CHECK(inner && inner->parentCoordinates() && near(inner->parentCoordinates()->size().width, 120));
    // From other (at 10, 105): a point of inner's, and inner's bounds.
    Offset p = other && inner ? other->localPositionOf(*inner, {5, 5}) : Offset{};
    CHECK(near(p.x, 25) && near(p.y, -35));
    Rect box = other && inner ? other->localBoundingBoxOf(*inner) : Rect{};
    CHECK(near(box.x, 20) && near(box.y, -40) && near(box.width, 40) && near(box.height, 40));
}

TEST(graphics_layer_records_content_and_draws_it_again) {
    std::optional<GraphicsLayer> layer;
    Color red{1, 0, 0, 1};
    ComposeTestRule rule([&] {
        auto l = rememberGraphicsLayer();
        layer = l;
        Column([&] {
            Box(Modifier().padding(10).size(100, 40).drawWithContent([l](ContentDrawScope& d) {
                    d.record(l, [&](DrawScope&) { d.drawContent(); });
                    d.drawLayer(l);  // where it is
                    l.properties().topLeft = {0, 50};  // and a faded copy under it
                    l.properties().alpha = 0.5f;
                    d.drawLayer(l);
                    l.properties() = {};
                }),
                [&] {
                    Text("kayıt");
                    Box(Modifier().size(20).background(red));
                });
        });
    }, {400, 800});
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    // The content only through the layer: twice, 50 dp apart, the copy in a half faded layer.
    std::vector<float> texts, rects;
    for (size_t i = 0; i < canvas.texts.size(); ++i)
        if (canvas.texts[i] == "kayıt") texts.push_back(canvas.baselines[i].y);
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        if (canvas.rectColors[i] == red) rects.push_back(canvas.rects[i].y);
    CHECK(texts.size() == 2 && near(texts[1] - texts[0], 50) && rects.size() == 2 && near(rects[0], 10) && near(rects[1], 60));
    bool faded = false;
    for (size_t i = 0; i < canvas.layerBounds.size(); ++i)
        faded = faded || (near(canvas.layerAlphas[i], 0.5f) && near(canvas.layerBounds[i].y, 60) && near(canvas.layerBounds[i].height, 40));
    CHECK(faded && layer && near(layer->size().width, 100) && near(layer->size().height, 40));
    // As pixels: the platform draws the recording, from its top left; nothing without one.
    CHECK(layer->toImageBitmap().empty());
    std::vector<Offset> drawn;
    Size asked;
    rule.host().setCallbacks({.renderImage = [&](Size size, const std::function<void(GraphicsContext&)>& draw) {
        asked = size;
        testing::RecordingCanvas offscreen;
        draw(offscreen);
        for (size_t i = 0; i < offscreen.rects.size(); ++i) drawn.push_back({offscreen.rects[i].x, offscreen.rects[i].y});
        return ImageBitmap::fromPixels(int(size.width), int(size.height), std::vector<uint8_t>(size_t(size.width * size.height * 4), 255));
    }});
    ImageBitmap shot = layer->toImageBitmap();
    CHECK(shot.width() == 100 && shot.height() == 40 && near(asked.width, 100) && drawn.size() == 1 && near(drawn[0].x, 0) && near(drawn[0].y, 0));
}

TEST(leaving_content_takes_no_taps) {
    auto selected = mutableStateOf(-1);
    auto shown = mutableStateOf(true);
    int buttonClicks = 0;
    ComposeTestRule rule([&] {
        Column([&] {
            AnimatedContent(selected.get(), [&](const int& item) {
                if (item >= 0) {
                    Text("ayrıntı " + std::to_string(item), Modifier().padding(0, 200, 0, 0));
                    return;
                }
                Column([&] {
                    for (int i = 0; i < 3; ++i)
                        key(i, [&] { Box(Modifier().size(100, 40).testTag("card" + std::to_string(i)).clickable([&, i] { selected.set(i); })); });
                });
            }, Modifier().height(300));
            AnimatedVisibility(shown.get(), [&] {
                Box(Modifier().size(100, 40).testTag("button").clickable([&] { ++buttonClicks; }));
            });
        });
    }, {400, 800});
    Offset first = rule.onNodeWithTag("card0").bounds().center(), second = rule.onNodeWithTag("card1").bounds().center();
    rule.host().pointerDown(first);
    rule.host().pointerUp(first);
    rule.advanceFrame();  // the list is fading out
    CHECK(selected.get() == 0 && rule.onNodeWithTag("card1").exists());
    rule.host().pointerDown(second);
    rule.host().pointerUp(second);
    rule.advanceFrame();
    CHECK(selected.get() == 0);  // the second card, on its way out, didn't take the tap
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("ayrıntı 0").exists() && !rule.onNodeWithTag("card1").exists());
    // AnimatedVisibility hiding its content: no clicks on the way out either.
    Offset button = rule.onNodeWithTag("button").bounds().center();
    shown.set(false);
    rule.advanceFrame();
    CHECK(rule.onNodeWithTag("button").exists());
    rule.host().pointerDown(button);
    rule.host().pointerUp(button);
    rule.waitForIdle();
    CHECK(buttonClicks == 0);
}

