TEST(brush_gradients_interpolate_in_the_painted_area) {
    Color red = Color::hex(0xFF0000), blue = Color::hex(0x0000FF), green = Color::hex(0x00FF00);
    Rect area{100, 50, 200, 100};
    auto same = [](Color a, Color b) {
        return std::abs(a.r - b.r) < 0.01f && std::abs(a.g - b.g) < 0.01f && std::abs(a.b - b.b) < 0.01f;
    };
    Brush h = Brush::horizontalGradient({red, blue});
    CHECK(same(h.colorAt({100, 60}, area), red));
    CHECK(same(h.colorAt({200, 60}, area), lerp(red, blue, 0.5f)));
    CHECK(same(h.colorAt({500, 60}, area), blue));  // clamped past the end
    Brush v = Brush::verticalGradient({red, green, blue}, 0, 100);
    CHECK(same(v.colorAt({0, 100}, area), green));
    Brush d = Brush::linearGradient({red, blue});  // to the bottom-right corner
    CHECK(same(d.colorAt({300, 150}, area), blue));
    Brush radial = Brush::radialGradient({red, blue});  // centered, radius 50 (half the height)
    CHECK(same(radial.colorAt({200, 100}, area), red));
    CHECK(same(radial.colorAt({200, 125}, area), lerp(red, blue, 0.5f)));
    Brush sweep = Brush::sweepGradient({red, blue});
    CHECK(same(sweep.colorAt({250, 100.01f}, area), red));     // 3 o'clock
    CHECK(same(sweep.colorAt({100, 100.01f}, area), lerp(red, blue, 0.5f)));  // 9 o'clock: halfway
    Brush stops = Brush::linearGradient(std::vector<ColorStop>{{0, red}, {0.2f, green}, {1, blue}}, {0, 0}, {100, 0});
    CHECK(same(stops.colorAt({110, 0}, area), lerp(red, green, 0.5f)));
    CHECK(same(stops.colorAt({160, 0}, area), lerp(green, blue, 0.5f)));
    CHECK(Brush::solid(red).isSolid() && Brush::solid(red) == Brush::solid(red) && !(h == v));
}

TEST(path_building_and_bounds) {
    Path p;
    p.moveTo(10, 10);
    p.relativeLineTo(20, 0);
    p.quadraticTo(40, 0, 50, 10);
    p.cubicTo(60, 20, 60, 30, 50, 40);
    p.close();
    Rect b = p.bounds();
    CHECK(sameRect(b, {10, 0, 50, 40}));
    CHECK(p.commands().size() == 5 && p.commands()[1].x == 30);
    Path oval;
    oval.addOval({0, 0, 100, 50});
    CHECK(sameRect(oval.bounds(), {0, 0, 100, 50}));
    CHECK(oval.commands().size() == 6);
    Path copy = oval;
    CHECK(copy == oval && !(copy == p));
    copy.reset();
    CHECK(copy.isEmpty());
    Path rounded;
    rounded.addRoundRect({0, 0, 40, 20}, 50);  // radius clamped to half the height
    CHECK(sameRect(rounded.bounds(), {0, 0, 40, 20}));
}

TEST(brushes_paths_and_draw_with_cache_reach_the_canvas) {
    auto builds = std::make_shared<int>(0);
    auto wide = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().size(50).background(Brush::verticalGradient({colors::Black, colors::White}), CircleShape));
            Box(Modifier().size(50).background(Brush::solid(colors::Black)));  // a plain fill
            Box(Modifier().size(wide.get() ? 80.f : 60.f, 40).drawWithCache([builds](CacheDrawScope& cache) {
                ++*builds;
                Path path;
                path.moveTo(0, 0);
                path.lineTo(cache.size().width, cache.size().height);
                return cache.onDrawBehind([path](DrawScope& d) { d.drawPath(path, colors::Black, Stroke(2)); });
            }));
        });
    });
    testing::RecordingCanvas first;
    rule.host().draw(first);
    rule.host().draw(first);
    CHECK(first.gradients == 2);  // drawn twice
    CHECK(*builds == 1);           // the cache survives redraws
    CHECK(first.paths.size() == 2 && sameRect(first.paths[0], {0, 100, 60, 40}));
    wide.set(true);
    rule.waitForIdle();
    testing::RecordingCanvas second;
    rule.host().draw(second);
    CHECK(*builds == 2);
    CHECK(second.paths.size() == 1 && sameRect(second.paths[0], {0, 100, 80, 40}));
}

TEST(interactive_list_items_take_the_tap_and_morph) {
    auto selected = mutableStateOf(false);
    bool checked = false;
    int clicks = 0;
    ComposeTestRule rule([&] {
        MaterialTheme(lightColorScheme(), [&] {
            Column([&] {
                ListItem([&] { ++clicks; }, {.headline = [] { Text("Tıkla"); }, .supporting = [] { Text("açıklama"); }}, Modifier().testTag("tık"));
                ListItem(selected.get(), [&] { selected.set(!selected.peek()); }, {.headline = [] { Text("Seç"); }}, Modifier().testTag("seç"));
                ListItem(checked, [&](bool v) { checked = v; }, {.headline = [] { Text("İşaretle"); }}, Modifier().testTag("işaret"));
                ListItem([&] { ++clicks; }, {.headline = [] { Text("Kapalı"); }}, Modifier().testTag("kapalı"), {.enabled = false});
            });
        });
    }, {400, 800});
    const ColorScheme& cs = lightColorScheme();
    auto draw = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        return canvas;
    };
    auto cornerOf = [&](const testing::RecordingCanvas& canvas, Color color) {
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (canvas.rectColors[i] == color) return canvas.rectCorners[i].topLeft;
        return -1.f;
    };
    auto textColor = [&](const testing::RecordingCanvas& canvas, const std::string& text) {
        for (size_t i = 0; i < canvas.texts.size(); ++i)
            if (canvas.texts[i] == text) return canvas.colors[i];
        return Color{};
    };
    CHECK(rule.onNodeWithTag("tık").bounds().height >= 56 && near(cornerOf(draw(), cs.surface), 4));  // a little rounded at rest
    rule.onNodeWithTag("tık").performClick();
    rule.onNodeWithTag("kapalı").performClick();  // disabled: nothing
    CHECK(clicks == 1);
    auto idle = draw();
    CHECK(textColor(idle, "Tıkla") == cs.onSurface && textColor(idle, "açıklama") == cs.onSurfaceVariant &&
          textColor(idle, "Kapalı") == cs.onSurface.copy(0.38f));
    rule.onNodeWithTag("seç").performClick();  // selected: secondaryContainer, rounder
    rule.advanceTimeBy(1000);
    rule.waitForIdle();
    auto chosen = draw();
    CHECK(selected.peek() && near(cornerOf(chosen, cs.secondaryContainer), 16, 0.5f) && textColor(chosen, "Seç") == cs.onSecondaryContainer);
    rule.onNodeWithTag("işaret").performClick();
    rule.waitForIdle();
    CHECK(checked);
    // Held: the pressed shape (16), back to 4 once let go.
    Offset at = rule.onNodeWithTag("tık").bounds().center();
    rule.host().pointerDown(at);
    rule.advanceTimeBy(1000);
    CHECK(near(cornerOf(draw(), cs.surface), 16, 0.5f));
    rule.host().pointerUp(at);
    rule.advanceTimeBy(1000);
    rule.waitForIdle();
    CHECK(near(cornerOf(draw(), cs.surface), 4, 0.5f));
}

TEST(segmented_list_items_round_the_ends_of_their_card) {
    auto first = ListItemDefaults::segmentedShapes(0, 3), middle = ListItemDefaults::segmentedShapes(1, 3), last = ListItemDefaults::segmentedShapes(2, 3);
    Rect r{0, 0, 300, 56};
    CornerRadii f = first.shape.radiiFor(r), m = middle.shape.radiiFor(r), l = last.shape.radiiFor(r);
    CHECK(near(f.topLeft, 16) && near(f.topRight, 16) && near(f.bottomLeft, 4) && near(m.topLeft, 4) && near(m.bottomRight, 4));
    CHECK(near(l.topLeft, 4) && near(l.bottomLeft, 16) && near(l.bottomRight, 16));
    CHECK(near(ListItemDefaults::segmentedShapes(0, 1).shape.radiiFor(r).bottomLeft, 4));  // alone: as it is
    int opened = -1;
    ComposeTestRule rule([&] {
        Column(Modifier(), {.verticalArrangement = Arrangement::spacedBy(ListItemDefaults::SegmentedGap)}, [&] {
            for (int i = 0; i < 3; ++i)
                SegmentedListItem([&, i] { opened = i; }, ListItemDefaults::segmentedShapes(i, 3), {.headline = [i] { Text(std::format("Öğe {}", i)); }},
                                  Modifier().testTag(std::format("öğe{}", i)));
        });
    }, {400, 800});
    CHECK(near(rule.onNodeWithTag("öğe1").bounds().y, rule.onNodeWithTag("öğe0").bounds().bottom() + 2));
    rule.onNodeWithTag("öğe2").performClick();
    CHECK(opened == 2);
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    std::vector<CornerRadii> corners;
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        if (canvas.rectColors[i] == lightColorScheme().surface) corners.push_back(canvas.rectCorners[i]);
    CHECK(corners.size() == 3 && near(corners[0].topLeft, 16) && near(corners[1].topLeft, 4) && near(corners[2].bottomLeft, 16));
}

