TEST(list_items_as_compose_1_4) {
    ComposeTestRule rule([] {
        Column([] {
            // Supporting text over two lines: three lines' worth (12 dp, its sides at the top).
            ListItem({.headline = [] { Text("Başlık"); }, .supporting = [] { Text("bir\niki"); },
                      .leading = [] { Box(Modifier().size(40).testTag("baş")); }},
                     Modifier().testTag("uzun"));
            // Two lines: its sides in the middle.
            ListItem({.headline = [] { Text("Başlık"); }, .supporting = [] { Text("tek"); },
                      .trailing = [] { Box(Modifier().size(24).testTag("son")); }},
                     Modifier().testTag("orta"));
        });
    });
    Rect tall = rule.onNodeWithTag("uzun").bounds(), lead = rule.onNodeWithTag("baş").bounds();
    CHECK(near(tall.height, 88) && near(lead.y, tall.y + 12));
    Rect mid = rule.onNodeWithTag("orta").bounds(), trail = rule.onNodeWithTag("son").bounds();
    CHECK(near(mid.height, 72) && near(trail.center().y, mid.center().y) && near(trail.right(), mid.right() - 16));
    // One node for accessibility: its texts together.
    int items = 0;
    for (const SemanticsNode& n : rule.host().semanticsTree()) items += n.label.find("Başlık") != std::string::npos && n.label.find("tek") != std::string::npos;
    CHECK(items == 1);
}

