TEST(permanent_and_dismissible_drawers) {
    std::optional<DrawerState> drawer;
    ComposeTestRule rule([&] {
        Column([&] {
            PermanentNavigationDrawer([] { PermanentDrawerSheet(Modifier().width(250), [] { Text("Kalıcı menü"); }); },
                                      Modifier().height(200), [] { Text("Kalıcı içerik", Modifier().testTag("permanent")); });
            auto s = rememberDrawerState();
            drawer = s;
            DismissibleNavigationDrawer([] { DismissibleDrawerSheet(Modifier().width(250), [] { Text("Açılır menü", Modifier().testTag("menu")); }); },
                                        s, [] { Text("İçerik", Modifier().testTag("content")); });
        });
    }, {600, 800});
    // Permanent: the content starts after the drawer.
    CHECK(near(rule.onNodeWithTag("permanent").bounds().x, 250) && rule.onNodeWithText("Kalıcı menü").exists());
    // Dismissible: closed, then open pushing the content over by the drawer's width.
    CHECK(near(rule.onNodeWithTag("content").bounds().x, 0) && !rule.onNodeWithTag("menu").exists());
    drawer->snapTo(DrawerValue::Open);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("content").bounds().x, 250) && near(rule.onNodeWithTag("menu").bounds().x, 12));
    rule.swipe({400, 500}, {100, 500}, 20);  // dragged closed
    rule.waitForIdle();
    CHECK(!drawer->isOpen() && near(rule.onNodeWithTag("content").bounds().x, 0));
    rule.swipe({50, 500}, {400, 500}, 20);  // and open
    rule.waitForIdle();
    CHECK(drawer->isOpen() && near(rule.onNodeWithTag("content").bounds().x, 250));
    CHECK(rule.host().keyDown(Key::Escape));  // back closes it
    rule.waitForIdle();
    CHECK(!drawer->isOpen());
}

