TEST(drawer_sheets_follow_the_back_gesture) {
    auto dismissible = mutableStateOf(false);
    auto rtl = mutableStateOf(false);
    std::optional<DrawerState> drawer;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        auto state = rememberDrawerState(DrawerValue::Open);
        drawer = state;
        scope = rememberCoroutineScope();
        CompositionLocalProvider({LocalLayoutDirection.provides(rtl.get() ? LayoutDirection::Rtl : LayoutDirection::Ltr)}, [&] {
            if (dismissible.get())
                DismissibleNavigationDrawer([] { DismissibleDrawerSheet(Modifier().width(300), [] { Text("Gelen"); }); }, state, [] {});
            else
                ModalNavigationDrawer([] { ModalDrawerSheet(Modifier(), [] { Text("Gelen"); }); }, state,
                                      [] { PermanentDrawerSheet(Modifier(), [] {}); });
        });
    }, {400, 800});
    rule.waitForIdle();
    // The sheet's layer (lower: scaleY) and its content's (scaled back across only).
    struct Scales {
        float sheetX = 1, sheetY = 1, originX = 0.5f, originY = 0.5f, contentX = 1, contentOriginX = 0.5f;
    };
    auto scales = [&] {
        rule.advanceFrame();
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        Scales out;
        for (const LayerTransform& t : canvas.layerTransforms) {
            if (t.scaleY != 1) out.sheetX = t.scaleX, out.sheetY = t.scaleY, out.originX = t.origin.x, out.originY = t.origin.y;
            else if (t.scaleX != 1) out.contentX = t.scaleX, out.contentOriginX = t.origin.x;
        }
        return out;
    };
    ComposeHost& host = rule.host();
    float p = Easing{0.1f, 0.1f, 0.f, 1.f}(0.5f);
    // From the drawer's own edge: wider (up to 12 dp of the sheet's 344 + 16), lower (48 of 800),
    // from the window's edge; the content keeps its shape, from its top right.
    host.backStarted({0, 400, 0, BackEventCompat::SwipeEdge::Left});
    host.backProgressed({40, 400, 0.5f, BackEventCompat::SwipeEdge::Left});
    Scales a = scales();
    CHECK(near(a.sheetX, 1 + 12 * p / 360, 0.001f) && near(a.sheetY, 1 - 48 * p / 800, 0.001f));
    CHECK(near(a.originX, 16.f / 360, 0.001f) && a.originY == 0.5f);
    CHECK(near(a.contentX, a.sheetY / a.sheetX, 0.001f) && a.contentOriginX == 1);
    host.backCancelled();  // as it was, still open
    rule.waitForIdle();
    Scales b = scales();
    CHECK(b.sheetX == 1 && b.sheetY == 1 && b.contentX == 1 && drawer->isOpen());
    // From the other edge: narrower (24 dp); done, it closes as it is.
    host.backStarted({400, 400, 0, BackEventCompat::SwipeEdge::Right});
    host.backProgressed({360, 400, 0.5f, BackEventCompat::SwipeEdge::Right});
    CHECK(near(scales().sheetX, 1 - 24 * p / 360, 0.001f));
    CHECK(host.backInvoked());
    rule.advanceTimeBy(48);
    Scales c = scales();
    CHECK(!drawer->isOpen() && near(c.sheetX, 1 - 24 * p / 360, 0.001f) && c.sheetY < 1);
    rule.waitForIdle();
    CHECK(drawer->openFraction() == 0 && !host.wantsBack());
    // Opened again: whole. From its edge, done: it goes back across as it closes, still lower.
    scope->launch([d = *drawer]() -> Task { co_await d.open(); });
    rule.waitForIdle();
    Scales d = scales();
    CHECK(drawer->isOpen() && d.sheetX == 1 && d.sheetY == 1);
    host.backStarted({0, 400, 0, BackEventCompat::SwipeEdge::Left});
    host.backProgressed({40, 400, 0.5f, BackEventCompat::SwipeEdge::Left});
    CHECK(host.backInvoked());
    rule.advanceTimeBy(150);
    Scales e = scales();
    CHECK(e.sheetX < 1 + 12 * p / 360 - 0.001f && e.sheetY < 1);
    rule.waitForIdle();
    CHECK(!drawer->isOpen());
    // A dismissible one: from its edge, which is the window's.
    dismissible.set(true);
    scope->launch([d = *drawer]() -> Task { co_await d.open(); });
    rule.waitForIdle();
    host.backStarted({0, 400, 0, BackEventCompat::SwipeEdge::Left});
    host.backProgressed({40, 400, 0.5f, BackEventCompat::SwipeEdge::Left});
    Scales f = scales();
    CHECK(near(f.sheetX, 1 + 12 * p / 300, 0.001f) && f.originX == 0 && near(f.sheetY, 1 - 48 * p / 800, 0.001f));
    host.backCancelled();
    // Right to left: the drawer's edge is the right one; mirrored.
    dismissible.set(false);
    rtl.set(true);
    rule.waitForIdle();
    host.backStarted({400, 400, 0, BackEventCompat::SwipeEdge::Right});
    host.backProgressed({360, 400, 0.5f, BackEventCompat::SwipeEdge::Right});
    Scales g = scales();
    CHECK(near(g.sheetX, 1 + 12 * p / 360, 0.001f) && near(g.originX, 1 - 16.f / 360, 0.001f) && g.contentOriginX == 0);
    host.backCancelled();
}

TEST(navigation_drawer_opens_closes_and_leaves_content_usable) {
    auto clicks = std::make_shared<int>(0);
    DrawerState* drawer = nullptr;
    auto scopeBox = std::make_shared<std::optional<CoroutineScope>>();
    ComposeTestRule rule([&] {
        auto& state = remember([] { return DrawerState(); });
        drawer = &state;
        *scopeBox = rememberCoroutineScope();
        ModalNavigationDrawer(
            [] {
                ModalDrawerSheet(Modifier().testTag("sheet"), [] {
                    NavigationDrawerItem([] { Text("Gelen kutusu"); }, true, [] {});
                });
            },
            state, [&] { Button([clicks] { ++*clicks; }, Modifier().padding(100).testTag("content"), [] { Text("İçerik"); }); });
    }, {400, 800});
    rule.onNodeWithText("İçerik").performClick();  // closed: the content works
    CHECK(*clicks == 1 && !rule.onNodeWithText("Gelen kutusu").exists());
    DrawerState state = *drawer;
    (*scopeBox)->launch([state]() -> Task { co_await state.open(); });
    rule.waitForIdle();
    CHECK(state.isOpen() && near(state.openFraction(), 1));
    Rect sheet = rule.onNodeWithTag("sheet").bounds();
    // 400 wide: min(360, 400 - 56) plus the 16 dp hidden past the edge; items 12 dp in, text 16 more.
    CHECK(near(sheet.width, 344 + 16) && near(rule.onNodeWithText("Gelen kutusu").bounds().x, 12 + 16));
    tap(rule, {380, 400});  // the scrim takes the tap and closes the drawer
    rule.waitForIdle();
    CHECK(*clicks == 1 && !state.isOpen() && !rule.onNodeWithText("Gelen kutusu").exists());
    rule.swipe({20, 400}, {300, 400}, 12);  // drag open from the content
    rule.waitForIdle();
    CHECK(state.isOpen());
    CHECK(rule.host().keyDown(Key::Escape));  // back closes it
    rule.waitForIdle();
    CHECK(!state.isOpen());
    (*scopeBox)->launch([state]() -> Task { co_await state.open(); });
    rule.waitForIdle();
    rule.swipe({300, 400}, {40, 400}, 12);  // drag it shut
    rule.waitForIdle();
    CHECK(!state.isOpen() && near(state.openFraction(), 0));
}

