TEST(double_measured_children_settle) {
    auto big = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            // A tab row measures its tabs twice; IntrinsicSize does the same.
            PrimaryTabRow(0, Modifier(), [&] {
                Tab(true, [] {}, [] { BoxWithConstraints(Modifier(), [](const Constraints& c) { Text(c.maxWidth > 50 ? "geniş" : "dar"); }); });
                Tab(false, [] {}, [] { Text("İki"); });
            });
            Row(Modifier().height(IntrinsicSize::Min), [&] {
                Box(Modifier().animateContentSize(tween(100)).testTag("anim"), [&] { Box(Modifier().size(big.get() ? 80.f : 40.f)); });
                Box(Modifier().width(2).fillMaxHeight());
            });
        });
    });
    rule.waitForIdle();
    uint64_t before = rule.host().stats().recompositions;
    for (int i = 0; i < 10; ++i) rule.advanceFrame();
    CHECK(rule.host().stats().recompositions == before && !rule.host().hasPendingWork());
    big.set(true);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("anim").bounds().height, 80) && !rule.host().hasPendingWork());
}

TEST(annotated_string_styles_wraps_and_links) {
    auto clicks = std::make_shared<int>(0);
    ComposeTestRule rule([clicks] {
        Column([&] {
            Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                     b.append("Merhaba ");
                     b.withStyle({.fontWeight = FontWeight::Bold, .color = colors::White}, [&] {
                         b.append("koyu ");
                         b.withStyle({.fontStyle = FontStyle::Italic}, [&] { b.append("eğik"); });
                     });
                     b.append(" ve ");
                     b.withLink([clicks] { ++*clicks; }, [&] { b.append("bağlantı"); });
                 }),
                 Modifier().testTag("styled"));
            // Two sizes on one line: as tall as the bigger one.
            Text(buildAnnotatedString([](AnnotatedString::Builder& b) {
                     b.append("küçük ");
                     b.withStyle({.fontSize = 32}, [&] { b.append("BÜYÜK"); });
                 }),
                 Modifier().testTag("mixed"));
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK((canvas.texts == std::vector<std::string>{"Merhaba ", "koyu ", "eğik", " ve ", "bağlantı", "küçük ", "BÜYÜK"}));
    CHECK(canvas.fonts.size() == 7 && canvas.fonts[1].weight == FontWeight::Bold && canvas.fonts[1].style == FontStyle::Normal);
    CHECK(canvas.fonts[2].weight == FontWeight::Bold && canvas.fonts[2].style == FontStyle::Italic);  // nested: both apply
    CHECK(canvas.colors[2] == colors::White && canvas.colors[4] == lightColorScheme().primary);  // links: primary
    CHECK(near(rule.onNodeWithTag("mixed").bounds().height, 40));  // 32 * 1.25
    // 16sp text, 8 dp per character: "Merhaba koyu eğik ve " is 21 characters, the link follows.
    Rect styled = rule.onNodeWithTag("styled").bounds();
    tap(rule, {styled.x + 8 * 23, styled.y + 10});  // on "bağlantı"
    rule.waitForIdle();
    tap(rule, {styled.x + 8 * 3, styled.y + 10});  // on "Merhaba"
    rule.waitForIdle();
    CHECK(*clicks == 1);
}

TEST(text_overflow_soft_wrap_and_max_lines) {
    ComposeTestRule rule([] {
        Column([] {
            // 16sp: 8 dp per character, 20 dp lines; 80 dp hold 10 characters.
            Text("bir iki üç dört beş", Modifier().width(80).testTag("wrap"));
            Text("bir iki üç dört beş", Modifier().width(80).testTag("ellipsis"),
                 {.maxLines = 1, .overflow = TextOverflow::Ellipsis});
            Text("bir iki üç dört beş", Modifier().width(80).testTag("clip"), {.maxLines = 1});
            Text("bir iki üç dört beş", Modifier().width(80).testTag("nowrap"),
                 {.overflow = TextOverflow::Ellipsis, .softWrap = false});
            Text("satır\n\nboş satır", Modifier().testTag("breaks"));
        });
    });
    CHECK(near(rule.onNodeWithTag("wrap").bounds().height, 40));  // "bir iki üç" / "dört beş"
    CHECK(near(rule.onNodeWithTag("ellipsis").bounds().height, 20) && near(rule.onNodeWithTag("clip").bounds().height, 20));
    CHECK(near(rule.onNodeWithTag("breaks").bounds().height, 60));  // the empty line counts
    auto texts = rule.drawnTexts();
    CHECK(std::count(texts.begin(), texts.end(), "bir iki ü…") == 2);             // maxLines 1 and no wrap: cut to fit "…"
    CHECK(std::find(texts.begin(), texts.end(), "bir iki üç") != texts.end());     // clip: the first line
}

