TEST(animate_item_glides_on_removal_and_fades_in_on_insert) {
    auto items = mutableStateListOf<int>({1, 2, 3, 4});
    ComposeTestRule rule([&] {
        LazyColumn(Modifier().fillMaxSize(), [&](LazyListScope& list) {
            list.items(items.items(), [](int v) { return v; }, [](int v) {
                Box(Modifier().animateItem(tween(200, 0, LinearEasing)).fillMaxWidth().height(50).testTag("item" + std::to_string(v)));
            });
        });
    }, {400, 800});
    CHECK(near(rule.onNodeWithTag("item3").bounds().y, 100));
    items.removeAt(0);  // 2, 3, 4 move up by 50
    rule.advanceTimeBy(112);
    float mid = rule.onNodeWithTag("item3").bounds().y;
    CHECK(mid > 55 && mid < 95);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("item3").bounds().y, 50));
    items.add(0, 9);  // inserted at the top: fades in while the others glide down
    rule.advanceTimeBy(48);
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(canvas.layers >= 1);  // the new item draws through an alpha layer
    rule.waitForIdle();
    testing::RecordingCanvas after;
    rule.host().draw(after);
    CHECK(after.layers == 0 && near(rule.onNodeWithTag("item3").bounds().y, 100));
}

TEST(animate_item_fades_a_removed_item_out_where_it_was) {
    auto items = mutableStateListOf<int>({1, 2, 3});
    auto tick = mutableStateOf(0);
    std::map<int, int> composed;
    std::vector<int> clicked;
    ComposeTestRule rule([&] {
        int t = tick.get();
        LazyColumn(Modifier().fillMaxSize(), [&](LazyListScope& list) {
            list.items(items.items(), [](int v) { return v; }, [&, t](int v) {
                ++composed[v];
                Text(std::format("öğe {} · {}", v, t),
                     Modifier()
                         .animateItem(tween(100), spring(Spring::DampingRatioNoBouncy, Spring::StiffnessMediumLow), tween(200, 0, LinearEasing))
                         .fillMaxWidth()
                         .height(50)
                         .clickable([&clicked, v] { clicked.push_back(v); }));
            });
        });
    }, {400, 800});
    auto drawn = [&](testing::RecordingCanvas& canvas, const std::string& text) {
        return std::find(canvas.texts.begin(), canvas.texts.end(), text) != canvas.texts.end();
    };
    items.removeAt(0);
    tick.set(1);  // the list composes again; the leaving item doesn't (its data is gone)
    rule.advanceTimeBy(96);
    testing::RecordingCanvas mid;
    rule.host().draw(mid);
    CHECK(drawn(mid, "öğe 1 · 0") && drawn(mid, "öğe 2 · 1"));  // shown as it last was
    CHECK(std::any_of(mid.layerAlphas.begin(), mid.layerAlphas.end(), [](float a) { return a > 0.3f && a < 0.7f; }));
    CHECK(composed[1] == 1 && composed[2] >= 2);
    CHECK(sameRect(rule.onNodeWithText("öğe 1 · 0").bounds(), {0, 0, 400, 50}));  // where it was
    rule.host().pointerDown({200, 5});  // on it: it takes no input
    rule.host().pointerUp({200, 5});
    rule.advanceFrame();
    CHECK(std::find(clicked.begin(), clicked.end(), 1) == clicked.end());
    rule.waitForIdle();
    testing::RecordingCanvas after;
    rule.host().draw(after);
    CHECK(!drawn(after, "öğe 1 · 0") && !rule.onNodeWithText("öğe 1 · 0").exists() && after.layers == 0);
    CHECK(near(rule.onNodeWithText("öğe 2 · 1").bounds().y, 0));
    items.removeAt(0);  // 2 leaves, and comes back before it is gone: an item again
    rule.advanceTimeBy(48);
    items.add(0, 2);
    tick.set(2);
    rule.waitForIdle();
    testing::RecordingCanvas back;
    rule.host().draw(back);
    CHECK(drawn(back, "öğe 2 · 2") && !drawn(back, "öğe 2 · 1") && back.layers == 0);
    CHECK(near(rule.onNodeWithText("öğe 2 · 2").bounds().y, 0) && near(rule.onNodeWithText("öğe 3 · 2").bounds().y, 50));
}

TEST(async_image_loads_away_from_the_ui_thread_and_caches) {
    clearImageCache();
    std::vector<std::pair<std::string, std::function<void(ImageBitmap)>>> requests;
    auto shown = mutableStateOf(false);
    AsyncImageOptions options{.placeholder = [] { Text("yükleniyor"); }, .error = [] { Text("hata"); },
                              .contentScale = ContentScale::Crop, .crossfadeMillis = 200};
    ComposeTestRule rule([&] {
        if (!shown.get()) return;
        Column([&] {
            AsyncImage("images/a.jpg", "foto", Modifier().size(100, 60).testTag("a"), options);
            AsyncImage("images/a.jpg", "foto 2", Modifier().size(50, 50), options);  // the same model: one load
            AsyncImage("https://example.com/yok.webp", "yok", Modifier().size(80, 40).testTag("b"), options);
        });
    }, {400, 800});
    rule.host().setCallbacks({.loadImageAsync = [&](const std::string& model, ImageRequestSize, std::function<void(ImageBitmap)> done) {
        requests.push_back({model, std::move(done)});
    }});
    shown.set(true);
    rule.waitForIdle();
    CHECK(requests.size() == 2 && requests[0].first == "images/a.jpg");
    CHECK(rule.onAllNodesWithText("yükleniyor").size() == 3 && sameRect(rule.onNodeWithTag("a").bounds(), {0, 0, 100, 60}));
    std::thread worker([&] { requests[0].second(ImageBitmap::fromPixels(4, 2, std::vector<uint8_t>(32, 255))); });
    worker.join();  // done from another thread: it reaches the UI thread with the next frame
    requests[1].second({});
    rule.advanceTimeBy(100);
    testing::RecordingCanvas mid;
    rule.host().draw(mid);
    CHECK(mid.images.size() == 2 && rule.onAllNodesWithText("yükleniyor").size() == 2);  // cross-fading
    CHECK(rule.onNodeWithText("hata").exists());
    rule.waitForIdle();
    testing::RecordingCanvas after;
    rule.host().draw(after);
    CHECK(after.images.size() == 2 && !rule.onNodeWithText("yükleniyor").exists());
    CHECK(sameRect(after.imageDestinations[0], {0, 0, 100, 60}));  // cropped to fill its size
    CHECK(rule.onNodeWithText("foto").exists());  // its description
    shown.set(false);
    rule.waitForIdle();
    shown.set(true);  // again: from the cache, at once (no cross-fade); the failed one is tried again
    rule.advanceFrame();
    CHECK(rule.onAllNodesWithText("yükleniyor").size() == 1);
    rule.waitForIdle();
    testing::RecordingCanvas again;
    rule.host().draw(again);
    CHECK(again.images.size() == 2 && rule.onAllNodesWithText("yükleniyor").size() == 1 && requests.size() == 3);
}

TEST(images_are_decoded_smaller_by_powers_of_two_never_below_the_size) {
    CHECK(imageSampleSize(4000, 3000, {1000, 1000}) == 4);        // fitted: 1000 x 750
    CHECK(imageSampleSize(4000, 3000, {1000, 1000, true}) == 2);  // cropped: 2000 x 1500 covers it
    CHECK(imageSampleSize(4000, 3000, {500, 0}) == 8 && imageSampleSize(4000, 3000, {0, 1500}) == 2);
    CHECK(imageSampleSize(4000, 3000, {1001, 0}) == 2);  // 1000 would be too narrow
    CHECK(imageSampleSize(300, 200, {1000, 1000}) == 1 && imageSampleSize(4000, 3000, {}) == 1);
    CHECK(imageSampleSize(10000, 100, {}) == 4);  // at most maxImageDimension across: 2500
    CHECK(imageCovers(1000, 750, {1000, 1000}) && !imageCovers(1000, 750, {1000, 1000, true}));
    CHECK(imageCovers(2000, 1500, {1000, 1000, true}) && !imageCovers(5, 5, {}) && !imageCovers(999, 750, {1000, 0}));
    // Scaled down by averaging, weighted by alpha (a transparent pixel adds no color).
    ImageBitmap image = ImageBitmap::fromPixels(3, 2, {255, 0, 0, 255, 0, 0, 255, 255, 0, 255, 0, 255,  //
                                                       255, 0, 0, 255, 255, 255, 255, 0, 255, 0, 255, 0});
    ImageBitmap half = scaleDown(image, 2);
    CHECK(half.width() == 2 && half.height() == 1);
    const uint8_t* p = half.pixels();
    CHECK(p[0] == 170 && p[1] == 0 && p[2] == 85 && p[3] == 191);
    CHECK(p[4] == 0 && p[5] == 255 && p[6] == 0 && p[7] == 128);
    CHECK(scaleDown(image, 1) == image);
}

TEST(disk_cache_keeps_the_recently_used_within_its_size) {
    namespace fs = std::filesystem;
    fs::path dir = fs::temp_directory_path() / std::format("kompoz-disk-cache-{}", std::chrono::steady_clock::now().time_since_epoch().count());
    auto bytes = [](uint8_t v) { return std::vector<uint8_t>(300, v); };
    {
        DiskCache cache(dir, 1000);  // each entry is 300 bytes and its key: three fit
        CHECK(!cache.get("https://x/a"));
        cache.put("https://x/a", bytes(1));
        cache.put("https://x/b", bytes(2));
        cache.put("https://x/c", bytes(3));
        CHECK(cache.get("https://x/a") == bytes(1));  // used: b is now the oldest
        cache.put("https://x/d", bytes(4));
        CHECK(!cache.get("https://x/b") && cache.get("https://x/c") == bytes(3) && cache.get("https://x/d") == bytes(4));
        CHECK(cache.size() <= 1000 && cache.size() > 900);
        cache.put("https://x/huge", std::vector<uint8_t>(2000, 5));  // would never fit: not kept, nothing goes for it
        CHECK(!cache.get("https://x/huge") && cache.get("https://x/a") == bytes(1));
        cache.put("https://x/a", bytes(9));  // replaced
        CHECK(cache.get("https://x/a") == bytes(9));
    }
    std::ofstream(dir / "0123456789abcdef.12.tmp") << "a write that never finished";
    std::ofstream(dir / "notes.txt") << "not the cache's";
    {
        DiskCache again(dir, 1000);  // the next run finds them
        CHECK(again.get("https://x/a") == bytes(9) && again.get("https://x/d") == bytes(4));
        CHECK(!fs::exists(dir / "0123456789abcdef.12.tmp") && fs::exists(dir / "notes.txt"));
        again.remove("https://x/a");
        CHECK(!again.get("https://x/a") && again.get("https://x/c") == bytes(3));
        again.clear();
        CHECK(again.size() == 0 && !again.get("https://x/c") && fs::exists(dir / "notes.txt"));
    }
    {
        DiskCache none(dir, 0);  // keeps nothing
        none.put("https://x/a", bytes(1));
        CHECK(!none.get("https://x/a"));
    }
    std::error_code ec;
    fs::remove_all(dir, ec);
}

