TEST(async_image_is_decoded_at_the_size_its_layout_gets) {
    clearImageCache();
    struct Request {
        std::string model;
        ImageRequestSize size;
        std::function<void(ImageBitmap)> done;
    };
    std::vector<Request> requests;
    auto photo = [](int w, int h) { return ImageBitmap::fromPixels(w, h, std::vector<uint8_t>(size_t(w) * size_t(h) * 4, 200)); };
    auto big = mutableStateOf(false), small = mutableStateOf(true), whole = mutableStateOf(false);
    std::vector<AsyncImageState> states;  // what the small one told
    ScrollState scroll;
    ComposeTestRule rule([&] {
        Column(Modifier().fillMaxSize().verticalScroll(scroll), [&] {
            if (small.get())
                AsyncImage("photo.jpg", "küçük", Modifier().size(100, 60).testTag("small"),
                           {.contentScale = ContentScale::Crop, .onState = [&](const AsyncImageState& s) { states.push_back(s); }});
            // Fitted to the width in a column that scrolls: only the width counts.
            if (big.get()) AsyncImage("photo.jpg", "büyük", Modifier().fillMaxWidth().testTag("big"));
            if (whole.get()) {
                AsyncImageState state = rememberAsyncImage("photo.jpg");
                Text(std::format("bütün {}", state.image.width()));
            }
        });
    }, {400, 800});
    rule.host().setDensity({2, 1});
    rule.host().setCallbacks({.loadImageAsync = [&](const std::string& model, ImageRequestSize size, std::function<void(ImageBitmap)> done) {
        requests.push_back({model, size, std::move(done)});
    }});
    small.set(false);
    rule.waitForIdle();
    small.set(true);
    rule.waitForIdle();
    CHECK(requests.size() == 1 && requests[0].size == (ImageRequestSize{200, 120, true}));  // its box, in pixels
    requests[0].done(photo(200, 150));  // a 4:3 photo decoded to cover it
    rule.waitForIdle();
    CHECK(sameRect(rule.onNodeWithTag("small").bounds(), {0, 0, 100, 60}));
    // Told each change: without a loader at first (an error), then loading again, then loaded.
    using Status = AsyncImageState::Status;
    CHECK(states.size() == 4 && states[0].status == Status::Loading && states[1].status == Status::Error);
    CHECK(states[2].status == Status::Loading && states[3].status == Status::Success && states[3].image.width() == 200);
    // A bigger one of the same photo: the small one at once, then one decoded for its width.
    big.set(true);
    rule.waitForIdle();
    CHECK(requests.size() == 2 && requests[1].size == (ImageRequestSize{800, 0, false}));
    CHECK(sameRect(rule.onNodeWithTag("big").bounds(), {0, 60, 400, 300}));  // already the photo's shape
    testing::RecordingCanvas before;
    rule.host().draw(before);
    CHECK(before.images.size() == 2 && before.images[0] == before.images[1]);
    requests[1].done(photo(800, 600));
    rule.waitForIdle();
    testing::RecordingCanvas after;
    rule.host().draw(after);
    CHECK(after.images.size() == 2 && after.images[0] != after.images[1]);
    CHECK(sameRect(rule.onNodeWithTag("big").bounds(), {0, 60, 400, 300}));  // the same layout
    // Both again: the big one in the cache does for both.
    small.set(false);
    big.set(false);
    rule.waitForIdle();
    small.set(true);
    big.set(true);
    rule.waitForIdle();
    CHECK(requests.size() == 2);
    // The whole image (rememberAsyncImage): the 800 one isn't, so it is loaded; the decoder
    // gives back what it has (smaller than asked would be: it is the whole image).
    whole.set(true);
    rule.waitForIdle();
    CHECK(requests.size() == 3 && requests[2].size.any() && rule.onNodeWithText("bütün 800").exists());
    requests[2].done(photo(1600, 1200));
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("bütün 1600").exists());
    // Two sizes asked for at once: one load; who needs more than it brought gets another.
    clearImageCache();
    small.set(false);
    big.set(false);
    whole.set(false);
    rule.waitForIdle();
    small.set(true);
    big.set(true);
    rule.waitForIdle();
    CHECK(requests.size() == 4 && requests[3].size == (ImageRequestSize{200, 120, true}));
    requests[3].done(photo(200, 150));
    rule.waitForIdle();
    CHECK(requests.size() == 5 && requests[4].size == (ImageRequestSize{800, 0, false}));
    requests[4].done(photo(100, 75));  // smaller than asked: the whole image, nothing more to ask for
    rule.waitForIdle();
    CHECK(requests.size() == 5);
    testing::RecordingCanvas last;
    rule.host().draw(last);
    CHECK(last.images.size() == 2 && last.images[0] != last.images[1]);
}

TEST(reverse_layout_puts_the_first_item_at_the_bottom) {
    LazyListState state;
    auto count = mutableStateOf(3);
    ComposeTestRule rule([&] {
        Column([&] {
            LazyColumn(Modifier().size(200, 400), {.state = state, .contentPadding = {0, 10, 0, 20}, .reverseLayout = true},
                       [&](LazyListScope& list) {
                           list.items(count.get(), [](int i) { Box(Modifier().fillMaxWidth().height(40).testTag(std::format("i{}", i))); });
                       });
            LazyRow(Modifier().size(400, 50), {.reverseLayout = true}, [&](LazyListScope& list) {
                list.items(3, [](int i) { Box(Modifier().width(60).fillMaxHeight().testTag(std::format("r{}", i))); });
            });
        });
    }, {400, 800});
    // A few: at the bottom, item 0 lowest, above the bottom padding (which stays at the bottom).
    CHECK(sameRect(rule.onNodeWithTag("i0").bounds(), {0, 340, 200, 40}));
    CHECK(sameRect(rule.onNodeWithTag("i2").bounds(), {0, 260, 200, 40}));
    CHECK(sameRect(rule.onNodeWithTag("r0").bounds(), {340, 400, 60, 50}) && sameRect(rule.onNodeWithTag("r1").bounds(), {280, 400, 60, 50}));
    count.set(50);
    rule.waitForIdle();
    CHECK(sameRect(rule.onNodeWithTag("i0").bounds(), {0, 340, 200, 40}) && state.firstVisibleItemIndex() == 0);
    CHECK(!state.canScrollBackward() && state.canScrollForward());
    // A finger pulling down brings the later items down from above (a quick flick: well past
    // the first ones, which go).
    rule.swipe({100, 100}, {100, 260}, 5);
    rule.waitForIdle();
    int first = state.firstVisibleItemIndex();
    CHECK(first >= 4 && !rule.onNodeWithTag("i0").exists());
    // Item `first` is the one at the bottom, scrolled down past it by the offset.
    Rect bottom = rule.onNodeWithTag(std::format("i{}", first)).bounds();
    CHECK(near(bottom.y, 340 + state.firstVisibleItemScrollOffset()));
    // At the start, pulling up does nothing.
    state.scrollToItem(0);
    rule.waitForIdle();
    rule.swipe({100, 300}, {100, 150}, 10);
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() == 0 && sameRect(rule.onNodeWithTag("i0").bounds(), {0, 340, 200, 40}));
    // At the far end, the last item stops under the top padding.
    state.scrollToItem(49);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("i49").bounds().y, 10) && !state.canScrollForward());
}

TEST(animate_scroll_to_item_glides_there) {
    LazyListState state;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        scope = rememberCoroutineScope();
        LazyColumn(Modifier().size(200, 400), {.state = state}, [&](LazyListScope& list) {
            list.items(1000, [](int i) { Box(Modifier().fillMaxWidth().height(i % 3 == 0 ? 60 : 40)); });  // estimates are off
        });
    });
    auto go = [&](int index, float offset) { scope->launch([state, index, offset]() -> Task { co_await state.animateScrollToItem(index, offset); }); };
    go(10, 0);
    for (int i = 0; i < 6; ++i) rule.advanceFrame();
    int mid = state.firstVisibleItemIndex();
    CHECK(mid > 0 && mid < 10);  // on its way, not a jump
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() == 10 && near(state.firstVisibleItemScrollOffset(), 0));
    // Far: a jump to close by, then the glide; exactly there in the end.
    go(600, 15);
    for (int i = 0; i < 4; ++i) rule.advanceFrame();
    CHECK(state.firstVisibleItemIndex() > 570 && state.firstVisibleItemIndex() < 600);
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() == 600 && near(state.firstVisibleItemScrollOffset(), 15));
    go(0, 0);
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() == 0 && near(state.firstVisibleItemScrollOffset(), 0));
    // The last one can't be first: it stops where the list ends.
    go(999, 0);
    rule.waitForIdle();
    CHECK(!state.canScrollForward() && state.firstVisibleItemIndex() < 999 && state.firstVisibleItemIndex() > 980);
    // A finger stops it, and so does a newer one.
    go(500, 0);  // from the end: a jump to just after it, then back towards it...
    for (int i = 0; i < 6; ++i) rule.advanceFrame();
    int before = state.firstVisibleItemIndex();
    CHECK(before >= 500 && before < 520);
    rule.swipe({100, 220}, {100, 160}, 4);  // ...until a finger pushes it on
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() > before);
    go(0, 0);
    rule.advanceFrame();
    rule.advanceFrame();
    go(100, 0);
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() == 100);
    scope->launch([state]() -> Task { co_await state.animateScrollBy(-130); });  // 40 + 40 + 60 - 10: into item 97
    rule.waitForIdle();
    CHECK(state.firstVisibleItemIndex() == 97 && near(state.firstVisibleItemScrollOffset(), 10));
}

TEST(animate_scroll_to_item_finds_items_bigger_than_guessed) {
    // Items 117..129 are ten times taller than the ones measured around 100: the guess for 130
    // (no further than three views: no jump) falls far short.
    LazyListState state;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        scope = rememberCoroutineScope();
        LazyColumn(Modifier().size(200, 400), {.state = state}, [&](LazyListScope& list) {
            list.items(200, [](int i) { Box(Modifier().fillMaxWidth().height(i >= 117 && i < 130 ? 400 : 40)); });
        });
    });
    state.scrollToItem(100);
    rule.waitForIdle();
    auto arrived = std::make_shared<bool>(false);
    scope->launch([state, arrived]() -> Task {
        co_await state.animateScrollToItem(130);
        *arrived = true;
    });
    // One glide, heading further as the items turn out taller (not a stop at the guess and another).
    int last = 100;
    bool forward = true;
    for (int t = 0; t < 700 && !*arrived; t += 16) {
        rule.advanceFrame();
        forward = forward && state.firstVisibleItemIndex() >= last;
        last = state.firstVisibleItemIndex();
    }
    CHECK(*arrived && forward && state.firstVisibleItemIndex() == 130 && near(state.firstVisibleItemScrollOffset(), 0));
    // To the end: it is over once the list can't go further (no waiting out the spring, again and again).
    *arrived = false;
    scope->launch([state, arrived]() -> Task {
        co_await state.animateScrollToItem(199);
        *arrived = true;
    });
    rule.advanceTimeBy(700);
    CHECK(*arrived && !state.canScrollForward());
}

TEST(scroll_state_animates_to_a_value) {
    ScrollState scroll;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        scope = rememberCoroutineScope();
        Column(Modifier().size(200, 400).verticalScroll(scroll), [] { Box(Modifier().fillMaxWidth().height(2000)); });
    });
    auto to = [&](float v) { scope->launch([scroll, v]() -> Task { co_await scroll.animateScrollTo(v); }); };
    to(1000);
    for (int i = 0; i < 5; ++i) rule.advanceFrame();
    CHECK(scroll.value() > 0 && scroll.value() < 1000);
    rule.waitForIdle();
    CHECK(near(scroll.value(), 1000));
    to(5000);  // only as far as it goes
    rule.waitForIdle();
    CHECK(near(scroll.value(), 1600));
    scope->launch([scroll]() -> Task { co_await scroll.animateScrollBy(-600, tween(200)); });
    rule.advanceTimeBy(100);
    CHECK(scroll.value() < 1600 && scroll.value() > 1000);
    rule.waitForIdle();
    CHECK(near(scroll.value(), 1000));
    to(0);  // a newer one takes over
    rule.advanceFrame();
    rule.advanceFrame();
    to(800);
    rule.waitForIdle();
    CHECK(near(scroll.value(), 800));
    to(0);  // and a finger
    for (int i = 0; i < 4; ++i) rule.advanceFrame();
    rule.swipe({100, 300}, {100, 250}, 4);
    float released = scroll.value();  // the animation stopped: from here the fling goes on, not back to 0
    rule.waitForIdle();
    CHECK(released > 100 && scroll.value() > released + 50);
}

TEST(scroll_states_tell_their_value_and_whether_they_scroll) {
    ScrollState scroll;
    LazyListState list;
    LazyGridState grid;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        scope = rememberCoroutineScope();
        Column([&] {
            // Read in composition: recomposed as they change.
            Text(std::format("değer {:.0f}/{:.0f} {}{}{}", scroll.value(), scroll.maxValue(), scroll.canScrollBackward() ? "<" : "",
                             scroll.canScrollForward() ? ">" : "", scroll.isScrollInProgress() ? " kayıyor" : ""));
            Text(std::string("liste") + (list.isScrollInProgress() ? " kayıyor" : "") + (grid.isScrollInProgress() ? " ızgara" : ""));
            Column(Modifier().size(200, 200).verticalScroll(scroll), [] { Box(Modifier().fillMaxWidth().height(1000)); });
            LazyColumn(Modifier().size(200, 200), {.state = list}, [](LazyListScope& s) {
                s.items(100, [](int i) { Text(std::to_string(i), Modifier().height(40)); });
            });
            LazyVerticalGrid(GridCells::Fixed(2), Modifier().size(200, 200), {.state = grid}, [](LazyGridScope& s) {
                s.items(100, [](int i) { Text(std::to_string(i), Modifier().height(40)); });
            });
        });
    }, {400, 1200});
    auto shows = [&](const std::string& text) { return rule.onNodeWithText(text).exists(); };
    CHECK(shows("değer 0/800 >") && shows("liste"));
    scroll.scrollTo(300);
    rule.waitForIdle();
    CHECK(shows("değer 300/800 <>"));
    // Dragged: scrolling; let go with speed: still, as it flings; then not.
    Rect area = rule.onNodeWithText("liste").bounds();
    float top = area.bottom() + 10;
    rule.host().pointerDown({100, top + 150});
    for (int i = 1; i <= 5; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({100, top + 150 - 20.f * float(i)});
    }
    rule.advanceFrame();
    CHECK(scroll.isScrollInProgress() && rule.onNodeWithText("kayıyor", true).exists());
    rule.host().pointerUp({100, top + 50});
    rule.advanceFrame();
    CHECK(scroll.isScrollInProgress());
    rule.waitForIdle();
    CHECK(!scroll.isScrollInProgress() && !rule.onNodeWithText("kayıyor", true).exists() && scroll.value() > 400);
    // A fling the wheel stops: done.
    rule.swipe({100, top + 150}, {100, top + 50}, 5);
    rule.advanceFrame();
    CHECK(scroll.isScrollInProgress());
    rule.host().scroll({100, top + 100}, 0);
    CHECK(!scroll.isScrollInProgress());
    // Held still before letting go: no fling, done at once.
    rule.host().pointerDown({100, top + 150});
    for (int i = 1; i <= 5; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({100, top + 150 + 10.f * float(i)});
    }
    rule.advanceTimeBy(200);
    rule.host().pointerUp({100, top + 200});
    CHECK(!scroll.isScrollInProgress());
    // Animated: while it runs.
    scope->launch([scroll]() -> Task { co_await scroll.animateScrollTo(0); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(scroll.isScrollInProgress());
    rule.waitForIdle();
    CHECK(!scroll.isScrollInProgress() && shows("değer 0/800 >"));
    // A list and a grid alike: flung, and animated (stopped by a touch: no more).
    float listTop = top + 200;
    rule.swipe({100, listTop + 180}, {100, listTop + 40}, 5);
    rule.advanceFrame();
    CHECK(list.isScrollInProgress() && shows("liste kayıyor"));
    rule.waitForIdle();
    CHECK(!list.isScrollInProgress() && list.firstVisibleItemIndex() > 3);
    scope->launch([list]() -> Task { co_await list.animateScrollToItem(0); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(list.isScrollInProgress());
    rule.host().pointerDown({100, listTop + 100});
    rule.advanceFrame();
    rule.host().pointerUp({100, listTop + 100});
    rule.waitForIdle();
    CHECK(!list.isScrollInProgress());
    scope->launch([list]() -> Task { co_await list.animateScrollBy(120); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(list.isScrollInProgress());
    rule.waitForIdle();
    CHECK(!list.isScrollInProgress());
    scope->launch([grid]() -> Task { co_await grid.animateScrollToItem(30); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(grid.isScrollInProgress() && shows("liste ızgara"));
    rule.waitForIdle();
    CHECK(!grid.isScrollInProgress());
}

TEST(scrolling_turned_off_for_the_user_and_scrolling_from_the_end) {
    ScrollState page, fixedScroll, fromEnd;
    LazyListState list, inner;
    FocusRequester deep;
    ComposeTestRule rule([&] {
        Column(Modifier().fillMaxSize().verticalScroll(page), [&] {
            // Not by the user: a drag on it goes to the page around it.
            LazyColumn(Modifier().size(200, 200).testTag("liste"), {.state = list, .userScrollEnabled = false}, [](LazyListScope& s) {
                s.items(50, [](int i) { Text(std::to_string(i), Modifier().height(40)); });
            });
            Column(Modifier().size(200, 200).verticalScroll(fixedScroll, false).testTag("sabit"), [&] {
                LazyColumn(Modifier().size(200, 100), {.state = inner}, [](LazyListScope& s) {  // what it leaves goes past the fixed one
                    s.items(3, [](int i) { Text("iç " + std::to_string(i), Modifier().height(40)); });
                });
                Box(Modifier().fillMaxWidth().height(400));
                Box(Modifier().size(40).focusRequester(deep).focusable().testTag("derin"));
            });
            // From the end: it shows its bottom first.
            Column(Modifier().size(200, 200).verticalScroll(fromEnd, true, true).testTag("sondan"), [] {
                for (int i = 0; i < 10; ++i) Text("satır " + std::to_string(i), Modifier().height(50));
            });
            Box(Modifier().height(2000));
        });
    }, {400, 800});
    float pageAt = page.value();
    rule.swipe({100, 150}, {100, 50}, 20);
    rule.waitForIdle();
    CHECK(list.firstVisibleItemIndex() == 0 && near(list.firstVisibleItemScrollOffset(), 0) && page.value() > pageAt + 50);
    page.scrollTo(0);
    rule.waitForIdle();
    rule.host().scroll({100, 300}, -3);  // nor the wheel, over the fixed one: the page takes it
    rule.waitForIdle();
    CHECK(near(fixedScroll.value(), 0) && page.value() > 0);
    page.scrollTo(0);
    rule.waitForIdle();
    rule.swipe({100, 250}, {100, 150}, 20);  // the list inside scrolls its 20, the rest to the page
    rule.waitForIdle();
    CHECK(near(fixedScroll.value(), 0) && page.value() > 50 && !inner.canScrollForward());
    page.scrollTo(0);
    rule.waitForIdle();
    // Accessibility can't scroll them either: the page, the list in the fixed one and the one from the end.
    auto tree = rule.host().semanticsTree();
    CHECK(std::count_if(tree.begin(), tree.end(), [](const SemanticsNode& n) { return n.scrollable; }) == 3);
    // In code, and bringing something into view, it still scrolls.
    list.scrollToItem(10);
    rule.waitForIdle();
    CHECK(list.firstVisibleItemIndex() == 10);
    deep.requestFocus();
    rule.waitForIdle();
    CHECK(fixedScroll.value() > 300);
    // From the end: value 0 at the bottom, rows 6–9 in view; a finger down scrolls back up.
    page.scrollTo(0);
    rule.waitForIdle();
    Rect view = rule.onNodeWithTag("sondan").bounds();
    CHECK(near(fromEnd.maxValue(), 300) && near(fromEnd.value(), 0) && near(rule.onNodeWithText("satır 9").bounds().bottom(), view.bottom()));
    rule.swipe({100, view.y + 50}, {100, view.y + 150}, 20);
    rule.waitForIdle();
    CHECK(fromEnd.value() > 50 && near(rule.onNodeWithText("satır 9").bounds().bottom(), view.bottom() + fromEnd.value()));
}

TEST(lazy_lists_arrange_items_that_all_fit) {
    auto many = mutableStateOf(false);
    LazyListState bottom;
    ComposeTestRule rule([&] {
        auto list = [&](const char* name, std::optional<Arrangement> arrangement, bool reverse = false) {
            LazyListOptions o{.reverseLayout = reverse, .arrangement = arrangement};
            if (std::string(name) == "alt") o.state = bottom;
            LazyColumn(Modifier().size(100, 400), o, [&](LazyListScope& s) {
                s.items(many.get() ? 11 : 3, [name](int i) { Box(Modifier().fillMaxWidth().height(40).testTag(name + std::to_string(i))); });
            });
        };
        Row([&] {
            list("alt", Arrangement::Bottom);
            list("orta", Arrangement::spacedBy(10, Arrangement::Kind::Center));
            list("yayık", Arrangement::SpaceBetween);
            list("ters", Arrangement::Top, true);  // on the screen: at the top, the first item lowest
            list("düz", std::nullopt);
        });
        LazyRow(Modifier().size(400, 40), {.arrangement = Arrangement::End}, [](LazyListScope& s) {
            s.items(2, [](int i) { Box(Modifier().size(50, 40).testTag("satır" + std::to_string(i))); });
        });
    }, {600, 800});
    auto y = [&](const std::string& tag) { return rule.onNodeWithTag(tag).bounds().y; };
    CHECK(near(y("alt0"), 280) && near(y("alt2"), 360));
    CHECK(near(y("orta0"), 130) && near(y("orta1"), 180) && near(y("orta2"), 230));  // 140 tall, 10 apart, in the middle
    CHECK(near(y("yayık0"), 0) && near(y("yayık1"), 180) && near(y("yayık2"), 360));
    CHECK(near(y("ters2"), 0) && near(y("ters0"), 80) && near(y("düz0"), 0));
    CHECK(near(rule.onNodeWithTag("satır0").bounds().x, 300) && near(rule.onNodeWithTag("satır1").bounds().x, 350));
    // More than fit (all composed, 440 dp in 400): they scroll as usual, from the top (the spacing
    // still between them).
    many.set(true);
    rule.waitForIdle();
    CHECK(near(y("alt0"), 0) && near(y("orta0"), 0) && near(y("orta1"), 50) && near(y("yayık1"), 40));
    bottom.scrollBy(20);
    rule.waitForIdle();
    CHECK(near(y("alt0"), -20));
}

TEST(paths_take_arcs_and_draw_scopes_clip_to_paths) {
    auto end = [](const Path& p) {
        const PathCommand& c = p.commands().back();
        return Offset{c.x, c.y};
    };
    auto at = [](Offset p, float x, float y) { return near(p.x, x, 0.01f) && near(p.y, y, 0.01f); };
    // A quarter of the circle in 100×100: from the right (0°), clockwise, to the bottom.
    Path quarter;
    quarter.addArc({0, 0, 100, 100}, 0, 90);
    CHECK(quarter.commands().front().verb == PathCommand::Verb::Move && at({quarter.commands().front().x, quarter.commands().front().y}, 100, 50));
    CHECK(at(end(quarter), 50, 100) && near(PathMeasure(quarter).length(), 3.14159f * 25, 0.3f));
    Path joined;  // joined by a line to where the arc starts, unless forced to move there
    joined.moveTo(0, 0);
    joined.arcTo({0, 0, 100, 100}, 180, 90, false);
    CHECK(joined.commands()[1].verb == PathCommand::Verb::Line && at(end(joined), 50, 0));
    Path moved;
    moved.moveTo(0, 0);
    moved.arcTo({0, 0, 100, 100}, 180, 90, true);
    CHECK(moved.commands()[1].verb == PathCommand::Verb::Move);
    Path back, wide, whole, oval;
    back.addArc({0, 0, 100, 100}, 0, -90);  // the other way: up to the top
    wide.addArc({0, 0, 200, 100}, 90, 270);  // three quarters of a wide oval, in three pieces
    whole.addArc({0, 0, 100, 100}, 30, 360);
    oval.addOval({0, 0, 100, 100});
    CHECK(at(end(back), 50, 0) && at(end(wide), 200, 50) && wide.commands().size() == 4 && whole == oval);
    CHECK(near(PathMeasure(wide).length(), 3 * PathMeasure(quarter).length() * 1.5f, 15));  // about 3/4 of a 200×100 oval
    // Relative curves, paths added and moved.
    Path curves;
    curves.moveTo(10, 10);
    curves.relativeQuadraticTo(10, 0, 10, 10);
    curves.relativeCubicTo(0, 10, 10, 10, 10, 0);
    CHECK(at({curves.commands()[1].x, curves.commands()[1].y}, 20, 20) && at(end(curves), 30, 20) && at({curves.commands()[2].x1, curves.commands()[2].y1}, 20, 30));
    Path square, two;
    square.addRect({0, 0, 10, 10});
    two.addPath(square, {5, 5});
    two.addPath(square, {20, 0});
    Rect b = two.bounds();
    CHECK(near(b.x, 5) && near(b.y, 0) && near(b.right(), 30) && near(b.bottom(), 15));
    square.translate({1, 2});
    CHECK(near(square.bounds().x, 1) && near(square.bounds().y, 2) && near(square.bounds().width, 10));
    curves.translate({5, -5});  // control points too
    CHECK(at({curves.commands()[1].x1, curves.commands()[1].y1}, 25, 5) && at({curves.commands()[2].x2, curves.commands()[2].y2}, 35, 25) &&
          at(end(curves), 35, 15));
    // Drawing: an oval; clipped to a triangle (in a layer, what is outside it erased — or inside);
    // transforms in order.
    Path triangle;
    triangle.moveTo(50, 20);
    triangle.lineTo(80, 80);
    triangle.lineTo(20, 80);
    triangle.close();
    ComposeTestRule rule([&] {
        Canvas(Modifier().size(100), [triangle](DrawScope& d) {
            d.drawOval(Color{1, 0, 0, 1}, {10, 10}, Size{80, 40});
            d.clipPath(triangle, [](DrawScope& in) { in.drawRect(Color{0, 0, 1, 1}); });
            d.clipPath(triangle, [](DrawScope& in) { in.drawRect(Color{0, 1, 0, 1}); }, ClipOp::Difference);
            d.withTransform([](DrawTransform& t) {
                t.translate(10, 20);
                t.rotate(45);
            }, [](DrawScope& in) { in.drawRect(colors::Black, {}, Size{10, 10}); });
            d.withTransform([](DrawTransform& t) {  // the clip inside the inset
                t.inset(10, 10, 10, 10);
                t.clipRect({0, 0}, Size{20, 20});
            }, [](DrawScope& in) { in.drawRect(colors::Black); });
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    // (The whole area but the triangle erased; then the triangle.)
    CHECK(canvas.paths.size() == 3 && sameRect(canvas.paths[0], {10, 10, 80, 40}) && sameRect(canvas.paths[1], {0, 0, 100, 100}) &&
          sameRect(canvas.paths[2], {20, 20, 60, 60}));
    CHECK((canvas.pathBlends == std::vector<BlendMode>{BlendMode::SrcOver, BlendMode::DstOut, BlendMode::DstOut}));
    CHECK(canvas.layerBounds.size() == 3 && canvas.translations.size() == 1 && near(canvas.translations[0].x, 10) &&
          near(canvas.translations[0].y, 20) && near(canvas.layerTransforms[2].rotationZ, 45));
    CHECK(!canvas.clips.empty() && sameRect(canvas.clips.back(), {10, 10, 20, 20}));
}

TEST(shadows_take_colors_and_clip_and_borders_take_brushes) {
    Color red{1, 0, 0, 1}, blue{0, 0, 1, 1};
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().size(100).shadow(8, RoundedCornerShape(16)));                     // as ever: no layer, black
            Box(Modifier().size(100).shadow(8, RoundedCornerShape(16), true, red, red));      // red, the content clipped
            Box(Modifier().size(100).shadow(8, RectangleShape, true, blue.copy(0.5f), blue.copy(0.5f)));  // fainter; a plain clip
            Box(Modifier().size(100).border(BorderStroke(2, red), RoundedCornerShape(10)));
            Box(Modifier().size(100).border(BorderStroke(4, Brush::linearGradient({red, blue})), RoundedCornerShape(10)));
        });
    }, {400, 800});
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    // Six shadow rects each.
    CHECK(canvas.rectColors.size() == 18);
    if (canvas.rectColors.size() == 18) {
        Color black = canvas.rectColors[0], tinted = canvas.rectColors[6], faint = canvas.rectColors[12];
        CHECK(black.r == 0 && black.b == 0 && tinted.r == 1 && tinted.g == 0 && near(tinted.a, black.a, 0.001f));
        CHECK(faint.b == 1 && near(faint.a, black.a / 2, 0.001f));
    }
    CHECK(canvas.layerBounds.size() == 1 && sameRect(canvas.layerBounds[0], {0, 100, 100, 100}) && near(canvas.layerCorners[0].topLeft, 16));
    CHECK(canvas.clips.size() == 1 && sameRect(canvas.clips[0], {0, 200, 100, 100}));
    // A colored border is a stroke; a brush's a path stroked half its width inside.
    CHECK(canvas.strokes.size() == 1 && canvas.strokeColors[0] == red);
    CHECK(canvas.paths.size() == 1 && sameRect(canvas.paths[0], {2, 402, 96, 96}));
}

TEST(z_index_puts_a_sibling_above_the_others) {
    auto z = mutableStateOf(1.f);
    std::vector<std::string> clicked;
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().size(200, 120), [&] {
                Box(Modifier().size(100, 100).zIndex(z.get()).clickable([&] { clicked.push_back("a"); }), [] { Text("a"); });
                Box(Modifier().size(100, 100).clickable([&] { clicked.push_back("b"); }), [] { Text("b"); });  // after: on top as composed
                Box(Modifier().size(100, 100).zIndex(-1).clickable([&] { clicked.push_back("c"); }), [] { Text("c"); });
            });
            // A layout's own placement order: y placed under x.
            Layout(Modifier(), [] { Text("x"); Text("y"); }, [](const std::vector<Measurable>& children, const Constraints& c) {
                Placeable x = children[0].measure(c.loosen()), y = children[1].measure(c.loosen());
                x.place(0, 0);
                y.place(0, 0, -1);
                return Size{std::max(x.width, y.width), std::max(x.height, y.height)};
            });
        });
    }, {400, 800});
    auto order = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        return canvas.texts;
    };
    CHECK((order() == std::vector<std::string>{"c", "b", "a", "y", "x"}));
    rule.host().pointerDown({50, 50});
    rule.host().pointerUp({50, 50});
    rule.waitForIdle();
    CHECK((clicked == std::vector<std::string>{"a"}));  // the one on top takes the touch
    z.set(0);  // back among the others in composition order
    rule.waitForIdle();
    CHECK((order() == std::vector<std::string>{"c", "a", "b", "y", "x"}));
    rule.host().pointerDown({50, 50});
    rule.host().pointerUp({50, 50});
    rule.waitForIdle();
    CHECK((clicked == std::vector<std::string>{"a", "b"}));
}

TEST(bottom_sheet_scaffold_peeks_expands_and_follows_drags) {
    SheetState sheet(SheetValue::PartiallyExpanded, false);  // may hide too
    std::optional<CoroutineScope> scope;
    PaddingValues seen;
    int contentClicks = 0;
    ComposeTestRule rule([&] {
        scope = rememberCoroutineScope();
        BottomSheetScaffold([] { Column(Modifier().fillMaxWidth().height(300), [] { Text("Ayrıntılar"); }); }, Modifier().fillMaxSize(),
                            {.scaffoldState = BottomSheetScaffoldState{sheet}, .sheetPeekHeight = 100}, [&](PaddingValues p) {
                                seen = p;
                                Box(Modifier().fillMaxSize().clickable([&] { ++contentClicks; }));
                            });
    }, {400, 800});
    // 48 of drag handle, then the content: 348 tall; 100 of it peeks out.
    auto top = [&] { return rule.onNodeWithText("Ayrıntılar").bounds().y - 48; };
    using V = SheetValue;
    CHECK(near(top(), 700) && sheet.currentValue() == V::PartiallyExpanded && near(seen.bottom, 100) && sheet.hasExpandedState());
    rule.host().pointerDown({200, 750});  // the sheet takes the touch, not the content under it
    rule.host().pointerUp({200, 750});
    rule.waitForIdle();
    CHECK(contentClicks == 0);
    auto run = [&](std::function<Task()> f) { scope->launch(std::move(f)); };
    run([sheet]() -> Task { co_await sheet.expand(); });
    for (int i = 0; i < 5; ++i) rule.advanceFrame();
    CHECK(top() < 700 && top() > 452 && sheet.targetValue() == V::Expanded && sheet.currentValue() == V::PartiallyExpanded);
    rule.waitForIdle();
    CHECK(near(top(), 452) && sheet.currentValue() == V::Expanded && near(sheet.requireOffset(), 452));
    run([sheet]() -> Task { co_await sheet.partialExpand(); });
    rule.waitForIdle();
    CHECK(near(top(), 700) && sheet.currentValue() == V::PartiallyExpanded);
    // Dragged up slowly and let go nearer the peek: back down; flung up: all the way.
    rule.host().pointerDown({200, 720});
    for (int i = 1; i <= 60; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({200, 720 - 100.f * float(i) / 60});
    }
    CHECK(top() > 599 && top() < 600 + ViewConfiguration{}.touchSlop + 2);  // it followed the finger
    rule.advanceFrame();
    rule.host().pointerUp({200, 620});
    rule.waitForIdle();
    CHECK(near(top(), 700) && sheet.currentValue() == V::PartiallyExpanded);
    rule.swipe({200, 720}, {200, 670}, 4);
    rule.waitForIdle();
    CHECK(near(top(), 452) && sheet.currentValue() == V::Expanded);
    rule.swipe({200, 470}, {200, 520}, 4);  // flung down: to the peek, not further
    rule.waitForIdle();
    CHECK(near(top(), 700) && sheet.currentValue() == V::PartiallyExpanded);
    rule.swipe({200, 720}, {200, 160}, 10);  // no higher than its height
    rule.advanceFrame();
    CHECK(top() >= 452 - 0.5f);
    rule.waitForIdle();
    run([sheet]() -> Task { co_await sheet.hide(); });
    rule.waitForIdle();
    CHECK(near(top(), 800) && sheet.currentValue() == V::Hidden && !sheet.isVisible());
}

TEST(bottom_sheet_scaffold_moves_before_the_list_in_it_scrolls) {
    SheetState sheet;
    LazyListState list;
    ComposeTestRule rule([&] {
        BottomSheetScaffold(
            [&] {
                LazyColumn(Modifier().fillMaxWidth().height(400), {.state = list}, [](LazyListScope& items) {
                    items.items(50, [](int i) { Box(Modifier().fillMaxWidth().height(40)); });
                });
            },
            Modifier().fillMaxSize(), {.scaffoldState = BottomSheetScaffoldState{sheet}, .sheetPeekHeight = 150}, [](PaddingValues) {});
    }, {400, 800});
    // 448 tall: peeks at 650, expanded at 352. Dragged up on the list: the sheet goes first...
    CHECK(near(sheet.requireOffset(), 650));
    rule.host().pointerDown({200, 760});
    for (int i = 1; i <= 20; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({200, 760 - 10.f * float(i)});
    }
    rule.advanceFrame();
    CHECK(sheet.requireOffset() > 449 && sheet.requireOffset() < 461 && list.firstVisibleItemScrollOffset() == 0);  // less the first step (to the slop)
    // ...all the way up, and then the list scrolls.
    for (int i = 21; i <= 40; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({200, 760 - 10.f * float(i)});
    }
    rule.advanceFrame();
    CHECK(near(sheet.requireOffset(), 352) && (list.firstVisibleItemIndex() > 0 || list.firstVisibleItemScrollOffset() > 50));
    for (int i = 0; i < 30; ++i) rule.advanceFrame();  // held still: no fling
    rule.host().pointerUp({200, 360});
    rule.waitForIdle();
    CHECK(sheet.currentValue() == SheetValue::Expanded);
    // Down: the list back to its top first, then the sheet comes down with it.
    list.scrollToItem(0);
    rule.waitForIdle();
    rule.swipe({200, 500}, {200, 700}, 60);
    rule.waitForIdle();
    CHECK(sheet.currentValue() == SheetValue::PartiallyExpanded && near(sheet.requireOffset(), 650));
}

TEST(bottom_sheet_scaffold_settles_with_the_flings_speed) {
    SheetState sheet;
    ComposeTestRule rule([&] {
        BottomSheetScaffold([] { Box(Modifier().fillMaxWidth().height(2000)); }, Modifier().fillMaxSize(),
                            {.scaffoldState = BottomSheetScaffoldState{sheet}, .sheetPeekHeight = 100}, [](PaddingValues) {});
    }, {400, 800});
    // Flung up 100 dp in 4 frames (1560 dp/s): it goes on at that speed, not from rest.
    rule.host().pointerDown({200, 720});
    for (int i = 1; i <= 4; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({200, 720 - 25.f * float(i)});
    }
    rule.host().pointerUp({200, 620});
    float released = sheet.requireOffset();
    rule.advanceFrame();
    rule.advanceFrame();
    float moved = released - sheet.requireOffset();
    // (Its first frame starts the clock: 16 ms of it.) From rest a spring (stiffness 400, ω 20)
    // goes x0·(1 − (1 + ωt)·e^(−ωt)); the fling adds about v·t·e^(−ωt) (18 dp) to it.
    float x0 = released, t = 0.016f, fromRest = x0 * (1 - (1 + 20 * t) * std::exp(-20 * t));
    CHECK(moved > fromRest + 12);
    rule.waitForIdle();
    CHECK(sheet.currentValue() == SheetValue::Expanded && near(sheet.requireOffset(), 0));  // and not past the top
}

TEST(bottom_sheet_scaffold_keeps_clear_of_the_system_bars_once) {
    SheetState sheet;
    auto inside = mutableStateOf(false);  // in a layout that already keeps clear of them
    PaddingValues seen;
    ComposeTestRule rule([&] {
        Modifier m = inside.get() ? Modifier().fillMaxSize().windowInsetsPadding(WindowInsets::systemBars()) : Modifier().fillMaxSize();
        Box(m, [&] {
            BottomSheetScaffold([] { Box(Modifier().fillMaxWidth().height(2000)); }, Modifier().fillMaxSize(),
                                {.scaffoldState = BottomSheetScaffoldState{sheet}, .sheetPeekHeight = 100},
                                [&](PaddingValues p) { seen = p; });
        });
    }, {400, 800});
    rule.host().setSystemInsets({.statusBars = {0, 24, 0, 0}, .navigationBars = {0, 0, 0, 48}});
    rule.waitForIdle();
    // 100 peeks out above the navigation bar; all the way up it stops under the status bar.
    CHECK(near(sheet.requireOffset(), 800 - 48 - 100) && near(seen.top, 24) && near(seen.bottom, 148));
    rule.swipe({200, 680}, {200, 600}, 4);
    rule.waitForIdle();
    CHECK(sheet.currentValue() == SheetValue::Expanded && near(sheet.requireOffset(), 24));
    inside.set(true);  // the bars are kept clear of around it: not again
    rule.waitForIdle();
    CHECK(near(seen.bottom, 100) && near(seen.top, 0) && near(sheet.requireOffset(), 0));
}

TEST(drag_and_drop_carries_data_from_a_source_to_a_target) {
    std::vector<std::string> log;
    auto fruits = mutableStateOf(std::vector<std::string>{"elma", "armut"});
    auto basket = mutableStateOf(std::vector<std::string>{});
    std::vector<HapticFeedbackType> felt;
    ComposeTestRule rule([&] {
        Column([&] {
            Row([&] {
                for (const std::string& name : fruits.get())
                    Box(Modifier()
                            .size(80, 40)
                            .dragAndDropSource([name](Offset) -> std::optional<DragAndDropTransferData> {
                                return DragAndDropTransferData{.text = name, .localState = name};
                            })
                            .clickable([&log, name] { log.push_back("click " + name); }),
                        [&] { Text(name); });
            });
            Box(Modifier().fillMaxWidth().height(100));
            Box(Modifier().fillMaxWidth().height(150).dragAndDropTarget(
                [&](const DragAndDropEvent& e) {
                    log.push_back("should " + e.text());
                    return e.hasMimeType("text/plain");
                },
                {.onDrop =
                     [&](const DragAndDropEvent& e) {
                         log.push_back(std::format("drop {} at {:.0f},{:.0f}", *e.localState<std::string>(), e.position.x, e.position.y));
                         std::vector<std::string> left = fruits.peek(), in = basket.peek();
                         std::erase(left, e.text());
                         in.push_back(e.text());
                         fruits.set(left);
                         basket.set(in);
                         return true;
                     },
                 .onStarted = [&](const DragAndDropEvent&) { log.push_back("started"); },
                 .onEntered = [&](const DragAndDropEvent&) { log.push_back("entered"); },
                 .onExited = [&](const DragAndDropEvent&) { log.push_back("exited"); },
                 .onEnded = [&](const DragAndDropEvent& e) { log.push_back(e.accepted ? "ended taken" : "ended"); }}));
            Box(Modifier().fillMaxWidth().height(100).dragAndDropTarget([](const DragAndDropEvent&) { return false; },
                                                                       {.onStarted = [&](const DragAndDropEvent&) { log.push_back("never"); }}));
        });
    }, {400, 800});
    rule.host().setCallbacks({.hapticFeedback = [&](HapticFeedbackType t) { felt.push_back(t); }});
    auto moveTo = [&](Offset from, Offset to) {
        for (int i = 1; i <= 8; ++i) {
            rule.advanceFrame();
            rule.host().pointerMove({from.x + (to.x - from.x) * float(i) / 8, from.y + (to.y - from.y) * float(i) / 8});
        }
    };
    // A tap still clicks.
    rule.host().pointerDown({40, 20});
    rule.host().pointerUp({40, 20});
    rule.waitForIdle();
    CHECK((log == std::vector<std::string>{"click elma"}));
    log.clear();
    // A finger holds the apple, then takes it to the basket (140..290 down).
    rule.host().pointerDown({40, 20});
    rule.advanceTimeBy(500);
    CHECK((log == std::vector<std::string>{"should elma", "started"}) && felt.size() == 1);
    moveTo({40, 20}, {200, 215});
    CHECK(!log.empty() && log.back() == "entered");
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(std::count(canvas.texts.begin(), canvas.texts.end(), "elma") == 2);  // and its faded copy under the finger
    CHECK(std::find(canvas.layerAlphas.begin(), canvas.layerAlphas.end(), 0.75f) != canvas.layerAlphas.end());
    rule.host().pointerUp({200, 215});
    rule.waitForIdle();
    CHECK((log == std::vector<std::string>{"should elma", "started", "entered", "drop elma at 200,75", "ended taken"}));
    CHECK(basket.peek() == std::vector<std::string>{"elma"} && fruits.peek() == std::vector<std::string>{"armut"});
    // Taken out again and let go elsewhere: no drop, and no click.
    log.clear();
    rule.host().pointerDown({40, 20});  // the pear is first now
    rule.advanceTimeBy(500);
    moveTo({40, 20}, {200, 215});
    moveTo({200, 215}, {200, 60});
    rule.host().pointerUp({200, 60});
    rule.waitForIdle();
    CHECK((log == std::vector<std::string>{"should armut", "started", "entered", "exited", "ended"}));
    // The mouse just drags; Escape calls it off.
    log.clear();
    rule.host().pointerDown({40, 20}, -1, 0, ComposeHost::PointerType::Mouse);
    moveTo({40, 20}, {200, 215});
    CHECK(log.size() == 3 && log[1] == "started" && log[2] == "entered");
    rule.host().keyDown(Key::Escape);
    rule.host().pointerUp({200, 215});
    rule.waitForIdle();
    CHECK((log == std::vector<std::string>{"should armut", "started", "entered", "exited", "ended"}) && fruits.peek().size() == 1);
    // A finger that moves before holding long enough doesn't drag.
    log.clear();
    rule.host().pointerDown({40, 20});
    moveTo({40, 20}, {40, 120});
    rule.advanceTimeBy(500);
    rule.host().pointerUp({40, 120});
    rule.waitForIdle();
    CHECK(log.empty());
}

TEST(drops_from_outside_the_app_reach_the_targets) {
    std::vector<std::string> log;
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().fillMaxWidth().height(200).dragAndDropTarget(
                [&](const DragAndDropEvent& e) {
                    log.push_back(std::format("should {}", e.hasMimeType("text/uri-list")));
                    return e.hasMimeType("text/uri-list");
                },
                {.onDrop =
                     [&](const DragAndDropEvent& e) {
                         log.push_back(std::format("drop {} at {:.0f},{:.0f}", e.data->files.empty() ? e.text() : e.data->files[0], e.position.x,
                                                   e.position.y));
                         return !e.data->files.empty();
                     },
                 .onEntered = [&](const DragAndDropEvent&) { log.push_back("entered"); },
                 .onExited = [&](const DragAndDropEvent&) { log.push_back("exited"); },
                 .onEnded = [&](const DragAndDropEvent& e) { log.push_back(e.accepted ? "ended taken" : "ended"); }}));
            // Only for drags within the app (they carry a localState).
            Box(Modifier().fillMaxWidth().height(200).dragAndDropTarget([](const DragAndDropEvent& e) { return e.data->localState.has_value(); },
                                                                       {.onStarted = [&](const DragAndDropEvent&) { log.push_back("never"); }}));
        });
    }, {400, 800});
    ComposeHost& host = rule.host();
    host.externalDragEntered({"text/uri-list", "text/plain"});  // what it may be: told what it is at the drop
    host.externalDragMoved({100, 300});
    host.externalDragMoved({100, 50});
    host.externalDrop({.text = "file:///tmp/a%20b.png\r\n", .mimeTypes = {"text/uri-list"}, .files = {"/tmp/a b.png"}}, {100, 60});
    rule.waitForIdle();
    CHECK((log == std::vector<std::string>{"should true", "entered", "drop /tmp/a b.png at 100,60", "ended taken"}));
    log.clear();  // brought over and taken away again
    host.externalDragEntered({"text/uri-list", "text/plain"});
    host.externalDragMoved({100, 50});
    host.externalDragLeft();
    CHECK((log == std::vector<std::string>{"should true", "entered", "exited", "ended"}));
    log.clear();  // text dropped where nothing said where it was: the target asks again, by what it is
    host.externalDrop({.text = "merhaba", .mimeTypes = {"text/plain"}}, {100, 50});
    CHECK((log == std::vector<std::string>{"should false"}));
}

TEST(window_size_classes_and_the_navigation_they_suit) {
    using W = WindowWidthSizeClass;
    using H = WindowHeightSizeClass;
    WindowSizeClass phone = WindowSizeClass::compute(400, 800);
    CHECK(phone.windowWidthSizeClass == W::Compact && phone.windowHeightSizeClass == H::Medium);
    CHECK(phone.isHeightAtLeastBreakpoint(HEIGHT_DP_MEDIUM_LOWER_BOUND) && !phone.isWidthAtLeastBreakpoint(WIDTH_DP_MEDIUM_LOWER_BOUND));
    CHECK(WindowSizeClass::compute(700, 1000).windowWidthSizeClass == W::Medium && WindowSizeClass::compute(700, 1000).windowHeightSizeClass == H::Expanded);
    CHECK(WindowSizeClass::compute(600, 480).windowWidthSizeClass == W::Medium && WindowSizeClass::compute(599.5f, 479).windowHeightSizeClass == H::Compact);
    CHECK(WindowSizeClass::compute(840, 900).windowWidthSizeClass == W::Expanded && WindowSizeClass::compute(840, 900).minHeightDp == 900);
    auto suits = [](float w, float h) { return NavigationSuiteScaffoldDefaults::calculateFromAdaptiveInfo({WindowSizeClass::compute(w, h)}); };
    CHECK(suits(400, 800) == NavigationSuiteType::NavigationBar && suits(700, 1000) == NavigationSuiteType::NavigationRail);
    CHECK(suits(1280, 800) == NavigationSuiteType::NavigationRail && suits(900, 400) == NavigationSuiteType::NavigationBar);  // a phone on its side
}

TEST(navigation_suite_scaffold_moves_its_items_and_keeps_the_screen) {
    auto tab = mutableStateOf(0);
    auto forced = mutableStateOf(std::optional<NavigationSuiteType>{});
    PaddingValues seen;
    ComposeTestRule rule([&] {
        NavigationSuiteScaffold(
            [&](NavigationSuiteScope& nav) {
                nav.item(tab.get() == 0, [&] { tab.set(0); }, Icons::Filled::Home, "Ev");
                nav.item(tab.get() == 1, [&] { tab.set(1); }, Icons::Filled::Settings, "Ayarlar");
            },
            Modifier().fillMaxSize(), {.layoutType = forced.get()}, [&] {
                Scaffold(Modifier().fillMaxSize(), {}, [&](PaddingValues p) {
                    seen = p;
                    auto count = remember([] { return mutableStateOf(0); });
                    Box(Modifier().fillMaxSize().padding(p).consumeWindowInsets(p).imePadding(), [&] {
                        Box(Modifier().fillMaxSize().testTag("ekran"));
                        TextButton([count] { count.set(count.peek() + 1); }, Modifier().testTag("sayac"), {},
                                   [&] { Text(std::format("sayaç {}", count.get())); });
                    });
                });
            });
    }, {400, 800});
    rule.host().setSystemInsets({.statusBars = {0, 24, 0, 0}, .navigationBars = {0, 0, 0, 48}});
    rule.waitForIdle();
    // Compact: a bar at the bottom; the screen's Scaffold pads by the status bar only (the bar
    // already keeps clear of the navigation bar).
    CHECK(rule.onNodeWithText("Ev").bounds().y > 650 && near(seen.top, 24) && near(seen.bottom, 0));
    rule.onNodeWithText("Ayarlar").performClick();
    CHECK(tab.peek() == 1);
    rule.onNodeWithTag("sayac").performClick();
    CHECK(rule.onNodeWithText("sayaç 1").exists());
    // The keyboard up: the screen ends at its top, the bar (under it) leaving no gap above it.
    CHECK(near(rule.onNodeWithTag("ekran").bounds().bottom(), 800 - 80 - 48));
    rule.host().setSystemInsets({.statusBars = {0, 24, 0, 0}, .navigationBars = {0, 0, 0, 48}, .ime = {0, 0, 0, 300}});
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("ekran").bounds().bottom(), 800 - 300));
    rule.host().setSystemInsets({.statusBars = {0, 24, 0, 0}, .navigationBars = {0, 0, 0, 48}, .ime = {0, 0, 0, 100}});  // lower than the bar: nothing
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("ekran").bounds().bottom(), 800 - 80 - 48));
    rule.host().setSystemInsets({.statusBars = {0, 24, 0, 0}, .navigationBars = {0, 0, 0, 48}});
    // Wider: a rail at the start, the screen beside it, still where it was.
    rule.host().setViewportSize({1000, 800});
    rule.waitForIdle();
    Rect home = rule.onNodeWithText("Ev").bounds();
    CHECK(home.x < 80 && home.y < 300 && rule.onNodeWithText("sayaç 1").exists());
    CHECK(rule.onNodeWithTag("sayac").bounds().x >= 80 && near(seen.bottom, 48));  // the rail doesn't keep clear of the bottom
    forced.set(NavigationSuiteType::NavigationDrawer);  // asked for: a drawer
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("sayac").bounds().x > 250 && rule.onNodeWithText("sayaç 1").exists() && rule.onNodeWithText("Ayarlar").exists());
    forced.set(NavigationSuiteType::None);
    rule.waitForIdle();
    CHECK(!rule.onNodeWithText("Ayarlar").exists() && near(rule.onNodeWithTag("sayac").bounds().x, 0) && rule.onNodeWithText("sayaç 1").exists());
}

TEST(navigation_suite_types_as_compose_1_4) {
    auto info = [](float w, float h, Posture posture = Posture::Flat) { return WindowAdaptiveInfo{WindowSizeClass::compute(w, h), posture}; };
    using T = NavigationSuiteType;
    namespace D = NavigationSuiteScaffoldDefaults;
    CHECK(D::navigationSuiteType(info(400, 800)) == T::ShortNavigationBarCompact);
    CHECK(D::navigationSuiteType(info(900, 400)) == T::ShortNavigationBarMedium);  // a phone on its side
    CHECK(D::navigationSuiteType(info(700, 1000, Posture::Tabletop)) == T::ShortNavigationBarMedium);
    CHECK(D::navigationSuiteType(info(1000, 800)) == T::WideNavigationRailCollapsed && D::navigationSuiteType(info(700, 1000)) == T::WideNavigationRailCollapsed);
    CHECK(D::calculateFromAdaptiveInfo(info(700, 1000, Posture::Tabletop)) == T::NavigationBar && D::calculateFromAdaptiveInfo(info(700, 1000)) == T::NavigationRail);
    // The window's posture comes from the host.
    std::optional<WindowAdaptiveInfo> seen;
    ComposeTestRule rule([&] { seen = currentWindowAdaptiveInfo(); }, {700, 1000});
    CHECK(seen && seen->windowPosture == Posture::Flat);
    rule.host().setMediaInfo({.windowPosture = Posture::Tabletop});
    rule.waitForIdle();
    CHECK(seen && seen->windowPosture == Posture::Tabletop);
}

TEST(navigation_suite_scaffold_with_its_own_items_a_primary_action_and_hiding) {
    auto tab = mutableStateOf(0);
    std::optional<NavigationSuiteScaffoldState> state;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        auto s = rememberNavigationSuiteScaffoldState();
        state = s;
        scope = rememberCoroutineScope();
        NavigationSuiteScaffold(
            [&] {
                NavigationSuiteItem(tab.get() == 0, [&] { tab.set(0); }, [] { Icon(Icons::Filled::Home, ""); }, [] { Text("Ev"); });
                NavigationSuiteItem(tab.get() == 1, [&] { tab.set(1); }, [] { Icon(Icons::Filled::Settings, ""); }, [] { Text("Ayarlar"); },
                                    Modifier(), {.badge = [] { Badge(Modifier(), [] { Text("3"); }); }});
            },
            Modifier().fillMaxSize(),
            {.state = s, .primaryActionContent = [] { Box(Modifier().size(56).testTag("eylem")); }},
            [&] { Box(Modifier().fillMaxSize().testTag("ekran")); });
    }, {400, 800});
    // Compact: a short bar (64 dp) at the bottom, its icons above the labels; the action above
    // its end, 16 dp in; the screen above the bar.
    Rect home = rule.onNodeWithText("Ev").bounds(), screen = rule.onNodeWithTag("ekran").bounds(), action = rule.onNodeWithTag("eylem").bounds();
    CHECK(near(screen.height, 800 - 64) && home.y > 736 && rule.onNodeWithText("3").exists());
    CHECK(near(action.x, 400 - 16 - 56) && near(action.y, 800 - 64 - 16 - 56));
    rule.onNodeWithText("Ayarlar").performClick();
    CHECK(tab.peek() == 1);
    // Hidden: the bar slides down, the screen takes its room (the action comes down with it).
    CHECK(state->currentValue() == NavigationSuiteScaffoldValue::Visible);
    scope->launch([s = *state]() -> Task { co_await s.hide(); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(state->targetValue() == NavigationSuiteScaffoldValue::Hidden && state->currentValue() == NavigationSuiteScaffoldValue::Hidden &&
          state->isAnimating());
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("ekran").bounds().height, 800) && rule.onNodeWithText("Ev").bounds().y >= 800 &&
          near(rule.onNodeWithTag("eylem").bounds().y, 800 - 16 - 56));
    scope->launch([s = *state]() -> Task { co_await s.show(); });
    rule.advanceFrame();
    rule.advanceFrame();  // on its way in: still Hidden until all the way
    CHECK(state->targetValue() == NavigationSuiteScaffoldValue::Visible && state->currentValue() == NavigationSuiteScaffoldValue::Hidden);
    state->snapTo(NavigationSuiteScaffoldValue::Visible);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("ekran").bounds().height, 800 - 64) && state->currentValue() == NavigationSuiteScaffoldValue::Visible);
    // Wider: a collapsed wide rail (96 dp) at the start, the action at its top, the screen beside it.
    rule.host().setViewportSize({1000, 800});
    rule.waitForIdle();
    home = rule.onNodeWithText("Ev").bounds(), screen = rule.onNodeWithTag("ekran").bounds(), action = rule.onNodeWithTag("eylem").bounds();
    CHECK(near(screen.x, 96) && near(screen.width, 1000 - 96) && home.x < 96 && action.x < 96 && action.y < home.y);
    CHECK(rule.onAllNodesWithTag("eylem").size() == 1);  // in the rail only
    scope->launch([s = *state]() -> Task { co_await s.toggle(); });  // hidden: out to the start
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("ekran").bounds().x, 0) && rule.onNodeWithText("Ev").bounds().right() <= 0.5f);
}

