TEST(tri_state_checkbox_shows_a_partly_checked_group) {
    auto a = mutableStateOf(false), b = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            ToggleableState all = a.get() && b.get() ? ToggleableState::On : a.get() || b.get() ? ToggleableState::Indeterminate : ToggleableState::Off;
            TriStateCheckbox(all, [&a, &b, all] {
                bool on = all != ToggleableState::On;  // partly or not at all: all of them
                a.set(on);
                b.set(on);
            }, Modifier().testTag("hepsi"));
            Checkbox(a.get(), [&a](bool v) { a.set(v); }, Modifier().testTag("a"));
            Checkbox(b.get(), [&b](bool v) { b.set(v); }, Modifier().testTag("b"));
        });
    }, {400, 800});
    CHECK(rule.onAllNodesWithText("unchecked").size() == 3);
    rule.onNodeWithTag("a").performClick();
    CHECK(rule.onNodeWithText("indeterminate").exists() && rule.onAllNodesWithText("checked").size() == 1);
    rule.onNodeWithTag("hepsi").performClick();
    CHECK(a.peek() && b.peek() && rule.onAllNodesWithText("checked").size() == 3);
    rule.onNodeWithTag("hepsi").performClick();
    CHECK(!a.peek() && !b.peek() && rule.onAllNodesWithText("unchecked").size() == 3);
}

TEST(auto_size_text_takes_the_largest_size_that_fits) {
    // FakeTextMeasurer: half the size per character, lines 1.25 times the size.
    ComposeTestRule rule([&] {
        Column([&] {
            Text("Merhaba", Modifier().size(200, 40), {.autoSize = TextAutoSize::StepBased(8, 64, 1)});       // the height decides: 32
            Text("Merhaba", Modifier().width(100), {.maxLines = 1, .autoSize = TextAutoSize::StepBased(8, 64, 1)});  // the width: 28
            Text("Merhaba", Modifier().width(10), {.maxLines = 1, .autoSize = TextAutoSize::StepBased(8, 64, 1)});   // nothing fits: the smallest
            Text("Merhaba", Modifier().size(400, 400), {.autoSize = TextAutoSize::StepBased(8, 64, 1)});      // room for the largest
        });
    }, {400, 800});
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    std::vector<float> sizes;
    for (size_t i = 0; i < canvas.texts.size(); ++i)
        if (canvas.texts[i].starts_with("Me")) sizes.push_back(canvas.fonts[i].size);  // (the one that doesn't fit is cut)
    CHECK(sizes.size() == 4 && near(sizes[0], 32) && near(sizes[1], 28) && near(sizes[2], 8) && near(sizes[3], 64));
}

TEST(subcompose_layout_composes_slots_from_what_it_measured) {
    auto title = mutableStateOf(std::string("Başlık metni"));
    auto log = std::make_shared<std::vector<std::string>>();
    ComposeTestRule rule([&] {
        Column([&] {
            // A slot that depends on another's size: a line as wide as the title (8 dp a character).
            SubcomposeLayout(Modifier(), [title](SubcomposeMeasureScope& s, const Constraints& c) {
                float w = 0, h = 0;
                for (const Measurable& m : s.subcompose(std::string("ana"), [title] { Text(title.get()); })) {
                    Placeable p = m.measure(c.loosen());
                    p.place(0, 0);
                    w = std::max(w, p.width);
                    h = std::max(h, p.height);
                }
                for (const Measurable& m : s.subcompose(std::string("rozet"), w, [w] { Text(std::format("genişlik {:.0f}", w)); })) {
                    Placeable p = m.measure(c.loosen());
                    p.place(0, h);
                    h += p.height;
                }
                return Size{w, h};
            });
            // Picked by the constraints, as BoxWithConstraints does; a slot keeps its state.
            SubcomposeLayout(Modifier().fillMaxWidth(), [log](SubcomposeMeasureScope& s, const Constraints& c) {
                bool wide = c.maxWidth >= 500;
                Size size{c.maxWidth, 0};
                for (const Measurable& m : s.subcompose(std::string(wide ? "geniş" : "dar"), [wide, log] {
                         auto taps = remember([] { return mutableStateOf(0); });
                         DisposableEffect(0, [wide, log]() -> std::function<void()> {
                             log->push_back(wide ? "+geniş" : "+dar");
                             return [wide, log] { log->push_back(wide ? "-geniş" : "-dar"); };
                         });
                         TextButton([taps] { taps.set(taps.peek() + 1); }, [&] { Text(std::format("{} düzen {}", wide ? "geniş" : "dar", taps.get())); });
                     })) {
                    Placeable p = m.measure(c.loosen());
                    p.place(0, 0);
                    size.height = std::max(size.height, p.height);
                }
                return size;
            });
        });
    }, {400, 800});
    CHECK(rule.onNodeWithText("Başlık metni").exists() && rule.onNodeWithText("genişlik 96").exists());
    CHECK(near(rule.onNodeWithText("genişlik 96").bounds().y, 20));  // under the title
    CHECK(rule.onNodeWithText("dar düzen 0").exists() && !rule.onNodeWithText("geniş düzen 0").exists());
    title.set("Kısa");  // the title is narrower: the line that depends on it is composed again
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("genişlik 32").exists() && !rule.onNodeWithText("genişlik 96").exists());
    rule.onNodeWithText("dar düzen 0").performClick();
    rule.host().setViewportSize({450, 800});  // measured again, the same slot: its state stays
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("dar düzen 1").exists());
    rule.host().setViewportSize({600, 800});  // wide: the other slot, the first one goes
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("geniş düzen 0").exists() && !rule.onNodeWithText("dar düzen 1").exists());
    CHECK((*log == std::vector<std::string>{"+dar", "-dar", "+geniş"}));
}

TEST(subcompose_layout_is_not_composed_again_for_a_probe_measure) {
    // width(IntrinsicSize::Max) measures its content first only to learn its natural width, with
    // no width limit: the slot that measure would pick isn't composed for it (or the two measures
    // would take turns composing every frame).
    auto runs = std::make_shared<int>(0);
    ComposeTestRule rule([&] {
        Column(Modifier().width(IntrinsicSize::Max), [&] {
            SubcomposeLayout(Modifier(), [runs](SubcomposeMeasureScope& s, const Constraints& c) {
                bool wide = c.maxWidth >= 500;  // a probe measure gets infinity: wide
                Size size{c.hasBoundedWidth() ? c.maxWidth : 100, 0};
                for (const Measurable& m : s.subcompose(std::string(wide ? "geniş" : "dar"), [wide, runs] {
                         ++*runs;
                         Text(wide ? "geniş" : "dar");
                     })) {
                    Placeable p = m.measure(c.loosen());
                    p.place(0, 0);
                    size.height = std::max(size.height, p.height);
                }
                return size;
            });
        });
    }, {400, 800});
    rule.waitForIdle();
    int settled = *runs;
    for (int i = 0; i < 5; ++i) rule.advanceFrame();
    CHECK(rule.onNodeWithText("dar").exists() && !rule.onNodeWithText("geniş").exists() && *runs == settled && !rule.host().hasPendingWork());
}

TEST(swipe_to_dismiss_confirms_or_springs_back) {
    auto confirmed = std::make_shared<std::vector<SwipeToDismissBoxValue>>();
    auto allow = std::make_shared<bool>(true);
    std::optional<SwipeToDismissBoxState> state;
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] {
        scope = rememberCoroutineScope();
        auto s = rememberSwipeToDismissBoxState([confirmed, allow](SwipeToDismissBoxValue v) {
            confirmed->push_back(v);
            return *allow;
        });
        state = s;
        SwipeToDismissBox(s, [] { Box(Modifier().fillMaxSize().testTag("background")); },
                          [] { Box(Modifier().fillMaxWidth().height(60).testTag("row")); });
    }, {400, 800});
    CHECK(!rule.onNodeWithTag("background").exists());  // covered at rest: not composed
    rule.host().pointerDown({300, 30});
    rule.host().pointerMove({280, 30});
    rule.waitForIdle();
    CHECK(sameRect(rule.onNodeWithTag("background").bounds(), {0, 0, 400, 60}));  // while dragged, the content's size
    rule.host().pointerUp({280, 30});
    rule.waitForIdle();
    rule.swipe({300, 30}, {220, 30}, 60);  // 80 of 400, slowly: not far enough
    rule.waitForIdle();
    CHECK(confirmed->empty() && near(rule.onNodeWithTag("row").node()->contentBounds().x, 0));
    rule.host().pointerDown({300, 30});  // far, then flung back: back in place, without asking
    for (int i = 1; i <= 20; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({300 - 12.f * float(i), 30});
    }
    for (int i = 1; i <= 3; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({60 + 20.f * float(i), 30});
    }
    rule.host().pointerUp({120, 30});
    rule.waitForIdle();
    CHECK(confirmed->empty() && near(rule.onNodeWithTag("row").node()->contentBounds().x, 0));
    *allow = false;
    rule.swipe({300, 30}, {60, 30}, 20);  // far, but refused
    rule.waitForIdle();
    CHECK(confirmed->size() == 1 && state->currentValue() == SwipeToDismissBoxValue::Settled);
    *allow = true;
    rule.swipe({300, 30}, {60, 30}, 20);
    rule.waitForIdle();
    CHECK(confirmed->size() == 2 && confirmed->back() == SwipeToDismissBoxValue::EndToStart);
    CHECK(state->currentValue() == SwipeToDismissBoxValue::EndToStart && near(state->progress(), 1));
    // A short flick (60 of 400) away is enough, as in Compose (125 dp/s).
    scope->launch([s = *state]() -> Task { co_await s.reset(); });
    rule.waitForIdle();
    rule.swipe({100, 30}, {160, 30}, 4);
    rule.waitForIdle();
    CHECK(confirmed->size() == 3 && confirmed->back() == SwipeToDismissBoxValue::StartToEnd &&
          state->currentValue() == SwipeToDismissBoxValue::StartToEnd && near(state->progress(), 1));
}

TEST(draggable_reports_deltas_with_the_latest_callback) {
    auto total = mutableStateOf(0.f);
    auto stops = std::make_shared<int>(0);
    ComposeTestRule rule([&] {
        auto drag = rememberDraggableState([total](float d) { total.set(total.peek() + d); }, [stops] { ++*stops; });
        Box(Modifier().size(200, 100).draggable(drag, Orientation::Horizontal));
    });
    rule.swipe({20, 50}, {120, 50}, 10);
    rule.waitForIdle();
    CHECK(near(total.peek(), 100 - ViewConfiguration{}.touchSlop) && *stops == 1);
}

TEST(draggable_flings_a_node_that_moves_with_the_finger) {
    auto x = mutableStateOf(0.f);
    float velocity = 0;
    ComposeTestRule rule([&] {
        auto drag = rememberDraggableState([x](float d) { x.set(x.peek() + d); }, [&](float v) { velocity = v; });
        Box(Modifier().offset([x] { return Offset{x.get(), 0}; }).size(40, 40).draggable(drag, Orientation::Horizontal));
    }, {400, 400});
    // The node follows the finger, so the pointer hardly moves over it: the drag's travel counts.
    rule.swipe({20, 20}, {80, 20}, 3);
    rule.waitForIdle();
    CHECK(near(x.peek(), 60 - ViewConfiguration{}.touchSlop) && velocity > 600);
    rule.swipe({x.peek() + 20, 20}, {x.peek() - 40, 20}, 3);
    CHECK(velocity < -600);
}

TEST(draggable2d_drags_any_way_from_the_slop_or_at_once) {
    auto at = mutableStateOf(Offset{}), back = mutableStateOf(Offset{}), now = mutableStateOf(Offset{});
    auto add = [](MutableState<Offset> s) { return [s](Offset d) { s.set({s.peek().x + d.x, s.peek().y + d.y}); }; };
    Offset started{-1, -1};
    std::optional<Velocity> stopped;
    std::optional<Draggable2DState> code;
    MutableInteractionSource source;
    bool dragged = false;
    ComposeTestRule rule([&] {
        auto state = rememberDraggable2DState(add(at));
        code = state;
        auto reversed = rememberDraggable2DState(add(back));
        auto immediate = rememberDraggable2DState(add(now));
        dragged = source.collectIsDraggedAsState();
        Column([&] {
            Box(Modifier().size(200).draggable2D(state, {.interactionSource = source,
                                                         .onDragStarted = [&](Offset p) { started = p; },
                                                         .onDragStopped = [&](Velocity v) { stopped = v; }}));
            Box(Modifier().size(200).draggable2D(reversed, {.reverseDirection = true}));
            Box(Modifier().size(100).draggable2D(immediate, {.startDragImmediately = true}));
        });
    }, {400, 800});
    // Diagonally, 50 dp (40 across, 30 down): what is past the touch slop, along the drag.
    rule.swipe({50, 50}, {90, 80}, 10);
    rule.waitForIdle();
    float keep = (50 - ViewConfiguration{}.touchSlop) / 50;
    CHECK(near(at.peek().x, 40 * keep) && near(at.peek().y, 30 * keep));
    CHECK(near(started.x, 50) && near(started.y, 50));  // where the finger went down
    CHECK(stopped && stopped->x > 100 && near(stopped->y, stopped->x * 0.75f, 1));  // the way it went
    rule.swipe({50, 250}, {90, 280}, 10);  // reversed: the other way
    rule.waitForIdle();
    CHECK(near(back.peek().x, -40 * keep) && near(back.peek().y, -30 * keep));
    // Told to the interaction source while dragging.
    rule.host().pointerDown({100, 100});
    rule.advanceFrame();
    rule.host().pointerMove({130, 130});
    rule.waitForIdle();
    CHECK(dragged);
    rule.host().pointerUp({130, 130});
    rule.waitForIdle();
    CHECK(!dragged);
    // At once: a move under the touch slop already counts.
    rule.host().pointerDown({50, 450});
    rule.advanceFrame();
    rule.host().pointerMove({53, 452});
    rule.waitForIdle();
    CHECK(near(now.peek().x, 3) && near(now.peek().y, 2));
    rule.host().pointerUp({53, 452});
    rule.waitForIdle();
    Offset before = at.peek();
    code->dispatchRawDelta({5, -5});  // from code, as a drag would
    CHECK(near(at.peek().x, before.x + 5) && near(at.peek().y, before.y - 5));
}

TEST(draggable2d_keeps_its_drag_from_the_scroll_around_it) {
    auto at = mutableStateOf(Offset{}), now = mutableStateOf(Offset{});
    ScrollState scroll;
    ComposeTestRule rule([&] {
        auto state = rememberDraggable2DState([at](Offset d) { at.set({at.peek().x + d.x, at.peek().y + d.y}); });
        auto immediate = rememberDraggable2DState([now](Offset d) { now.set({now.peek().x + d.x, now.peek().y + d.y}); });
        Column(Modifier().fillMaxSize().verticalScroll(scroll), [&] {
            Box(Modifier().size(200).draggable2D(state));
            Box(Modifier().size(200).draggable2D(immediate, {.startDragImmediately = true}));
            Box(Modifier().fillMaxWidth().height(2000));
        });
    }, {400, 800});
    rule.swipe({100, 150}, {100, 50}, 10);  // up, on the draggable: it is the drag's, the page stays
    rule.waitForIdle();
    CHECK(near(at.peek().y, -(100 - ViewConfiguration{}.touchSlop)) && near(scroll.value(), 0));
    rule.swipe({100, 350}, {100, 250}, 10);  // the same at once
    rule.waitForIdle();
    CHECK(near(now.peek().y, -100) && near(scroll.value(), 0));
    rule.swipe({100, 600}, {100, 400}, 10);  // off it the page scrolls
    rule.waitForIdle();
    CHECK(scroll.value() > 100);
}

TEST(scrollable2d_drags_flings_and_wheels_both_ways) {
    // The content moves with the finger, within [-1000, 0] across and [-300, 0] down; the box
    // is in a page that scrolls.
    auto pan = mutableStateOf(Offset{});
    std::optional<Scrollable2DState> scrolled;
    ScrollState page;
    ComposeTestRule rule([&] {
        auto state = rememberScrollable2DState([pan](Offset d) {
            Offset p = pan.peek(), to{std::clamp(p.x + d.x, -1000.f, 0.f), std::clamp(p.y + d.y, -300.f, 0.f)};
            pan.set(to);
            return Offset{to.x - p.x, to.y - p.y};
        });
        scrolled = state;
        Column(Modifier().fillMaxSize().verticalScroll(page), [&] {
            Box(Modifier().size(300).scrollable2D(state));
            Box(Modifier().fillMaxWidth().height(2000));
        });
    }, {400, 800});
    // Up and left, 128 dp: what is past the touch slop, along the drag.
    rule.host().pointerDown({250, 250});
    for (int i = 1; i <= 10; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({250 - 10.f * float(i), 250 - 8.f * float(i)});
    }
    float keep = (std::hypot(100.f, 80.f) - ViewConfiguration{}.touchSlop) / std::hypot(100.f, 80.f);
    CHECK(near(pan.peek().x, -100 * keep) && near(pan.peek().y, -80 * keep) && scrolled->isScrollInProgress());
    rule.host().pointerUp({150, 170});
    rule.advanceFrame();
    CHECK(scrolled->isScrollInProgress());  // flinging on
    rule.advanceTimeBy(3000);
    rule.waitForIdle();
    Offset flung = pan.peek();
    CHECK(flung.x < -100 * keep - 20 && flung.y < -80 * keep - 20 && near(flung.y / flung.x, 0.8f, 0.05f) && !scrolled->isScrollInProgress());
    CHECK(near(page.value(), 0));  // the gesture was the box's
    // Mostly down a lot: the fling reaches the top end (-300) and goes on across alone.
    rule.swipe({200, 290}, {170, 10}, 6);
    rule.advanceTimeBy(3000);
    rule.waitForIdle();
    CHECK(near(pan.peek().y, -300) && pan.peek().x < flung.x - 40);
    // Into the corner: both ends reached, the fling is over at once.
    scrolled->dispatchRawDelta({-1000, -300});
    rule.swipe({100, 100}, {60, 60}, 3);
    rule.advanceTimeBy(100);
    CHECK(!scrolled->isScrollInProgress());
    // A press stops a fling.
    scrolled->dispatchRawDelta({1000, 300});  // back to the start
    rule.swipe({100, 200}, {50, 200}, 4);
    Offset released = pan.peek();
    rule.host().pointerDown({150, 150});
    rule.advanceTimeBy(1000);
    CHECK(pan.peek().x < 0 && near(pan.peek().x, released.x, 30));  // it stopped about where it was let go
    rule.host().pointerUp({150, 150});
    rule.waitForIdle();
    // The wheel: a notch down moves the content up, the sideways one left.
    Offset at = pan.peek();
    rule.host().scroll({150, 150}, -1);
    rule.host().scroll({150, 150}, 0, 1);
    rule.waitForIdle();
    CHECK(near(pan.peek().y, at.y - 48) && near(pan.peek().x, at.x - 48) && near(page.value(), 0));
}

TEST(semantics_tree_merges_buttons_and_performs_actions) {
    auto clicks = std::make_shared<int>(0);
    auto checked = mutableStateOf(true);
    auto dialog = mutableStateOf(false);
    ScrollState scroll;
    ComposeTestRule rule([&] {
        Column(Modifier().fillMaxSize().verticalScroll(scroll), [&] {
            Text("Başlık", Modifier().semantics({.heading = true}));
            Button([clicks] { ++*clicks; }, [] {
                Icon(Icons::Filled::Add, "Artı");
                Text("Ekle");
            });
            Checkbox(checked.get(), [&](bool v) { checked.set(v); });
            TextField("merhaba", nullptr, Modifier(), {.placeholder = "yaz"});
            Box(Modifier().height(2000));
            if (dialog.get()) AlertDialog([] {}, {.title = [] { Text("Uyarı"); }});
        });
    });
    auto find = [&](std::vector<SemanticsNode>& tree, auto pred) -> SemanticsNode* {
        for (auto& n : tree)
            if (pred(n)) return &n;
        return nullptr;
    };
    auto tree = rule.host().semanticsTree();
    SemanticsNode* button = find(tree, [](auto& n) { return n.role == SemanticsRole::Button; });
    SemanticsNode* box = find(tree, [](auto& n) { return n.role == SemanticsRole::Checkbox; });
    SemanticsNode* field = find(tree, [](auto& n) { return n.editable; });
    SemanticsNode* heading = find(tree, [](auto& n) { return n.heading; });
    CHECK(button && button->label == "Artı Ekle" && button->clickable);
    CHECK(!find(tree, [](auto& n) { return n.label == "Ekle"; }));  // merged into the button
    CHECK(box && box->checked == true && box->label.empty());
    CHECK(field && field->value == "merhaba" && !field->focused);
    CHECK(heading && heading->label == "Başlık");
    CHECK(find(tree, [](auto& n) { return n.scrollable; }) != nullptr);
    if (button) CHECK(rule.host().performSemanticsAction(button->id, SemanticsAction::Click) && *clicks == 1);
    if (box) {
        CHECK(rule.host().performSemanticsAction(box->id, SemanticsAction::Click));
        rule.waitForIdle();
        CHECK(!checked.peek());
    }
    if (field) {
        CHECK(rule.host().performSemanticsAction(field->id, SemanticsAction::Click));
        auto again = rule.host().semanticsTree();
        SemanticsNode* f = find(again, [](auto& n) { return n.editable; });
        CHECK(f && f->focused && f->id == field->id);  // ids stay
    }
    auto list = find(tree, [](auto& n) { return n.scrollable; });
    if (list) CHECK(rule.host().performSemanticsAction(list->id, SemanticsAction::ScrollForward) && scroll.value() > 100);
    dialog.set(true);
    rule.waitForIdle();
    auto modal = rule.host().semanticsTree();
    CHECK(find(modal, [](auto& n) { return n.label == "Uyarı"; }) && !find(modal, [](auto& n) { return n.role == SemanticsRole::Button; }));
}

// ---- Nested scrolling ---------------------------------------------------------------------

namespace {
// A finger drag in `frames` moves that holds still before lifting (no fling).
void slowDrag(ComposeTestRule& rule, Offset from, Offset to, int frames = 20) {
    rule.host().pointerDown(from);
    for (int i = 1; i <= frames; ++i) {
        rule.advanceFrame();
        float t = float(i) / float(frames);
        rule.host().pointerMove({from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t});
    }
    rule.advanceTimeBy(200);
    rule.host().pointerUp(to);
    rule.advanceFrame();
}

// Records the calls it gets; takes half of every pre-scroll if asked to.
struct RecordingConnection : NestedScrollConnection {
    RecordingConnection(Log log, std::string name, bool takeHalf = false) : log(std::move(log)), name(std::move(name)), takeHalf(takeHalf) {}
    Offset onPreScroll(Offset available, NestedScrollSource) override {
        log->push_back(name + ".pre");
        Offset used = takeHalf ? Offset{0, available.y / 2} : Offset{};
        preUsed += used.y;
        return used;
    }
    Offset onPostScroll(Offset, Offset available, NestedScrollSource) override {
        log->push_back(name + ".post");
        postAvailable += available.y;
        return {};
    }
    Velocity onPreFling(Velocity available) override {
        log->push_back(name + ".preFling");
        preFlingVelocity = available.y;
        return {};
    }
    Velocity onPostFling(Velocity, Velocity available) override {
        log->push_back(name + ".postFling");
        postFlingVelocity = available.y;
        return {};
    }
    Log log;
    std::string name;
    bool takeHalf;
    float preUsed = 0, postAvailable = 0, preFlingVelocity = 0, postFlingVelocity = 0;
};
} // namespace

TEST(nested_scrollables_hand_over_at_the_edge) {
    ScrollState outer, inner;
    ComposeTestRule rule([&] {
        Column(Modifier().fillMaxSize().verticalScroll(outer), [&] {
            Box(Modifier().height(100));
            Column(Modifier().fillMaxWidth().height(300).verticalScroll(inner), [&] { Box(Modifier().height(600)); });
            Box(Modifier().height(1000));
        });
    }, {400, 800});
    CHECK(near(inner.maxValue(), 300) && near(outer.maxValue(), 600));
    // Up 500: the first 25 dp start the drag, the inner one scrolls to its end, the outer one takes the rest.
    slowDrag(rule, {200, 350}, {200, -150});
    CHECK(near(inner.value(), 300) && near(outer.value(), 175));
    // Down: the inner one (under the finger) goes back first.
    slowDrag(rule, {200, 150}, {200, 400});
    CHECK(near(inner.value(), 62.5f) && near(outer.value(), 175));
    slowDrag(rule, {200, 100}, {200, 400});
    CHECK(near(inner.value(), 0) && near(outer.value(), 0));
    // A fling on the inner one carries on in the outer one once the inner one is at its end.
    rule.swipe({200, 350}, {200, 150}, 4);
    rule.waitForIdle();
    CHECK(near(inner.value(), 300) && outer.value() > 50);
}

TEST(nested_scroll_connections_pre_outer_first_post_inner_first) {
    auto log = std::make_shared<std::vector<std::string>>();
    auto outer = std::make_shared<RecordingConnection>(log, "A", true);
    auto innerConnection = std::make_shared<RecordingConnection>(log, "B");
    ScrollState list;
    ComposeTestRule rule([&] {
        Box(Modifier().fillMaxSize().nestedScroll(outer), [&] {
            Box(Modifier().fillMaxSize().nestedScroll(innerConnection), [&] {
                Column(Modifier().fillMaxSize().verticalScroll(list), [&] { Box(Modifier().height(5000)); });
            });
        });
    }, {400, 800});
    slowDrag(rule, {200, 600}, {200, 400});  // 10 dp per move; the first one starts the drag
    CHECK(near(outer->preUsed, -95) && near(list.value(), 95));  // A took half of every step
    CHECK(log->size() >= 4 && (*log)[0] == "A.pre" && (*log)[1] == "B.pre" && (*log)[2] == "B.post" && (*log)[3] == "A.post");
    // Holding still before lifting: no fling, but both get the (zero) fling callbacks.
    CHECK(log->size() >= 4 && log->back() == "A.postFling" && near(outer->preFlingVelocity, 0));
    // A flick: the velocity follows the finger (up = negative), and what is left when the fling
    // stops (none: it slowed down) comes after.
    log->clear();
    rule.swipe({200, 600}, {200, 400}, 4);
    CHECK(outer->preFlingVelocity < -1000);
    CHECK(std::find(log->begin(), log->end(), "A.postFling") == log->end());  // still flinging
    rule.waitForIdle();
    CHECK(log->back() == "A.postFling" && near(outer->postFlingVelocity, 0));
    CHECK(near(outer->postAvailable, 0));  // the list never ran out
}

TEST(a_scrollable_takes_its_drags_from_an_outer_drag_handler) {
    ScrollState list;
    auto outerDrags = std::make_shared<int>(0);
    ComposeTestRule rule([&] {
        Box(Modifier().fillMaxSize().pointerInput(0, [outerDrags](PointerInputScope& s) -> Task {
            co_await detectDragGestures(s, {.onDrag = [outerDrags](PointerInputChange& c, Offset) {
                                                c.consume();
                                                ++*outerDrags;
                                            }});
        }),
            [&] { Column(Modifier().fillMaxWidth().height(400).verticalScroll(list), [&] { Box(Modifier().height(2000)); }); });
    }, {400, 800});
    slowDrag(rule, {200, 300}, {200, 100});
    CHECK(list.value() > 150 && *outerDrags == 0);
    float before = list.value();
    slowDrag(rule, {100, 200}, {300, 200});  // sideways: not along the list
    CHECK(near(list.value(), before) && *outerDrags > 0);
}

TEST(pager_takes_over_from_a_row_inside_its_page) {
    PagerState* pager = nullptr;
    ScrollState rows[3];
    ComposeTestRule rule([&] {
        auto state = rememberPagerState(0, [] { return 3; });
        pager = &remember([&] { return state; });
        HorizontalPager(state, Modifier().fillMaxWidth().height(200), [&](int page) {
            Row(Modifier().fillMaxSize().horizontalScroll(rows[page]), [] { Box(Modifier().width(800).height(10)); });
        });
    }, {400, 800});
    // Left 700: the first 35 dp start the drag, the row scrolls its 400, the pager 265 (0.66 pages)...
    rule.host().pointerDown({390, 100});
    for (int i = 1; i <= 20; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({390 - 35.f * float(i), 100});
    }
    CHECK(near(rows[0].value(), 400) && near(pager->currentPageOffsetFraction(), 265.f / 400 - 1));
    // ...and going back moves the pager back to its page before the row scrolls again.
    for (int i = 1; i <= 10; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({-310 + 30.f * float(i), 100});
    }
    CHECK(near(pager->currentPageOffsetFraction(), 0) && pager->currentPage() == 0 && near(rows[0].value(), 365));
    rule.advanceTimeBy(200);
    rule.host().pointerUp({-10, 100});
    rule.waitForIdle();
    CHECK(pager->currentPage() == 0);
    // The row first scrolls its last 35 dp; pulled 0.7 pages, the pager snaps to the next page.
    slowDrag(rule, {390, 100}, {390 - 335, 100});
    rule.waitForIdle();
    CHECK(pager->currentPage() == 1 && near(pager->currentPageOffsetFraction(), 0) && near(rows[0].value(), 400));
    testing::RecordingCanvas canvas;  // the neighbor pages don't show outside the pager (across, 30 dp more for shadows)
    rule.host().draw(canvas);
    CHECK(std::any_of(canvas.clips.begin(), canvas.clips.end(), [](Rect r) { return sameRect(r, {0, -30, 400, 260}); }));
}

TEST(reversed_pager_goes_back_to_its_page_before_a_row_in_it_scrolls) {
    std::optional<PagerState> pager;
    ScrollState rows[3];
    ComposeTestRule rule([&] {
        auto state = rememberPagerState(0, [] { return 3; });
        pager = state;
        HorizontalPager(state, Modifier().fillMaxWidth().height(200), [&](int page) {
            Row(Modifier().fillMaxSize().horizontalScroll(rows[page]), [] { Box(Modifier().width(800).height(10)); });
        }, {.reverseLayout = true});
    }, {400, 800});
    // Right: the row is at its start, the pager goes on (from the end, the finger the other way)...
    rule.host().pointerDown({10, 100});
    for (int i = 1; i <= 10; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({10 + 20.f * float(i), 100});
    }
    CHECK(pager->currentPageOffsetFraction() > 0.3f && near(rows[0].value(), 0));
    // ...and back left, the pager back to its page first, then the row scrolls.
    for (int i = 1; i <= 10; ++i) {
        rule.advanceFrame();
        rule.host().pointerMove({210 - 30.f * float(i), 100});
    }
    CHECK(near(pager->currentPageOffsetFraction(), 0, 0.01f) && pager->currentPage() == 0 && rows[0].value() > 100);
    rule.host().pointerUp({-90, 100});
    rule.waitForIdle();
}

TEST(pager_turns_the_page_with_a_flick_past_a_row_on_it) {
    for (auto direction : {LayoutDirection::Ltr, LayoutDirection::Rtl})
        for (bool userScroll : {true, false}) {
            PagerState pages(0, [] { return 3; });
            LazyListState row;
            float outerFling = 0;
            auto outer = nestedScrollConnection({.onPostFling = [&](Velocity, Velocity available) {
                outerFling = std::max(outerFling, std::abs(available.x));
                return Velocity{};
            }});
            ComposeTestRule rule([&] {
                CompositionLocalProvider({LocalLayoutDirection.provides(direction)}, [&] {
                    Box(Modifier().nestedScroll(outer), [&] {
                        HorizontalPager(pages, Modifier().width(200).height(60), [&](int page) {
                            if (page == 0)
                                LazyRow(Modifier().fillMaxSize(), {.state = row},
                                        [](LazyListScope& l) { l.items(3, [](int) { Box(Modifier().size(100, 60)); }); });
                        }, {.userScrollEnabled = userScroll});
                    });
                });
            }, {200, 400});
            // At its end. (Under a pager that doesn't scroll by itself the row starts at its start
            // and flings into its end: pulled past it, it would stretch and the release would
            // only relax that.)
            if (userScroll) row.scrollToItem(2);
            rule.waitForIdle();
            // A quick 100 dp flick towards the next page: the first 25 start the drag, the pager
            // takes the rest (less than half a page)...
            bool rtl = direction == LayoutDirection::Rtl;
            float x = rtl ? 50 : 150, toNext = rtl ? 25 : -25;
            rule.host().pointerDown({x, 30});
            for (int i = 1; i <= 4; ++i) {
                rule.advanceFrame();
                rule.host().pointerMove({x + toNext * float(i), 30});
            }
            CHECK(near(pages.currentPageOffsetFraction(), userScroll ? 0.375f : 0, 0.01f));
            // ...and the row's fling, stopped at its end, turns the page. None of it goes on to
            // the pager's parents, also when the pager doesn't scroll by itself.
            rule.host().pointerUp({x + toNext * 4, 30});
            rule.waitForIdle();
            CHECK(pages.currentPage() == (userScroll ? 1 : 0) && near(pages.currentPageOffsetFraction(), 0, 0.01f));
            CHECK(row.firstVisibleItemIndex() == 1 && outerFling == 0);
        }
}

TEST(rtl_snapping_row_settles_on_with_what_an_inner_fling_left) {
    LazyListState list;
    ScrollState inner;
    ComposeTestRule rule([&] {
        CompositionLocalProvider({LocalLayoutDirection.provides(LayoutDirection::Rtl)}, [&] {
            LazyRow(Modifier().width(200).height(60), {.state = list, .flingBehavior = rememberSnapFlingBehavior(list, SnapPosition::Start)},
                    [&](LazyListScope& l) {
                        l.items(4, [&](int i) {
                            if (i == 3)
                                Row(Modifier().size(100, 60).horizontalScroll(inner).testTag("iç"), [] { Box(Modifier().size(200, 60)); });
                            else
                                Box(Modifier().size(100, 60));
                        });
                    });
        });
    }, {200, 400});
    list.scrollToItem(3);  // at its end
    rule.waitForIdle();
    // To the right, towards the ends: the inner row flings into its end and the list, which
    // can't go on either, settles towards its end with the rest (it stays there).
    Rect r = rule.onNodeWithTag("iç").bounds();
    rule.swipe({r.x + 10, r.y + 30}, {r.x + 90, r.y + 30}, 4);
    rule.waitForIdle();
    CHECK(near(inner.value(), inner.maxValue()) && list.firstVisibleItemIndex() == 2);
}

TEST(snapping_grid_settles_with_a_row_lined_up) {
    LazyGridState grid, free;
    ComposeTestRule rule([&] {
        Row([&] {
            for (LazyGridState* s : {&grid, &free})
                LazyVerticalGrid(GridCells::Fixed(2), Modifier().size(150, 450),
                                 {.state = *s, .flingBehavior = s == &grid ? std::optional(rememberSnapFlingBehavior(grid, SnapPosition::Start)) : std::nullopt},
                                 [](LazyGridScope& g) { g.items(200, [](int) { Box(Modifier().fillMaxWidth().height(100)); }); });
        });
    }, {300, 800});
    // The same fling on both: the snapping one stops with a row at the top, the other anywhere.
    rule.swipe({75, 400}, {75, 250}, 4);
    rule.swipe({225, 400}, {225, 250}, 4);
    rule.waitForIdle();
    CHECK(grid.firstVisibleItemIndex() > 0 && near(grid.firstVisibleItemScrollOffset(), 0, 0.01f) && grid.firstVisibleItemIndex() % 2 == 0);
    CHECK(free.firstVisibleItemIndex() > 0 && free.firstVisibleItemScrollOffset() > 0.5f);
}

