TEST(infinite_transition_states_are_read_where_they_are_needed) {
    // As Compose's State from animateFloat: read while drawing, only drawn again; while laying
    // out, only laid out again; in a composition, composed again.
    std::vector<float> drawn;
    std::vector<Color> tints;
    int composed = 0, labels = 0;
    ComposeTestRule rule([&] {
        ++composed;
        auto t = rememberInfiniteTransition();
        auto angle = t.animateFloatState(0, 100000, tween(100000, 0, LinearEasing));  // a unit a millisecond, for long
        auto tint = t.animateColorState(colors::Black, colors::White, tween(100000, 0, LinearEasing));
        Column([&] {
            Box(Modifier().size(40).graphicsLayer([angle, &drawn](GraphicsLayerScope& l) { drawn.push_back(l.rotationZ = angle.get()); }));
            Box(Modifier().size(40).drawBehind([tint, &tints](DrawScope&) { tints.push_back(tint.get()); }));
            Box(Modifier().offset([angle] { return Offset{angle.get() / 100, 0}; }).size(10).testTag("kayan"));
            composable(CallSite::current(), [&labels, angle] {  // composed again as it changes
                ++labels;
                Text(std::to_string(int(angle.get())), Modifier().testTag("açı"));
            });
        });
    });
    auto draw = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
    };
    draw();
    CHECK(rule.host().hasPendingWork());  // drawn: the next frame is asked for
    int composedBefore = composed, labelsBefore = labels;
    float x0 = rule.onNodeWithTag("kayan").node()->contentBounds().x;
    rule.advanceTimeBy(250);
    draw();
    CHECK(composed == composedBefore);  // the section never composed again...
    CHECK(labels > labelsBefore && rule.onNodeWithText("0").exists() == false);  // ...but the text reading it did
    CHECK(drawn.size() >= 2 && drawn.back() > drawn.front() + 200);
    CHECK(tints.size() >= 2 && tints.back().r > tints.front().r);
    CHECK(rule.onNodeWithTag("kayan").node()->contentBounds().x > x0 + 2);  // laid out again where it is now
    // Read only while drawing: idle until drawn, then the next frame is asked for.
    ComposeTestRule drawnOnly([&] {
        auto angle = rememberInfiniteTransition().animateFloatState(0, 360, infiniteRepeatable(tween(1000, 0, LinearEasing)));
        Box(Modifier().size(40).graphicsLayer([angle](GraphicsLayerScope& l) { l.rotationZ = angle.get(); }));
    });
    CHECK(!drawnOnly.host().hasPendingWork());
    testing::RecordingCanvas canvas;
    drawnOnly.host().draw(canvas);
    CHECK(drawnOnly.host().hasPendingWork());
}

TEST(a_size_probe_measures_afresh) {
    float full = 0, narrowest = 0;
    ComposeTestRule rule([&] {
        Layout(Modifier(), [] { Text("bir iki üç"); }, [&](const std::vector<Measurable>& children, const Constraints&) {
            Placeable placeable = children[0].measure({0, kInfinity, 0, kInfinity});
            full = placeable.width;
            placeable.place(0, 0);
            detail::ProbeMeasure probe;  // the same constraints, but a word a line
            detail::MinIntrinsicWidth min;
            narrowest = children[0].measure({0, kInfinity, 0, kInfinity}).width;
            return Size{full, 20};
        });
    });
    CHECK(full > 0 && narrowest > 0 && narrowest < full / 2);
}

TEST(grid_sizes_tracks_as_compose) {
    using T = GridTrackSize;
    ComposeTestRule rule([&] {
        Column([&] {
            // Fixed, then two flexible columns sharing what's left after their min content.
            Grid(Modifier().width(300).testTag("g"), {.columns = {T::Fixed(50), T::Flex(1), T::Flex(2)}, .rows = {T::Fixed(40), T::Auto()}, .rowGap = 5, .columnGap = 10}, [] {
                Box(Modifier().size(20, 20).testTag("a"));
                Box(Modifier().size(30, 30).testTag("b"));
                Box(Modifier().size(30, 30).testTag("c"));
                Box(Modifier().size(10, 60).testTag("d"));
            });
            // A percentage of the room after the gaps; MinMax from its minimum.
            Grid(Modifier().width(210), {.columns = {T::Percentage(0.5f), T::MinMax(40, 1)}, .columnGap = 10}, [] {
                Box(Modifier().fillMaxWidth().height(10).testTag("yarım"));
                Box(Modifier().fillMaxWidth().height(10).testTag("kalan"));
            });
            // Auto columns grow from min towards max content by how much they can.
            Grid(Modifier().width(200), {.columns = {T::Auto(), T::Auto()}}, [] {
                GridLeaf(20, 100, 1000, Modifier().testTag("oto1"));
                GridLeaf(40, 200, 1000, Modifier().testTag("oto2"));
            });
            // Rows are as tall as their items at their column's width.
            Grid(Modifier(), {.columns = {T::Fixed(40), T::MinContent(), T::MaxContent()}}, [] {
                GridLeaf(10, 400, 2000, Modifier().testTag("metin"));
                GridLeaf(10, 400, 2000, Modifier().testTag("dar"));
                GridLeaf(10, 400, 2000, Modifier().testTag("geniş"));
            });
            // One across a fixed and a content column grows only the content one.
            Grid(Modifier().testTag("yayılan"), {.columns = {T::Fixed(30), T::MinContent()}}, [] {
                Box(Modifier().size(100, 10).gridItem(1, 1, 1, 2));
                Box(Modifier().size(5, 10).gridItem(2, 2).testTag("büyüyen"));
            });
            // Unbounded: a percentage is the content's size; flexible tracks keep their minimum.
            Row(Modifier().horizontalScroll(rememberScrollState()), [] {
                Grid(Modifier().testTag("sınırsız"), {.columns = {T::Percentage(0.5f), T::Flex(1)}}, [] {
                    Box(Modifier().size(70, 10));
                    GridLeaf(15, 90, 150, Modifier().testTag("esnek"));
                });
            });
        });
    }, {400, 2000});
    auto rect = [&](const char* tag) { return rule.onNodeWithTag(tag).bounds(); };
    Rect g = rect("g");
    CHECK(near(g.width, 300) && near(g.height, 105));
    CHECK(near(rect("a").x, g.x) && near(rect("a").y, g.y));
    CHECK(near(rect("b").x, g.x + 60) && near(rect("b").y, g.y));
    CHECK(near(rect("c").x, g.x + 60 + 30 + 170.f / 3 + 10));
    CHECK(near(rect("d").x, g.x) && near(rect("d").y, g.y + 45));
    CHECK(near(rect("yarım").width, 100) && near(rect("kalan").width, 100) && near(rect("kalan").x, rect("yarım").x + 110));
    CHECK(near(rect("oto1").width, 20 + 80 * 140.f / 240) && near(rect("oto2").width, 40 + 160 * 140.f / 240));
    CHECK(near(rect("metin").width, 40) && near(rect("metin").height, 50));
    CHECK(near(rect("dar").width, 10) && near(rect("dar").height, 200));
    CHECK(near(rect("geniş").width, 400) && near(rect("geniş").height, 5));
    CHECK(near(rect("büyüyen").x - rect("yayılan").x, 30) && near(rect("büyüyen").width, 5) && near(rect("yayılan").width, 100));
    CHECK(near(rect("sınırsız").width, 70 + 15) && near(rect("esnek").width, 15));
}

TEST(grid_places_items_as_compose) {
    using T = GridTrackSize;
    std::vector<GridTrackSize> three(3, T::Fixed(10));
    ComposeTestRule rule([&] {
        Column([&] {
            Grid(Modifier().testTag("g"), {.columns = three}, [] {
                Box(Modifier().size(10).gridItem(2, 3).testTag("a"));  // where asked
                Box(Modifier().size(10).gridItem(0, 0, 1, 2).testTag("b"));  // the first free cells
                Box(Modifier().size(10).gridItem(0, 0, 1, 2).testTag("c"));  // doesn't fit after b: the next row
                Box(Modifier().size(10).testTag("d"));  // a is there: the next row
                Box(Modifier().size(10).gridItem(-1, 0).testTag("e"));  // no rows configured: placed automatically
                Box(Modifier().size(10).gridItem(0, 1).testTag("f"));  // the first free row of the first column
                Box(Modifier().size(10).gridItem("yok").testTag("g1"));  // an unknown area: placed automatically
            });
            Grid(Modifier().testTag("h"), {.columns = three, .rows = {T::Fixed(10), T::Fixed(10)}, .flow = GridFlow::Column,
                                           .areas = {{"başlık", 1, 1, 1, 3}, {"sağ", 0, 3}}}, [] {
                Box(Modifier().fillMaxWidth().height(10).gridItem("başlık").testTag("başlık"));
                Box(Modifier().size(10).testTag("s1"));  // down the first column, under the header
                Box(Modifier().size(10).testTag("s2"));  // the column is full: the next one
                Box(Modifier().size(10).gridItem("sağ").testTag("sağ"));  // the last column's first free row
                Box(Modifier().size(10).gridItem(-1, -2).testTag("son"));  // from the end
                Box(Modifier().size(4).gridItem({1, 2}, {2, 3}, Alignment::Center).testTag("orta"));
                Box(Modifier().size(4).gridItem(2, 1, 1, 1, Alignment::BottomEnd).testTag("köşe"));
            });
            // A row's first free column from where the last one placed automatically ended.
            Grid(Modifier().testTag("i"), {.columns = {T::Fixed(10), T::Fixed(10), T::Fixed(10), T::Fixed(10)}}, [] {
                Box(Modifier().size(10).gridItem(1, 2));
                Box(Modifier().size(10).gridItem(0, 0, 1, 2));  // past the one in the second column: a hole before it
                Box(Modifier().size(10).gridItem(1, 0).testTag("imleç"));
            });
        });
    }, {400, 800});
    auto at = [&](const char* grid, const char* tag) {
        Rect g = rule.onNodeWithTag(grid).bounds(), r = rule.onNodeWithTag(tag).bounds();
        return Offset{r.x - g.x, r.y - g.y};
    };
    auto cell = [&](const char* grid, const char* tag, int row, int column) {
        Offset o = at(grid, tag);
        return near(o.x, column * 10.f) && near(o.y, row * 10.f);
    };
    CHECK(cell("g", "a", 1, 2) && cell("g", "b", 0, 0) && cell("g", "c", 1, 0) && cell("g", "d", 2, 0));
    CHECK(cell("g", "e", 2, 1) && cell("g", "f", 3, 0) && cell("g", "g1", 2, 2));
    CHECK(near(rule.onNodeWithTag("g").bounds().height, 40));
    CHECK(cell("h", "başlık", 0, 0) && near(rule.onNodeWithTag("başlık").bounds().width, 30));
    CHECK(cell("h", "s1", 1, 0) && cell("h", "s2", 1, 1) && cell("h", "sağ", 1, 2));
    CHECK(near(at("h", "son").x, 10) && near(at("h", "son").y, 10));
    CHECK(near(at("h", "orta").x, 10 + 8) && near(at("h", "orta").y, 8));
    CHECK(near(at("h", "köşe").x, 6) && near(at("h", "köşe").y, 16));
    CHECK(cell("i", "imleç", 0, 4));
}

TEST(dynamic_color_comes_from_the_host) {
    auto log = std::make_shared<std::vector<std::string>>();
    ComposeTestRule rule([log] {
        Text(isDynamicColorAvailable() ? "dinamik" : "varsayılan", Modifier().testTag("state"));
        log->push_back(dynamicLightColorScheme() == lightColorScheme() ? "baseline" : "palette");
    });
    CHECK(rule.onNodeWithTag("state").text() == "varsayılan" && log->back() == "baseline");
    rule.host().setDynamicTonalPalette(testPalette());
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("state").text() == "dinamik" && log->back() == "palette");
    size_t runs = log->size();
    rule.host().setDynamicTonalPalette(testPalette());  // the same palette: nothing to do
    rule.waitForIdle();
    CHECK(log->size() == runs);
    rule.host().setDynamicTonalPalette(std::nullopt);
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("state").text() == "varsayılan");
}

TEST(checkbox_draws_as_compose_1_4) {
    auto state = mutableStateOf(ToggleableState::Off);
    auto enabled = mutableStateOf(true);
    ColorScheme cs;
    ComposeTestRule rule([&] {
        cs = colorScheme();
        TriStateCheckbox(state.get(), [] {}, Modifier().testTag("kutu"), enabled.get());
    });
    auto sameColor = [](Color a, Color b) { return near(a.r, b.r, 0.01f) && near(a.g, b.g, 0.01f) && near(a.b, b.b, 0.01f) && near(a.a, b.a, 0.01f); };
    struct Drawn {
        testing::RecordingCanvas canvas;
        Rect box;
    };
    auto drawn = [&] {
        auto d = std::make_shared<Drawn>();
        rule.host().draw(d->canvas);
        Offset c = rule.onNodeWithTag("kutu").bounds().center();
        d->box = {c.x - 10, c.y - 10, 20, 20};
        return d;
    };
    // Off: a 2 dp outline inside the 20 dp box, in the surface's variant text color; no tick.
    auto off = drawn();
    CHECK(off->canvas.strokes.size() == 1 && sameRect(off->canvas.strokes[0], off->box));
    CHECK(sameColor(off->canvas.strokeColors[0], cs.onSurfaceVariant) && off->canvas.paths.empty());
    CHECK(near(off->canvas.strokeCorners[0].topLeft, 2));
    // Ticked: drawn along, then all of it: one 20 dp box in the primary color, the tick in its text color.
    state.set(ToggleableState::On);
    rule.advanceFrame();
    rule.advanceFrame();
    auto growing = drawn();
    CHECK(growing->canvas.paths.size() == 1 && growing->canvas.paths[0].width < 11);
    rule.advanceTimeBy(1000);
    auto on = drawn();
    CHECK(on->canvas.strokes.empty() && on->canvas.rects.size() == 1 && sameRect(on->canvas.rects[0], on->box));
    CHECK(sameColor(on->canvas.rectColors[0], cs.primary) && near(on->canvas.rectRadii[0], 2));
    CHECK(on->canvas.paths.size() == 1 && sameRect(on->canvas.paths[0], {on->box.x + 4, on->box.y + 6, 12, 8}));
    CHECK(sameColor(on->canvas.pathColors[0], cs.onPrimary) && near(on->canvas.pathStrokes[0], 2));
    // Indeterminate from ticked: bent into a dash across the middle.
    state.set(ToggleableState::Indeterminate);
    rule.advanceFrame();
    rule.advanceFrame();
    auto bending = drawn();
    CHECK(bending->canvas.paths.size() == 1 && bending->canvas.paths[0].height > 0.5f && bending->canvas.paths[0].height < 7.5f);
    rule.advanceTimeBy(1000);
    auto dash = drawn();
    CHECK(dash->canvas.paths.size() == 1 && sameRect(dash->canvas.paths[0], {dash->box.x + 4, dash->box.y + 10, 12, 0}));
    // Unticked: the tick whole for 100 ms (only fading), then gone at once.
    state.set(ToggleableState::Off);
    rule.advanceFrame();
    rule.advanceFrame();
    auto fading = drawn();
    // Faded by the fast effects spring (most of it within 50 ms), still a straight dash.
    rule.advanceFrame();
    rule.advanceFrame();
    auto faded = drawn();
    CHECK(faded->canvas.paths.size() == 1 && near(faded->canvas.paths[0].height, 0, 0.05f) && faded->canvas.rectColors[0].a < 0.3f);
    CHECK(fading->canvas.paths.size() == 1 && near(fading->canvas.paths[0].width, 12) && fading->canvas.pathColors[0].a < 0.99f);
    rule.advanceTimeBy(1000);
    CHECK(drawn()->canvas.paths.empty());
    // Indeterminate from off: a dash from the start, drawn along.
    state.set(ToggleableState::Indeterminate);
    rule.advanceFrame();
    rule.advanceFrame();
    auto dashing = drawn();
    CHECK(dashing->canvas.paths.size() == 1 && near(dashing->canvas.paths[0].height, 0) && dashing->canvas.paths[0].width < 11);
    rule.advanceTimeBy(1000);
    // Disabled: the surface's text faded, at once; the tick still in the primary's text color.
    state.set(ToggleableState::On);
    rule.advanceTimeBy(1000);
    enabled.set(false);
    rule.advanceFrame();
    auto disabledOn = drawn();
    CHECK(disabledOn->canvas.rects.size() == 1 && sameColor(disabledOn->canvas.rectColors[0], cs.onSurface.copy(0.38f)));
    CHECK(disabledOn->canvas.paths.size() == 1 && sameColor(disabledOn->canvas.pathColors[0], cs.onPrimary));
    state.set(ToggleableState::Off);
    rule.advanceTimeBy(1000);
    auto disabledOff = drawn();
    CHECK(disabledOff->canvas.strokes.size() == 1 && sameColor(disabledOff->canvas.strokeColors[0], cs.onSurface.copy(0.38f)));
    CHECK(disabledOff->canvas.rects.size() == 1 && disabledOff->canvas.rectColors[0].a == 0 && sameRect(disabledOff->canvas.rects[0], {disabledOff->box.x + 2, disabledOff->box.y + 2, 16, 16}));
}

TEST(radio_button_draws_as_compose_1_4) {
    auto selected = mutableStateOf(false);
    auto enabled = mutableStateOf(true);
    ColorScheme cs;
    ComposeTestRule rule([&] {
        cs = colorScheme();
        RadioButton(selected.get(), [] {}, Modifier().testTag("radyo"), enabled.get());
    });
    auto sameColor = [](Color a, Color b) { return near(a.r, b.r, 0.01f) && near(a.g, b.g, 0.01f) && near(a.b, b.b, 0.01f) && near(a.a, b.a, 0.01f); };
    auto drawn = [&] {
        auto canvas = std::make_shared<testing::RecordingCanvas>();
        rule.host().draw(*canvas);
        return canvas;
    };
    Offset c = rule.onNodeWithTag("radyo").bounds().center();
    // A 20 dp ring, 2 dp wide, in the surface's variant text color; no dot.
    auto off = drawn();
    CHECK(off->strokes.size() == 1 && sameRect(off->strokes[0], {c.x - 10, c.y - 10, 20, 20}) && off->rects.empty());
    CHECK(sameColor(off->strokeColors[0], cs.onSurfaceVariant));
    // Selected: the dot grows to 5 dp across 10, both in the primary color, the color eased in.
    selected.set(true);
    rule.advanceFrame();
    rule.advanceFrame();
    auto easing = drawn();
    CHECK(easing->strokeColors.size() == 1 && !sameColor(easing->strokeColors[0], cs.primary));
    rule.advanceTimeBy(1000);
    auto on = drawn();
    CHECK(on->rects.size() == 1 && sameRect(on->rects[0], {c.x - 5, c.y - 5, 10, 10}) && sameColor(on->rectColors[0], cs.primary));
    CHECK(sameColor(on->strokeColors[0], cs.primary));
    // Unselected: the dot shrinks away (none of it drawn once under the ring's half width).
    selected.set(false);
    bool shrinking = false, inside = true;
    for (int i = 0; i < 30; ++i) {
        rule.advanceFrame();
        auto f = drawn();
        for (Rect r : f->rects) shrinking |= r.width > 0.5f && r.width < 9.5f, inside &= r.width > 0;
    }
    CHECK(shrinking && inside);
    selected.set(true);
    rule.advanceTimeBy(1000);
    // Disabled: the surface's text faded, at once.
    enabled.set(false);
    rule.advanceFrame();
    auto disabled = drawn();
    CHECK(sameColor(disabled->strokeColors[0], cs.onSurface.copy(0.38f)) && sameColor(disabled->rectColors[0], cs.onSurface.copy(0.38f)));
    selected.set(false);
    rule.advanceTimeBy(1000);
    auto disabledOff = drawn();
    CHECK(sameColor(disabledOff->strokeColors[0], cs.onSurface.copy(0.38f)) && disabledOff->rects.empty());
}

TEST(cards_as_compose_1_4) {
    ColorScheme cs;
    ComposeTestRule rule([&] {
        cs = colorScheme();
        Column([&] {
            Card(Modifier().size(100, 40).testTag("dolu"), [] { Box(Modifier().size(200, 40)); });
            ElevatedCard(Modifier().size(100, 40).testTag("yüksek"), [] {});
            OutlinedCard(Modifier().size(100, 40).testTag("çizgili"), [] {});
            Card([] {}, Modifier().size(100, 40).testTag("tıklanır"), [] {});
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto fillOf = [&](const char* tag) -> std::optional<std::pair<Color, float>> {
        Rect r = rule.onNodeWithTag(tag).bounds();
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (near(canvas.rects[i].x, r.x, 0.01f) && near(canvas.rects[i].y, r.y, 0.01f) && near(canvas.rects[i].width, r.width, 0.01f) &&
                near(canvas.rects[i].height, r.height, 0.01f))
                return std::pair{canvas.rectColors[i], canvas.rectRadii[i]};
        return std::nullopt;
    };
    auto filled = fillOf("dolu"), elevated = fillOf("yüksek"), outlined = fillOf("çizgili"), clickable = fillOf("tıklanır");
    CHECK(filled && filled->first == cs.surfaceContainerHighest && near(filled->second, 12));
    CHECK(clickable && clickable->first == cs.surfaceContainerHighest && near(clickable->second, 12));
    CHECK(elevated && elevated->first == cs.surfaceContainerLow && near(elevated->second, 12));
    CHECK(outlined && outlined->first == cs.surface && near(outlined->second, 12));
    // Their content clipped to their corners.
    Rect card = rule.onNodeWithTag("dolu").bounds();
    bool clipped = false;
    for (size_t i = 0; i < canvas.layerBounds.size(); ++i) clipped |= sameRect(canvas.layerBounds[i], card) && near(canvas.layerCorners[i].topLeft, 12);
    CHECK(clipped);
    // The elevated one's shadow the one of 1 dp (spread 0.8 dp at most); none for the others.
    auto shadowSpread = [&](const char* tag) {
        Rect r = rule.onNodeWithTag(tag).bounds();
        float most = 0;
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (canvas.rectColors[i].a < 0.1f && near(canvas.rects[i].center().x, r.center().x, 2) && near(canvas.rects[i].center().y, r.center().y, 2))
                most = std::max(most, canvas.rects[i].height - r.height);
        return most;
    };
    CHECK(near(shadowSpread("yüksek"), 0.8f, 0.05f) && near(shadowSpread("dolu"), 0, 0.01f));
}

TEST(buttons_as_compose_1_4) {
    ColorScheme cs;
    auto rtl = mutableStateOf(false);
    ComposeTestRule rule([&] {
        cs = colorScheme();
        Column([&] {
            // 8 dp above and below (46 for a 30 dp label), at least 58 wide (a TextButton too).
            Button([] {}, Modifier().testTag("dolu"), [] { Box(Modifier().size(4, 30)); });
            TextButton([] {}, Modifier().testTag("metin"), {}, [] { Box(Modifier().size(4, 20)); });
            // An icon's padding: 16 dp before, 24 after; the start mirrored right to left.
            CompositionLocalProvider({LocalLayoutDirection.provides(rtl.get() ? LayoutDirection::Rtl : LayoutDirection::Ltr)}, [&] {
                Button([] {}, Modifier().testTag("simgeli"), {.contentPadding = ButtonDefaults::ButtonWithIconContentPadding},
                       [] { Box(Modifier().size(20).testTag("simge")); });
                // Squeezed: each side gives way by its share (16:24).
                Button([] {}, Modifier().width(50).testTag("sıkışık"), {.contentPadding = ButtonDefaults::ButtonWithIconContentPadding},
                       [] { Box(Modifier().widthIn(0, 40).fillMaxWidth().height(20).testTag("sıkışık-içi")); });
            });
            OutlinedButton([] {}, Modifier().testTag("çizgili"), {}, [] { Box(Modifier().size(4, 20)); });
            OutlinedButton([] {}, Modifier().testTag("kapalı"), {.enabled = false}, [] { Box(Modifier().size(4, 20)); });
            ElevatedButton([] {}, Modifier().testTag("yüksek"), {}, [] { Box(Modifier().size(80, 20)); });
        });
    });
    auto canvas = std::make_shared<testing::RecordingCanvas>();
    auto redraw = [&] {
        canvas = std::make_shared<testing::RecordingCanvas>();
        rule.host().draw(*canvas);
    };
    redraw();
    // A button's container: the opaque fill or outline across its middle.
    auto container = [&](const char* tag) -> Rect {
        Rect b = rule.onNodeWithTag(tag).bounds();
        for (size_t i = 0; i < canvas->rects.size(); ++i)
            if (canvas->rectColors[i].a > 0.5f && near(canvas->rects[i].center().y, b.center().y, 0.1f) && near(canvas->rects[i].center().x, b.center().x, 0.1f))
                return canvas->rects[i];
        for (Rect r : canvas->strokes)
            if (near(r.center().y, b.center().y, 0.1f) && near(r.center().x, b.center().x, 0.1f)) return r;
        return {};
    };
    Rect filled = container("dolu");
    CHECK(near(filled.height, 46) && near(filled.width, 58));
    Rect textBounds = rule.onNodeWithTag("metin").bounds();
    CHECK(near(textBounds.width, 58));
    Rect iconed = container("simgeli"), icon = rule.onNodeWithTag("simge").bounds();
    CHECK(near(iconed.width, 60) && near(icon.x, iconed.x + 16));
    Rect squeezed = container("sıkışık"), inside = rule.onNodeWithTag("sıkışık-içi").bounds();
    CHECK(near(inside.width, 40) && near(inside.x, squeezed.x + 4));
    rtl.set(true);
    rule.waitForIdle();
    redraw();
    iconed = container("simgeli");
    icon = rule.onNodeWithTag("simge").bounds();
    CHECK(near(icon.x + icon.width, iconed.x + iconed.width - 16));
    // Outlined: outlineVariant, a tenth of it disabled.
    auto strokeOf = [&](const char* tag) {
        Rect b = rule.onNodeWithTag(tag).bounds();
        for (size_t i = 0; i < canvas->strokes.size(); ++i)
            if (near(canvas->strokes[i].center().y, b.center().y, 0.1f)) return canvas->strokeColors[i];
        return Color{};
    };
    CHECK(strokeOf("çizgili") == cs.outlineVariant && strokeOf("kapalı") == cs.outlineVariant.copy(0.1f));
    // Elevations: 1 dp (spread 0.8) for the elevated one, none for the filled one; 3 and 1 hovered.
    auto shadowSpread = [&](const char* tag) {
        Rect r = container(tag);
        float most = 0;
        for (size_t i = 0; i < canvas->rects.size(); ++i)
            if (canvas->rectColors[i].a < 0.1f && near(canvas->rects[i].center().x, r.center().x, 2) && near(canvas->rects[i].center().y, r.center().y, 2))
                most = std::max(most, canvas->rects[i].height - r.height);
        return most;
    };
    CHECK(near(shadowSpread("yüksek"), 0.8f, 0.05f) && near(shadowSpread("dolu"), 0, 0.01f));
    rule.host().pointerMove(rule.onNodeWithTag("yüksek").bounds().center());
    rule.advanceTimeBy(300);
    redraw();
    CHECK(near(shadowSpread("yüksek"), 2.4f, 0.05f));
    rule.host().pointerMove(rule.onNodeWithTag("dolu").bounds().center());
    rule.advanceFrame();
    rule.advanceFrame();
    rule.advanceFrame();
    redraw();
    float easing = shadowSpread("yüksek");
    CHECK(easing > 0.85f && easing < 2.35f);  // on its way back down
    rule.advanceTimeBy(300);
    redraw();
    CHECK(near(shadowSpread("yüksek"), 0.8f, 0.05f) && near(shadowSpread("dolu"), 0.8f, 0.05f));
    // Pressed: back down, though hovered.
    Offset at = rule.onNodeWithTag("dolu").bounds().center();
    rule.host().pointerDown(at, -1, 0, ComposeHost::PointerType::Mouse);
    rule.advanceTimeBy(300);
    redraw();
    CHECK(near(shadowSpread("dolu"), 0, 0.01f));
    rule.host().pointerUp(at);
    rule.waitForIdle();
}

TEST(chips_as_compose_1_4) {
    ColorScheme cs;
    auto picked = mutableStateOf(false);
    std::map<std::string, Color> seen;  // each part's content color
    ComposeTestRule rule([&] {
        cs = colorScheme();
        auto part = [&](std::string name, float width) {
            return Content([&seen, name, width] {
                seen[name] = LocalContentColor.current();
                Box(Modifier().size(width, 18).testTag(name));
            });
        };
        Column([&] {
            AssistChip([] {}, part("yardım", 40), {.trailingIcon = part("yardım-son", 18)}, Modifier().testTag("yardım-çip"));
            SuggestionChip([] {}, part("öneri", 40), {.leadingIcon = part("öneri-baş", 18)});
            InputChip(false, [] {}, part("giriş", 40), {}, Modifier().testTag("giriş-çip"));
            InputChip(true, [] {}, part("seçili-giriş", 40), {.leadingIcon = part("seçili-giriş-baş", 18), .trailingIcon = part("seçili-giriş-son", 18)},
                      Modifier().testTag("seçili-giriş-çip"));
            // The avatar before an icon, in the label's color.
            InputChip(true, [] {}, part("avatarlı", 40), {.leadingIcon = part("avatarsız-simge", 18), .avatar = part("avatar", 24)},
                      Modifier().testTag("avatarlı-çip"));
            FilterChip(picked.get(), [] {}, part("filtre", 40), {.leadingIcon = picked.get() ? part("tik", 18) : Content()},
                       Modifier().testTag("filtre-çip"));
            FilterChip(true, [] {}, part("kapalı", 40), {.enabled = false}, Modifier().testTag("kapalı-çip"));
            FilterChip(false, [] {}, part("kapalı-boş", 40), {.enabled = false}, Modifier().testTag("kapalı-boş-çip"));
        });
    });
    auto bounds = [&](const char* tag) { return rule.onNodeWithTag(tag).bounds(); };
    // 8 dp around and between the parts: 16 at an end without an icon (an input chip's 12).
    auto chip = bounds;
    Rect assist = bounds("yardım"), assistEnd = bounds("yardım-son");
    CHECK(near(assistEnd.x - (assist.x + assist.width), 8));
    Rect input = bounds("giriş"), inputChip = chip("giriş-çip");
    CHECK(near(inputChip.width, 64) && near(input.x, inputChip.x + 12));
    Rect withAvatar = chip("avatarlı-çip"), avatar = bounds("avatar");
    CHECK(near(withAvatar.width, 4 + 24 + 56 + 4) && near(avatar.x, withAvatar.x + 4));
    Rect both = chip("seçili-giriş-çip");
    CHECK(near(both.width, 8 + 18 + 56 + 18 + 8));
    // Colors: an assist chip's label the surface's text, its icons primary; a suggestion chip's
    // label the variant; a selected input chip's leading icon primary, its trailing one onSecondaryContainer.
    CHECK(seen["yardım"] == cs.onSurface && seen["yardım-son"] == cs.primary);
    CHECK(seen["öneri"] == cs.onSurfaceVariant && seen["öneri-baş"] == cs.primary);
    CHECK(seen["giriş"] == cs.onSurfaceVariant && seen["avatar"] == cs.onSecondaryContainer && !seen.contains("avatarsız-simge"));
    CHECK(seen["seçili-giriş"] == cs.onSecondaryContainer && seen["seçili-giriş-baş"] == cs.primary && seen["seçili-giriş-son"] == cs.onSecondaryContainer);
    // Disabled: selected on the surface's text at 12%, unselected in a line of it.
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto fillOf = [&](const char* tag) {
        Rect b = bounds(tag);
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (sameRect(canvas.rects[i], {b.x, b.center().y - 16, b.width, 32})) return canvas.rectColors[i];
        return Color{};
    };
    auto lineOf = [&](const char* tag) {
        Rect b = bounds(tag);
        for (size_t i = 0; i < canvas.strokes.size(); ++i)
            if (sameRect(canvas.strokes[i], {b.x, b.center().y - 16, b.width, 32})) return canvas.strokeColors[i];
        return Color{};
    };
    CHECK(fillOf("kapalı-çip") == cs.onSurface.copy(0.12f) && lineOf("kapalı-boş-çip") == cs.onSurface.copy(0.12f));
    CHECK(lineOf("filtre-çip") == cs.outlineVariant && seen["kapalı"] == cs.onSurface.copy(0.38f));
    // A filter chip's check grows in and its room shrinks away; it says it's a checkbox.
    Rect plain = chip("filtre-çip");
    CHECK(near(plain.width, 72));
    picked.set(true);
    rule.advanceFrame();
    rule.advanceFrame();
    rule.advanceFrame();
    float growing = chip("filtre-çip").width;
    CHECK(growing > 73 && growing < 89);
    rule.advanceTimeBy(1000);
    CHECK(near(chip("filtre-çip").width, 8 + 18 + 56 + 8) && seen["tik"] == cs.onSecondaryContainer);
    picked.set(false);
    rule.advanceFrame();
    rule.advanceFrame();
    rule.advanceFrame();
    float shrinking = chip("filtre-çip").width;
    CHECK(shrinking > 73 && shrinking < 89);
    rule.advanceTimeBy(1000);
    CHECK(near(chip("filtre-çip").width, 72));
    int checkboxes = 0, checked = 0;
    for (const SemanticsNode& n : rule.host().semanticsTree())
        if (n.role == SemanticsRole::Checkbox) ++checkboxes, checked += n.checked == true;
    CHECK(checkboxes == 6 && checked == 3);  // the filter and input chips; the selected three (one disabled)
}

TEST(fabs_as_compose_1_4) {
    ComposeTestRule rule([&] {
        Column([&] {
            FloatingActionButton([] {}, [] { Icon(Icons::Filled::Add, "Ekle"); }, Modifier().testTag("fab"));
            ExtendedFloatingActionButton([] {}, Icons::Filled::Add, "Yeni", Modifier().testTag("geniş"));
            ExtendedFloatingActionButton([] {}, Icons::Filled::Add, "", Modifier().testTag("kısa"));
            Text("Yeni", Modifier().testTag("ölçü"), {.font = typography().labelLarge});
        });
    });
    // 16 dp before the icon, 12 between, 20 after the label; at least 80 wide.
    Rect wide = rule.onNodeWithTag("geniş").bounds(), icon = rule.onNodeWithText("Yeni").bounds();  // (the icon says it too)
    CHECK(near(icon.x, wide.x + 16) && near(wide.width, 16 + 24 + 12 + rule.onNodeWithTag("ölçü").bounds().width + 20));
    CHECK(near(rule.onNodeWithTag("kısa").bounds().width, 80));
    // 6 dp up (a 4.8 dp spread), 8 hovered (6.4), 6 again pressed.
    auto spread = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        Rect r = rule.onNodeWithTag("fab").bounds();
        float most = 0;
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (canvas.rectColors[i].a < 0.1f && near(canvas.rects[i].center().x, r.center().x, 2) && near(canvas.rects[i].center().y, r.center().y, 4))
                most = std::max(most, canvas.rects[i].height - r.height);
        return most;
    };
    CHECK(near(spread(), 4.8f, 0.05f));
    Offset at = rule.onNodeWithTag("fab").bounds().center();
    rule.host().pointerMove(at);
    rule.advanceTimeBy(300);
    CHECK(near(spread(), 6.4f, 0.05f));
    rule.host().pointerDown(at, -1, 0, ComposeHost::PointerType::Mouse);
    rule.advanceTimeBy(300);
    CHECK(near(spread(), 4.8f, 0.05f));
    rule.host().pointerUp(at);
    rule.waitForIdle();
}

TEST(navigation_bar_items_as_compose_1_4) {
    ColorScheme cs;
    auto tab = mutableStateOf(0);
    ComposeTestRule rule([&] {
        cs = colorScheme();
        NavigationBar(Modifier(), [&] {
            NavigationBarItem(tab.get() == 0, [&] { tab.set(0); }, Icons::Filled::Home, "Bir");
            NavigationBarItem(tab.get() == 1, [&] { tab.set(1); }, Icons::Filled::List, "İki");
        });
    }, {400, 300});
    rule.waitForIdle();
    Rect first = rule.onNodeWithText("Bir").bounds(), second = rule.onNodeWithText("İki").bounds();
    auto draw = [&] {
        auto canvas = std::make_shared<testing::RecordingCanvas>();
        rule.host().draw(*canvas);
        return canvas;
    };
    auto sameColor3 = [](Color a, Color b) { return near(a.r, b.r, 0.01f) && near(a.g, b.g, 0.01f) && near(a.b, b.b, 0.01f); };
    auto indicatorUnder = [&](const testing::RecordingCanvas& canvas, Rect label) -> std::optional<std::pair<Rect, Color>> {
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (near(canvas.rects[i].center().x, label.center().x, 0.5f) && sameColor3(canvas.rectColors[i], cs.secondaryContainer))
                return std::pair{canvas.rects[i], canvas.rectColors[i]};
        return std::nullopt;
    };
    // The label 4 dp under the 64 × 32 indicator 12 dp down (the bar 80 tall): 48 dp down.
    auto canvas = draw();
    auto shown = indicatorUnder(*canvas, first);
    CHECK(shown && near(shown->first.width, 64) && near(shown->first.height, 32) && near(shown->first.y, first.y - 36));
    CHECK(!indicatorUnder(*canvas, second));
    auto colorOf = [&](const testing::RecordingCanvas& c, const std::string& text) {
        for (size_t i = 0; i < c.texts.size(); ++i)
            if (c.texts[i] == text) return c.colors[i];
        return Color{};
    };
    CHECK(colorOf(*canvas, "Bir") == cs.secondary && colorOf(*canvas, "İki") == cs.onSurfaceVariant);
    // Picked: the indicator grows out of the middle, fading in; the colors eased.
    tab.set(1);
    rule.advanceFrame();
    rule.advanceFrame();
    rule.advanceFrame();
    canvas = draw();
    auto growing = indicatorUnder(*canvas, second);
    bool fading = std::ranges::any_of(canvas->layerAlphas, [](float a) { return a > 0.01f && a < 0.99f; });
    CHECK(growing && growing->first.width > 4 && growing->first.width < 60 && fading);
    CHECK(colorOf(*canvas, "İki") != cs.secondary);
    rule.advanceTimeBy(1000);
    canvas = draw();
    auto grown = indicatorUnder(*canvas, second);
    CHECK(grown && near(grown->first.width, 64) && colorOf(*canvas, "İki") == cs.secondary && !indicatorUnder(*canvas, first));
    // The ripple on the indicator starts where the finger went down.
    Offset at{first.center().x + 20, first.y - 20};
    rule.host().pointerDown(at);
    rule.advanceFrame();
    draw();  // (a ripple starts when it is first drawn)
    rule.advanceFrame();
    canvas = draw();
    bool fromFinger = false;
    for (size_t i = 0; i < canvas->rects.size(); ++i) {
        Rect r = canvas->rects[i];
        fromFinger |= near(r.width, r.height, 0.01f) && canvas->rectColors[i].a < 0.2f && near(r.center().x, at.x, 3) && near(r.center().y, at.y, 3);
    }
    CHECK(fromFinger);
    rule.host().pointerUp(at);
    rule.waitForIdle();
    CHECK(tab.peek() == 0);
    int tabs = 0, picked = 0;
    for (const SemanticsNode& n : rule.host().semanticsTree())
        if (n.role == SemanticsRole::Tab) ++tabs, picked += n.checked == true;
    CHECK(tabs == 2 && picked == 1);
}

TEST(navigation_rail_as_compose_1_4) {
    ColorScheme cs;
    auto tab = mutableStateOf(0);
    ComposeTestRule rule([&] {
        cs = colorScheme();
        NavigationRail(Modifier().testTag("ray"), [] { Box(Modifier().size(40).testTag("baş")); }, [&] {
            NavigationRailItem(tab.get() == 0, [&] { tab.set(0); }, Icons::Filled::Home, "Bir");
            NavigationRailItem(tab.get() == 1, [&] { tab.set(1); }, Icons::Filled::List, "İki");
        });
    }, {400, 600});
    // 4 dp above, the header, 8 under it; 80 × 56 items 4 dp apart, the label 36 dp down.
    Rect rail = rule.onNodeWithTag("ray").bounds(), header = rule.onNodeWithTag("baş").bounds();
    Rect first = rule.onNodeWithText("Bir").bounds(), second = rule.onNodeWithText("İki").bounds();
    CHECK(near(rail.width, 80) && near(header.y, rail.y + 4));
    float firstTop = header.y + 40 + 4 + 8 + 4;
    CHECK(near(first.y, firstTop + 36) && near(second.y, firstTop + 56 + 4 + 36));
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    bool indicator = false;
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        indicator |= canvas.rectColors[i] == cs.secondaryContainer && near(canvas.rects[i].width, 56) && near(canvas.rects[i].height, 32) &&
                     near(canvas.rects[i].y, firstTop) && near(canvas.rects[i].center().x, rail.center().x);
    CHECK(indicator);
    Color label{};
    for (size_t i = 0; i < canvas.texts.size(); ++i)
        if (canvas.texts[i] == "Bir") label = canvas.colors[i];
    CHECK(label == cs.secondary);
    // Picked: it grows in; the ripple on its indicator starts under the finger.
    tab.set(1);
    rule.advanceFrame();
    rule.advanceFrame();
    rule.advanceFrame();
    testing::RecordingCanvas growing;
    rule.host().draw(growing);
    bool part = false;
    for (size_t i = 0; i < growing.rects.size(); ++i)
        part |= growing.rectColors[i] == cs.secondaryContainer && growing.rects[i].width > 4 && growing.rects[i].width < 52;
    CHECK(part);
    rule.waitForIdle();
    Offset at{rail.center().x + 15, firstTop + 20};
    rule.host().pointerDown(at);
    rule.advanceFrame();
    testing::RecordingCanvas first0;
    rule.host().draw(first0);
    rule.advanceFrame();
    testing::RecordingCanvas pressed;
    rule.host().draw(pressed);
    bool fromFinger = false;
    for (size_t i = 0; i < pressed.rects.size(); ++i) {
        Rect r = pressed.rects[i];
        fromFinger |= near(r.width, r.height, 0.01f) && pressed.rectColors[i].a < 0.2f && near(r.center().x, at.x, 3) && near(r.center().y, at.y, 3);
    }
    CHECK(fromFinger);
    rule.host().pointerUp(at);
    rule.waitForIdle();
    CHECK(tab.peek() == 0);
}

