TEST(segmented_buttons_as_compose_1_4) {
    ColorScheme cs;
    auto picked = mutableStateOf(0);
    ComposeTestRule rule([&] {
        cs = colorScheme();
        SingleChoiceSegmentedButtonRow(Modifier().width(300), [&] {
            for (int i = 0; i < 2; ++i)
                SegmentedButton(picked.get() == i, [&, i] { picked.set(i); }, [i] { Text(i == 0 ? "Bir" : "Iki"); });
        });
    });
    auto layer = [&] {
        testing::RecordingCanvas c;
        rule.host().draw(c);
        return c;
    };
    // Without an icon the label sits over half of the icon's room: centered in the segment.
    Rect two = rule.onNodeWithText("Iki").bounds(), one = rule.onNodeWithText("Bir").bounds();
    CHECK(near(two.center().x, 225, 1));
    // Selected: the container at once, the label sliding right, the check growing in.
    picked.set(1);
    rule.advanceFrame();
    rule.advanceFrame();
    auto c = layer();
    bool container = false;
    for (size_t i = 0; i < c.rects.size(); ++i) container |= c.rectColors[i] == cs.secondaryContainer && c.rects[i].x > 140;
    CHECK(container);
    float sliding = rule.onNodeWithText("Iki").bounds().center().x;
    CHECK(sliding > 225.5f && sliding < 237.5f);
    bool growing = std::ranges::any_of(c.layerTransforms, [](const LayerTransform& t) { return t.scaleX > 0.01f && t.scaleX < 0.99f; });
    CHECK(growing);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithText("Iki").bounds().center().x, 238, 1));
    // The other loses its check at once.
    CHECK(near(rule.onNodeWithText("Bir").bounds().center().x, one.center().x, 13.5f));
}

