TEST(time_input_types_hours_and_minutes) {
    std::optional<TimePickerState> state;
    ComposeTestRule rule([&] {
        auto s = rememberTimePickerState(9, 30);
        state = s;
        TimeInput(s, Modifier(), {.hourLabel = "Saat", .minuteLabel = "Dakika"});
    }, {400, 800});
    CHECK(rule.onNodeWithText("Saat").exists() && rule.onNodeWithText("Dakika").exists());
    auto retype = [&](const char* shown, const char* typed) {
        auto field = rule.onNodeWithText(shown);
        field.performClick().performKey(Key::End).performKey(Key::Backspace).performKey(Key::Backspace);
        field.performTextInput(typed);
    };
    retype("09", "14");
    CHECK(state->hour() == 14);
    rule.onNodeWithText("14").performTextInput("7");  // "147": typing into a full field starts it over
    CHECK(state->hour() == 7 && rule.onNodeWithText("7").exists());
    rule.onNodeWithText("7").performTextInput("5");  // 75 isn't an hour: 5
    CHECK(state->hour() == 5 && rule.onNodeWithText("5").exists());
    retype("30", "45");  // leaving the hour field writes it out in full
    CHECK(state->minute() == 45 && rule.onNodeWithText("05").exists());
    rule.onNodeWithText("45").performTextInput("9");
    CHECK(state->minute() == 9);
    rule.onNodeWithText("9").performTextInput("5");  // 95 isn't a minute either; 5 is
    CHECK(state->minute() == 5);
    rule.onNodeWithText("5").performKey(Key::Backspace);  // emptied: the time stays as it was
    CHECK(state->minute() == 5 && !rule.onNodeWithText("5").exists());
    rule.host().textInput("x");  // not a digit
    rule.waitForIdle();
    CHECK(state->minute() == 5 && !rule.onNodeWithText("x").exists());
    rule.host().textInput("7");
    rule.waitForIdle();
    CHECK(state->minute() == 7 && rule.onNodeWithText("7").exists());
}

