TEST(slider_tells_its_interaction_source_presses_drags_and_hovers) {
    using T = Interaction::Type;
    MutableInteractionSource source, off;
    std::vector<T> log, offLog;
    auto value = mutableStateOf(0.f);
    auto shown = mutableStateOf(true);
    ComposeTestRule rule([&] {
        LogInteractions(source, log);
        LogInteractions(off, offLog);
        Column([&] {
            if (shown.get())
                Slider(value.get(), [value](float v) { value.set(v); }, Modifier().width(220).testTag("kaydırıcı"),
                       {.valueFrom = 0, .valueTo = 100, .interactionSource = source});
            Slider(50, [](float) {}, Modifier().width(220).testTag("kapalı"), {.enabled = false, .interactionSource = off});
            Text(std::format("basılı {} sürükleniyor {}", source.collectIsPressedAsState(), source.collectIsDraggedAsState()));
        });
    });
    // The track runs from 10 to 210: x = 10 + 2 * value.
    rule.host().pointerDown({60, 22});
    rule.waitForIdle(0);
    CHECK((log == std::vector{T::Press}) && rule.onNodeWithText("basılı true sürükleniyor false").exists() && near(value.peek(), 25));
    rule.host().pointerMove({63, 22});  // under the touch slop: still a press
    rule.waitForIdle(0);
    CHECK((log == std::vector{T::Press}));
    for (float x = 70; x <= 160; x += 10) rule.host().pointerMove({x, 22});
    rule.waitForIdle(0);
    CHECK((log == std::vector{T::Press, T::DragStart}) && rule.onNodeWithText("basılı true sürükleniyor true").exists() && near(value.peek(), 75));
    rule.host().pointerUp({160, 22});
    rule.waitForIdle();
    CHECK((log == std::vector{T::Press, T::DragStart, T::DragStop, T::Release}) && rule.onNodeWithText("basılı false sürükleniyor false").exists());
    log.clear();
    tap(rule, {110, 22});  // a tap: a press and its release, no drag
    rule.waitForIdle();
    CHECK((log == std::vector{T::Press, T::Release}) && near(value.peek(), 50));
    log.clear();
    // Gone while dragged: both cancelled.
    rule.host().pointerDown({110, 22});
    for (float x = 120; x <= 160; x += 10) rule.host().pointerMove({x, 22});
    rule.waitForIdle(0);
    shown.set(false);
    rule.waitForIdle(0);
    CHECK((log == std::vector{T::Press, T::DragStart, T::DragCancel, T::Cancel}) && !source.collectIsPressedAsState() &&
          !source.collectIsDraggedAsState());
    rule.host().pointerUp({160, 22});
    shown.set(true);
    rule.waitForIdle();
    log.clear();
    // The mouse over it: hovered (only then).
    rule.host().pointerMove({100, 22});
    rule.waitForIdle();
    CHECK(source.collectIsHoveredAsState() && (log == std::vector{T::HoverEnter}));
    Rect disabled = rule.onNodeWithTag("kapalı").bounds();
    rule.host().pointerMove({100, disabled.y + 22});
    rule.waitForIdle();
    CHECK(!source.collectIsHoveredAsState() && (log == std::vector{T::HoverEnter, T::HoverExit}));
    // A disabled one tells nothing.
    tap(rule, {100, disabled.y + 22});
    rule.waitForIdle();
    CHECK(offLog.empty());
}

TEST(slider_takes_only_touches_not_taken_and_keeps_those_it_takes) {
    using T = Interaction::Type;
    MutableInteractionSource source;
    std::vector<T> log;
    auto value = mutableStateOf(50.f);
    auto thumbTakes = mutableStateOf(0);  // what the thumb's own handler takes: 0 nothing, 1 moves, 2 presses
    ScrollState across, down;
    int outerClicks = 0;
    ComposeTestRule rule([&] {
        LogInteractions(source, log);
        Column(Modifier().fillMaxSize().verticalScroll(down), [&] {
            Row(Modifier().fillMaxWidth().horizontalScroll(across), [&] {
                Box(Modifier().clickable([&] { ++outerClicks; }), [&] {
                    Slider(value.get(), [value](float v) { value.set(v); }, Modifier().width(220),
                           {.valueFrom = 0, .valueTo = 100, .interactionSource = source, .thumb = [&](const SliderState& st) {
                                int takes = thumbTakes.get();
                                SliderDefaults::CircleThumb(st);
                                Box(Modifier().matchParentSize().pointerInput(takes, [takes](PointerInputScope& sc) -> Task {
                                    while (true) {
                                        PointerEvent e = co_await sc.awaitPointerEvent();
                                        if ((takes == 1 && e.type == PointerEventType::Move) || (takes == 2 && e.type == PointerEventType::Press))
                                            e.change.consume();
                                    }
                                }));
                            }});
                });
                Box(Modifier().size(1000, 48));
            });
            Box(Modifier().fillMaxWidth().height(2000));
        });
    });
    // The track runs from 10 to 210: x = 10 + 2 * value. A drag along it moves the thumb, not the
    // row it is in; a tap on it isn't the box's around it.
    slowDrag(rule, {60, 22}, {160, 22}, 20);
    CHECK(near(value.peek(), 75) && near(across.value(), 0));
    tap(rule, {110, 22});
    rule.waitForIdle();
    CHECK(near(value.peek(), 50) && outerClicks == 0);
    // Moves the thumb itself takes, it doesn't follow; a press the thumb takes, it doesn't take.
    thumbTakes.set(1);
    rule.waitForIdle();
    slowDrag(rule, {110, 22}, {190, 22}, 20);
    CHECK(near(value.peek(), 50));
    thumbTakes.set(2);
    rule.waitForIdle();
    log.clear();
    slowDrag(rule, {110, 22}, {190, 22}, 20);
    CHECK(near(value.peek(), 50) && log.empty());
    // A drag the column around it takes (down): the press is cancelled, not released.
    thumbTakes.set(0);
    rule.waitForIdle();
    log.clear();
    slowDrag(rule, {60, 22}, {60, 4}, 20);
    CHECK(down.value() > 0 && (log == std::vector{T::Press, T::Cancel}));
}

TEST(navigation_rail_items_take_their_options) {
    using T = Interaction::Type;
    ColorScheme cs;
    MutableInteractionSource own;
    std::vector<T> log;
    int clicks = 0;
    ComposeTestRule rule([&] {
        cs = colorScheme();
        LogInteractions(own, log);
        NavigationRail(Modifier(), {}, [&] {
            NavigationRailItem(false, [&] { ++clicks; }, [] { Icon(Icons::Filled::Home, "ev", Modifier().testTag("simge")); }, [] { Text("Kapalı"); },
                               Modifier().testTag("kapalı"), {.enabled = false});
            NavigationRailItem(false, [] {}, [] { Icon(Icons::Filled::List, "liste"); }, [] { Text("Kendi"); }, Modifier().testTag("kendi"),
                               {.interactionSource = own});
        });
    }, {400, 600});
    // The icon 4 dp down the item; disabled: onSurface at 38%, and a tap does nothing.
    Rect off = rule.onNodeWithTag("kapalı").bounds();
    CHECK(near(rule.onNodeWithTag("simge").bounds().y, off.y + 4));
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    Color label{};
    for (size_t i = 0; i < canvas.texts.size(); ++i)
        if (canvas.texts[i] == "Kapalı") label = canvas.colors[i];
    CHECK(near(label.a, cs.onSurface.a * 0.38f, 0.01f));
    tap(rule, off.center());
    rule.waitForIdle();
    CHECK(clicks == 0);
    // Its own interaction source hears its presses.
    tap(rule, rule.onNodeWithTag("kendi").bounds().center());
    rule.waitForIdle();
    CHECK(!log.empty() && log.front() == T::Press);
}

TEST(range_slider_tells_each_thumbs_source) {
    using T = Interaction::Type;
    MutableInteractionSource start, end;
    std::vector<T> startLog, endLog;
    auto range = mutableStateOf(std::pair(20.f, 80.f));
    ComposeTestRule rule([&] {
        LogInteractions(start, startLog);
        LogInteractions(end, endLog);
        RangeSlider(range.get(), [range](std::pair<float, float> v) { range.set(v); }, Modifier().width(220),
                    {.valueFrom = 0, .valueTo = 100, .interactionSource = start, .endInteractionSource = end});
    });
    auto x = [](float v) { return 10 + 2 * v; };
    tap(rule, {x(30), 22});  // nearer the start
    rule.waitForIdle();
    CHECK((startLog == std::vector{T::Press, T::Release}) && endLog.empty());
    startLog.clear();
    rule.swipe({x(70), 22}, {x(90), 22});  // the end, dragged
    rule.waitForIdle();
    CHECK(startLog.empty() && (endLog == std::vector{T::Press, T::DragStart, T::DragStop, T::Release}));
    CHECK(near(range.peek().first, 30) && near(range.peek().second, 90));
    endLog.clear();
    range.set({50, 50});  // together: the press is told once the drag's direction picks a thumb
    rule.waitForIdle();
    rule.host().pointerDown({x(50), 22});
    rule.waitForIdle(0);
    CHECK(startLog.empty() && endLog.empty());
    for (float d = 5; d <= 40; d += 5) rule.host().pointerMove({x(50) - d, 22});
    rule.waitForIdle(0);
    CHECK((startLog == std::vector{T::Press, T::DragStart}) && endLog.empty() && start.collectIsDraggedAsState());
    rule.host().pointerUp({x(50) - 40, 22});
    rule.waitForIdle();
    CHECK((startLog == std::vector{T::Press, T::DragStart, T::DragStop, T::Release}) && endLog.empty());
    CHECK(near(range.peek().first, 30) && near(range.peek().second, 50));
}

TEST(draggable_tells_its_drags_and_clickable_can_leave_out_the_indication) {
    using T = Interaction::Type;
    MutableInteractionSource source;
    std::vector<T> log;
    float moved = 0;
    ComposeTestRule rule([&] {
        LogInteractions(source, log);
        auto drag = rememberDraggableState([&](float d) { moved += d; });
        Column([&] {
            Box(Modifier().size(100).draggable(drag, Orientation::Horizontal, true, source).testTag("sürgü"));
            Box(Modifier().size(60).clickable([] {}, {.indication = false}).testTag("sade"));
            Box(Modifier().size(60).clickable([] {}).testTag("normal"));
        });
    });
    Offset c = centerOf(rule.onNodeWithTag("sürgü").bounds());
    rule.host().pointerDown(c);
    for (int i = 1; i <= 5; ++i) rule.host().pointerMove({c.x + 10.f * float(i), c.y});
    rule.waitForIdle(0);
    CHECK(source.collectIsDraggedAsState() && (log == std::vector{T::DragStart}) && moved > 0);
    rule.host().pointerUp({c.x + 50, c.y});
    rule.waitForIdle();
    CHECK(!source.collectIsDraggedAsState() && (log == std::vector{T::DragStart, T::DragStop}));
    auto overlaid = [&](const char* tag) {  // pressed: is anything (the ripple) drawn over it?
        Rect b = rule.onNodeWithTag(tag).bounds();
        testing::RecordingCanvas before, pressed;
        rule.host().draw(before);
        rule.host().pointerDown(centerOf(b));
        rule.advanceTimeBy(100);
        rule.host().draw(pressed);
        rule.host().pointerUp(centerOf(b));
        rule.waitForIdle();
        return pressed.rects.size() > before.rects.size();
    };
    CHECK(!overlaid("sade") && overlaid("normal"));
}

TEST(draggable_anchors_and_state_without_a_screen) {
    DraggableAnchors<int> anchors{{0, 0}, {1, 100}, {2, 250}};
    anchors.at(1, 120);  // replaced
    CHECK(anchors.size() == 3 && anchors.positionOf(1) == 120.f && !anchors.positionOf(5) && anchors.minPosition() == 0 && anchors.maxPosition() == 250);
    CHECK(anchors.closestAnchor(70) == 1 && anchors.closestAnchor(50) == 0 && anchors.closestAnchor(70, false) == 0 && anchors.closestAnchor(130, true) == 2);
    CHECK(!anchors.closestAnchor(260, true) && anchors.closestAnchor(260, false) == 2);
    AnchoredDraggableState<int> state(0, DraggableAnchors<int>{{0, 0}, {1, 100}});
    CHECK(state.offset() == 0 && state.currentValue() == 0 && state.targetValue() == 0);
    CHECK(state.dispatchRawDelta(25) == 25 && near(state.progress(0, 1), 0.25f) && state.targetValue() == 1 && state.currentValue() == 0);
    CHECK(state.dispatchRawDelta(1000) == 75 && state.offset() == 100 && state.currentValue() == 1);  // kept within; on an anchor: its value
    CHECK(state.dispatchRawDelta(-30) == -30 && state.targetValue() == 0 && state.settledValue() == 0);  // settled only by settling
    state.snapTo(1);
    CHECK(state.offset() == 100 && state.settledValue() == 1 && state.targetValue() == 1);
    AnchoredDraggableState<int> three(0, anchors);
    three.dispatchRawDelta(90);  // nearer the next anchor, not on it: still the first value
    CHECK(three.currentValue() == 0 && three.targetValue() == 1);
    three.dispatchRawDelta(85);  // 175: past `to`, the progress stays 1
    CHECK(near(three.progress(0, 1), 1, 0.001f) && near(three.progress(1, 2), 55.f / 130.f, 0.001f));
    AnchoredDraggableState<int> later(1);  // no anchors yet: no offset, its value waits
    CHECK(std::isnan(later.offset()) && later.requireOffset() == 0 && later.dispatchRawDelta(10) == 0);
    later.updateAnchors({{0, 0}, {1, 80}});
    CHECK(later.offset() == 80 && later.currentValue() == 1);
    auto restored = Saver<AnchoredDraggableState<int>>::restore(Saver<AnchoredDraggableState<int>>::save(later));  // its value is saved
    CHECK(restored && restored->currentValue() == 1);
}

TEST(anchored_draggable_follows_the_finger_and_settles_on_an_anchor) {
    enum class Spot { Start, Middle, End };
    std::optional<AnchoredDraggableState<Spot>> state;
    std::optional<CoroutineScope> scope;
    auto width = mutableStateOf(356.f);
    ComposeTestRule rule([&] {
        auto s = rememberAnchoredDraggableState(Spot::Start, {.confirmValueChange = [](const Spot& v) { return v != Spot::End; }});
        state = s;
        scope = rememberCoroutineScope();
        Column([&] {
            Box(Modifier().width(width.get()).height(56).onSizeChanged([s](Size size) {
                s.updateAnchors({{Spot::Start, 0}, {Spot::Middle, (size.width - 56) / 2}, {Spot::End, size.width - 56}});
            }), [&] {
                Box(Modifier().offset([s] { return Offset{s.requireOffset(), 0}; }).anchoredDraggable(s, Orientation::Horizontal).size(56),
                    [] { Box(Modifier().fillMaxSize().testTag("tutamak")); });
            });
            Text(std::format("şimdi {} hedef {}", int(s.currentValue()), int(s.targetValue())));
        });
    });
    AnchoredDraggableState<Spot> s = *state;
    auto x = [&] { return rule.onNodeWithTag("tutamak").bounds().x; };
    auto drag = [&](std::initializer_list<float> steps) {  // then held still: released without speed
        Offset c{x() + 28, 28};
        rule.host().pointerDown(c);
        for (float d : steps) rule.host().pointerMove({c.x + d, c.y});
        rule.advanceTimeBy(150);
        return Offset{c.x + *(steps.end() - 1), c.y};
    };
    CHECK(x() == 0 && s.anchors().positionOf(Spot::End) == 300.f);
    Offset up = drag({20, 40, 60});  // the first step is the touch slop: 40 dp
    CHECK(near(x(), 40) && rule.onNodeWithText("şimdi 0 hedef 1").exists());
    rule.host().pointerUp(up);  // not half way: back
    rule.waitForIdle();
    CHECK(x() == 0 && s.currentValue() == Spot::Start && rule.onNodeWithText("şimdi 0 hedef 0").exists());
    up = drag({20, 60, 120});  // 100 of 150: on to the middle
    rule.host().pointerUp(up);
    rule.waitForIdle();
    CHECK(x() == 150 && s.currentValue() == Spot::Middle && s.settledValue() == Spot::Middle);
    up = drag({20, 60, 120});  // past half way to the end, which isn't allowed: back
    rule.host().pointerUp(up);
    rule.waitForIdle();
    CHECK(x() == 150 && s.currentValue() == Spot::Middle);
    rule.swipe({x() + 28, 28}, {x() - 2, 28}, 3);  // flung: 20 dp is enough
    rule.waitForIdle();
    CHECK(x() == 0 && s.currentValue() == Spot::Start && s.lastVelocity() < -125);
    rule.host().scroll({x() + 28, 28}, 0, -5);  // the wheel doesn't move it
    CHECK(s.offset() == 0);
    scope->launch([s]() -> Task { co_await s.animateTo(Spot::Middle); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(s.isAnimationRunning() && s.offset() > 0);
    drag({-20, -30});  // the user takes over: the animation stops
    CHECK(!s.isAnimationRunning());
    rule.host().pointerUp({x() + 28, 28});
    rule.waitForIdle();
    CHECK(x() == 0 && s.currentValue() == Spot::Start);
    scope->launch([s]() -> Task { co_await s.animateTo(Spot::End); });  // from code: no confirmation asked
    rule.advanceFrame();
    CHECK(s.isAnimationRunning() && s.targetValue() == Spot::End && s.currentValue() == Spot::Start);
    rule.waitForIdle();
    CHECK(x() == 300 && s.currentValue() == Spot::End && !s.isAnimationRunning());
    s.snapTo(Spot::Middle);
    rule.waitForIdle();
    CHECK(x() == 150 && rule.onNodeWithText("şimdi 1 hedef 1").exists());
    width.set(200);  // new anchors: it stays at its value, where that is now (not the anchor nearest 150)
    rule.waitForIdle();
    CHECK(x() == 72 && s.currentValue() == Spot::Middle);
}

TEST(anchored_draggable_keeps_its_drag_from_the_scrollables_around_it) {
    std::optional<AnchoredDraggableState<int>> state;
    ScrollState scroll;
    ComposeTestRule rule([&] {
        auto s = rememberAnchoredDraggableState(0);
        state = s;
        Row(Modifier().fillMaxWidth().horizontalScroll(scroll), [&] {
            Box(Modifier().width(200).height(56), [&] {
                Box(Modifier().offset([s] { return Offset{s.requireOffset(), 0}; }).anchoredDraggable(s, Orientation::Horizontal).size(56),
                    [] { Box(Modifier().fillMaxSize().testTag("tutamak")); });
            });
            Box(Modifier().width(800).height(56));
        });
        s.updateAnchors({{0, 0}, {1, 144}});
    });
    rule.host().pointerDown({28, 28});
    for (float d : {20.f, -20.f, -60.f, -100.f}) rule.host().pointerMove({28 + d, 28});  // past its start: nothing left for the row
    CHECK(state->offset() == 0 && scroll.value() == 0);
    for (float d : {-60.f, 40.f, 120.f, 400.f}) rule.host().pointerMove({28 + d, 28});  // past its end too
    CHECK(state->offset() == 144 && scroll.value() == 0);
    rule.host().pointerUp({428, 28});
    rule.waitForIdle();
    CHECK(state->currentValue() == 1 && scroll.value() == 0);
}

TEST(ripple_spreads_from_the_press_and_fades_once_let_go) {
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().size(200, 100).clickable([] {}).testTag("kutu"));
            Box(Modifier().size(100).clickable([] {}, {.indication = ripple(false, 30)}).testTag("sınırsız"));
            Box(Modifier().size(100).clickable([] {}, {.indication = Indication::Kind::StateLayer}).testTag("düz"));
            CompositionLocalProvider({LocalIndication.provides(false)}, [] { Box(Modifier().size(100).clickable([] {}).testTag("yok")); });
        });
    });
    float alpha = 0;  // the last ripple's, as drawn
    auto circles = [&] {  // the ripples drawn now (squares round as circles)
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        std::vector<Rect> out;
        for (size_t i = 0; i < canvas.rects.size(); ++i)
            if (const Rect& r = canvas.rects[i]; near(r.width, r.height, 0.01f) && r.width > 0) {
                out.push_back(r);
                alpha = canvas.rectColors[i].a;
            }
        return std::pair(out, canvas);
    };
    Rect b = rule.onNodeWithTag("kutu").bounds();
    rule.host().pointerDown({b.x + 20, b.y + 20});
    rule.advanceFrame();
    rule.advanceFrame();
    auto [early, _] = circles();
    CHECK(early.size() == 1);
    if (early.size() == 1) {  // small, near the press
        Offset c = centerOf(early[0]);
        CHECK(early[0].width / 2 < 80 && early[0].width / 2 >= 60 && c.x < b.x + 60 && c.y < b.y + 45);
    }
    rule.advanceTimeBy(300);  // spread: to the farthest corner, around the middle; held, it stays (and nothing moves)
    auto [spread, canvas] = circles();
    CHECK(spread.size() == 1 && !rule.host().hasPendingWork());
    if (spread.size() == 1) {
        Offset c = centerOf(spread[0]);
        CHECK(near(spread[0].width / 2, std::hypot(200.f, 100.f) / 2, 0.5f) && near(c.x, b.x + 100) && near(c.y, b.y + 50));
    }
    CHECK(std::ranges::any_of(canvas.clips, [&](const Rect& r) { return near(r.x, b.x) && near(r.width, b.width); }));  // clipped to it
    float held = alpha;
    rule.host().pointerUp({b.x + 20, b.y + 20});
    rule.advanceTimeBy(80);
    CHECK(circles().first.size() == 1 && alpha < held * 0.8f && alpha > 0);  // fading
    rule.waitForIdle();
    CHECK(circles().first.empty() && !rule.host().hasPendingWork());
    rule.host().keyDown(Key::Tab);  // the keyboard: Enter's ripple comes from the middle
    rule.host().keyDown(Key::Enter);
    rule.advanceFrame();
    rule.advanceFrame();
    auto [keyed, keyCanvas] = circles();
    CHECK(keyed.size() == 1 && near(centerOf(keyed.empty() ? Rect{} : keyed[0]).x, b.x + 100, 2));
    rule.waitForIdle();
    CHECK(circles().first.empty());
    rule.host().pointerDown({b.x + 20, b.y + 90});  // ends the keyboard focus
    rule.host().pointerUp({b.x + 20, b.y + 90});
    rule.waitForIdle();
    Rect u = rule.onNodeWithTag("sınırsız").bounds();  // unbounded: from the middle, its own radius, not clipped
    rule.host().pointerDown({u.x + 10, u.y + 10});
    rule.advanceFrame();
    rule.advanceFrame();
    auto [start, startCanvas] = circles();  // from the middle at once, not from the press
    CHECK(start.size() == 1 && near(centerOf(start.empty() ? Rect{} : start[0]).x, u.x + 50, 1));
    rule.advanceTimeBy(300);
    auto [wide, wideCanvas] = circles();
    CHECK(wide.size() == 1 && wideCanvas.clips.empty());
    if (wide.size() == 1) CHECK(near(wide[0].width / 2, 30, 0.5f) && near(centerOf(wide[0]).x, u.x + 50) && near(centerOf(wide[0]).y, u.y + 50));
    rule.host().pointerUp({u.x + 10, u.y + 10});
    rule.waitForIdle();
    Rect f = rule.onNodeWithTag("düz").bounds();  // a state layer: the whole of it, no circle
    rule.host().pointerDown(centerOf(f));
    rule.advanceTimeBy(100);
    testing::RecordingCanvas flat;
    rule.host().draw(flat);
    auto whole = [&](const Rect& r) { return near(r.x, f.x) && near(r.y, f.y) && near(r.width, f.width); };
    CHECK(std::ranges::any_of(flat.rects, whole) && std::ranges::all_of(circles().first, whole));
    rule.host().pointerUp(centerOf(f));
    rule.waitForIdle();
    Rect n = rule.onNodeWithTag("yok").bounds();  // LocalIndication says none
    testing::RecordingCanvas before, after;
    rule.host().draw(before);
    rule.host().pointerDown(centerOf(n));
    rule.advanceTimeBy(100);
    rule.host().draw(after);
    CHECK(after.rects.size() == before.rects.size());
    rule.host().pointerUp(centerOf(n));
    rule.waitForIdle();
}

TEST(a_lifted_finger_leaves_no_hover_highlight) {
    ComposeTestRule rule([&] { Box(Modifier().size(100).clickable([] {}).testTag("kutu")); });
    Rect b = rule.onNodeWithTag("kutu").bounds();
    auto highlighted = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        return std::ranges::any_of(canvas.rects, [&](const Rect& r) { return near(r.x, b.x) && near(r.y, b.y) && near(r.width, b.width); });
    };
    rule.host().pointerDown(centerOf(b));  // a tap with a finger
    rule.host().pointerUp(centerOf(b));
    rule.waitForIdle();
    CHECK(!highlighted());
    rule.host().pointerMove(centerOf(b));  // the mouse over it
    rule.waitForIdle();
    CHECK(highlighted());
}

TEST(lazy_list_layout_info_tells_what_is_in_view) {
    LazyListState state, headed;
    int compositions = 0;
    ComposeTestRule rule([&] {
        Column([&] {
            auto info = state.layoutInfo();
            ++compositions;
            int last = info.visibleItemsInfo.empty() ? -1 : info.visibleItemsInfo.back().index;
            Text(std::format("son {} / {}", last, info.totalItemsCount));
            LazyColumn(Modifier().fillMaxWidth().height(200), {.state = state, .contentPadding = {0, 10, 0, 10}, .spacing = 4}, [&](LazyListScope& l) {
                l.item("başlık", "header", [] { Box(Modifier().height(40)); });
                l.items(30, [](int i) { return size_t(i); }, [](int) { return size_t(7); }, [](int) { Box(Modifier().height(36)); });
            });
            LazyColumn(Modifier().fillMaxWidth().height(100), {.state = headed}, [&](LazyListScope& l) {
                l.stickyHeader([] { Box(Modifier().height(20)); });
                l.items(20, [](int) { Box(Modifier().height(30)); });
            });
        });
    });
    LazyListLayoutInfo info = state.layoutInfo();
    CHECK(info.totalItemsCount == 31 && info.viewportStartOffset == -10 && info.viewportEndOffset == 190 && info.beforeContentPadding == 10 &&
          info.afterContentPadding == 10 && info.mainAxisItemSpacing == 4 && info.orientation == Orientation::Vertical && info.viewportSize.height == 200);
    CHECK(info.visibleItemsInfo.size() == 5 && rule.onNodeWithText("son 4 / 31").exists());  // 164..200 shows in the bottom padding
    if (info.visibleItemsInfo.size() == 5) {
        const auto& v = info.visibleItemsInfo;
        CHECK(v[0].index == 0 && v[0].offset == 0 && v[0].size == 40 && v[0].contentType == LazyListScope::typeHash("header"));
        CHECK(v[1].index == 1 && v[1].offset == 44 && v[1].size == 36 && v[1].contentType == 7 && v[4].offset == 164);
        CHECK(v[1].key != v[2].key);
    }
    state.scrollToItem(10, 6);  // partly scrolled out at the top: a negative offset
    rule.waitForIdle();
    info = state.layoutInfo();
    CHECK(!info.visibleItemsInfo.empty() && info.visibleItemsInfo[0].index == 10 && info.visibleItemsInfo[0].offset == -6);
    CHECK(rule.onNodeWithText("son 14 / 31").exists());  // 154..190 is the last in view
    int before = compositions;
    rule.waitForIdle();  // nothing moved: nothing told
    CHECK(compositions == before);
    headed.scrollToItem(5);  // the pinned header comes first, at the top
    rule.waitForIdle();
    auto h = headed.layoutInfo().visibleItemsInfo;
    CHECK(h.size() >= 2 && h[0].index == 0 && h[0].offset == 0 && h[1].index == 5);
}

TEST(text_measurer_lays_text_out_for_drawing) {
    std::optional<TextLayoutMeasurer> measurer;
    std::optional<TextLayoutResult> drawn;
    ComposeTestRule rule([&] {
        auto m = rememberTextMeasurer();
        measurer = m;
        Canvas(Modifier().size(200, 100).testTag("tuval"), [m, &drawn](DrawScope& d) {
            drawn = m.measure("Merhaba dünya", {.fontSize = 20});
            d.drawText(*drawn, {10, 20});
            d.drawText(*drawn, {10, 60}, Color::hex(0xD32F2F));
            d.drawText(m, "kısa", {150, 0}, {.fontSize = 10});
        });
    });
    // The fake measurer: a code point is half the font size wide; ascent 0.8, line height 1.25 of it.
    TextLayoutResult one = measurer->measure("Merhaba dünya", {.fontSize = 20});
    CHECK(one.size().width == 130 && one.size().height == 25 && one.lineCount() == 1 && one.firstBaseline() == 16 && !one.hasVisualOverflow());
    TextLayoutResult two = measurer->measure("Merhaba dünya", {.fontSize = 20, .textAlign = TextAlign::Center}, 80);
    CHECK(two.lineCount() == 2 && two.size().width == 80 && two.size().height == 50);  // wrapped: as wide as it may be
    CHECK(two.getLineStart(0) == 0 && two.getLineEnd(0) == 7 && two.getLineStart(1) == 8 && two.getLineEnd(1) == 14);
    CHECK(two.getLineTop(1) == 25 && two.getLineBottom(1) == 50 && two.getLineBaseline(1) == 41 && two.lastBaseline() == 41);
    CHECK(two.getLineLeft(0) == 5 && two.getLineLeft(1) == 15 && two.getLineRight(1) == 65);  // centered in 80
    CHECK(two.getLineForOffset(3) == 0 && two.getLineForOffset(10) == 1 && two.getLineForOffset(14) == 1);
    CHECK(two.getLineForVerticalPosition(10) == 0 && two.getLineForVerticalPosition(30) == 1 && two.getLineForVerticalPosition(99) == 1);
    CHECK(two.getOffsetForPosition({20, 30}) == 8 && two.getOffsetForPosition({16, 5}) == 1 && two.getOffsetForPosition({200, 30}) == 14);
    Rect d = two.getBoundingBox(8), u = two.getBoundingBox(9);  // "d", then "ü" (two bytes)
    CHECK(d.x == 15 && d.y == 25 && d.width == 10 && d.height == 25 && u.x == 25 && u.width == 10);
    Rect caret = two.getCursorRect(9);
    CHECK(caret.x == 25 && caret.y == 25 && caret.height == 25 && caret.width == 0);
    auto selected = two.getSelectionRects(3, 10);  // "hab", the line break's mark, "dü"
    CHECK(selected.size() == 3 && two.getBoundingBox(14).width == 0);
    if (selected.size() == 3) CHECK(selected[0].x == 35 && selected[0].width == 40 && selected[2].x == 15 && selected[2].y == 25 && selected[2].width == 20);
    TextLayoutResult cut = measurer->measure("Merhaba dünya", {.fontSize = 20, .maxLines = 1, .overflow = TextOverflow::Ellipsis}, 80);
    CHECK(cut.lineCount() == 1 && cut.isLineEllipsized(0) && cut.didOverflowHeight() && !cut.didOverflowWidth() && cut.hasVisualOverflow());
    TextLayoutResult wide = measurer->measure("Merhaba dünya", {.fontSize = 20, .softWrap = false}, 80);
    CHECK(wide.didOverflowWidth() && !wide.didOverflowHeight() && wide.lineCount() == 1);
    TextLayoutResult tall = measurer->measure("a\nb\nc", {.fontSize = 20}, kInfinity, 60);
    CHECK(tall.lineCount() == 3 && tall.didOverflowHeight() && !tall.isLineEllipsized(2));
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    Rect at = rule.onNodeWithTag("tuval").bounds();
    std::vector<size_t> where;
    for (size_t i = 0; i < canvas.texts.size(); ++i)
        if (canvas.texts[i] == "Merhaba dünya" || canvas.texts[i] == "kısa") where.push_back(i);
    CHECK(where.size() == 3);
    if (where.size() == 3) {
        CHECK(near(canvas.baselines[where[0]].x, at.x + 10) && near(canvas.baselines[where[0]].y, at.y + 36));
        CHECK(canvas.colors[where[1]] == Color::hex(0xD32F2F) && near(canvas.baselines[where[1]].y, at.y + 76));
        CHECK(canvas.fonts[where[2]].size == 10 && near(canvas.baselines[where[2]].x, at.x + 150));
    }
}

TEST(text_tells_how_it_was_laid_out) {
    int calls = 0;
    std::optional<TextLayoutResult> last;
    auto width = mutableStateOf(100.f);
    auto cut = mutableStateOf(false);
    auto other = mutableStateOf(0);
    ComposeTestRule rule([&] {
        Column([&] {
            other.get();
            Text("bir iki üç dört beş altı yedi sekiz dokuz on", Modifier().width(width.get()),
                 {.fontSize = 10, .maxLines = 2, .overflow = TextOverflow::Ellipsis}, [&, cut](const TextLayoutResult& r) {
                     ++calls;
                     last = r;
                     cut.set(r.hasVisualOverflow());
                 });
            if (cut.get()) Text("devamını oku");
        });
    });
    CHECK(calls == 1 && last && last->lineCount() == 2 && last->isLineEllipsized(1) && rule.onNodeWithText("devamını oku").exists());
    other.set(1);  // composed again, laid out the same: not told again
    rule.waitForIdle();
    CHECK(calls == 1);
    width.set(400);  // all of it fits now
    rule.waitForIdle();
    CHECK(calls == 2 && last->lineCount() == 1 && !last->hasVisualOverflow() && !rule.onNodeWithText("devamını oku").exists());
    CHECK(last->getLineForOffset(int(last->text().size())) == 0 && last->size().width == 400);  // as wide as its node
}

TEST(flings_go_along_androids_spline) {
    ScrollState scroll;
    ComposeTestRule rule([&] {
        Column(Modifier().size(200, 400).verticalScroll(scroll), [] { Box(Modifier().fillMaxWidth().height(20000)); });
    });
    auto flick = [&](float distance, int frames) {  // a steady finger up, let go: how far the fling went, and for how long
        scroll.scrollTo(0);
        rule.waitForIdle();
        rule.swipe({100, 380}, {100, 380 - distance}, frames);
        float released = scroll.value(), last = released;
        int ms = 0, still = 0;
        while (still < 3 && ms < 10000) {  // till it stops moving
            rule.advanceFrame();
            ms += 16;
            still = scroll.value() == last ? still + 1 : 0;
            last = scroll.value();
        }
        return std::pair{scroll.value() - released, ms - 3 * 16};
    };
    auto [slow, slowMs] = flick(160, 16);   // 625 dp/s
    auto [fast, fastMs] = flick(320, 8);    // 2500 dp/s
    // As far and as long as the spline says for those speeds (as the finger's speed is measured,
    // a little under): four times as fast, eleven times as far (an exponential decay: four).
    float slowSpline = detail::splineFlingDistance(625), fastSpline = detail::splineFlingDistance(2500);
    CHECK(near(slow, slowSpline, 0.15f * slowSpline) && near(fast, fastSpline, 0.1f * fastSpline) && fast > 9 * slow);
    CHECK(std::abs(slowMs - detail::splineFlingDurationMillis(625)) < 50 && std::abs(fastMs - detail::splineFlingDurationMillis(2500)) < 50);
}

TEST(animatable_carries_a_velocity_into_springs_and_decays) {
    DecayAnimationSpec decay = exponentialDecay();
    CHECK(near(decay.velocityAt(420, 0), 420) && near(decay.calculateTargetValue(0, 420), 100, 0.05f) && near(decay.durationMillis(420), 1987, 2));
    CHECK(near(decay.valueAt(10, -420, 1e6f), -90, 0.05f) && decay.durationMillis(0.05f) == 0);
    // Android's fling spline (OverScroller's numbers, in dp): it starts at the velocity given and
    // goes much further the faster it is.
    DecayAnimationSpec fling = splineBasedDecay();
    CHECK(near(fling.calculateTargetValue(0, 3200), 1464.1f, 1) && near(fling.durationMillis(3200), 1307, 2) && near(fling.velocityAt(3200, 0), 3200, 10));
    CHECK(near(fling.valueAt(0, 3200, 1400), 1464.1f, 1) && near(fling.calculateTargetValue(100, -2000), 100 - 647.4f, 1) && fling.velocityAt(3200, 1400) == 0);
    CHECK(fling.valueAt(0, 3200, 300) > 600 && fling.velocityAt(3200, 300) < 3200 && fling.velocityAt(3200, 300) > 0);
    CHECK(near(fling.valueAt(0, 3200, 0.995f * fling.durationMillis(3200)), 1464.1f, 2));  // all but there at the very end
    CHECK(fling.calculateTargetValue(0, 8000) > 10 * fling.calculateTargetValue(0, 2000) && near(fling.calculateTargetValue(0, 1000), 194.3f, 0.5f));
    float x = 0, v = 0;
    spring().springMotion(10, 0, 100, x, v);  // from rest at the target, pushed: it moves that way first
    CHECK(x > 0 && v > 0);
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] { scope = rememberCoroutineScope(); });
    Animatable<float> a(0.f);
    scope->launch([a]() -> Task { co_await a.animateDecay(1000, exponentialDecay()); });
    rule.advanceFrame();
    rule.advanceFrame();
    float v1 = a.velocity(), p1 = a.peek();
    rule.advanceTimeBy(200);
    CHECK(p1 > 0 && v1 > 0 && a.velocity() < v1 && a.peek() > p1 && a.isRunning());
    rule.advanceTimeBy(3000);
    CHECK(!a.isRunning() && a.velocity() == 0 && near(a.peek(), 1000 / 4.2f, 0.5f) && near(a.targetValue(), 1000 / 4.2f, 0.5f));
    a.snapTo(0);
    a.updateBounds(0.f, 100.f);  // a bound ends it there
    scope->launch([a]() -> Task { co_await a.animateDecay(1000, exponentialDecay()); });
    rule.advanceTimeBy(500);
    CHECK(!a.isRunning() && a.peek() == 100 && a.velocity() == 0 && a.targetValue() == 100);
    a.snapTo(250);
    CHECK(a.peek() == 100);  // kept within
    a.updateBounds(std::nullopt, std::nullopt);
    a.snapTo(0);
    float most = 0;  // thrown from the target: a spring carries it out and back
    scope->launch([a]() -> Task { co_await a.animateTo(0.f, spring(), 2000.f); });
    for (int i = 0; i < 60; ++i) {
        rule.advanceFrame();
        most = std::max(most, a.peek());
    }
    CHECK(most > 15 && a.peek() == 0 && !a.isRunning());  // v0 / (e * sqrt(stiffness)): about 19 dp
    scope->launch([a]() -> Task { co_await a.animateTo(100.f, tween(160)); });  // a tween's speed, measured
    rule.advanceFrame();
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(a.velocity() > 100);
    rule.waitForIdle();
    CHECK(a.peek() == 100 && a.velocity() == 0);
}

TEST(velocity_tracker_measures_the_last_stretch) {
    VelocityTracker t;
    for (int i = 0; i <= 5; ++i) t.addPosition(1000 + i * 10, {float(i) * 10, float(i) * -5});
    Offset v = t.calculateVelocity();
    CHECK(near(v.x, 1000, 1) && near(v.y, -500, 1));
    t.addPosition(1200, {50, -25});  // stood still for a while: nothing
    CHECK(t.calculateVelocity().x == 0 && t.calculateVelocity().y == 0);
    for (int i = 1; i <= 20; ++i) t.addPosition(1200 + i * 10, {50 + float(std::max(0, i - 10)) * 20.f, -25});  // only the last 100 ms count
    CHECK(near(t.calculateVelocity().x, 2000, 5));
    t.resetTracking();
    t.addPosition(5, {1, 1});
    CHECK(t.calculateVelocity().x == 0);
    VelocityTracker paused;  // moved, then held 45 ms (within the 100): the pause ends it
    for (int i = 0; i <= 5; ++i) paused.addPosition(i * 10, {float(i) * 10, 0});
    paused.addPosition(95, {50, 0});
    CHECK(paused.calculateVelocity().x == 0);
}

TEST(draggable_tells_the_velocity_it_was_let_go_with) {
    float velocity = -1;
    int plain = 0;
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().size(300, 60).draggable(rememberDraggableState([](float) {}, [&](float v) { velocity = v; }), Orientation::Horizontal)
                    .testTag("hızlı"));
            Box(Modifier().size(300, 60).draggable(rememberDraggableState([](float) {}, [&] { ++plain; }), Orientation::Vertical).testTag("düz"));
        });
    });
    Rect b = rule.onNodeWithTag("hızlı").bounds();
    rule.swipe({b.x + 20, b.y + 30}, {b.x + 220, b.y + 30}, 5);  // 200 dp in 80 ms
    CHECK(velocity > 1500 && velocity < 4000);
    velocity = -1;
    rule.host().pointerDown({b.x + 200, b.y + 30});  // then held still: none
    for (float d : {-20.f, -40.f, -60.f}) rule.host().pointerMove({b.x + 200 + d, b.y + 30});
    rule.advanceTimeBy(200);
    rule.host().pointerUp({b.x + 140, b.y + 30});
    rule.waitForIdle();
    CHECK(velocity == 0);
    Rect p = rule.onNodeWithTag("düz").bounds();
    rule.swipe({p.x + 20, p.y + 5}, {p.x + 20, p.y + 55}, 5);
    CHECK(plain == 1);
}

TEST(anchored_draggable_settles_with_the_flings_speed_within_its_ends) {
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] { scope = rememberCoroutineScope(); });
    auto make = [] { return AnchoredDraggableState<int>(0, DraggableAnchors<int>{{0, 0}, {1, 100}}); };
    AnchoredDraggableState<int> slow = make(), fast = make();
    slow.dispatchRawDelta(60);
    fast.dispatchRawDelta(60);
    scope->launch([slow]() -> Task { co_await slow.settle(0); });
    scope->launch([fast]() -> Task { co_await fast.settle(6000); });
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(fast.offset() > slow.offset());  // it goes on at the speed it was flung
    float most = 0;
    for (int i = 0; i < 60; ++i) {
        rule.advanceFrame();
        most = std::max(most, fast.offset());
    }
    CHECK(most <= 100 && fast.offset() == 100 && slow.offset() == 100 && fast.currentValue() == 1 && fast.lastVelocity() == 6000);
}

TEST(keyframes_go_through_their_frames) {
    AnimationSpec k = keyframes(400, {{300, 1.2f}, {100, 0.5f, FastOutSlowInEasing}});  // sorted by time
    bool done = false;
    CHECK(near(k.progress(0, done), 0, 0.001f) && near(k.progress(50, done), 0.25f, 0.001f) && near(k.progress(100, done), 0.5f, 0.001f));
    float mid = k.progress(200, done);  // eased from 0.5 to 1.2: past the linear middle
    CHECK(mid > 0.85f && mid < 1.2f && near(k.progress(300, done), 1.2f, 0.001f) && near(k.progress(350, done), 1.1f, 0.001f) && !done);
    CHECK(k.progress(400, done) == 1 && done);
    AnimationSpec start = keyframes(200, {{0, 0.5f}, {200, 0.8f}});  // frames at the ends replace 0 and 1
    CHECK(near(start.progress(0, done), 0.5f, 0.001f) && near(start.progress(100, done), 0.65f, 0.001f));
    AnimationSpec back = repeatable(2, keyframes(100, {{50, 1}}), RepeatMode::Reverse);  // up, then the frames backwards
    CHECK(near(back.progress(50, done), 1, 0.001f) && near(back.progress(125, done), 1, 0.001f) && near(back.progress(175, done), 0.5f, 0.001f));
    CHECK(near(keyframes(100, {{50, 1}}, 20).progress(10, done), 0, 0.001f));  // waits its delay
    // For floats the values are values: a pulse from 1 to 1 through 1.3 and 0.9.
    AnimationSpec pulse = keyframes(400, {{100, 1.3f}, {250, 0.9f}});
    CHECK(near(pulse.valueAt(0, 1, 1, done), 1, 0.001f) && near(pulse.valueAt(100, 1, 1, done), 1.3f, 0.001f) &&
          near(pulse.valueAt(175, 1, 1, done), 1.1f, 0.001f) && near(pulse.valueAt(325, 1, 1, done), 0.95f, 0.001f) && !done);
    CHECK(pulse.valueAt(500, 1, 1, done) == 1 && done);
    CHECK(near(tween(100, 0, LinearEasing).valueAt(25, 10, 20, done), 12.5f, 0.001f));  // the others along the progress
    AnimationSpec swing = repeatable(2, keyframes(100, {{50, 5}}), RepeatMode::Reverse);
    CHECK(near(swing.valueAt(25, 0, 10, done), 2.5f, 0.001f) && near(swing.valueAt(175, 0, 10, done), 2.5f, 0.001f) &&
          near(swing.valueAt(130, 0, 10, done), 7, 0.001f) && swing.valueAt(250, 0, 10, done) == 0);  // back at 70 ms: 5 to 10, 2/5 on
    std::optional<CoroutineScope> scope;
    ComposeTestRule rule([&] { scope = rememberCoroutineScope(); });
    Animatable<float> scale(1.f);
    float most = 1;
    scope->launch([scale]() -> Task { co_await scale.animateTo(1.f, keyframes(400, {{100, 1.3f}, {250, 0.9f}})); });
    for (int i = 0; i < 30; ++i) {
        rule.advanceFrame();
        most = std::max(most, scale.peek());
    }
    CHECK(most > 1.25f && scale.peek() == 1 && !scale.isRunning());
    auto to = mutableStateOf(0.f);  // animateFloatAsState too: from 0 to 10 through 5 (not halfway's 50)
    float seen = 0, peak = 0;
    ComposeTestRule state([&] {
        seen = animateFloatAsState(to.get(), keyframes(400, {{100, 5}, {200, 5}}));
        peak = std::max(peak, seen);
    });
    to.set(10);
    state.waitForIdle();
    CHECK(seen == 10 && peak == 10);  // 5, 5, then up to 10
    to.set(0);
    state.advanceTimeBy(150);
    CHECK(near(seen, 5, 0.3f));
}

TEST(animated_content_picks_its_transition_from_the_states_and_animates_its_size) {
    auto n = mutableStateOf(5);
    auto big = mutableStateOf(false);
    auto sized = mutableStateOf(true);
    ComposeTestRule rule([&] {
        Column([&] {
            // Up: faded in from 0.2; down: from 0.6 (to tell them apart).
            AnimatedContent<int>(n.get(), [](const int& v) { Text(std::format("sayı {}", v)); }, Modifier().testTag("sayaç"),
                                 [](const int& from, const int& to) {
                                     return togetherWith(fadeIn(to > from ? 0.2f : 0.6f, tween(300)), fadeOut(0, tween(300)));
                                 });
            AnimatedContent<bool>(big.get(), [](const bool& b) { Box(Modifier().size(b ? 300.f : 100.f, b ? 150.f : 50.f)); },
                                  Modifier().testTag("kutu"),
                                  sized.get() ? togetherWith(fadeIn(0, tween(300)), fadeOut(0, tween(300))).withSizeTransform(SizeTransform{.spec = tween(320)})
                                              : togetherWith(fadeIn(0, tween(300)), fadeOut(0, tween(300))).withSizeTransform(std::nullopt));
        });
    });
    auto firstAlpha = [&](const char* text) {  // the alpha of the layer the newest text is drawn in
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        float a = -1;
        for (float alpha : canvas.layerAlphas) a = alpha;
        (void)text;
        return a;
    };
    n.set(6);
    rule.advanceFrame();
    float up = firstAlpha("sayı 6");
    rule.waitForIdle();
    n.set(4);
    rule.advanceFrame();
    float down = firstAlpha("sayı 4");
    rule.waitForIdle();
    CHECK(up > 0.15f && up < 0.4f && down > 0.55f && down < 0.8f);
    CHECK(rule.onNodeWithTag("kutu").bounds().width == 100);
    big.set(true);
    rule.advanceFrame();
    rule.advanceTimeBy(160);
    Rect half = rule.onNodeWithTag("kutu").bounds();
    CHECK(half.width > 110 && half.width < 290 && half.height > 55 && half.height < 145);
    testing::RecordingCanvas clipped;
    rule.host().draw(clipped);
    CHECK(std::ranges::any_of(clipped.clips, [&](const Rect& r) { return near(r.x, half.x) && near(r.width, half.width); }));
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("kutu").bounds().width == 300 && rule.onNodeWithTag("kutu").bounds().height == 150);
    sized.set(false);  // no SizeTransform: as big as the contents shown (both, while they cross)
    big.set(false);
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(rule.onNodeWithTag("kutu").bounds().width == 300);
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("kutu").bounds().width == 100);
}

TEST(animated_content_aligns_its_contents_and_keeps_same_key_content) {
    auto big = mutableStateOf(false);
    struct Screen {
        int kind;  // 0 loading, 1 loaded
        int data;
        bool operator==(const Screen&) const = default;
    };
    auto screen = mutableStateOf(Screen{0, 0});
    auto composedLoaded = std::make_shared<int>(0);
    ComposeTestRule rule([&] {
        Column([&] {
            AnimatedContent<bool>(big.get(), [](const bool& b) { Box(Modifier().size(b ? 200.f : 100.f, b ? 80.f : 40.f).testTag(b ? "büyük" : "küçük")); },
                                  Modifier().testTag("ortalı"),
                                  togetherWith(fadeIn(0, tween(300)), fadeOut(0, tween(300))).withSizeTransform(SizeTransform{.clip = false, .spec = tween(300)}),
                                  {.contentAlignment = Alignment::Center});
            AnimatedContent<Screen>(screen.get(), [composedLoaded](const Screen& s) {
                if (s.kind == 0) {
                    Text("Yükleniyor");
                    return;
                }
                auto seen = remember([composedLoaded] { return ++*composedLoaded; });  // once per content shown
                Text(std::format("veri {} ({})", s.data, seen));
            }, Modifier().testTag("ekran"), defaultContentTransform(), {.contentKey = [](const Screen& s) { return uint64_t(s.kind); }});
        });
    });
    Rect box = rule.onNodeWithTag("ortalı").bounds();
    CHECK(near(box.width, 100) && near(box.height, 40));
    big.set(true);
    rule.advanceFrame();
    rule.advanceTimeBy(150);
    // Half way: the box between the sizes, both contents centered in it (the big one sticks out).
    box = rule.onNodeWithTag("ortalı").bounds();
    Rect small = rule.onNodeWithTag("küçük").bounds(), large = rule.onNodeWithTag("büyük").bounds();
    CHECK(box.width > 110 && box.width < 190);
    CHECK(near(small.x + 50, box.x + box.width / 2) && near(small.y + 20, box.y + box.height / 2));
    CHECK(near(large.x + 100, box.x + box.width / 2) && near(large.y + 40, box.y + box.height / 2));
    rule.waitForIdle();
    box = rule.onNodeWithTag("ortalı").bounds();
    large = rule.onNodeWithTag("büyük").bounds();
    CHECK(near(box.width, 200) && near(large.x, box.x) && !rule.onNodeWithTag("küçük").exists());
    // Loading → loaded is new content (a transition); new data on the loaded screen is not.
    screen.set({1, 7});
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(rule.onNodeWithText("Yükleniyor").exists() && rule.onNodeWithText("veri 7 (1)").exists());  // crossing
    screen.set({1, 8});  // new data half way: the loaded content takes it, the leaving one stays as it was
    rule.advanceFrame();
    CHECK(rule.onNodeWithText("Yükleniyor").exists() && rule.onNodeWithText("veri 8 (1)").exists() && !rule.onNodeWithText("veri 8 (2)").exists());
    rule.waitForIdle();
    CHECK(!rule.onNodeWithText("Yükleniyor").exists());
    screen.set({1, 9});
    rule.advanceFrame();
    CHECK(rule.onNodeWithText("veri 9 (1)").exists() && !rule.onNodeWithText("veri 8 (1)").exists());  // in place, state kept
    CHECK(!rule.host().hasPendingWork());
    screen.set({0, 9});  // back to loading: a transition again
    rule.advanceFrame();
    rule.advanceFrame();
    CHECK(rule.onNodeWithText("Yükleniyor").exists() && rule.onNodeWithText("veri 9 (1)").exists());
    rule.waitForIdle();
    screen.set({1, 10});
    rule.waitForIdle();
    CHECK(rule.onNodeWithText("veri 10 (2)").exists());  // a new loaded content
}

TEST(animate_enter_exit_gives_children_their_own_transitions) {
    auto open = mutableStateOf(false);
    auto later = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            AnimatedVisibility(open.get(), Modifier(), EnterTransition::None, ExitTransition::None, [&](const AnimatedVisibilityScope& s) {
                Column([&] {
                    Box(Modifier().size(100, 40).then(s.animateEnterExit(fadeIn(0, tween(300)), fadeOut(0, tween(300)))).testTag("perde"));
                    Box(s.animateEnterExit(slideInVertically(1, tween(600)), slideOutVertically(1, tween(600))).size(100, 40),
                        [] { Box(Modifier().fillMaxSize().testTag("sayfa")); });
                });
            });
            // Shown from the start (composed after the rule has settled, to see its first frames): no entrance.
            if (later.get())
                AnimatedVisibility(true, Modifier(), EnterTransition::None, ExitTransition::None, [&](const AnimatedVisibilityScope& s) {
                    Box(Modifier().size(100, 40).then(s.animateEnterExit(fadeIn(0, tween(300)), fadeOut(0, tween(300)))).testTag("baştan"));
                });
        });
    });
    auto alphas = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        return canvas.layerAlphas;
    };
    later.set(true);
    rule.advanceFrame();
    rule.advanceTimeBy(48);
    CHECK(!rule.onNodeWithTag("perde").exists() && rule.onNodeWithTag("baştan").exists() && alphas().empty());
    open.set(true);
    rule.advanceFrame();
    rule.advanceTimeBy(48);
    // The content came in at once (EnterTransition::None); its children come in their own ways.
    auto a = alphas();
    CHECK(a.size() == 1 && a[0] > 0 && a[0] < 0.5f);
    Rect perde = rule.onNodeWithTag("perde").bounds();
    float rest = perde.bottom();  // where the sliding one ends up
    CHECK(near(rule.onNodeWithTag("sayfa").bounds().y, rest + 40, 4));  // a whole height down
    rule.advanceTimeBy(350);
    CHECK(alphas().empty());  // the fade is done
    float y = rule.onNodeWithTag("sayfa").bounds().y;
    CHECK(y > rest + 1 && y < rest + 39);  // the slide is not
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("sayfa").bounds().y, rest));
    // Hidden: the content stays until both are out.
    open.set(false);
    rule.advanceFrame();
    CHECK(rule.onNodeWithTag("perde").exists() && rule.onNodeWithTag("sayfa").exists());
    rule.advanceTimeBy(350);
    y = rule.onNodeWithTag("sayfa").bounds().y;
    CHECK(rule.onNodeWithTag("perde").exists() && y > rest + 1 && y < rest + 39);
    rule.waitForIdle();
    CHECK(!rule.onNodeWithTag("perde").exists() && !rule.onNodeWithTag("sayfa").exists());
    // Shown again half way out: they turn back from where they are.
    open.set(true);
    rule.waitForIdle();
    open.set(false);
    rule.advanceFrame();
    rule.advanceTimeBy(300);
    float turned = rule.onNodeWithTag("sayfa").bounds().y;
    open.set(true);
    rule.advanceFrame();
    rule.advanceFrame();
    y = rule.onNodeWithTag("sayfa").bounds().y;
    CHECK(y > rest && y <= turned + 0.5f);
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("perde").exists() && near(rule.onNodeWithTag("sayfa").bounds().y, rest));
}

TEST(animated_content_waits_for_its_childrens_exits) {
    auto page = mutableStateOf(0);
    ComposeTestRule rule([&] {
        AnimatedContent<int>(page.get(), [](const AnimatedContentScope& s, const int& p) {
            Box(s.animateEnterExit(slideInHorizontally(1, tween(500)), slideOutHorizontally(-1, tween(500))).size(100, 40),
                [&] { Box(Modifier().fillMaxSize().testTag(std::format("sayfa {}", p))); });
        }, Modifier(), togetherWith(fadeIn(0, tween(100)), fadeOut(0, tween(100))));
    });
    float rest = rule.onNodeWithTag("sayfa 0").bounds().x;
    page.set(1);
    rule.advanceFrame();
    CHECK(rule.onNodeWithTag("sayfa 1").bounds().x > rest + 90);  // coming in from the right
    rule.advanceTimeBy(300);
    // The old page's own fade is over; its child still slides out, so it stays.
    CHECK(rule.onNodeWithTag("sayfa 0").exists() && rule.onNodeWithTag("sayfa 0").bounds().x < rest - 1);
    rule.waitForIdle();
    CHECK(!rule.onNodeWithTag("sayfa 0").exists() && near(rule.onNodeWithTag("sayfa 1").bounds().x, rest));
}

namespace {
// Skipped while its modifier is the same as last time.
void ActionBox(Modifier m, CallSite site = CallSite::current()) {
    composable(site, m, [=] { Box(m.size(10)); });
}
} // namespace

TEST(semantics_ranges_live_regions_custom_actions_and_order) {
    auto value = mutableStateOf(50.f);
    auto finished = std::make_shared<int>(0);
    auto said = std::make_shared<std::vector<std::string>>();
    auto round = mutableStateOf(0);
    ComposeTestRule rule([&] {
        Column([&] {
            Slider(value.get(), [&](float v) { value.set(v); }, Modifier().testTag("ayar"),
                   {.valueFrom = 0, .valueTo = 100, .steps = 3, .onValueChangeFinished = [finished] { ++*finished; }});
            Slider(0.5f, [](float) {}, Modifier().testTag("kapalı"), {.enabled = false});
            LinearProgressIndicator(0.3f, Modifier().testTag("yükleme"));
            CircularProgressIndicator(Modifier().testTag("bekleme"));
            Text(std::format("{} yeni ileti", round.get()), Modifier().testTag("sayaç").semantics({.liveRegion = LiveRegionMode::Polite}));
            ActionBox(Modifier().testTag("ileti").semantics({.contentDescription = "İleti",
                                                              .customActions = {{"Arşivle", [said, n = round.get()] {
                                                                                     said->push_back(std::format("arşivle {}", n));
                                                                                     return true;
                                                                                 }},
                                                                                {"Sil", [] { return false; }}}}));
            // Two semantics on one node: their actions together, the first range, live region and index.
            Box(Modifier()
                    .size(10)
                    .semantics({.contentDescription = "iki", .progressBarRangeInfo = ProgressBarRangeInfo{1, 0, 2},
                                .customActions = {{"bir", [] { return true; }}}})
                    .semantics({.progressBarRangeInfo = ProgressBarRangeInfo{9, 0, 9}, .setProgress = [](float) { return true; },
                                .liveRegion = LiveRegionMode::Assertive, .customActions = {{"iki", [] { return true; }}}, .traversalIndex = 3}));
            // Read in the order their traversal indexes give: b, c, then a and what is inside it.
            Column(Modifier().semantics({.contentDescription = "sıra"}), [] {
                Column(Modifier().semantics({.contentDescription = "a", .traversalIndex = 2}), [] { Text("a1"); });
                Text("b", Modifier().semantics({.traversalIndex = -1}));
                Text("c");
            });
        });
    }, {400, 800});
    auto tree = [&] { return rule.host().semanticsTree(); };
    auto node = [&](const std::string& label) {
        for (const SemanticsNode& n : tree())
            if (n.label == label) return n;
        return SemanticsNode{.id = -1};
    };
    auto byTag = [&](const char* tag) {  // the node under a tagged one's middle
        Offset at = rule.onNodeWithTag(tag).bounds().center();
        SemanticsNode best{.id = -1};
        for (const SemanticsNode& n : tree())
            if (n.bounds.contains(at) && (best.id < 0 || n.bounds.width * n.bounds.height <= best.bounds.width * best.bounds.height)) best = n;
        return best;
    };
    // A slider: its value in its range with its steps; set to 70 it snaps to 75 (the steps are 25 apart).
    SemanticsNode slider = byTag("ayar");
    CHECK((slider.role == SemanticsRole::Slider && slider.range == ProgressBarRangeInfo{50, 0, 100, 3} && slider.settable));
    CHECK(rule.host().performSemanticsAction(slider.id, SemanticsAction::SetProgress, 70));
    rule.waitForIdle();
    CHECK(value.get() == 75 && *finished == 1 && byTag("ayar").range->current == 75);
    CHECK(!byTag("kapalı").settable && byTag("kapalı").range.has_value());  // disabled: shown, not set
    CHECK(!rule.host().performSemanticsAction(byTag("kapalı").id, SemanticsAction::SetProgress, 0.2f));
    // Progress bars.
    CHECK((byTag("yükleme").range == ProgressBarRangeInfo{0.3f, 0, 1} && byTag("bekleme").range == ProgressBarRangeInfo::Indeterminate));
    // A live region.
    CHECK(node("0 yeni ileti").liveRegion == LiveRegionMode::Polite && node("İleti").liveRegion == LiveRegionMode::None);
    // Custom actions: offered by label, done by index; the latest composition's are the ones called.
    SemanticsNode message = node("İleti");
    CHECK((message.customActions == std::vector<std::string>{"Arşivle", "Sil"}));
    round.set(1);
    rule.waitForIdle();
    message = node("İleti");
    CHECK(rule.host().performSemanticsAction(message.id, SemanticsAction::CustomAction, 0));
    CHECK(!rule.host().performSemanticsAction(message.id, SemanticsAction::CustomAction, 1));  // it said it couldn't
    CHECK(!rule.host().performSemanticsAction(message.id, SemanticsAction::CustomAction, 2));  // there is none
    CHECK((*said == std::vector<std::string>{"arşivle 1"}));
    SemanticsNode two = node("iki");
    CHECK((two.customActions == std::vector<std::string>{"bir", "iki"} && two.range == ProgressBarRangeInfo{1, 0, 2} && two.settable &&
           two.liveRegion == LiveRegionMode::Assertive));
    // Traversal order among the nodes of a parent.
    std::vector<std::string> order;
    int parent = node("sıra").id;
    std::function<void(int)> walk = [&](int p) {
        for (const SemanticsNode& n : tree())
            if (n.parent == p) {
                order.push_back(n.label);
                walk(n.id);
            }
    };
    walk(parent);
    CHECK((order == std::vector<std::string>{"b", "c", "a", "a1"}));
    // ...and in the list itself, parents before what is inside them, in that order ("iki", with
    // its index of 3, after "sıra" among the column's nodes).
    std::vector<std::string> listed;
    bool in = false;
    for (const SemanticsNode& n : tree()) {
        if (n.label == "sıra") in = true;
        else if (in) listed.push_back(n.label);
    }
    CHECK((listed == std::vector<std::string>{"b", "c", "a", "a1", "iki"}));
}

TEST(on_layout_rect_changed_debounces_and_throttles) {
    struct Told {
        char who;
        float y, visible;
    };
    auto told = std::make_shared<std::vector<Told>>();
    auto shown = mutableStateOf(true);
    ScrollState scroll;
    ComposeTestRule rule([&] {
        auto report = [told](char who) {
            return [told, who](const RelativeLayoutBounds& b) { told->push_back({who, b.positionInWindow().y, b.fractionVisibleInWindow()}); };
        };
        Column(Modifier().fillMaxSize().verticalScroll(scroll), [&] {
            Box(Modifier().fillMaxWidth().height(200));
            if (shown.get()) Box(Modifier().fillMaxWidth().height(100).onLayoutRectChanged(report('a')));       // at 200: debounced 64 ms
            Box(Modifier().fillMaxWidth().height(100).onLayoutRectChanged(report('b'), 100, 0));                // at 300: throttled
            Box(Modifier().fillMaxWidth().height(100).onLayoutRectChanged(report('c'), 0, 0));                  // at 400: at once
            Box(Modifier().fillMaxWidth().height(1000));
        });
    }, {400, 450});
    auto of = [&](char who) {
        std::vector<Told> out;
        for (const Told& t : *told)
            if (t.who == who) out.push_back(t);
        return out;
    };
    // Laid out (the rule waits until all is still): each told once, c half in the window.
    CHECK(of('a').size() == 1 && of('b').size() == 1 && of('c').size() == 1);
    CHECK(near(of('a')[0].y, 200) && near(of('a')[0].visible, 1) && near(of('c')[0].y, 400) && near(of('c')[0].visible, 0.5f));
    // Scrolled 10 dp a frame (16 ms) for 12 frames: c each frame; b at once, then not for 100 ms
    // (the 8th frame, 112 ms on); a not while it moves.
    rule.advanceTimeBy(200);
    told->clear();
    for (int i = 1; i <= 12; ++i) {
        scroll.scrollTo(10.f * float(i));
        rule.advanceFrame();
    }
    CHECK(of('c').size() == 12 && near(of('c').back().y, 400 - 120) && near(of('c').back().visible, 1));
    CHECK(of('b').size() == 2 && near(of('b')[0].y, 300 - 10) && near(of('b')[1].y, 300 - 80) && of('a').empty());
    rule.waitForIdle();  // stopped: a told where it stopped, b its last place once the throttle lets it
    CHECK(of('a').size() == 1 && near(of('a')[0].y, 200 - 120) && of('b').size() == 3 && near(of('b')[2].y, 300 - 120));
    CHECK(of('c').size() == 12);
    // Leaving the layout, even while its new place waits to be told: nothing told (b and c move
    // up, and are told).
    told->clear();
    scroll.scrollTo(130);
    rule.advanceFrame();
    shown.set(false);
    rule.waitForIdle();
    CHECK(of('a').empty() && of('c').size() == 2 && near(of('c').back().y, 300 - 130));
    CHECK(of('b').size() == 1 && near(of('b')[0].y, 200 - 130));  // its throttle still running at the scroll: the latest place only
}

TEST(system_gesture_exclusion_keeps_the_rects_in_view) {
    auto shown = mutableStateOf(true);
    ScrollState scroll;
    ComposeTestRule rule([&] {
        Column([&] {
            if (shown.get()) Box(Modifier().size(100, 50).systemGestureExclusion());  // 0..50, all of it
            // Only its first 30 dp across (a slider's edge, say).
            Box(Modifier().size(200, 60).systemGestureExclusion([](const LayoutCoordinates& c) { return Rect{0, 0, 30, c.size().height}; }));
            Column(Modifier().fillMaxWidth().height(100).verticalScroll(scroll), [] {  // what is scrolled out of it is not kept
                Box(Modifier().fillMaxWidth().height(80));
                Box(Modifier().size(50, 80).systemGestureExclusion());
                Box(Modifier().size(50, 80).systemGestureExclusion());  // 160..240: never in view
            });
            Box(Modifier().size(40));
        });
    }, {400, 800});
    auto rects = [&] { return rule.host().systemGestureExclusion(); };
    auto same = [](const Rect& a, Rect b) { return near(a.x, b.x) && near(a.y, b.y) && near(a.width, b.width) && near(a.height, b.height); };
    auto r = rects();
    CHECK(r.size() == 3 && same(r[0], {0, 0, 100, 50}) && same(r[1], {0, 50, 30, 60}) && same(r[2], {0, 110 + 80, 50, 20}));
    scroll.scrollTo(60);  // more of the last one in view
    rule.waitForIdle();
    r = rects();
    CHECK(r.size() == 3 && same(r[2], {0, 110 + 20, 50, 80}));
    shown.set(false);  // gone, and the others up 50 dp
    rule.waitForIdle();
    r = rects();
    CHECK(r.size() == 2 && same(r[0], {0, 0, 30, 60}) && same(r[1], {0, 60 + 20, 50, 80}));
}

TEST(gradient_tile_modes_go_on_past_the_ends) {
    Color a{1, 0, 0, 1}, b{0, 0, 1, 1};
    auto at = [&](TileMode mode, float x) {  // 0..10 dp from red to blue, painting 0..100
        return Brush::horizontalGradient({a, b}, 0, 10, mode).colorAt({x, 5}, {0, 0, 100, 10});
    };
    auto same = [](Color p, Color q) { return near(p.r, q.r, 0.01f) && near(p.b, q.b, 0.01f) && near(p.a, q.a, 0.01f); };
    Color quarter = lerp(a, b, 0.25f);
    CHECK(same(at(TileMode::Clamp, 2.5f), quarter) && same(at(TileMode::Clamp, 32.5f), b) && same(at(TileMode::Clamp, -5), a));
    CHECK(same(at(TileMode::Repeated, 12.5f), quarter) && same(at(TileMode::Repeated, 32.5f), quarter) && same(at(TileMode::Repeated, -7.5f), quarter));
    CHECK(same(at(TileMode::Mirror, 12.5f), lerp(a, b, 0.75f)) && same(at(TileMode::Mirror, 22.5f), quarter) && same(at(TileMode::Mirror, -2.5f), quarter));
    CHECK(same(at(TileMode::Decal, 2.5f), quarter) && at(TileMode::Decal, 12.5f).a == 0 && at(TileMode::Decal, -1).a == 0);
    // A radial one too; and the mode makes brushes differ.
    Brush rings = Brush::radialGradient({a, b}, Offset{50, 50}, 10, TileMode::Repeated);
    CHECK(same(rings.colorAt({50 + 12.5f, 50}, {0, 0, 100, 100}), quarter));
    CHECK(!(Brush::horizontalGradient({a, b}, 0, 10, TileMode::Mirror) == Brush::horizontalGradient({a, b}, 0, 10)));
}

TEST(keep_screen_on_while_laid_out) {
    auto video = mutableStateOf(false);
    auto popup = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            Text("Tarif");
            if (video.get()) Box(Modifier().size(100).keepScreenOn());
            if (popup.get()) Popup({}, [] { Box(Modifier().size(10).keepScreenOn()); });
        });
    }, {400, 800});
    ComposeHost& host = rule.host();
    CHECK(!host.keepScreenOn());
    video.set(true);
    rule.waitForIdle();
    CHECK(host.keepScreenOn());
    video.set(false);
    rule.waitForIdle();
    CHECK(!host.keepScreenOn());
    popup.set(true);  // in a popup too
    rule.waitForIdle();
    CHECK(host.keepScreenOn());
    popup.set(false);
    rule.waitForIdle();
    CHECK(!host.keepScreenOn());
}

TEST(sensitive_content_while_laid_out) {
    auto card = mutableStateOf(false);
    auto taken = mutableStateOf(false);
    auto popup = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            Text("Ödeme");
            if (card.get()) TextField("4111", [](std::string) {}, Modifier().sensitiveContent());
            if (taken.get()) Box(Modifier().size(10).sensitiveContent(false));  // taken back: no hint
            if (popup.get()) Popup({}, [] { Box(Modifier().size(10).sensitiveContent()); });
        });
    }, {400, 800});
    ComposeHost& host = rule.host();
    CHECK(!host.sensitiveContent());
    card.set(true);
    rule.waitForIdle();
    CHECK(host.sensitiveContent());
    card.set(false);
    taken.set(true);
    rule.waitForIdle();
    CHECK(!host.sensitiveContent());
    popup.set(true);  // in a popup too
    rule.waitForIdle();
    CHECK(host.sensitiveContent());
    popup.set(false);
    rule.waitForIdle();
    CHECK(!host.sensitiveContent());
    // The same text taking the hint back (not skipped as if nothing changed).
    auto hint = mutableStateOf(true);
    ComposeTestRule same([&] { Text("4111", Modifier().sensitiveContent(hint.get())); }, {400, 800});
    CHECK(same.host().sensitiveContent());
    hint.set(false);
    same.waitForIdle();
    CHECK(!same.host().sensitiveContent());
}

TEST(keyboard_insets_follow_its_slide) {
    ComposeTestRule rule([&] {
        WindowInsets ime = WindowInsets::ime(), from = WindowInsets::imeAnimationSource(), to = WindowInsets::imeAnimationTarget();
        Column(Modifier().fillMaxSize().imePadding(), [&] {
            Text(std::format("{} {} {} {}", ime.bottom, from.bottom, to.bottom, WindowInsets::isImeVisible()));
            Box(Modifier().fillMaxWidth().weight(1).testTag("içerik"));
        });
    }, {400, 800});
    ComposeHost& host = rule.host();
    auto shows = [&](const char* text, float height) {
        rule.waitForIdle();
        return rule.onNodeWithText(text).exists() && near(rule.onNodeWithTag("içerik").bounds().bottom(), height);
    };
    CHECK(shows("0 0 0 false", 800));
    // On its way up, a third of the way: the padding follows it; where it goes is known.
    host.setSystemInsets({.ime = {0, 0, 0, 100}, .imeAnimating = true, .imeVisible = true, .imeAnimationTarget = {0, 0, 0, 300}});
    CHECK(shows("100 0 300 true", 700));
    // Up and still: where it started and where it went are where it is.
    host.setSystemInsets({.ime = {0, 0, 0, 300}, .imeVisible = true, .imeAnimationTarget = {0, 0, 0, 123}});  // (a stale one)
    CHECK(shows("300 300 300 true", 500));
    // On its way down: not up any more.
    host.setSystemInsets({.ime = {0, 0, 0, 200}, .imeAnimating = true, .imeAnimationSource = {0, 0, 0, 300}});
    CHECK(shows("200 300 0 false", 600));
}

TEST(autofill_hears_of_text_fields_and_fills_them) {
    auto user = mutableStateOf(std::string());
    auto form = mutableStateOf(true);
    auto locked = mutableStateOf(false);
    std::optional<TextFieldState> password, code;
    std::vector<std::string> log;
    Rect focusedAt;
    ComposeTestRule rule([&] {
        password = rememberTextFieldState();
        code = rememberTextFieldState();
        if (form.get())
            Column([&] {
                TextField(user.get(), [&](std::string v) { user.set(std::move(v)); },
                          Modifier().semantics({.contentType = ContentType::Username + ContentType::EmailAddress}).testTag("kullanıcı"),
                          {.label = "E-posta"});
                SecureTextField(*password, Modifier().semantics({.contentType = ContentType::Password}).testTag("parola"),
                                {.label = "Parola", .keyboardOptions = {}});  // a plain keyboard: hidden text alone makes it a password
                TextField("sabit", [](std::string) {}, Modifier().testTag("not"),
                          {.label = "Not", .keyboardOptions = {.keyboardType = KeyboardType::Password}, .readOnly = locked.get()});
                TextField(*code, Modifier().semantics({.contentDescription = "Kod"}).semantics({.contentType = ContentType::SmsOtpCode}),
                          {.keyboardOptions = {.keyboardType = KeyboardType::NumberPassword}, .inputTransformation = InputTransformation::allCaps()});
                Button([autofill = autofillManager()] { autofill.commit(); }, [] { Text("Giriş"); });
                Button([autofill = autofillManager()] { autofill.cancel(); }, [] { Text("Vazgeç"); });
            });
    }, {400, 800});
    ComposeHost& host = rule.host();
    host.setCallbacks({.autofillFocus = [&](int id, Rect bounds, bool entered) {
                           log.push_back(std::format("{} {}", entered ? "giriş" : "çıkış", id));
                           if (entered) focusedAt = bounds;
                       },
                       .autofillValue = [&](int id, const std::string& text) { log.push_back(std::format("değer {} {}", id, text)); },
                       .autofillVisibility = [&](int id, bool visible) { log.push_back(std::format("{} {}", visible ? "görünür" : "gitti", id)); },
                       .autofillDone = [&](bool commit) { log.push_back(commit ? "kaydet" : "bırak"); }});
    host.invalidate();
    rule.waitForIdle();
    std::vector<SemanticsNode> fields;
    for (const SemanticsNode& n : host.semanticsTree())
        if (n.editable) fields.push_back(n);
    CHECK(fields.size() == 4);
    int userId = fields[0].id, passwordId = fields[1].id, noteId = fields[2].id, codeId = fields[3].id;
    CHECK((fields[0].contentType == std::vector<std::string>{"username", "emailAddress"}) && !fields[0].password);
    CHECK((fields[1].contentType == std::vector<std::string>{"password"}) && fields[1].password);  // hidden text
    CHECK(fields[2].contentType.empty() && fields[2].password);                                     // a password keyboard
    CHECK((fields[3].contentType == std::vector<std::string>{"smsOTPCode"}) && fields[3].password);  // from its second semantics
    // Each field is told as it comes into the layout.
    CHECK((log == std::vector<std::string>{std::format("görünür {}", userId), std::format("görünür {}", passwordId), std::format("görünür {}", noteId),
                                          std::format("görünür {}", codeId)}));
    log.clear();
    // Focused: entered, where it is; typed into: its text.
    rule.onNodeWithTag("kullanıcı").performTextInput("ay");
    CHECK(log.size() >= 2 && log[0] == std::format("giriş {}", userId) && log.back() == std::format("değer {} ay", userId));
    CHECK(host.focusedNode() && sameRect(focusedAt, host.focusedNode()->bounds()) && focusedAt.width > 100);
    log.clear();
    // Filled by the password manager: the focused one through the input method, the other one directly.
    CHECK(host.performSemanticsAction(userId, SemanticsAction::SetText, "ayse@example.com"));
    CHECK(host.performSemanticsAction(passwordId, SemanticsAction::SetText, "gizli"));
    rule.waitForIdle();
    CHECK(user.get() == "ayse@example.com" && password->text() == "gizli");
    CHECK((log == std::vector<std::string>{std::format("değer {} ayse@example.com", userId), std::format("değer {} gizli", passwordId)}));
    host.textInput("!");  // the input method has the filled text: typing goes on from it
    rule.waitForIdle();
    CHECK(user.get() == "ayse@example.com!");
    CHECK(host.performSemanticsAction(codeId, SemanticsAction::SetText, "ab12"));  // its input transformation still holds
    rule.waitForIdle();
    CHECK(code->text() == "AB12" && code->selection() == (TextRange{4, 4}));  // the caret at its end
    CHECK(!(Modifier().semantics({.contentType = ContentType::Username}) == Modifier().semantics({.contentType = ContentType::Password})));
    CHECK(!host.performSemanticsAction(userId, SemanticsAction::Click, "x") && !host.performSemanticsAction(9999, SemanticsAction::SetText, "x"));
    locked.set(true);
    rule.waitForIdle();
    CHECK(!host.performSemanticsAction(noteId, SemanticsAction::SetText, "x"));  // read-only
    log.clear();
    // Sent or dropped.
    rule.onNodeWithText("Giriş").performClick();
    rule.onNodeWithText("Vazgeç").performClick();
    CHECK(std::find(log.begin(), log.end(), "kaydet") != log.end() && log.back() == "bırak");
    log.clear();
    // The form goes: the focus leaves it, and its fields are gone.
    rule.onNodeWithTag("kullanıcı").performClick();
    log.clear();
    form.set(false);
    rule.waitForIdle();
    CHECK(std::find(log.begin(), log.end(), std::format("çıkış {}", userId)) != log.end());
    CHECK(std::find(log.begin(), log.end(), std::format("gitti {}", userId)) != log.end() &&
          std::find(log.begin(), log.end(), std::format("gitti {}", passwordId)) != log.end());
}

TEST(on_focus_event_and_progress_semantics) {
    auto events = std::make_shared<std::vector<std::string>>();
    auto changes = std::make_shared<std::vector<std::string>>();
    FocusRequester a, b, far;
    auto name = [](FocusState s) { return std::string(s.isFocused ? "focused" : s.hasFocus ? "inside" : "none"); };
    ComposeTestRule rule([&] {
        Column([&] {
            Column(Modifier().onFocusEvent([events, name](FocusState s) { events->push_back(name(s)); })
                       .onFocusChanged([changes, name](FocusState s) { changes->push_back(name(s)); }),
                   [&] {
                       Box(Modifier().size(20).focusRequester(a).focusable());
                       Box(Modifier().size(20).focusRequester(b).focusable());
                   });
            Box(Modifier().size(20).focusRequester(far).focusable());
            Box(Modifier().size(50).testTag("ilerleme").progressSemantics(15, 0, 10, 4));  // kept in its range
            Box(Modifier().size(50).testTag("belirsiz").progressSemantics());
        });
    }, {400, 800});
    a.requestFocus();
    rule.waitForIdle();
    b.requestFocus();  // the focus moves inside: an event, no change
    rule.waitForIdle();
    far.requestFocus();  // it leaves
    rule.waitForIdle();
    a.requestFocus();
    rule.waitForIdle();
    rule.host().clearFocus();
    rule.waitForIdle();
    CHECK((*events == std::vector<std::string>{"inside", "inside", "none", "inside", "none"}));
    CHECK((*changes == std::vector<std::string>{"inside", "none", "inside", "none"}));
    // ...and nothing while the focus moves elsewhere.
    events->clear();
    far.requestFocus();
    rule.waitForIdle();
    rule.host().clearFocus();
    rule.waitForIdle();
    CHECK(events->empty());
    auto range = [&](const char* tag) {
        Offset at = rule.onNodeWithTag(tag).bounds().center();
        for (const SemanticsNode& n : rule.host().semanticsTree())
            if (n.bounds.contains(at) && n.range) return n.range;
        return std::optional<ProgressBarRangeInfo>{};
    };
    CHECK((range("ilerleme") == ProgressBarRangeInfo{10, 0, 10, 4} && range("belirsiz") == ProgressBarRangeInfo::Indeterminate));
}

TEST(scroll_containers_clip_along_their_axis_and_leave_room_across) {
    ComposeTestRule rule([&] {
        Column(Modifier().padding(40), [&] {
            Column(Modifier().size(200, 100).verticalScroll(rememberScrollState()), [] { Box(Modifier().size(200, 300)); });
            LazyRow(Modifier().size(200, 100), {}, [](LazyListScope& l) { l.items(10, [](int) { Box(Modifier().size(80, 100)); }); });
        });
    }, {400, 800});
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto has = [&](Rect want) { return std::any_of(canvas.clips.begin(), canvas.clips.end(), [&](Rect r) { return sameRect(r, want); }); };
    CHECK(has({40 - 30, 40, 200 + 60, 100}));   // the column: its height, 30 dp more each side across
    CHECK(has({40, 140 - 30, 200, 100 + 60}));  // the row: its width, 30 dp more above and below
}

TEST(bring_into_view_spec_puts_the_focused_item_where_it_says) {
    std::vector<FocusRequester> items(30), row(20), plain(20), scrolled(20);
    FocusRequester big;
    auto rtl = mutableStateOf(false);
    bool sameWith = true, sameWithout = false;  // a scroll modifier with a spec of its own is never taken as the same
    BringIntoViewSpec at100{[](float offset, float, float) { return offset - 100; }};  // its start 100 dp in
    ComposeTestRule rule([&] {
        Row(Modifier().fillMaxSize(), [&] {
            CompositionLocalProvider({LocalBringIntoViewSpec.provides(at100)}, [&] {
                LazyColumn(Modifier().width(100).fillMaxHeight().testTag("liste"), {}, [&](LazyListScope& l) {
                    l.items(30, [&](int i) { Box(Modifier().fillMaxWidth().height(50).focusRequester(items[size_t(i)]).focusable().testTag(std::format("ö{}", i))); });
                });
                ScrollState st;
                sameWith = Modifier().verticalScroll(st) == Modifier().verticalScroll(st);
                Column(Modifier().width(100).fillMaxHeight().verticalScroll(rememberScrollState()), [&] {
                    for (int i = 0; i < 20; ++i)
                        Box(Modifier().fillMaxWidth().height(50).focusRequester(scrolled[size_t(i)]).focusable().testTag(std::format("s{}", i)));
                });
            });
            ScrollState st;
            sameWithout = Modifier().verticalScroll(st) == Modifier().verticalScroll(st);
            // Not under it: just far enough.
            Column(Modifier().width(100).fillMaxHeight().verticalScroll(rememberScrollState()), [&] {
                for (int i = 0; i < 20; ++i)
                    Box(Modifier().fillMaxWidth().height(50).focusRequester(plain[size_t(i)]).focusable().testTag(std::format("d{}", i)));
                Box(Modifier().fillMaxWidth().height(700).focusRequester(big).focusable().testTag("büyük"));  // taller than the column
            });
            CompositionLocalProvider({LocalLayoutDirection.provides(rtl.get() ? LayoutDirection::Rtl : LayoutDirection::Ltr),
                                      LocalBringIntoViewSpec.provides(BringIntoViewSpec{[](float offset, float, float) { return offset - 30; }})},
                                     [&] {
                                         LazyRow(Modifier().width(200).height(50), {}, [&](LazyListScope& l) {
                                             l.items(20, [&](int i) {
                                                 Box(Modifier().width(50).fillMaxHeight().focusRequester(row[size_t(i)]).focusable().testTag(std::format("r{}", i)));
                                             });
                                         });
                                     });
        });
    }, {500, 500});
    CHECK(!sameWith && sameWithout);
    auto top = [&](const std::string& tag) { return rule.onNodeWithTag(tag).bounds().y; };
    items[12].requestFocus();
    rule.waitForIdle();
    CHECK(near(top("ö12"), 100));  // forwards: 100 dp in
    items[3].requestFocus();
    rule.waitForIdle();
    CHECK(near(top("ö3"), 100));  // back: 100 dp in too
    items[0].requestFocus();
    rule.waitForIdle();
    CHECK(near(top("ö0"), 0));  // as far as the list goes
    scrolled[12].requestFocus();  // a scrolling column under it too
    rule.waitForIdle();
    CHECK(near(top("s12"), 100));
    // The default: the end just shows.
    plain[14].requestFocus();
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("d14").bounds().bottom(), 500));
    big.requestFocus();  // bigger than the view: its start shows, not its end
    rule.waitForIdle();
    CHECK(near(top("büyük"), 0));
    // Along a row: from its start, the right one right to left.
    row[10].requestFocus();
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("r10").bounds().x, 300 + 30));  // the row starts at x = 300
    rtl.set(true);
    rule.waitForIdle();
    row[8].requestFocus();  // (composed: just out of view)
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("r8").bounds().right(), 500 - 30));
}

// An indication of the test's own: what it heard, and a mark it draws over the content.
struct HeardIndication final : IndicationNode {
    std::vector<Interaction::Type> heard;
    Color mark;
    std::shared_ptr<int> frames;  // counted by a coroutine of its own from its first press on
    HeardIndication(Color m, std::shared_ptr<int> f) : mark(m), frames(std::move(f)) {}
    void onInteraction(const Interaction& i) override {
        heard.push_back(i.type);
        if (i.type == Interaction::Type::Press && heard.size() == 1)
            coroutineScope().launch([f = frames]() -> Task {
                while (true) {
                    co_await awaitFrame();
                    ++*f;
                }
            });
    }
    void draw(ContentDrawScope& d) override {
        d.drawContent();
        d.drawRect(mark, {}, Size{4, 4});
    }
};
struct HeardFactory final : IndicationNodeFactory {
    Color mark;
    mutable std::vector<std::weak_ptr<HeardIndication>> made;
    std::shared_ptr<int> frames = std::make_shared<int>(0);
    explicit HeardFactory(Color m) : mark(m) {}
    std::shared_ptr<IndicationNode> create() const override {
        auto node = std::make_shared<HeardIndication>(mark, frames);
        made.push_back(node);
        return node;
    }
};

TEST(custom_indication_hears_its_component_and_draws_around_it) {
    auto red = std::make_shared<HeardFactory>(Color::hex(0xff0000)), blue = std::make_shared<HeardFactory>(Color::hex(0x0000ff));
    auto useBlue = mutableStateOf(false), enabled = mutableStateOf(true);
    auto tick = mutableStateOf(0);
    MutableInteractionSource own;
    ComposeTestRule rule([&] {
        (void)tick.get();  // recomposed: the same factory keeps its node
        Column([&] {
            Box(Modifier().size(100, 50).clickable([] {}, {.enabled = enabled.get(), .indication = Indication(useBlue.get() ? blue : red)}).testTag("tık"));
            // A component of one's own: its source, drawn by Modifier.indication.
            Box(Modifier().size(100, 50).indication(own, Indication(blue)).testTag("kendi"));
            CompositionLocalProvider({LocalIndication.provides(Indication(red))}, [&] { Button([] {}, [] { Text("Düğme"); }); });
        });
    }, {400, 800});
    auto clickNode = [&] { return red->made.empty() ? nullptr : red->made.front().lock(); };
    CHECK(red->made.size() == 2 && blue->made.size() == 1);  // the box and the button; the component of one's own
    auto box = clickNode();
    Offset c = rule.onNodeWithTag("tık").bounds().center();
    rule.host().pointerDown(c, -1, 0, ComposeHost::PointerType::Touch);  // a tap
    rule.advanceFrame();
    rule.host().pointerUp(c);
    rule.waitForIdle();
    CHECK(box && (box->heard == std::vector<Interaction::Type>{Interaction::Type::Press, Interaction::Type::Release}));
    // A mouse going over it and away.
    rule.host().pointerMove(c);
    rule.waitForIdle();
    rule.host().pointerExit();
    rule.waitForIdle();
    CHECK(box->heard.size() == 4 && box->heard[2] == Interaction::Type::HoverEnter && box->heard[3] == Interaction::Type::HoverExit);
    // The keyboard: focused, then Enter presses it.
    rule.host().keyDown(Key::Tab);
    rule.waitForIdle();
    rule.host().keyDown(Key::Enter);
    rule.waitForIdle();
    CHECK(box->heard.size() == 7 && box->heard[4] == Interaction::Type::Focus && box->heard[5] == Interaction::Type::Press &&
          box->heard[6] == Interaction::Type::Release);
    rule.host().keyDown(Key::Escape);  // (the focus off it)
    rule.waitForIdle();
    // Drawn around the content: its mark over the box (and the button), the other's over the component.
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto marks = [&](Color c) { return std::count_if(canvas.rectColors.begin(), canvas.rectColors.end(), [&](Color k) { return k == c; }); };
    CHECK(marks(Color::hex(0xff0000)) == 2 && marks(Color::hex(0x0000ff)) == 1);
    // The component's own source: what is emitted to it.
    Interaction press = Interaction::press({10, 10});
    own.tryEmit(press);
    own.tryEmit(press.cancel());
    rule.waitForIdle();
    auto mine = blue->made.front().lock();
    CHECK(mine && (mine->heard == std::vector<Interaction::Type>{Interaction::Type::Press, Interaction::Type::Cancel}));
    // Recomposed: the same node. Another factory: a new node, the old one gone with its coroutines.
    tick.set(1);
    rule.waitForIdle();
    CHECK(red->made.size() == 2 && clickNode() == box);
    std::weak_ptr<HeardIndication> old = box;
    box.reset();
    useBlue.set(true);
    rule.waitForIdle();
    CHECK(blue->made.size() == 2 && old.expired());
    int counted = *red->frames;  // its coroutines went with it
    for (int i = 0; i < 5; ++i) rule.advanceFrame();
    CHECK(counted > 0 && *red->frames == counted);
    // Disabled: no indication at all, the content as it is.
    enabled.set(false);
    rule.waitForIdle();
    CHECK(blue->made[1].expired());
    testing::RecordingCanvas after;
    rule.host().draw(after);
    CHECK(std::count_if(after.rectColors.begin(), after.rectColors.end(), [](Color k) { return k == Color::hex(0x0000ff); }) == 1);  // the component's only
}

// A text toolbar of the test's own: what it was asked to show, and how often hidden.
struct RecordingToolbar final : TextToolbar {
    int shows = 0, hides = 0;
    Rect rect;
    std::function<void()> copy, paste, cut, selectAll;
    TextToolbarStatus shown = TextToolbarStatus::Hidden;
    void showMenu(Rect r, std::function<void()> onCopy, std::function<void()> onPaste, std::function<void()> onCut,
                  std::function<void()> onSelectAll) override {
        ++shows;
        rect = r;
        copy = std::move(onCopy), paste = std::move(onPaste), cut = std::move(onCut), selectAll = std::move(onSelectAll);
        shown = TextToolbarStatus::Shown;
    }
    void hide() override {
        ++hides;
        shown = TextToolbarStatus::Hidden;
    }
    TextToolbarStatus status() const override { return shown; }
};

TEST(text_toolbar_of_ones_own_is_told_instead_of_kompoz_drawing_one) {
    auto toolbar = std::make_shared<RecordingToolbar>();
    auto value = mutableStateOf(std::string("merhaba güzel dünya"));
    auto locked = mutableStateOf(false);
    std::string clipboard;
    ComposeTestRule rule([&] {
        CompositionLocalProvider({LocalTextToolbar.provides(std::shared_ptr<TextToolbar>(toolbar))}, [&] {
            Column(Modifier().fillMaxSize(), [&] {
                Box(Modifier().height(200));
                TextField(value.get(), [&](std::string v) { value.set(std::move(v)); }, Modifier().fillMaxWidth().testTag("field"),
                          {.singleLine = true, .readOnly = locked.get()});
                SelectionContainer(Modifier().testTag("seçilen"), [] { Text("Seçilebilir metin"); });
                Box(Modifier().fillMaxWidth().height(300).testTag("below"));
            });
        });
    }, {400, 800});
    auto& host = rule.host();
    host.setCallbacks({.getClipboard = [&] { return clipboard; }, .setClipboard = [&](const std::string& c) { clipboard = c; }});
    Rect field = rule.onNodeWithTag("field").bounds();
    auto at = [&](int index) { return Offset{field.x + 16 + 8.5f * float(index), field.y + 28}; };
    auto longPress = [&](Offset p) {
        host.pointerDown(p);
        rule.advanceTimeBy(500);
        host.pointerUp(p);
        rule.waitForIdle();
    };
    longPress(at(10));  // "güzel" selected
    CHECK(host.inTouchSelection() && !rule.onNodeWithText("Copy").exists());  // not Kompoz's own
    CHECK(toolbar->shows == 1 && toolbar->status() == TextToolbarStatus::Shown && toolbar->copy && toolbar->paste && toolbar->cut &&
          toolbar->selectAll);
    // Over the selection: "güzel", characters 8..13, on the field's line.
    CHECK(near(toolbar->rect.x, field.x + 16 + 8.5f * 8) && near(toolbar->rect.width, 8.5f * 5) && toolbar->rect.y >= field.y &&
          toolbar->rect.bottom() <= field.bottom());
    rule.waitForIdle();
    CHECK(toolbar->shows == 1);  // told once while nothing changes
    toolbar->copy();
    rule.waitForIdle();
    CHECK(clipboard == "güzel" && !host.inTouchSelection() && toolbar->hides == 1 && toolbar->status() == TextToolbarStatus::Hidden);
    // Select all from it: told again where the whole text is.
    longPress(at(3));
    CHECK(toolbar->shows == 2);
    toolbar->selectAll();
    rule.waitForIdle();
    CHECK(toolbar->shows == 3 && near(toolbar->rect.x, field.x + 16));
    // A press elsewhere hides it.
    Offset below = rule.onNodeWithTag("below").bounds().center();
    host.pointerDown(below);
    host.pointerUp(below);
    rule.waitForIdle();
    CHECK(toolbar->hides == 2 && toolbar->status() == TextToolbarStatus::Hidden);
    // Made read-only while shown: told again, with copy and select all only.
    longPress(at(3));
    CHECK(toolbar->shows == 4 && toolbar->paste);
    locked.set(true);
    rule.waitForIdle();
    CHECK(toolbar->shows == 5 && toolbar->copy && !toolbar->paste && !toolbar->cut && toolbar->selectAll);
    host.pointerDown(below);
    host.pointerUp(below);
    rule.waitForIdle();
    // A SelectionContainer's text: copy and select all.
    Rect text = rule.onNodeWithTag("seçilen").bounds();
    longPress({text.x + 8, text.y + 8});
    CHECK(toolbar->shows == 6 && toolbar->copy && !toolbar->paste && !toolbar->cut && toolbar->selectAll);
    toolbar->copy();
    rule.waitForIdle();
    CHECK(clipboard == "Seçilebilir" && toolbar->status() == TextToolbarStatus::Hidden);
}

TEST(path_data_arcs_become_cubics) {
    using V = PathCommand::Verb;
    // A half circle over the top (y down): two quarter turns, the first ending at its top; the
    // handles 4/3 tan(pi/8) of the radius long, along the circle.
    auto half = VectorPath::parse("M0,12A12,12 0 0,1 24,12");
    CHECK(half.size() == 3 && half[1].verb == V::Cubic && half[2].verb == V::Cubic);
    CHECK(near(half[1].x, 12) && near(half[1].y, 0) && near(half[2].x, 24) && near(half[2].y, 12));
    CHECK(near(half[1].x1, 0, 0.01f) && near(half[1].y1, 12 - 6.6274f, 0.01f) && near(half[1].x2, 12 - 6.6274f, 0.01f) && near(half[1].y2, 0, 0.01f));
    auto under = VectorPath::parse("M0,12A12,12 0 0,0 24,12");  // the other way round: under the bottom
    CHECK(under.size() == 3 && near(under[1].x, 12) && near(under[1].y, 24));
    // Relative, its flags run together: the same half circle.
    auto compact = VectorPath::parse("M0,12a12,12 0 0124,0");
    CHECK(compact.size() == 3 && near(compact[1].x, 12) && near(compact[1].y, 0) && near(compact[2].x, 24) && near(compact[2].y, 12));
    // Radii too small to reach: the smallest that does (5 here).
    auto small = VectorPath::parse("M0,0A1,1 0 0,1 10,0");
    CHECK(small.size() == 3 && near(small[1].x, 5) && near(small[1].y, -5));
    // The large arc: three quarter turns around (12, 12).
    auto large = VectorPath::parse("M12,0A12,12 0 1,0 24,12");
    CHECK(large.size() == 4 && near(large[1].x, 0) && near(large[1].y, 12) && near(large[3].x, 24) && near(large[3].y, 12));
    auto largeOther = VectorPath::parse("M12,0A12,12 0 1,1 24,12");  // the other way: around (24, 0)
    CHECK(largeOther.size() == 4 && near(largeOther[1].x, 24) && near(largeOther[1].y, -12) && near(largeOther[2].x, 36) && near(largeOther[2].y, 0));
    // An ellipse turned a quarter: its radii swap places.
    auto turned = VectorPath::parse("M0,10A10,5 90 0,1 0,30");
    CHECK(turned.size() == 3 && near(turned[1].x, 5) && near(turned[1].y, 20));
    // No radius: a line. After it the path goes on from its end.
    auto flat = VectorPath::parse("M0,0A0,5 0 0,1 10,0h5");
    CHECK(flat.size() == 3 && flat[1].verb == V::Line && near(flat[2].x, 15));
    // A circle from two arcs: four quarter turns.
    CHECK(ImageVector::fromSvgPath("M2,12a10,10 0 1,0 20,0a10,10 0 1,0 -20,0").commands().size() == 5);
}

TEST(vector_drawable_xml_becomes_an_image_vector) {
    const char* xml = R"(<?xml version="1.0" encoding="utf-8"?>
<!-- a test drawable -->
<vector xmlns:android="http://schemas.android.com/apk/res/android" xmlns:aapt="http://schemas.android.com/aapt"
    android:width="48dp" android:height="40dp" android:viewportWidth="24" android:viewportHeight="20" android:autoMirrored="true">
    <path android:fillColor="#FF0000" android:pathData="M0,0h12v12h-12z"/>
    <group android:translateX="12" android:translateY="12">
        <path android:strokeColor="#800000FF" android:strokeWidth="2" android:strokeLineCap="round" android:strokeLineJoin="bevel"
              android:strokeAlpha="0.5" android:pathData="M0,0h6"/>
        <group android:rotation="90" android:pivotX="6" android:pivotY="6" android:scaleX="2">
            <path android:fillColor="#0F0" android:fillType="evenOdd" android:pathData="M6,0L6,6L8,6"/>
        </group>
    </group>
    <clip-path android:pathData="M0,0h24v24h-24z"/>
    <path android:pathData="M0,16h4" android:fillAlpha="0.25">
        <aapt:attr name="android:fillColor">
            <gradient android:startColor="#8FF0" android:endColor="#000000" android:type="linear"/>
        </aapt:attr>
    </path>
</vector>)";
    ImageVector v = ImageVector::fromVectorXml(xml);
    CHECK(!v.empty() && near(v.defaultWidth(), 48) && near(v.defaultHeight(), 40) && near(v.viewportWidth(), 24) && near(v.viewportHeight(), 20) &&
          v.autoMirror());
    const auto& paths = v.paths();
    CHECK(paths.size() == 4);
    if (paths.size() == 4) {
        CHECK(paths[0].fill && paths[0].fill->colorAt({}, {}) == Color::hex(0xFF0000) && !paths[0].stroke && paths[0].commands.size() == 5);
        // Moved by its group; its stroke's color half transparent, then half again.
        const VectorPath& line = paths[1];
        CHECK(!line.fill && line.stroke && near(line.stroke->colorAt({}, {}).a, 128 / 255.f, 0.01f) && near(line.strokeAlpha, 0.5f) &&
              near(line.strokeLineWidth, 2) && line.strokeLineCap == StrokeCap::Round && line.strokeLineJoin == StrokeJoin::Bevel);
        CHECK(near(line.commands[0].x, 12) && near(line.commands[0].y, 12) && near(line.commands[1].x, 18) && near(line.commands[1].y, 12));
        // Turned a quarter clockwise about its pivot (and stretched along x first), inside the moved group.
        const VectorPath& turned = paths[2];
        CHECK(turned.fill && turned.fill->colorAt({}, {}) == Color::hex(0x00FF00) && turned.pathFillType == Path::FillType::EvenOdd);
        CHECK(near(turned.commands[0].x, 24) && near(turned.commands[0].y, 18) && near(turned.commands[1].x, 18) && near(turned.commands[1].y, 18));
        CHECK(near(turned.commands[2].x, 18) && near(turned.commands[2].y, 22));  // 2 right of the pivot, stretched to 4, turned to below it
        // A gradient no longer than a point: its start color (#ARGB), with its own alpha.
        CHECK(paths[3].fill && paths[3].fill->kind() == Brush::Kind::Linear && paths[3].fill->colorAt({}, {}) == Color::hex(0xFFFF00, 0x88 / 255.f) &&
              near(paths[3].fillAlpha, 0.25f));
        CHECK(near(paths[3].commands[0].x, 0) && near(paths[3].commands[0].y, 16) && near(paths[3].commands[1].x, 4));  // out of both groups
    }
    CHECK(ImageVector::fromVectorXml("<shape/>").empty() && ImageVector::fromVectorXml("not xml").empty());
    // From an asset: read once through the platform.
    int reads = 0;
    auto shown = mutableStateOf(false);
    ComposeTestRule rule([&] {
        if (shown.get()) Image(VectorPainter(vectorResource("vectors/test.xml")), "test", Modifier().testTag("vektör"));
    }, {400, 800});
    rule.host().setCallbacks({.readAsset = [&](std::string_view path) {
        ++reads;
        std::string text = path == "vectors/test.xml" ? xml : "";
        return std::vector<uint8_t>(text.begin(), text.end());
    }});
    shown.set(true);
    rule.waitForIdle();
    rule.host().invalidate();
    rule.waitForIdle();
    CHECK(reads == 1 && near(rule.onNodeWithTag("vektör").bounds().width, 48) && near(rule.onNodeWithTag("vektör").bounds().height, 40));
}

TEST(vector_drawable_gradients_become_brushes) {
    const char* xml = R"(<vector xmlns:android="http://schemas.android.com/apk/res/android" xmlns:aapt="http://schemas.android.com/aapt"
    android:width="48dp" android:height="48dp" android:viewportWidth="24" android:viewportHeight="24">
    <path android:pathData="M0,0h24v24h-24z">
        <aapt:attr name="android:fillColor">
            <gradient android:type="linear" android:startX="0" android:startY="0" android:endX="24" android:endY="0"
                      android:startColor="#FF0000" android:centerColor="#00FF00" android:endColor="#0000FF"/>
        </aapt:attr>
    </path>
    <group android:translateX="4" android:translateY="2">
        <path android:pathData="M0,0h8v8h-8z" android:strokeWidth="1">
            <aapt:attr name="android:strokeColor">
                <gradient android:type="radial" android:centerX="4" android:centerY="4" android:gradientRadius="4" android:tileMode="mirror">
                    <item android:offset="0" android:color="#FFFFFF"/>
                    <item android:offset="0.25" android:color="#FF0000"/>
                    <item android:offset="1" android:color="#000000"/>
                </gradient>
            </aapt:attr>
        </path>
    </group>
    <group android:scaleX="2" android:scaleY="2">
        <path android:pathData="M0,0h4v4h-4z">
            <aapt:attr name="android:fillColor">
                <gradient android:type="sweep" android:centerX="2" android:centerY="2" android:startColor="#FFFF00" android:endColor="#00FFFF"/>
            </aapt:attr>
        </path>
        <path android:pathData="M0,0h4v4h-4z">
            <aapt:attr name="android:fillColor">
                <gradient android:type="radial" android:centerX="2" android:centerY="2" android:gradientRadius="1" android:tileMode="repeat"
                          android:startColor="#000000" android:endColor="#FFFFFF"/>
            </aapt:attr>
        </path>
    </group>
    <path android:pathData="M0,0h4v4h-4z">
        <aapt:attr name="android:fillColor">
            <gradient android:type="radial" android:startColor="#FF0000" android:endColor="#FFFFFF"/>
        </aapt:attr>
    </path>
</vector>)";
    ImageVector v = ImageVector::fromVectorXml(xml);
    const auto& paths = v.paths();
    CHECK(paths.size() == 5);
    if (paths.size() != 5) return;
    auto same = [](Color a, Color b) { return near(a.r, b.r, 0.01f) && near(a.g, b.g, 0.01f) && near(a.b, b.b, 0.01f) && near(a.a, b.a, 0.01f); };
    const Rect viewport{0, 0, 24, 24};
    // Linear: start, center and end colors from its start point to its end.
    const Brush& linear = *paths[0].fill;
    CHECK(linear.kind() == Brush::Kind::Linear && same(linear.colorAt({0, 5}, viewport), Color::hex(0xFF0000)) &&
          same(linear.colorAt({12, 5}, viewport), Color::hex(0x00FF00)) && same(linear.colorAt({24, 5}, viewport), Color::hex(0x0000FF)));
    // Radial, stroking, of its items, back and forth past its radius; its center moved with its group.
    CHECK(!paths[1].fill && paths[1].stroke && paths[1].stroke->kind() == Brush::Kind::Radial && paths[1].stroke->tileMode() == TileMode::Mirror);
    if (paths[1].stroke) {
        const Brush& radial = *paths[1].stroke;
        CHECK(same(radial.colorAt({8, 6}, viewport), colors::White) && same(radial.colorAt({9, 6}, viewport), Color::hex(0xFF0000)) &&
              same(radial.colorAt({8, 10}, viewport), colors::Black) && same(radial.colorAt({15, 6}, viewport), Color::hex(0xFF0000)));
    }
    // Sweep, clockwise from 3 o'clock round its center (scaled with its group): left of it, halfway.
    const Brush& sweep = *paths[2].fill;
    CHECK(sweep.kind() == Brush::Kind::Sweep && same(sweep.colorAt({8, 4}, viewport), Color::hex(0xFFFF00)) &&
          same(sweep.colorAt({0, 4}, viewport), Color{0.5f, 1, 0.5f, 1}));
    // Its radius scaled too, and repeated past it.
    const Brush& rings = *paths[3].fill;
    CHECK(rings.tileMode() == TileMode::Repeated && same(rings.colorAt({5, 4}, viewport), Color{0.5f, 0.5f, 0.5f, 1}));
    // A radial one without a radius (Android refuses it): its start color.
    CHECK(paths[4].fill->kind() == Brush::Kind::Solid && paths[4].fill->colorAt({}, {}) == Color::hex(0xFF0000));
    // Drawn twice as large as its viewport: its gradients too (the middle of the square, the middle color).
    ComposeTestRule rule([&] { Image(VectorPainter(v), "degrade", Modifier().testTag("degrade")); }, {200, 200});
    Rect image = rule.onNodeWithTag("degrade").bounds();
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    bool middle = false;
    for (size_t i = 0; i < canvas.paths.size(); ++i)
        if (near(canvas.paths[i].x, image.x) && near(canvas.paths[i].width, 48)) middle = same(canvas.pathColors[i], Color::hex(0x00FF00));
    CHECK(near(image.width, 48) && middle);
    // The same with stops of one's own: Brush::radialGradient/sweepGradient(ColorStops).
    Brush ownRadial = Brush::radialGradient({{0, colors::Black}, {0.8f, colors::White}}, Offset{10, 10}, 10);
    CHECK(same(ownRadial.colorAt({14, 10}, viewport), Color{0.5f, 0.5f, 0.5f, 1}) && same(ownRadial.colorAt({19, 10}, viewport), colors::White));
    Brush ownSweep = Brush::sweepGradient({{0, colors::Black}, {0.5f, colors::White}}, Offset{10, 10});
    CHECK(same(ownSweep.colorAt({10, 20}, viewport), Color{0.5f, 0.5f, 0.5f, 1}) && same(ownSweep.colorAt({0, 10}, viewport), colors::White));
    // Scaled: points and radius, not its far edge.
    Brush far = Brush::linearGradient({colors::Black, colors::White}).scaled(2, 2);
    Brush down = Brush::verticalGradient({colors::Black, colors::White}, 0, 10).scaled(2, 2);
    CHECK(same(down.colorAt({0, 10}, Rect{0, 0, 48, 48}), Color{0.5f, 0.5f, 0.5f, 1}));
    CHECK(same(far.colorAt({12, 12}, viewport), Color{0.5f, 0.5f, 0.5f, 1}) &&
          same(ownRadial.scaled(2, 2).colorAt({28, 20}, Rect{0, 0, 48, 48}), Color{0.5f, 0.5f, 0.5f, 1}));
}

TEST(image_vector_groups_move_and_clip_their_paths) {
    const Color red = Color::hex(0xC03030), blue = Color::hex(0x3050C0);
    auto box = [](const std::vector<PathCommand>& commands) {  // its points' bounds
        float x0 = 1e9f, y0 = 1e9f, x1 = -1e9f, y1 = -1e9f;
        for (const PathCommand& c : commands)
            if (c.verb != PathCommand::Verb::Close) x0 = std::min(x0, c.x), y0 = std::min(y0, c.y), x1 = std::max(x1, c.x), y1 = std::max(y1, c.y);
        return Rect{x0, y0, x1 - x0, y1 - y0};
    };
    auto same = [](Color a, Color b) { return near(a.r, b.r, 0.01f) && near(a.g, b.g, 0.01f) && near(a.b, b.b, 0.01f); };
    ImageVector v = ImageVector::Builder(48, 48, 24, 24)
                        .group({.rotate = 90, .pivotX = 12, .pivotY = 12, .clipPathData = "M0,0h12v24h-12z"},
                               [&](ImageVector::Builder& b) {
                                   b.path("M12,2L12,6", std::nullopt, Brush::solid(red), 2);
                                   b.addGroup({.scaleX = 2, .scaleY = 2, .translationX = 1})
                                       .path("M0,0h2v2h-2z", Brush::linearGradient({colors::Black, colors::White}, {0, 0}, {2, 0}), Brush::solid(red), 1)
                                       .clearGroup();
                               })
                        .path("M0,0h4v4h-4z", Brush::solid(blue))
                        .build();
    const auto& paths = v.paths();
    CHECK(paths.size() == 3);
    if (paths.size() != 3) return;
    // Turned a quarter clockwise about the middle: its line from the top to the right; its clip
    // (the left half) the top half.
    const VectorPath& line = paths[0];
    CHECK(near(line.commands[0].x, 22) && near(line.commands[0].y, 12) && near(line.commands[1].x, 18) && near(line.commands[1].y, 12) &&
          near(line.strokeLineWidth, 2));
    CHECK(line.clipPaths.size() == 1);
    if (!line.clipPaths.empty()) {
        Rect clip = box(line.clipPaths[0]);
        CHECK(near(clip.x, 0) && near(clip.y, 0) && near(clip.width, 24) && near(clip.height, 12));
    }
    // Inside a group of its own too: scaled twice (its stroke twice as wide), moved, then turned,
    // its gradient with it (now from the top down); clipped by the outer group still.
    const VectorPath& square = paths[1];
    Rect at = box(square.commands);
    CHECK(near(at.x, 20) && near(at.y, 1) && near(at.width, 4) && near(at.height, 4) && near(square.strokeLineWidth, 2) && square.clipPaths.size() == 1);
    CHECK(square.fill && same(square.fill->colorAt({0, 3}, {0, 0, 24, 24}), Color{0.5f, 0.5f, 0.5f, 1}) &&
          same(square.fill->colorAt({0, 1}, {0, 0, 24, 24}), colors::Black));
    // Out of the groups: as it is.
    CHECK(near(box(paths[2].commands).x, 0) && near(box(paths[2].commands).width, 4) && paths[2].clipPaths.empty());
    // Drawn: each clipped path inside a layer clipped to its clip (twice the viewport); tinted, not
    // as the one-color raster even without strokes (that would leave its clips out).
    ImageVector half = ImageVector::Builder(24, 24, 24, 24).addGroup({.clipPathData = "M0,0h12v24h-12z"}).path("M0,0h24v24h-24z", Brush::solid(red)).build();
    ImageVector middle = ImageVector::Builder(24, 24, 24, 24).addGroup({.clipPathData = "M6,6h12v12h-12z"}).path("M0,0h24v24h-24z", Brush::solid(blue)).build();
    ComposeTestRule rule([&] {
        Column([&] {
            Image(VectorPainter(v), "grup", Modifier().testTag("grup"));
            Icon(half, "ton", Modifier().size(24), Color::hex(0x30A030));
            Image(VectorPainter(middle), "orta", Modifier().testTag("orta"));
        });
    }, {200, 200});
    Rect image = rule.onNodeWithTag("grup").bounds();
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(canvas.depth == 0);  // its layers popped
    // A clip away from the top left: the layer over it, the outline from the layer's top left.
    Rect mid = rule.onNodeWithTag("orta").bounds();
    bool midLayer = false;
    for (size_t i = 0; i < canvas.layerBounds.size(); ++i) {
        const Rect& r = canvas.layerBounds[i];
        midLayer = midLayer || (near(r.x, mid.x + 6) && near(r.y, mid.y + 6) && near(r.width, 12) && near(r.height, 12));
    }
    bool midOutline = false;
    for (const Path& outline : canvas.layerOutlines) {
        Rect r = outline.bounds();
        midOutline = midOutline || (near(r.x, 0) && near(r.y, 0) && near(r.width, 12) && near(r.height, 12));
    }
    CHECK(midLayer && midOutline);
    int clipLayers = 0;
    for (const Path& outline : canvas.layerOutlines) {
        Rect r = outline.bounds();
        if (near(r.x, 0) && near(r.y, 0) && near(r.width, 48) && near(r.height, 24)) ++clipLayers;
    }
    CHECK(clipLayers == 2 && std::count(canvas.vectors.begin(), canvas.vectors.end(), half.id()) == 0 &&
          std::count(canvas.pathColors.begin(), canvas.pathColors.end(), Color::hex(0x30A030)) == 1);
    bool layerAt = false;
    for (const Rect& r : canvas.layerBounds) layerAt = layerAt || (near(r.x, image.x) && near(r.y, image.y) && near(r.width, 48) && near(r.height, 24));
    CHECK(layerAt);
    // A clip of nothing: its paths not drawn.
    ImageVector none = ImageVector::Builder(24, 24, 24, 24).addGroup({.clipPathData = "M5,5"}).path("M0,0h4v4h-4z", Brush::solid(red)).build();
    ComposeTestRule empty([&] { Image(VectorPainter(none), "yok"); }, {100, 100});
    testing::RecordingCanvas nothing;
    empty.host().draw(nothing);
    CHECK(std::count(nothing.pathColors.begin(), nothing.pathColors.end(), red) == 0 && nothing.layerOutlines.empty());
    // Mirrored: its clips and its gradients too.
    ImageVector left = ImageVector::Builder(24, 24, 24, 24)
                           .addGroup({.clipPathData = "M0,0h6v24h-6z"})
                           .path("M0,0h24v24h-24z", Brush::horizontalGradient({colors::Black, colors::White}),
                                 Brush::horizontalGradient({colors::Black, colors::White}), 1)
                           .build()
                           .mirrored();
    CHECK(left.paths().size() == 1);
    if (left.paths().size() == 1) {
        const VectorPath& p = left.paths()[0];
        CHECK(p.clipPaths.size() == 1 && near(box(p.clipPaths[0]).x, 18) && near(box(p.clipPaths[0]).width, 6));
        CHECK(same(p.fill->colorAt({0, 5}, {0, 0, 24, 24}), colors::White) && same(p.fill->colorAt({24, 5}, {0, 0, 24, 24}), colors::Black));
        CHECK(p.stroke && same(p.stroke->colorAt({0, 5}, {0, 0, 24, 24}), colors::White));
    }
    // A path's own clip paths, in a group: moved with it, inside the group's clips. A centered
    // gradient (the middle, the nearer edge) moved and scaled with its group too.
    VectorPath own;
    own.commands = VectorPath::parse("M0,0h4v4h-4z");
    own.clipPaths = {VectorPath::parse("M0,0h2v2h-2z")};
    own.fill = Brush::radialGradient({colors::Black, colors::White});
    ImageVector clipped = ImageVector::Builder(24, 24, 24, 24).group({.scaleX = 0.5f, .scaleY = 0.5f, .translationX = 4, .clipPathData = "M0,0h24v24h-24z"},
                                                                     [&](ImageVector::Builder& b) { b.path(own); }).build();
    const VectorPath& inner = clipped.paths()[0];
    CHECK(inner.clipPaths.size() == 2 && near(box(inner.clipPaths[0]).width, 12) && near(box(inner.clipPaths[1]).x, 4) &&
          near(box(inner.clipPaths[1]).width, 1));
    // Its middle (12, 12) to (10, 6), its radius (12) to 6.
    CHECK(same(inner.fill->colorAt({10, 6}, {0, 0, 24, 24}), colors::Black) && same(inner.fill->colorAt({13, 6}, {0, 0, 24, 24}), Color{0.5f, 0.5f, 0.5f, 1}));
    // From a vector drawable: a <clip-path> clips what comes after it in its group; a group's
    // scale widens its strokes.
    ImageVector xml = ImageVector::fromVectorXml(R"(<vector xmlns:android="http://schemas.android.com/apk/res/android"
        android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">
        <group android:scaleX="2" android:scaleY="2">
            <clip-path android:pathData="M0,0h6v6h-6z"/>
            <path android:strokeColor="#000" android:strokeWidth="1" android:pathData="M1,1h2"/>
            <group android:translateX="1">
                <clip-path android:pathData="M0,0h2v2h-2z"/>
                <path android:fillColor="#000" android:pathData="M0,0h1v1h-1z"/>
            </group>
            <path android:fillColor="#000" android:pathData="M0,0h1v1h-1z"/>
        </group>
        <path android:fillColor="#000" android:pathData="M0,0h1v1h-1z"/>
    </vector>)");
    const auto& xp = xml.paths();
    CHECK(xp.size() == 4);
    if (xp.size() == 4) {
        CHECK(xp[0].clipPaths.size() == 1 && near(box(xp[0].clipPaths[0]).width, 12) && near(xp[0].strokeLineWidth, 2));
        CHECK(xp[1].clipPaths.size() == 2 && near(box(xp[1].clipPaths[1]).x, 2) && near(box(xp[1].clipPaths[1]).width, 4));
        CHECK(xp[2].clipPaths.size() == 1 && xp[3].clipPaths.empty() && near(box(xp[3].commands).width, 1));
    }
}

TEST(vector_paths_trim_and_vectors_come_from_composable_content) {
    // Trimmed: only a piece of a line (twice the viewport) drawn.
    const Color ink = Color::hex(0x2040A0);
    auto drawnBounds = [&](float start, float end, float offset, const char* data = "M0,12h24") {
        VectorPath line{.commands = VectorPath::parse(data), .fill = std::nullopt, .stroke = Brush::solid(ink), .strokeLineWidth = 1,
                        .trimPathStart = start, .trimPathEnd = end, .trimPathOffset = offset};
        ImageVector v = ImageVector::Builder(48, 48, 24, 24).path(line).build();
        ComposeTestRule rule([&] { Image(VectorPainter(v), "çizgi", Modifier().testTag("çizgi")); }, {100, 100});
        Rect image = rule.onNodeWithTag("çizgi").bounds();
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        std::optional<Rect> drawn;
        for (size_t i = 0; i < canvas.paths.size(); ++i)
            if (canvas.pathColors[i] == ink) drawn = Rect{canvas.paths[i].x - image.x, canvas.paths[i].y - image.y, canvas.paths[i].width, canvas.paths[i].height};
        return drawn;
    };
    auto spans = [](std::optional<Rect> r, float x0, float x1) { return r && near(r->x, x0, 0.5f) && near(r->right(), x1, 0.5f); };
    CHECK(spans(drawnBounds(0, 1, 0), 0, 48));         // untrimmed
    CHECK(spans(drawnBounds(0, 0.5f, 0), 0, 24));      // its first half
    CHECK(spans(drawnBounds(0.25f, 0.75f, 0), 12, 36));
    CHECK(spans(drawnBounds(0, 0.5f, 0.5f), 24, 48));  // moved on: its second half
    CHECK(spans(drawnBounds(0.5f, 1, 0.25f), 0, 48));  // 0.75 to 1.25: round its end, both ends drawn
    CHECK(!drawnBounds(0, 0, 0));                      // nothing
    // Every contour's length together: three quarters of two lines (12 and 24 long), the first and
    // 15 of the second.
    std::optional<Rect> two = drawnBounds(0, 0.75f, 0, "M0,0h12M0,12h24");
    CHECK(two && near(two->width, 30, 0.5f) && near(two->height, 24, 0.5f));
    // From a vector drawable.
    ImageVector xml = ImageVector::fromVectorXml(R"(<vector xmlns:android="http://schemas.android.com/apk/res/android"
        android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">
        <path android:strokeColor="#000" android:strokeWidth="1" android:pathData="M0,0h4" android:trimPathStart="0.1"
              android:trimPathEnd="0.6" android:trimPathOffset="0.2"/>
    </vector>)");
    CHECK(xml.paths().size() == 1 && near(xml.paths()[0].trimPathStart, 0.1f, 0.01f) && near(xml.paths()[0].trimPathEnd, 0.6f, 0.01f) &&
          near(xml.paths()[0].trimPathOffset, 0.2f, 0.01f));
    // Composable content: what it reads makes it again; made the same, the same vector.
    auto turn = mutableStateOf(0.f);
    auto other = mutableStateOf(0);
    Painter seen, red, blue;
    int remembered = 0;
    ComposeTestRule rule([&] {
        other.get();
        // Two in one composable: each its own.
        red = rememberVectorPainter(24, 24, 24, 24, [](ImageVector::Builder& v) { v.path("M0,0h4v4h-4z", Brush::solid(Color::hex(0xFF0000))); });
        blue = rememberVectorPainter(24, 24, 24, 24, [](ImageVector::Builder& v) { v.path("M0,0h4v4h-4z", Brush::solid(Color::hex(0x0000FF))); });
        seen = rememberVectorPainter(48, 48, 24, 24, [&](ImageVector::Builder& v) {
            remembered = remember([] { static int made = 0; return ++made; });  // kept inside it
            v.group({.rotate = turn.get(), .pivotX = 12, .pivotY = 12}, [&](ImageVector::Builder& g) { g.path("M12,2L12,6", std::nullopt, Brush::solid(ink), 2); });
        });
        Image(seen, "dönen", Modifier().testTag("dönen"));
    }, {100, 100});
    Painter first = seen, firstRed = red, firstBlue = blue;
    int firstRemembered = remembered;
    other.set(1);
    rule.waitForIdle();
    CHECK(seen == first && remembered == firstRemembered);  // recomposed, made the same
    CHECK(red == firstRed && blue == firstBlue && !(red == blue));
    turn.set(90);
    rule.waitForIdle();
    CHECK(!(seen == first) && remembered == firstRemembered);
    Rect image = rule.onNodeWithTag("dönen").bounds();
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    bool turned = false;  // its line now from the right edge in (18..22, at 12): 36..44 px
    for (size_t i = 0; i < canvas.paths.size(); ++i)
        turned = turned || (canvas.pathColors[i] == ink && near(canvas.paths[i].x - image.x, 36, 2.5f) && near(canvas.paths[i].right() - image.x, 44, 2.5f));
    CHECK(turned);
}

TEST(animated_vectors_play_their_animations) {
    const char* xml = R"(<?xml version="1.0" encoding="utf-8"?>
<animated-vector xmlns:android="http://schemas.android.com/apk/res/android" xmlns:aapt="http://schemas.android.com/aapt">
    <aapt:attr name="android:drawable">
        <vector android:name="root" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">
            <group android:name="spin" android:pivotX="12" android:pivotY="12">
                <path android:name="dot" android:strokeColor="#000000" android:strokeWidth="1" android:pathData="M12,2L12,6"/>
            </group>
            <path android:name="bar" android:fillColor="#FF0000" android:pathData="M0,0h4v4h-4z"/>
            <path android:name="line" android:strokeColor="#000000" android:strokeWidth="1" android:pathData="M0,20h24"/>
        </vector>
    </aapt:attr>
    <target android:name="spin">
        <aapt:attr name="android:animation">
            <set>
                <objectAnimator android:propertyName="rotation" android:valueFrom="90" android:valueTo="180" android:startOffset="100"
                    android:duration="200" android:interpolator="@android:interpolator/linear"/>
                <objectAnimator android:propertyName="rotation" android:valueFrom="0" android:valueTo="90" android:duration="100"
                    android:interpolator="@android:interpolator/linear"/>
            </set>
        </aapt:attr>
    </target>
    <target android:name="bar">
        <aapt:attr name="android:animation">
            <set android:ordering="sequentially">
                <objectAnimator android:propertyName="fillColor" android:valueFrom="#FF0000" android:valueTo="#0000FF" android:duration="100"
                    android:interpolator="@android:interpolator/linear"/>
                <objectAnimator android:propertyName="pathData" android:valueType="pathType" android:valueFrom="M0,0h4v4h-4z"
                    android:valueTo="M0,0h8v8h-8z" android:duration="100" android:interpolator="@android:anim/linear_interpolator"/>
            </set>
        </aapt:attr>
    </target>
    <target android:name="line">
        <aapt:attr name="android:animation">
            <objectAnimator android:duration="60" android:startOffset="100" android:repeatCount="1" android:repeatMode="reverse"
                android:interpolator="@android:interpolator/linear">
                <propertyValuesHolder android:propertyName="trimPathEnd" android:valueFrom="0.8" android:valueTo="0"/>
                <propertyValuesHolder android:propertyName="strokeWidth" android:valueTo="3"/>
            </objectAnimator>
        </aapt:attr>
    </target>
    <target android:name="root">
        <aapt:attr name="android:animation">
            <objectAnimator android:propertyName="alpha" android:valueFrom="1" android:valueTo="0.5" android:duration="200"
                android:interpolator="@android:interpolator/accelerate_quad"/>
        </aapt:attr>
    </target>
</animated-vector>)";
    AnimatedImageVector avd = AnimatedImageVector::fromAnimatedVectorXml(xml);
    CHECK(!avd.empty() && avd.totalDurationMillis() == 300);  // the group's: its longer animator (together), 100 in and 200 long
    auto box = [](const std::vector<PathCommand>& commands) {
        float x0 = 1e9f, y0 = 1e9f, x1 = -1e9f, y1 = -1e9f;
        for (const PathCommand& c : commands)
            if (c.verb != PathCommand::Verb::Close) x0 = std::min(x0, c.x), y0 = std::min(y0, c.y), x1 = std::max(x1, c.x), y1 = std::max(y1, c.y);
        return Rect{x0, y0, x1 - x0, y1 - y0};
    };
    auto same = [](Color a, Color b) { return near(a.r, b.r, 0.01f) && near(a.g, b.g, 0.01f) && near(a.b, b.b, 0.01f); };
    auto at = [&](float t) { return avd.vectorAt(t).paths(); };
    // As it starts: the drawable as it is.
    CHECK(at(0) == avd.imageVector().paths() && at(0).size() == 3);
    if (at(0).size() != 3) return;
    CHECK(same(at(0)[1].fill->colorAt({}, {}), Color::hex(0xFF0000)) && near(box(at(0)[1].commands).width, 4));
    // Its group turning (linear): 45° at 50; from 100 its second animator (started later, over the
    // first): 112.5° at 150.
    const PathCommand dot = at(50)[0].commands[0], later = at(150)[0].commands[0];
    CHECK(near(dot.x, 19.07f, 0.05f) && near(dot.y, 4.93f, 0.05f) && near(later.x, 21.24f, 0.05f) && near(later.y, 15.83f, 0.05f));
    // One after the other: the color first (halfway at 50, done at 100), then the shape (halfway at 150).
    CHECK(same(at(50)[1].fill->colorAt({}, {}), Color{0.5f, 0, 0.5f, 1}) && same(at(100)[1].fill->colorAt({}, {}), Color::hex(0x0000FF)));
    CHECK(near(box(at(100)[1].commands).width, 4, 0.01f) && near(box(at(150)[1].commands).width, 6, 0.01f) &&
          near(box(at(220)[1].commands).width, 8, 0.01f));
    // From 100, there and back (repeatMode reverse), holding where it ends; before it starts, its
    // own value. A property without valueFrom starts at its own value.
    CHECK(near(at(99)[2].trimPathEnd, 1, 0.001f) && near(at(115)[2].trimPathEnd, 0.6f, 0.001f) && near(at(130)[2].trimPathEnd, 0.4f, 0.001f) &&
          near(at(130)[2].strokeLineWidth, 2, 0.001f));
    CHECK(near(at(175)[2].trimPathEnd, 0.2f, 0.001f) && near(at(230)[2].trimPathEnd, 0.8f, 0.001f) && near(at(300)[2].trimPathEnd, 0.8f, 0.001f) &&
          near(at(300)[2].strokeLineWidth, 1, 0.001f));
    // The vector's alpha, accelerating (t²): a quarter of the way at the halfway mark.
    CHECK(near(at(100)[1].fillAlpha, 0.875f, 0.005f) && near(at(200)[1].fillAlpha, 0.5f, 0.005f));
    CHECK(AnimatedImageVector::fromAnimatedVectorXml("<vector/>").empty() && AnimatedImageVector::fromAnimatedVectorXml("not xml").empty());
    // A vector drawable read the same way, whether in an animated one or not.
    CHECK(ImageVector::fromVectorXml(xml).paths() == avd.imageVector().paths());
    // Painted: at its start, then played to its end, then back.
    auto atEnd = mutableStateOf(false);
    ComposeTestRule rule([&] { Image(rememberAnimatedVectorPainter(avd, atEnd.get()), "canlı", Modifier().size(24)); }, {100, 100});
    auto colors = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        return canvas.pathColors;
    };
    auto shows = [&](Color c) {
        std::vector<Color> drawn = colors();
        return std::any_of(drawn.begin(), drawn.end(), [&](Color d) { return same(d, c) && near(d.a, c.a, 0.02f); });
    };
    CHECK(shows(Color::hex(0xFF0000)));
    atEnd.set(true);
    rule.advanceTimeBy(48);
    CHECK(!shows(Color::hex(0xFF0000)) && !shows(Color::hex(0x0000FF).copy(0.5f)));  // on its way
    rule.waitForIdle();
    CHECK(shows(Color::hex(0x0000FF).copy(0.5f)));  // at its end (the vector half transparent)
    atEnd.set(false);
    rule.waitForIdle();
    CHECK(shows(Color::hex(0xFF0000)));  // played back to its start
}

TEST(text_draw_style_strokes_its_glyphs) {
    ComposeTestRule rule([&] {
        Column([&] {
            Text("dolu");
            Text("çizgi", {.drawStyle = Stroke(2, StrokeCap::Butt, StrokeJoin::Round)});
            Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                     b.append("bir ");
                     b.withStyle({.drawStyle = Stroke(3, StrokeCap::Butt, StrokeJoin::Round)}, [&] { b.append("hat"); });
                 }),
                 Modifier(), {});
            // Inherited through LocalTextStyle, a span's Fill filling again.
            ProvideTextStyle({.drawStyle = Stroke(1, StrokeCap::Butt, StrokeJoin::Bevel)}, [&] {
                Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                         b.append("miras ");
                         b.withStyle({.drawStyle = Fill}, [&] { b.append("dolu"); });
                     }),
                     Modifier(), {});
            });
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto fontOf = [&](std::string_view text) -> std::optional<Font> {
        for (size_t i = 0; i < canvas.texts.size(); ++i)
            if (canvas.texts[i] == text) return canvas.fonts[i];
        return std::nullopt;
    };
    CHECK(fontOf("dolu") && near(fontOf("dolu")->strokeWidth, 0, 0.001f));
    CHECK(fontOf("çizgi") && near(fontOf("çizgi")->strokeWidth, 2, 0.001f) && fontOf("çizgi")->strokeJoin == StrokeJoin::Round);
    CHECK(fontOf("bir ") && near(fontOf("bir ")->strokeWidth, 0, 0.001f) && fontOf("hat") && near(fontOf("hat")->strokeWidth, 3, 0.001f) &&
          fontOf("hat")->strokeJoin == StrokeJoin::Round);
    CHECK(fontOf("miras ") && near(fontOf("miras ")->strokeWidth, 1, 0.001f) && fontOf("miras ")->strokeJoin == StrokeJoin::Bevel);
    int filled = 0;  // "dolu" twice: the plain text and the span filled again
    for (size_t i = 0; i < canvas.texts.size(); ++i)
        if (canvas.texts[i] == "dolu" && canvas.fonts[i].strokeWidth == 0) ++filled;
    CHECK(filled == 2);
}

TEST(text_geometric_transform_stretches_and_slants) {
    ComposeTestRule rule([&] {
        Column([&] {
            Text("abcd", Modifier().testTag("düz"), {.fontSize = 20});
            Text("abcd", Modifier().testTag("geniş"), {.fontSize = 20, .textGeometricTransform = TextGeometricTransform{2, 0.25f}});
            Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                     b.append("ab");
                     b.withStyle({.textGeometricTransform = TextGeometricTransform{0.5f, -0.5f}}, [&] { b.append("cd"); });
                 }),
                 Modifier().testTag("parça"), {.fontSize = 20});
        });
    });
    // Its advances stretched: twice as wide; a span half as wide.
    float plain = rule.onNodeWithTag("düz").bounds().width;
    CHECK(near(plain, 40, 0.5f) && near(rule.onNodeWithTag("geniş").bounds().width, 80, 0.5f) &&
          near(rule.onNodeWithTag("parça").bounds().width, 30, 0.5f));
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    bool wide = false, span = false;
    for (size_t i = 0; i < canvas.texts.size(); ++i) {
        const Font& f = canvas.fonts[i];
        wide = wide || (canvas.texts[i] == "abcd" && near(f.scaleX, 2, 0.001f) && near(f.skewX, 0.25f, 0.001f));
        span = span || (canvas.texts[i] == "cd" && near(f.scaleX, 0.5f, 0.001f) && near(f.skewX, -0.5f, 0.001f));
    }
    CHECK(wide && span);
}

TEST(font_variations_pick_a_variable_fonts_instance) {
    using namespace FontVariation;
    CHECK(weight(650) == (Setting{"wght", 650}) && width(80) == (Setting{"wdth", 80}) && slant(-10) == (Setting{"slnt", -10}) &&
          italic(1) == (Setting{"ital", 1}) && grade(50) == (Setting{"GRAD", 50}) && opticalSizing(14) == (Setting{"opsz", 14}));
    std::vector<Setting> s = settings(FontWeight::SemiBold, FontStyle::Italic, {width(75)});
    CHECK(s.size() == 3 && s[0] == weight(600) && s[1] == italic(1) && s[2] == width(75));
    CHECK(settings(FontWeight::Normal, FontStyle::Normal)[1] == italic(0));
    // The same file at two weights: two families' worth of files, told apart by their settings.
    FontFamily light = FontFamily::fromFiles({{"fonts/Flex.ttf", FontWeight::Light, FontStyle::Normal, {weight(300)}}});
    FontFamily heavy = FontFamily::fromFiles({{"fonts/Flex.ttf", FontWeight::Light, FontStyle::Normal, {weight(800)}}});
    FontFamily again = FontFamily::fromFiles({{"fonts/Flex.ttf", FontWeight::Light, FontStyle::Normal, {weight(300)}}});
    CHECK(light.id != heavy.id && light.id == again.id && FontFamily::files(heavy.id)[0].variationSettings == std::vector<Setting>{weight(800)});
}

TEST(image_vector_builder_draws_paths_in_their_own_paints) {
    const Color red = Color::hex(0xC03030), blue = Color::hex(0x3050C0), green = Color::hex(0x30A030);
    ImageVector two = ImageVector::Builder(48, 48, 24, 24)
                          .path("M0,0h12v12h-12z", Brush::solid(red))
                          .path("M12,12h12v12h-12z", std::nullopt, Brush::solid(blue), 2)
                          .build();
    VectorPath faded;
    faded.commands = VectorPath::parse("M0,12h12v12h-12z");
    faded.fill = Brush::solid(red);
    faded.fillAlpha = 0.5f;
    ImageVector fills = ImageVector::Builder(24, 24, 24, 24).path("M0,0h12v12h-12z", Brush::solid(red)).path(faded).build();
    ImageVector arrow = ImageVector::Builder(24, 24, 24, 24).path("M0,0h12v12h-12z", Brush::solid(red)).autoMirror().build();
    // Its filled paths together, for drawing it tinted in one go (a square: move, three lines, close).
    CHECK(fills.commands().size() == 10 && two.commands().size() == 5 && two.paths().size() == 2);
    auto rtl = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            Image(VectorPainter(two), "iki", Modifier().testTag("resim"));  // its default size, its own paints
            Icon(two, "ton", Modifier().size(24).testTag("ton"), green);     // tinted, its stroke too
            Icon(fills, "dolgu", Modifier().size(24), green);                // tinted fills only: the cached raster
            Image(VectorPainter(fills), "yarı", Modifier().size(24).testTag("yarı"));
            Image(VectorPainter(two), "süzgeç", Modifier().size(24).testTag("süzgeç"), Alignment::Center, ContentScale::Fit, 1,
                  ColorFilter::tint(blue));  // a filter tints it, its stroke too
            CompositionLocalProvider({LocalLayoutDirection.provides(rtl.get() ? LayoutDirection::Rtl : LayoutDirection::Ltr)},
                                     [&] { Image(VectorPainter(arrow), "ok", Modifier().size(24).testTag("ok")); });
        });
    }, {400, 800});
    Rect image = rule.onNodeWithTag("resim").bounds();
    CHECK(near(image.width, 48) && near(image.height, 48));
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto inside = [](Rect r, Rect in) { return r.x >= in.x - 0.5f && r.y >= in.y - 0.5f && r.right() <= in.right() + 0.5f && r.bottom() <= in.bottom() + 0.5f; };
    bool redFill = false, blueStroke = false;
    for (size_t i = 0; i < canvas.paths.size(); ++i) {
        if (!inside(canvas.paths[i], image)) continue;
        Rect r = canvas.paths[i];
        redFill = redFill || (canvas.pathColors[i] == red && near(canvas.pathStrokes[i], 0) && near(r.x, image.x) && near(r.width, 24));
        blueStroke = blueStroke || (canvas.pathColors[i] == blue && near(canvas.pathStrokes[i], 4) && near(r.x, image.x + 24) && near(r.width, 24));
    }
    CHECK(redFill && blueStroke);  // twice the viewport: its stroke twice as wide too
    Rect tinted = rule.onNodeWithTag("ton").bounds();
    int greens = 0;
    for (size_t i = 0; i < canvas.paths.size(); ++i)
        if (canvas.pathColors[i] == green) greens += inside(canvas.paths[i], tinted) ? 1 : 100;
    CHECK(greens == 2);  // the tinted one path by path (it has a stroke); the fills-only one not as paths
    CHECK(std::count(canvas.vectors.begin(), canvas.vectors.end(), fills.id()) == 1);  // but as the cached raster
    Rect half = rule.onNodeWithTag("yarı").bounds();
    bool halfAlpha = false;
    for (size_t i = 0; i < canvas.paths.size(); ++i)
        if (inside(canvas.paths[i], half) && near(canvas.paths[i].y, half.y + 12)) halfAlpha = near(canvas.pathColors[i].a, red.a * 0.5f, 0.01f);
    CHECK(halfAlpha);
    Rect filtered = rule.onNodeWithTag("süzgeç").bounds();
    int blues = 0;
    for (size_t i = 0; i < canvas.paths.size(); ++i)
        if (inside(canvas.paths[i], filtered) && canvas.pathColors[i] == blue) ++blues;
    CHECK(blues == 2);
    // Mirrored right to left: its square at the right.
    auto squareX = [&] {
        testing::RecordingCanvas c;
        rule.host().draw(c);
        Rect ok = rule.onNodeWithTag("ok").bounds();
        for (size_t i = 0; i < c.paths.size(); ++i)
            if (inside(c.paths[i], ok)) return c.paths[i].x - ok.x;
        return -1.f;
    };
    CHECK(near(squareX(), 0));
    rtl.set(true);
    rule.waitForIdle();
    CHECK(near(squareX(), 12));
}

TEST(clip_scrollable_container_clips_along_its_axis) {
    int clicks = 0;
    ComposeTestRule rule([&] {
        Column(Modifier().padding(40), [&] {
            Box(Modifier().size(200, 100).clipScrollableContainer(Orientation::Vertical), [] { Box(Modifier().size(300, 300)); });
            Box(Modifier().size(200, 100).clipScrollableContainer(Orientation::Horizontal), [&] {
                Box(Modifier().offset(0, 100).size(80, 40).clickable([&] { ++clicks; }));  // 10 dp in its 30 below, 30 past
            });
        });
    }, {400, 800});
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto has = [&](Rect want) { return std::any_of(canvas.clips.begin(), canvas.clips.end(), [&](Rect r) { return sameRect(r, want); }); };
    CHECK(has({40 - 30, 40, 200 + 60, 100}));   // its height, 30 dp more each side across
    CHECK(has({40, 140 - 30, 200, 100 + 60}));  // its width, 30 dp more above and below
    auto tap = [&](Offset at) {
        rule.host().pointerDown(at, -1, 0, ComposeHost::PointerType::Mouse);
        rule.advanceFrame();
        rule.host().pointerUp(at);
        rule.waitForIdle();
    };
    tap({80, 245});  // 240..270 shows
    CHECK(clicks == 1);
    tap({80, 275});  // past it: cut off
    CHECK(clicks == 1);
    // The same text turned the other way clips the other way (not skipped as if nothing changed).
    auto vertical = mutableStateOf(true);
    ComposeTestRule turned([&] {
        Text("Kart", Modifier().padding(40).size(200, 100).clipScrollableContainer(vertical.get() ? Orientation::Vertical : Orientation::Horizontal));
    }, {400, 800});
    vertical.set(false);
    turned.waitForIdle();
    testing::RecordingCanvas after;
    turned.host().draw(after);
    CHECK(std::any_of(after.clips.begin(), after.clips.end(), [](Rect r) { return sameRect(r, {40, 40 - 30, 200, 100 + 60}); }));
}

TEST(what_shows_past_a_scroll_container_across_counts_as_shown) {
    std::optional<bool> visible;
    Rect shown;
    int clicks = 0;
    ComposeTestRule rule([&] {
        Column(Modifier().padding(40), [&] {
            // 20 dp out of the column's side, in its 30: all of it shows.
            Column(Modifier().size(200, 100).verticalScroll(rememberScrollState()), [&] {
                Box(Modifier().size(50).offset(-20, 0).onVisibilityChanged([&](bool v) { visible = v; }).onGloballyPositioned([&](const LayoutCoordinates& c) {
                    shown = c.boundsInWindow();
                }));
            });
            // Hanging 10 dp under a row: still clicked there (in its 30).
            LazyRow(Modifier().size(200, 100), {}, [&](LazyListScope& l) {
                l.item([&] { Box(Modifier().size(80, 100), [&] { Box(Modifier().offset(0, 100).size(80, 20).clickable([&] { ++clicks; })); }); });
            });
            Spacer(Modifier().height(40));
            // A box cutting off a row 10 dp under it: the row is drawn (its 30 dp across reach into the box).
            Box(Modifier().size(200, 100).clipToBounds(), [&] {
                LazyRow(Modifier().offset(0, 110).size(200, 100), {}, [](LazyListScope& l) { l.items(3, [](int) { Box(Modifier().size(80, 100)); }); });
            });
        });
    }, {400, 800});
    rule.waitForIdle();
    CHECK(visible == true && near(shown.x, 20) && near(shown.width, 50));
    rule.host().pointerDown({80, 245}, -1, 0, ComposeHost::PointerType::Mouse);  // the row 140..240, the part 240..260
    rule.advanceFrame();
    rule.host().pointerUp({80, 245});
    rule.waitForIdle();
    CHECK(clicks == 1);
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(std::any_of(canvas.clips.begin(), canvas.clips.end(), [](Rect r) { return sameRect(r, {40, 390 - 30, 200, 160}); }));  // the inner row at 390
}

TEST(semantics_merge_clear_and_hide) {
    ComposeTestRule rule([&] {
        Column([&] {
            Row(Modifier().semantics({.mergeDescendants = true}), [&] {  // read as one
                Icon(Icons::Filled::Star, "Yıldızlı");
                Text("Favoriler");
                Text("gizli", Modifier().hideFromAccessibility());  // not part of it
                Box(Modifier().clearAndSetSemantics({.contentDescription = "3 yorum"}), [] { Text("üç"); });  // its own words only
                Button([] {}, [] { Text("Aç"); });  // interactive: on its own
            });
            Box(Modifier().clearAndSetSemantics({.contentDescription = "Puan: 4 / 5"}), [&] {
                Row([&] {
                    for (int i = 0; i < 4; ++i) Icon(Icons::Filled::Star, "yıldız");
                    Text("4/5");
                    Button([] {}, [] { Text("İç düğme"); });
                });
            });
            Text("Süs", Modifier().hideFromAccessibility());
            Box(Modifier().hideFromAccessibility(), [&] { Button([] {}, [] { Text("Gizli düğme"); }); });
            // Two semantics modifiers on one node: the toggle's role and state, the description after.
            Box(Modifier().size(40).toggleable(true, [](bool) {}, SemanticsRole::Switch).semantics({.contentDescription = "Wi-Fi"}).testTag("anahtar"));
            Text("Düz metin");
            Text("Temizlenen metin", Modifier().clearAndSetSemantics({}));  // says nothing, not even its text
            Text("Süs 2", Modifier().semantics({.heading = true}).hideFromAccessibility());  // hidden by a later modifier
            // The first role and state set win; a state set only later is kept.
            Box(Modifier().size(40).semantics({.role = SemanticsRole::Tab}).semantics({.contentDescription = "Sekme", .role = SemanticsRole::Image}));
            Box(Modifier().size(40).semantics({.contentDescription = "Bildirim"}).toggleable(false, [](bool) {}, SemanticsRole::Switch));
        });
    });
    auto tree = rule.host().semanticsTree();
    auto find = [&](const std::string& label) -> const SemanticsNode* {
        for (const auto& n : tree)
            if (n.label == label) return &n;
        return nullptr;
    };
    auto any = [&](const std::string& part) {
        return std::ranges::any_of(tree, [&](const SemanticsNode& n) { return n.label.find(part) != std::string::npos; });
    };
    const SemanticsNode* row = find("Yıldızlı Favoriler 3 yorum");
    const SemanticsNode* open = find("Aç");
    CHECK(row && open && open->parent == row->id && open->clickable);
    CHECK(!find("Favoriler") && !find("Yıldızlı"));  // merged, not on their own
    const SemanticsNode* rating = find("Puan: 4 / 5");
    CHECK(rating && !any("yıldız") && !any("4/5") && !any("İç düğme"));
    CHECK(!any("Süs") && !any("Gizli düğme"));
    const SemanticsNode* wifi = find("Wi-Fi");
    CHECK(wifi && wifi->role == SemanticsRole::Switch && wifi->checked == true && wifi->clickable);
    CHECK(find("Düz metin"));
    CHECK(!any("gizli") && !any("üç") && !any("Temizlenen metin") && !any("Süs 2"));
    const SemanticsNode* tab = find("Sekme");
    const SemanticsNode* bell = find("Bildirim");
    CHECK(tab && tab->role == SemanticsRole::Tab);
    CHECK(bell && bell->role == SemanticsRole::Switch && bell->checked == false);
    rule.onNodeWithTag("anahtar").assertIsOn().assertContentDescriptionEquals("Wi-Fi");
    CHECK(rule.onNodeWithContentDescription("Wi-Fi").exists() && rule.onNodeWithContentDescription("Puan: 4 / 5").exists());
}

TEST(on_globally_positioned_tells_where_a_node_ended_up) {
    std::vector<LayoutCoordinates> moved, placed, inner, clipped;
    auto wide = mutableStateOf(false);
    auto other = mutableStateOf(0);
    ScrollState scroll;
    ComposeTestRule rule([&] {
        other.get();
        Column(Modifier().padding(20), [&] {
            Box(Modifier().size(wide.get() ? 150.f : 100.f, 50).onGloballyPositioned([&](const LayoutCoordinates& c) { moved.push_back(c); }));
            Box(Modifier().size(50).clip(RoundedCornerShape(8)), [&] {  // a child bigger than a clip: only the clip's part shows
                Box(Modifier().requiredSize(100).onGloballyPositioned([&](const LayoutCoordinates& c) { clipped.push_back(c); }));
            });
            Column(Modifier().height(200).fillMaxWidth().verticalScroll(scroll), [&] {
                Box(Modifier().height(300));
                Box(Modifier().size(80, 40).padding(10)
                        .onGloballyPositioned([&](const LayoutCoordinates& c) { inner.push_back(c); })
                        .onPlaced([&](const LayoutCoordinates& c) { placed.push_back(c); }));
            });
        });
    });
    CHECK(moved.size() == 1 && inner.size() == 1 && placed.size() == 1);
    if (moved.size() == 1) {
        const LayoutCoordinates& c = moved[0];
        CHECK(c.size().width == 100 && c.size().height == 50 && c.positionInRoot().x == 20 && c.positionInRoot().y == 20 &&
              c.positionInParent().x == 0 && c.positionInParent().y == 0 && c.boundsInRoot().height == 50);
        CHECK(c.localToRoot({5, 5}).x == 25 && c.rootToLocal({25, 25}).y == 5 && c.positionInWindow().y == 20 && c.isAttached());
    }
    if (inner.size() == 1) {  // inside the padding, below the view: nothing of it shows
        const LayoutCoordinates& c = inner[0];
        CHECK(c.size().width == 60 && c.size().height == 20 && c.positionInRoot().x == 30 && c.positionInRoot().y == 430 &&
              c.boundsInRoot().height == 0 && c.positionInParent().y == 310);
    }
    CHECK(clipped.size() == 1 && clipped[0].size().width == 100 && clipped[0].boundsInRoot().width == 50 && clipped[0].boundsInRoot().height == 50);
    other.set(1);  // composed again, nothing moved: not told again
    rule.waitForIdle();
    CHECK(moved.size() == 1 && inner.size() == 1 && placed.size() == 1);
    scroll.scrollTo(150);  // scrolled into view: its place on the screen changes, not in its parent
    rule.waitForIdle();
    CHECK(inner.size() == 2 && placed.size() == 1 && moved.size() == 1);
    if (inner.size() == 2)  // as far as it goes: 340 - 200
        CHECK(inner[1].positionInRoot().y == 290 && inner[1].boundsInRoot().height == 20 && inner[1].positionInParent().y == 310);
    wide.set(true);  // bigger: told
    rule.waitForIdle();
    CHECK(moved.size() == 2 && moved.back().size().width == 150);
}

TEST(selectable_and_toggleable_rows_take_the_tap_for_their_controls) {
    auto choice = mutableStateOf(0);
    auto on = mutableStateOf(false);
    auto tri = mutableStateOf(ToggleableState::Off);
    ComposeTestRule rule([&] {
        Column(Modifier().selectableGroup().testTag("grup"), [&] {
            for (int i = 0; i < 3; ++i)
                Row(Modifier().fillMaxWidth().height(56).selectable(choice.get() == i, [choice, i] { choice.set(i); }, SemanticsRole::RadioButton)
                        .testTag(std::format("satır {}", i)),
                    {.verticalAlignment = Alignment::CenterVertically}, [&] {
                        RadioButton(choice.get() == i, {}, Modifier().testTag(std::format("düğme {}", i)));
                        Text(std::format("seçenek {}", i));
                    });
            Row(Modifier().fillMaxWidth().height(56).toggleable(on.get(), [on](bool v) { on.set(v); }, SemanticsRole::Switch).testTag("anahtar satırı"),
                {.verticalAlignment = Alignment::CenterVertically}, [&] {
                    Text("Bildirimler");
                    Switch(on.get(), {}, Modifier().testTag("anahtar"));
                });
            Row(Modifier().fillMaxWidth().height(56)
                    .triStateToggleable(tri.get(), [tri] { tri.set(tri.peek() == ToggleableState::Off ? ToggleableState::Indeterminate
                                                                 : tri.peek() == ToggleableState::Indeterminate ? ToggleableState::On
                                                                                                                  : ToggleableState::Off); },
                                        SemanticsRole::Checkbox)
                    .testTag("üç"),
                [&] { TriStateCheckbox(tri.get(), {}, Modifier().testTag("kutu")); });
        });
    });
    rule.onNodeWithTag("satır 0").assertIsSelected();
    rule.onNodeWithTag("düğme 2").performClick();  // the control has no callback: the row takes the tap
    CHECK(choice.peek() == 2);
    rule.waitForIdle();
    rule.onNodeWithTag("satır 2").assertIsSelected();
    rule.onNodeWithTag("satır 0").assertIsNotSelected();
    rule.onNodeWithText("seçenek 1").performClick();
    CHECK(choice.peek() == 1);
    rule.onNodeWithTag("anahtar").performClick();
    CHECK(on.peek());
    rule.waitForIdle();
    rule.onNodeWithTag("anahtar satırı").assertIsOn();
    rule.onNodeWithTag("kutu").performClick();
    CHECK(tri.peek() == ToggleableState::Indeterminate);
    rule.waitForIdle();
    auto* s = rule.onNodeWithTag("üç").node()->modifier.find<SemanticsElement>();
    CHECK(s && !s->properties.checked && s->properties.stateDescription == "Partially checked" && s->properties.role == SemanticsRole::Checkbox);
    auto* g = rule.onNodeWithTag("grup").node()->modifier.find<SemanticsElement>();
    CHECK(g && g->properties.selectableGroup);
    CHECK(!rule.onNodeWithTag("düğme 0").node()->modifier.find<ClickableElement>());  // no callback, not clickable
}

TEST(match_parent_size_and_fill_parent_max) {
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().testTag("kutu"), [&] {
                Box(Modifier().size(120, 60));
                Box(Modifier().matchParentSize().testTag("arka"), [] { Box(Modifier().size(300)); });  // as big as the others made it, no bigger
            });
            LazyColumn(Modifier().size(200, 300), {.contentPadding = {0, 20, 0, 20}}, [&](LazyListScope& l) {
                l.item([] { Box(Modifier().fillParentMaxHeight(0.5f).fillParentMaxWidth(0.5f).testTag("yarı")); });
                l.item([] { Box(Modifier().fillParentMaxSize().testTag("tam")); });
            });
            Box(Modifier().size(200), [] { Box(Modifier().fillParentMaxWidth(0.5f).height(10).testTag("dışarıda")); });  // outside a list: as fillMaxWidth
        });
    });
    Rect box = rule.onNodeWithTag("kutu").bounds(), back = rule.onNodeWithTag("arka").bounds();
    CHECK(box.width == 120 && box.height == 60 && back.width == 120 && back.height == 60 && back.x == box.x);
    Rect half = rule.onNodeWithTag("yarı").bounds(), full = rule.onNodeWithTag("tam").bounds();
    CHECK(half.width == 100 && half.height == 130 && full.width == 200 && full.height == 260);  // the list's viewport past its padding
    CHECK(rule.onNodeWithTag("dışarıda").bounds().width == 100);
}

TEST(snackbars_lay_out_as_compose_and_host_your_own) {
    ComposeTestRule rule([&] {
        Column([&] {
            Snackbar([] { Text("Kaydedildi"); }, Modifier().testTag("tek"),
                     {.action = [] { TextButton([] {}, [] { Text("Geri al"); }); }});
            Snackbar([] { Text("Uzun bir ileti iki satıra iner çünkü sığmaz bu genişliğe"); }, Modifier().width(300).testTag("çift"),
                     {.action = [] { TextButton([] {}, [] { Text("Tamam"); }); }});
            Snackbar([] { Text("Yalnız"); }, Modifier().testTag("yalnız"));  // nothing else: still 48
            Snackbar([] { Text("Büyük eylemli"); }, Modifier().testTag("büyük"), {.action = [] { Text("EYLEM", {.fontSize = 28}); }});
            Snackbar([] { Text("İki satıra inen bir ileti"); }, Modifier().width(240).testTag("iki"),
                     {.action = [] { TextButton([] {}, [] { Text("Tamam"); }); }});
            Snackbar([] { Text("Alt satırda eylem"); }, Modifier().testTag("alt"),
                     {.action = [] { TextButton([] {}, [] { Text("Uzun bir eylem adı"); }); }, .actionOnNewLine = true,
                      .containerColor = Color{0.1f, 0.2f, 0.3f, 1}});
        });
    }, {800, 1000});
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    std::map<std::string, Offset> at;
    for (size_t i = 0; i < canvas.texts.size(); ++i) at[canvas.texts[i]] = canvas.baselines[i];
    Rect one = rule.onNodeWithTag("tek").bounds(), two = rule.onNodeWithTag("çift").bounds(), below = rule.onNodeWithTag("alt").bounds();
    // One line: 48 dp, 600 wide inside its 16 and 8 dp sides (624, as Compose's), the action on
    // the text's baseline at the end (the button's 12 dp padding around its label).
    CHECK(near(one.width, 624) && near(one.height, 48) && near(at["Kaydedildi"].y, at["Geri al"].y) && near(at["Kaydedildi"].x, one.x + 16));
    CHECK(near(rule.onNodeWithText("Geri al").bounds().right() + 12, one.right() - 8));
    // Two lines: the first baseline 30 down, 68 dp at least.
    LayoutNode* longText = rule.onNodeWithText("Uzun bir ileti iki satıra iner çünkü sığmaz bu genişliğe").node();
    CHECK(longText && near(longText->bounds().y + longText->alignmentLine(FirstBaseline), two.y + 30) && two.height > 69);
    CHECK(near(longText->bounds().bottom() + 6, two.bottom()));  // more than two lines: the text's 6 dp below it
    LayoutNode* twoLines = rule.onNodeWithText("İki satıra inen bir ileti").node();
    CHECK(twoLines && twoLines->alignmentLine(LastBaseline) > twoLines->alignmentLine(FirstBaseline) &&
          near(rule.onNodeWithTag("iki").bounds().height, 68));  // two lines: 68 dp
    CHECK(near(rule.onNodeWithTag("yalnız").bounds().height, 48));
    CHECK(near(at["Büyük eylemli"].y, at["EYLEM"].y));  // a taller action still on the text's baseline
    // The action on a line of its own, at the end; its own container color.
    Rect action = rule.onNodeWithText("Uzun bir eylem adı").bounds();
    CHECK(action.y > at["Alt satırda eylem"].y && near(action.right() + 12, below.right() - 8) && near(at["Alt satırda eylem"].y, below.y + 30));
    CHECK(std::ranges::count(canvas.rectColors, Color{0.1f, 0.2f, 0.3f, 1}) == 1);
}

