TEST(pointer_events_enter_move_exit_press_release_and_scroll) {
    auto log = std::make_shared<std::vector<std::string>>();
    ScrollState scroll;
    auto takeWheel = mutableStateOf(false);
    ComposeTestRule rule([&] {
        Column([&] {
            auto record = [log](const char* name) {
                return [log, name](PointerEvent& e) {
                    std::string entry = std::format("{} {:g},{:g}", name, e.change.position.x, e.change.position.y);
                    if (e.button) entry += std::format(" b{}", int(*e.button));
                    if (e.keyboardModifiers.ctrl) entry += " ctrl";
                    if (e.type == PointerEventType::Scroll) entry += std::format(" d{:g}", e.change.scrollDelta.y);
                    log->push_back(entry);
                };
            };
            Box(Modifier()
                    .padding(10)
                    .size(100, 50)
                    .onPointerEvent(PointerEventType::Enter, record("enter"))
                    .onPointerEvent(PointerEventType::Exit, record("exit"))
                    .onPointerEvent(PointerEventType::Move, record("move"))
                    .onPointerEvent(PointerEventType::Press, record("press"))
                    .onPointerEvent(PointerEventType::Release, record("release")));
            Column(Modifier().height(100).verticalScroll(scroll), [&] {
                Box(Modifier().size(100, 400).onPointerEvent(PointerEventType::Scroll, [log, &takeWheel](PointerEvent& e) {
                    log->push_back(std::format("scroll d{:g}", e.change.scrollDelta.y));
                    if (takeWheel.peek()) e.change.consume();
                }));
            });
        });
    });
    rule.host().pointerMove({20, 20});  // over it: in, then the move (local to the box)
    rule.host().pointerMove({30, 25});
    rule.host().setKeyboardModifiers({.ctrl = true});
    rule.host().pointerDown({30, 25}, -1, 0, ComposeHost::PointerType::Mouse);
    rule.host().pointerUp({30, 25});
    rule.host().setKeyboardModifiers({});
    rule.host().mouseButton({40, 30}, PointerButton::Tertiary, true);
    rule.host().mouseButton({40, 30}, PointerButton::Tertiary, false);
    rule.host().pointerMove({300, 20});  // away: out
    rule.host().pointerMove({300, 30});
    CHECK((*log == std::vector<std::string>{"enter 10,10", "move 10,10", "move 20,15", "press 20,15 b0 ctrl", "release 20,15 b0 ctrl",
                                            "press 30,20 b2", "release 30,20 b2", "exit 290,10"}));
    log->clear();
    rule.host().pointerMove({20, 20});
    rule.host().pointerExit();  // the mouse left the window
    CHECK((*log == std::vector<std::string>{"enter 10,10", "move 10,10", "exit 10,10"}));
    // The wheel: the handler hears it (down: positive) and the list scrolls, unless it consumes it.
    log->clear();
    rule.host().scroll({50, 120}, -1);
    rule.waitForIdle();
    float scrolled = scroll.value();
    CHECK((*log == std::vector<std::string>{"scroll d1"}) && scrolled > 0);
    takeWheel.set(true);
    rule.host().scroll({50, 120}, -1);
    rule.waitForIdle();
    CHECK(scroll.value() == scrolled && log->size() == 2);
}

TEST(on_click_matches_buttons_pointers_and_keys) {
    int primary = 0, secondary = 0, withCtrl = 0, mouseOnly = 0, doubles = 0, longs = 0;
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().size(100, 40).onClick([&] { ++primary; }));
            Box(Modifier().size(100, 40).onClick([&] { ++secondary; }, {.matcher = PointerMatcher::mouse(PointerButton::Secondary)}));
            Box(Modifier().size(100, 40).onClick([&] { ++withCtrl; }, {.keyboardModifiers = [](const KeyModifiers& m) { return m.ctrl; }}));
            Box(Modifier().size(100, 40).onClick([&] { ++mouseOnly; }, {.matcher = PointerMatcher::mouse(PointerButton::Primary)}));
            Box(Modifier().size(100, 40).onClick([&] {}, {.onDoubleClick = [&] { ++doubles; }, .onLongClick = [&] { ++longs; }}));
        });
    });
    auto click = [&](Offset p) {
        rule.host().pointerDown(p, -1, 0, ComposeHost::PointerType::Mouse);
        rule.advanceFrame();
        rule.host().pointerUp(p);
        rule.advanceTimeBy(400);
    };
    click({50, 20});
    tap(rule, {50, 20});  // a finger too
    rule.advanceTimeBy(400);
    CHECK(primary == 2);
    click({50, 60});  // the primary button: not this one's
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, true);
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, false);
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, true);
    rule.host().mouseButton({50, 150}, PointerButton::Secondary, false);  // let go elsewhere: no click
    rule.host().mouseButton({50, 60}, PointerButton::Tertiary, false);
    CHECK(secondary == 1);
    rule.host().mouseButton({50, 150}, PointerButton::Secondary, true);  // pressed elsewhere (after one let go elsewhere), let go over it
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, false);
    rule.host().mouseButton({50, 60}, PointerButton::Tertiary, true);  // another button pressed, this one let go
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, false);
    CHECK(secondary == 1);  // no clicks
    tap(rule, {50, 60});  // after a finger's tap: only a mouse has that button anyway
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, true);
    rule.host().mouseButton({50, 60}, PointerButton::Secondary, false);
    CHECK(secondary == 2);
    click({50, 100});
    rule.host().setKeyboardModifiers({.ctrl = true});
    click({50, 100});
    rule.host().setKeyboardModifiers({});
    CHECK(withCtrl == 1);
    tap(rule, {50, 140});
    rule.advanceTimeBy(400);
    click({50, 140});
    CHECK(mouseOnly == 1);
    for (int i = 0; i < 2; ++i) {  // a double click
        rule.host().pointerDown({50, 180}, -1, 0, ComposeHost::PointerType::Mouse);
        rule.advanceFrame();
        rule.host().pointerUp({50, 180});
        rule.advanceTimeBy(48);
    }
    rule.advanceTimeBy(400);
    rule.host().pointerDown({50, 180}, -1, 0, ComposeHost::PointerType::Mouse);  // a long press
    rule.advanceTimeBy(800);
    rule.host().pointerUp({50, 180});
    rule.advanceTimeBy(400);
    CHECK(doubles == 1 && longs == 1);
}

TEST(tooltip_area_shows_by_the_mouse_after_a_moment) {
    ComposeTestRule rule([&] {
        Box(Modifier().fillMaxSize(), [&] {
            Box(Modifier().padding(40), [&] {
                TooltipArea([] { Text("ipucu", Modifier().testTag("ipucu")); }, Modifier().testTag("alan"),
                            [] { Box(Modifier().size(120, 60)); });
            });
            Box(Modifier().padding(200, 400, 0, 0), [&] {
                TooltipArea([] { Box(Modifier().size(30, 10).testTag("altında")); }, Modifier(),
                            {.delayMillis = 100, .tooltipPlacement = TooltipPlacement::ComponentRect()}, [] { Box(Modifier().size(80, 40)); });
            });
        });
    });
    rule.host().pointerMove({60, 50});
    rule.advanceTimeBy(300);
    CHECK(!rule.onNodeWithTag("ipucu").exists());  // not yet
    rule.host().pointerMove({70, 55});
    rule.advanceTimeBy(300);
    auto tip = rule.onNodeWithTag("ipucu");
    CHECK(tip.exists());
    if (tip.exists()) CHECK(tip.bounds().x == 70 && tip.bounds().y == 55 + 16);  // at the pointer, 16 dp below
    rule.host().pointerMove({90, 60});  // it follows the mouse
    rule.waitForIdle();
    CHECK(rule.onNodeWithTag("ipucu").bounds().x == 90);
    rule.host().pointerDown({90, 60}, -1, 0, ComposeHost::PointerType::Mouse);  // a press hides it
    rule.host().pointerUp({90, 60});
    rule.waitForIdle();
    CHECK(!rule.onNodeWithTag("ipucu").exists());
    rule.host().pointerMove({91, 60});
    rule.advanceTimeBy(600);
    CHECK(rule.onNodeWithTag("ipucu").exists());
    rule.host().pointerMove({300, 300});  // leaving hides it
    rule.waitForIdle();
    CHECK(!rule.onNodeWithTag("ipucu").exists());
    // By the area: below it, centered.
    rule.host().pointerMove({220, 420});
    rule.advanceTimeBy(200);
    auto below = rule.onNodeWithTag("altında");
    CHECK(below.exists());
    if (below.exists()) CHECK(below.bounds().x == 200 + 40 - 15 && below.bounds().y == 440);
}

bool nearColor(Color a, Color b, float tolerance = 0.003f) {
    return near(a.r, b.r, tolerance) && near(a.g, b.g, tolerance) && near(a.b, b.b, tolerance) && near(a.a, b.a, tolerance);
}

TEST(color_filters_tint_matrices_and_lighting) {
    Color red{1, 0, 0, 0.5f}, blue{0, 0, 1, 1}, halfBlue{0, 0, 1, 0.5f};
    CHECK(nearColor(ColorFilter::tint(blue).apply(red), Color{0, 0, 1, 0.5f}));             // SrcIn: its shape in the color
    CHECK(nearColor(ColorFilter::tint(halfBlue, BlendMode::SrcAtop).apply(Color{1, 0, 0, 1}), Color{0.5f, 0, 0.5f, 1}));
    CHECK(nearColor(ColorFilter::tint(halfBlue, BlendMode::Src).apply(red), halfBlue));
    CHECK(nearColor(ColorFilter::tint(halfBlue, BlendMode::DstIn).apply(Color{1, 0, 0, 1}), Color{1, 0, 0, 0.5f}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 1, 1, 1}, BlendMode::Modulate).apply(Color{1, 0.5f, 0, 1}), Color{0.5f, 0.5f, 0, 1}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 1}, BlendMode::Multiply).apply(Color{1, 1, 0, 1}), Color{0.5f, 0.5f, 0, 1}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 1}, BlendMode::Screen).apply(Color{1, 0, 0, 1}), Color{1, 0.5f, 0.5f, 1}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 1}, BlendMode::Darken).apply(Color{1, 0, 0, 1}), Color{0.5f, 0, 0, 1}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 1}, BlendMode::Lighten).apply(Color{1, 0, 0, 1}), Color{1, 0.5f, 0.5f, 1}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 1}, BlendMode::Plus).apply(Color{0.75f, 0, 0, 1}), Color{1, 0.5f, 0.5f, 1}));
    CHECK(nearColor(ColorFilter::tint(halfBlue, BlendMode::SrcOver).apply(Color{1, 0, 0, 1}), Color{0.5f, 0, 0.5f, 1}));
    CHECK(nearColor(ColorFilter::tint(blue).apply(Color{1, 0, 0, 0}), Color{0, 0, 0, 0}));  // nothing there: nothing
    ColorMatrix gray;
    gray.setToSaturation(0);
    CHECK(nearColor(ColorFilter::colorMatrix(gray).apply(Color{1, 0, 0, 1}), Color{0.213f, 0.213f, 0.213f, 1}));
    ColorMatrix scale;
    scale.setToScale(0.5f, 1, 1, 1);
    scale.timesAssign(gray);  // gray first, then halve the red
    CHECK(nearColor(scale.apply(Color{0, 1, 0, 1}), Color{0.3575f, 0.715f, 0.715f, 1}));
    scale.reset();
    CHECK(scale == ColorMatrix{});
    CHECK(nearColor(ColorFilter::lighting(Color{0.5f, 1, 1, 1}, Color{0.1f, 0.25f, 0, 0}).apply(Color{1, 0.5f, 0, 0.8f}), Color{0.6f, 0.75f, 0, 0.8f}));
    // Where it matters that the colors are premultiplied, and what each mode does with alpha.
    CHECK(nearColor(ColorFilter::tint(Color{0, 0, 0.4f, 1}).apply(Color{1, 0, 0, 0.5f}), Color{0, 0, 0.4f, 0.5f}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 0.5f}, BlendMode::Multiply).apply(Color{1, 1, 0, 1}), Color{0.75f, 0.75f, 0, 1}));
    CHECK(nearColor(ColorFilter::tint(Color{0.5f, 0.5f, 0.5f, 1}, BlendMode::Screen).apply(Color{0.5f, 0, 0, 1}), Color{0.75f, 0.5f, 0.5f, 1}));
    CHECK(nearColor(ColorFilter::tint(halfBlue, BlendMode::SrcAtop).apply(Color{1, 0, 0, 0.5f}), Color{0.5f, 0, 0.5f, 0.5f}));
    // A matrix's fifth column is added, and kept when another goes before it.
    ColorMatrix lift;
    lift.values[4] = 0.1f;
    CHECK(nearColor(lift.apply(Color{0.5f, 0, 0, 1}), Color{0.6f, 0, 0, 1}));
    ColorMatrix half;
    half.setToScale(0.5f, 1, 1, 1);
    half.values[9] = 0.2f;  // and lifts green
    lift.timesAssign(half);
    CHECK(nearColor(lift.apply(Color{1, 0, 0, 1}), Color{0.6f, 0.2f, 0, 1}));
}

TEST(images_draw_through_a_color_filter) {
    ImageBitmap photo = ImageBitmap::fromPixels(2, 1, {255, 0, 0, 255, 0, 255, 0, 128});
    auto filter = mutableStateOf(std::optional<ColorFilter>(ColorFilter::tint(Color{0, 0, 1, 1})));
    auto tick = mutableStateOf(0);
    ComposeTestRule rule([&] {
        Column([&] {
            (void)tick.get();
            Image(photo, "resim", Modifier().size(20, 10), ContentScale::FillBounds, 1, filter.get());
            Canvas(Modifier().size(20, 10), [&](DrawScope& d) { d.drawImage(photo, {}, Size{20, 10}, 1, ColorFilter::lighting(Color{0, 0, 0, 1}, Color{})); });
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(canvas.images.size() == 2 && canvas.images[0] != photo.id() && canvas.images[1] != photo.id());
    ImageBitmap tinted = ColorFilter::tint(Color{0, 0, 1, 1}).apply(photo);
    CHECK(canvas.images.size() == 2 && canvas.images[0] == tinted.id());  // made once, then kept
    const uint8_t* px = tinted.pixels();
    CHECK(px[0] == 0 && px[2] == 255 && px[3] == 255 && px[4] == 0 && px[6] == 255 && px[7] == 128);
    ImageBitmap green = ColorFilter::tint(Color{0, 1, 0, 1}).apply(photo);  // another filter: its own copy
    CHECK(green.id() != tinted.id() && green.pixels()[1] == 255 && green.pixels()[2] == 0);
    tick.set(1);  // recomposed: the same filtered image
    rule.waitForIdle();
    testing::RecordingCanvas again;
    rule.host().draw(again);
    CHECK(again.images.size() == 2 && again.images[0] == canvas.images[0] && again.images[1] == canvas.images[1]);
    filter.set(std::nullopt);  // no filter: the image itself
    rule.waitForIdle();
    testing::RecordingCanvas plain;
    rule.host().draw(plain);
    CHECK(!plain.images.empty() && plain.images[0] == photo.id());
}

TEST(drop_and_inner_shadows_of_shapes) {
    Shadow soft{Color{0, 0, 0, 0.4f}, {0, 6}, 10, 2};
    ComposeTestRule rule([&] {
        Column(Modifier().padding(20), [&] {
            Box(Modifier().size(80, 40).dropShadow(RoundedCornerShape(12), soft).background(Color{1, 0, 0, 1}, 12));
            Box(Modifier().size(80, 40).background(Color{0, 1, 0, 1}).innerShadow(CircleShape, Shadow{Color{0, 0, 0, 1}, {1, 2}, 4}),
                [] { Box(Modifier().size(10).background(Color{0, 0, 1, 1})); });
            Box(Modifier().size(30).dropShadow(OutlineShape(MaterialShapes::Heart()), soft));
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    CHECK(canvas.shadows.size() == 2 && canvas.pathShadows.size() == 1);
    if (canvas.shadows.size() != 2 || canvas.pathShadows.size() != 1) return;
    const auto& drop = canvas.shadows[0];
    CHECK(drop.rect.x == 20 && drop.rect.y == 20 && drop.rect.width == 80 && drop.rect.height == 40 && !drop.inner);
    CHECK(drop.radii == CornerRadii(12) && drop.shadow == soft);
    const auto& inner = canvas.shadows[1];
    CHECK(inner.inner && inner.rect.y == 60 && inner.radii == CornerRadii(20) && inner.shadow.blurRadius == 4);  // a circle: half the shorter side
    // An outline shape: its own outline (inside its 30 dp bounds), not a rounded rect.
    const auto& heart = canvas.pathShadows[0];
    CHECK(!heart.inner && heart.shadow == soft && heart.bounds.x >= 20 && heart.bounds.right() <= 50 + 0.5f &&
          heart.bounds.y >= 100 && heart.bounds.bottom() <= 130 + 0.5f && heart.bounds.width > 20);
    // Before what comes after: the drop shadow under its background, the inner one over the
    // background before it and under the content inside.
    CHECK(canvas.order.rfind("sr", 0) == 0 && canvas.order.find("rsr") != std::string::npos);
    // Recorded and replayed.
    DisplayList list(rule.host().textMeasurer());
    list.begin({400, 800}, 0.5f);
    rule.host().draw(list);
    list.end();
    testing::RecordingCanvas replayed;
    list.replay(replayed);
    CHECK(replayed.shadows.size() == 2 && replayed.shadows[0].shadow == soft && replayed.shadows[1].inner);
    CHECK(replayed.pathShadows.size() == 1 && replayed.pathShadows[0].shadow == soft && sameRect(replayed.pathShadows[0].bounds, heart.bounds));
}

TEST(a_changed_shadow_is_a_changed_modifier) {
    auto blur = mutableStateOf(2.f);
    auto spread = mutableStateOf(0.f);
    ComposeTestRule rule([&] {
        // Text skips when it gets an equal modifier: a new shadow must not look equal.
        Text("gölgeli", Modifier().dropShadow(RectangleShape, Shadow{Color{0, 0, 0, 1}, {}, blur.get(), spread.get()}));
    });
    auto drawn = [&] {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        return canvas.shadows.empty() ? Shadow{} : canvas.shadows[0].shadow;
    };
    CHECK(drawn().blurRadius == 2);
    blur.set(8);
    rule.waitForIdle();
    CHECK(drawn().blurRadius == 8);
    spread.set(3);
    rule.waitForIdle();
    CHECK(drawn().spread == 3);
}

TEST(shadow_default_draws_fading_rings_and_display_list_damage_reaches_the_blur) {
    struct Rings final : GraphicsContext {  // only the defaults
        std::vector<Rect> rects;
        std::vector<Color> colors;
        void fillRoundRect(const Rect& r, const CornerRadii&, Color c) override { rects.push_back(r), colors.push_back(c); }
        void strokeRoundRect(const Rect&, const CornerRadii&, float, Color) override {}
        void drawLine(Offset, Offset, float, Color) override {}
        void drawText(std::string_view, Offset, const Font&, Color, bool) override {}
        void drawVector(const ImageVector&, const Rect&, Color) override {}
        void drawArc(const Rect&, float, float, float, Color, bool) override {}
        void drawImage(const ImageBitmap&, const Rect&, const Rect&, float) override {}
        void pushLayer(const Rect&, const CornerRadii&, float, const LayerTransform&) override {}
        void popLayer() override {}
        void pushClip(const Rect&) override {}
        void popClip() override {}
        void pushTranslation(Offset) override {}
        void popTranslation() override {}
        void drawPath(const Path&, Offset, const Brush&, const Rect&, const PathStroke&) override {}
    } rings;
    rings.drawShadow({10, 10, 20, 20}, 4, Shadow{Color{0, 0, 0, 1}, {0, 3}, 6, 1}, false);
    CHECK(rings.rects.size() == 6);
    if (rings.rects.size() == 6) {
        CHECK(near(rings.rects[0].x, 10 - 7, 0.01f) && near(rings.rects[0].y, 10 - 7 + 3, 0.01f));  // the widest: spread and blur out
        CHECK(near(rings.rects[5].x, 10 - 2, 0.01f) && rings.colors[5].a > rings.colors[0].a);    // the innermost, darkest
    }
    rings.drawShadow({10, 10, 20, 20}, 4, Shadow{Color{0, 0, 0, 1}, {}, 6, 0}, true);
    CHECK(rings.rects.size() == 6);  // no inner shadow by default
    testing::FakeTextMeasurer measurer;
    DisplayList list(measurer);
    list.begin({400, 400}, 1);
    list.drawShadow({100, 100, 40, 40}, 0, Shadow{Color{0, 0, 0, 1}, {0, 10}, 5, 2}, false);
    list.end();
    list.begin({400, 400}, 1);
    auto d = list.end();  // gone: its area is the damage
    CHECK(d && d->x <= 100 - 2 - 15 && d->bottom() >= 140 + 2 + 10 + 15 && d->right() >= 140 + 2 + 15);
    list.begin({400, 400}, 1);
    list.drawShadow({100, 100, 40, 40}, 0, Shadow{Color{0, 0, 0, 1}, {0, 10}, 5, 2}, true);
    list.end();
    list.begin({400, 400}, 1);
    d = list.end();  // an inner one stays inside its rect
    CHECK(d && d->x >= 100 - 3 && d->right() <= 140 + 3 && d->bottom() <= 140 + 3);
}

TEST(link_annotations_open_urls_call_listeners_and_restyle_on_hover_and_press) {
    std::vector<std::string> opened, tags;
    Color red{1, 0, 0, 1}, green{0, 1, 0, 1}, blue{0, 0, 1, 1};
    ComposeTestRule rule([&] {
        Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                 b.append("aa ");
                 b.withLink(LinkAnnotation::Url("https://kompoz.dev", TextLinkStyles{.style = SpanStyle{.color = red},
                                                                                     .hoveredStyle = SpanStyle{.color = green},
                                                                                     .pressedStyle = SpanStyle{.color = blue}}),
                            [&] { b.append("site"); });
                 b.append(" bb ");
                 b.withLink(LinkAnnotation::Clickable("etiket", {}, [&](const LinkAnnotation& l) { tags.push_back(l.tag); }),
                            [&] { b.append("tık"); });
             }),
             Modifier(), {.fontSize = 10});
    });
    rule.host().setCallbacks({.openUri = [&](const std::string& uri) { opened.push_back(uri); }});
    auto colorOf = [&](const std::string& text) {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        for (size_t i = 0; i < canvas.texts.size(); ++i)
            if (canvas.texts[i] == text) return canvas.colors[i];
        return Color{};
    };
    CHECK(colorOf("site") == red);  // its style; a link without styles: the primary color
    {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        bool underlined = std::ranges::any_of(canvas.lines, [](const auto& l) { return l.first.x == 15 && l.second.x == 35; });
        CHECK(underlined);  // under "site" (15 to 35 dp)
    }
    CHECK(colorOf("tık") == lightColorScheme().primary);
    // "aa " is 15 dp, "site" 20: the mouse over it, then pressed on it.
    rule.host().pointerMove({25, 5});
    rule.waitForIdle();
    CHECK(colorOf("site") == green);
    rule.host().pointerDown({25, 5}, -1, 0, ComposeHost::PointerType::Mouse);
    rule.advanceFrame();
    rule.waitForIdle(0);
    CHECK(colorOf("site") == blue);
    rule.host().pointerUp({25, 5});
    rule.advanceTimeBy(400);
    CHECK((opened == std::vector<std::string>{"https://kompoz.dev"}) && colorOf("site") == green);
    rule.host().pointerMove({5, 5});  // off the link
    rule.waitForIdle();
    CHECK(colorOf("site") == red);
    rule.host().pointerMove({25, 5});
    rule.host().pointerMove({300, 300});  // over the link, then out of the text altogether
    rule.waitForIdle();
    CHECK(colorOf("site") == red);
    tap(rule, {60, 5});  // "aa site bb " is 55 dp: "tık" after it
    rule.advanceTimeBy(400);
    CHECK((tags == std::vector<std::string>{"etiket"}) && opened.size() == 1);
}

TEST(links_take_the_keyboard_focus_and_accessibility_clicks) {
    std::vector<std::string> opened, tags;
    Color red{1, 0, 0, 1}, yellow{1, 1, 0, 1};
    ComposeTestRule rule([&] {
        Column([&] {
            Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                     b.append("aa ");
                     b.withLink(LinkAnnotation::Url("https://kompoz.dev", TextLinkStyles{.style = SpanStyle{.color = red},
                                                                                         .focusedStyle = SpanStyle{.color = yellow}}),
                                [&] { b.append("site"); });
                     b.append(" bb ");
                     b.withLink(LinkAnnotation::Clickable("etiket", TextLinkStyles{.focusedStyle = SpanStyle{.color = yellow}},
                                                          [&](const LinkAnnotation& l) { tags.push_back(l.tag); }),
                                [&] { b.append("tık"); });
                 }),
                 Modifier(), {.fontSize = 10});
            // A link over two lines (30 dp wide): its node over the first.
            Text(buildAnnotatedString([&](AnnotatedString::Builder& b) {
                     b.withLink(LinkAnnotation::Clickable("uzun", {}, [&](const LinkAnnotation& l) { tags.push_back(l.tag); }),
                                [&] { b.append("abc def"); });
                 }),
                 Modifier().width(30).testTag("uzun"), {.fontSize = 10});
        });
    });
    rule.host().setCallbacks({.openUri = [&](const std::string& uri) { opened.push_back(uri); }});
    auto colorOf = [&](const std::string& text) {
        testing::RecordingCanvas canvas;
        rule.host().draw(canvas);
        for (size_t i = 0; i < canvas.texts.size(); ++i)
            if (canvas.texts[i] == text) return canvas.colors[i];
        return Color{};
    };
    // Each link a node of its own over it, said with its text and clickable.
    auto linkNode = [&](const std::string& label) -> std::optional<SemanticsNode> {
        for (const auto& n : rule.host().semanticsTree())
            if (n.label == label && n.clickable) return n;
        return std::nullopt;
    };
    auto site = linkNode("site");
    CHECK(site && near(site->bounds.x, 15) && near(site->bounds.width, 20));
    CHECK(linkNode("tık") && linkNode("abc def"));
    // Tab: the first link, its focused style; Enter opens it.
    rule.host().keyDown(Key::Tab);
    rule.waitForIdle();
    CHECK(colorOf("site") == yellow && colorOf("tık") == lightColorScheme().primary);
    rule.host().keyDown(Key::Enter);
    rule.waitForIdle();
    CHECK((opened == std::vector<std::string>{"https://kompoz.dev"}));
    // Tab on: the next one; Shift+Tab back.
    rule.host().keyDown(Key::Tab);
    rule.waitForIdle();
    CHECK(colorOf("site") == red && colorOf("tık") == yellow);
    rule.host().keyDown(Key::Enter);
    rule.waitForIdle();
    CHECK((tags == std::vector<std::string>{"etiket"}));
    rule.host().keyDown(Key::Tab, {.shift = true});
    rule.waitForIdle();
    CHECK(colorOf("site") == yellow);
    // An accessibility service's click opens it too.
    if (auto n = linkNode("tık")) CHECK(rule.host().performSemanticsAction(n->id, SemanticsAction::Click));
    CHECK((tags == std::vector<std::string>{"etiket", "etiket"}));
    // The long link: a tap on either line, once each.
    Rect longLink = rule.onNodeWithTag("uzun").bounds();
    tap(rule, {longLink.x + 5, longLink.y + 5});
    tap(rule, {longLink.x + 5, longLink.y + 17});
    rule.advanceTimeBy(400);
    CHECK((tags == std::vector<std::string>{"etiket", "etiket", "uzun", "uzun"}) && opened.size() == 1);
}

TEST(min_lines_start_and_middle_ellipsis_and_baseline_shift) {
    ComposeTestRule rule([&] {
        Column([&] {
            Text("a", Modifier().testTag("üç"), {.fontSize = 10, .minLines = 3});
            Text("a\nb\nc\nd", Modifier().testTag("dört"), {.fontSize = 10, .minLines = 3});
            Text("abcdefghij", Modifier().width(30), {.fontSize = 10, .maxLines = 1, .overflow = TextOverflow::StartEllipsis});
            Text("klmnopqrst", Modifier().width(30), {.fontSize = 10, .overflow = TextOverflow::MiddleEllipsis, .softWrap = false});
            Text("uvw xyz uvw", Modifier().width(30).testTag("çok"), {.fontSize = 10, .overflow = TextOverflow::MiddleEllipsis});  // wraps: clipped
            Text(buildAnnotatedString([](AnnotatedString::Builder& b) {
                     b.append("x");
                     b.withStyle({.baselineShift = BaselineShift::Superscript}, [&] { b.append("2"); });
                     b.append("H");
                     b.withStyle({.baselineShift = BaselineShift::Subscript}, [&] { b.append("o"); });
                 }),
                 Modifier().testTag("simge"), {.fontSize = 10});
        });
    });
    CHECK(rule.onNodeWithTag("üç").bounds().height == 38);   // three lines of 12.5
    CHECK(rule.onNodeWithTag("dört").bounds().height == 50);  // more than that: as many as it has
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    auto has = [&](const std::string& t) { return std::find(canvas.texts.begin(), canvas.texts.end(), t) != canvas.texts.end(); };
    CHECK(has("…") && has("fghij"));         // the start cut: its end kept (5 letters and the ellipsis fill 30)
    CHECK(has("klm") && has("st"));          // the middle cut: the start gets the odd one
    CHECK(rule.onNodeWithTag("çok").bounds().height == 38 && !has("uvw…"));  // more lines: no cut inside
    // Superscript: half its ascent (4) up, the line taller above; subscript: 4 down, taller below.
    float top = rule.onNodeWithTag("simge").bounds().y;
    std::map<std::string, float> base;
    for (size_t i = 0; i < canvas.texts.size(); ++i) base[canvas.texts[i]] = canvas.baselines[i].y - top;
    CHECK(near(base["x"], 12, 0.01f) && near(base["2"], 8, 0.01f) && near(base["H"], 12, 0.01f) && near(base["o"], 16, 0.01f));
}

TEST(slider_thumbs_and_tracks_are_slots_given_its_state) {
    auto value = mutableStateOf(25.f);
    std::optional<SliderState> seen;
    ComposeTestRule rule([&] {
        Column([&] {
            Slider(value.get(), [value](float v) { value.set(v); }, Modifier().width(200).testTag("kaydırıcı"),
                   {.valueFrom = 0, .valueTo = 100,
                    .thumb = [&](const SliderState& s) {
                        seen = s;
                        Box(Modifier().size(s.isPressed() ? 20 : 10).testTag("başparmak"));
                    },
                    .track = [](const SliderState&) { Box(Modifier().fillMaxWidth().height(6).testTag("iz")); }});
            Slider(50, [](float) {}, Modifier().width(200), {.valueTo = 100, .thumb = [](const SliderState& s) { SliderDefaults::ValueThumb(s); }});
        });
    });
    // The track: as long as the slider less the thumb, from half a thumb in; the thumb's middle at the value along it.
    Rect slider = rule.onNodeWithTag("kaydırıcı").bounds(), thumb = rule.onNodeWithTag("başparmak").bounds(), track = rule.onNodeWithTag("iz").bounds();
    CHECK(slider.height == 48 && track.width == 190 && track.x == slider.x + 5 && near(track.y + 3, slider.y + 24, 0.01f));  // 48 dp to touch
    CHECK(near(thumb.x - slider.x, 190 * 0.25f, 0.01f) && thumb.width == 10);
    CHECK(seen && seen->value() == 25 && seen->valueFrom() == 0 && seen->valueTo() == 100 && near(seen->valueAsFraction(), 0.25f, 1e-4f));
    CHECK(rule.onNodeWithText("50").exists());  // the value thumb shows it
    rule.host().pointerDown({slider.x + 5 + 190 * 0.75f, slider.y + 22});  // held: the thumb knows it
    rule.advanceFrame();
    rule.waitForIdle(0);
    CHECK(value.get() == 75 && seen->isPressed() && !seen->isDragging() && rule.onNodeWithTag("başparmak").bounds().width == 20);
    rule.host().pointerUp({slider.x + 5 + 190 * 0.75f, slider.y + 22});
    rule.waitForIdle();
    CHECK(!seen->isPressed() && rule.onNodeWithTag("başparmak").bounds().width == 10);
}

TEST(remembered_slider_state_keeps_its_value_and_steps) {
    int finished = 0;
    std::optional<SliderState> kept;
    ComposeTestRule rule([&] {
        auto state = rememberSliderState(2, 3, 1, 5, [&] { ++finished; });  // 1..5 in four parts
        kept = state;
        Slider(state, Modifier().width(220).testTag("puan"), {.valueFrom = 0, .valueTo = 1000});  // the options' range isn't used
    });
    CHECK(kept && kept->value() == 2 && kept->steps() == 3 && (kept->tickFractions() == std::vector<float>{0, 0.25f, 0.5f, 0.75f, 1}));
    Rect b = rule.onNodeWithTag("puan").bounds();
    tap(rule, {b.x + 10 + 200 * 0.7f, b.y + 22});  // nearest the step at 0.75
    rule.waitForIdle();
    CHECK(kept->value() == 4 && finished == 1);
    kept->setValue(9);  // set from code: kept in range
    rule.waitForIdle();
    CHECK(kept->value() == 5);
}

TEST(material3_slider_track_keeps_apart_from_its_bar_thumb) {
    ComposeTestRule rule([&] {
        Column([&] {
            Slider(0.5f, [](float) {}, Modifier().width(204).testTag("m3"),
                   {.thumb = [](const SliderState& s) { SliderDefaults::Thumb(s); }, .track = [](const SliderState& s) { SliderDefaults::Track(s); }});
            Slider(1, [](float) {}, Modifier().width(204).testTag("adımlı"),
                   {.valueFrom = 0, .valueTo = 4, .steps = 3, .colors = SliderColors{.thumbColor = Color{1, 0, 0, 1}},
                    .thumb = [](const SliderState& s) { SliderDefaults::ShapeThumb(s, RectangleShape, {8, 8}); },
                    .track = [](const SliderState& s) { SliderDefaults::Track(s); }});
            VerticalSlider(0.5f, [](float) {}, Modifier().height(204).testTag("dikey"), {.thumb = [](const SliderState& s) { SliderDefaults::Thumb(s); }});
        });
    });
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    // The first: a 4 dp bar thumb, a 200 dp track from 2 dp in; the value at 100: the active
    // stretch ends 2 + 6 short of it, the inactive one starts 8 past it, a stop dot at its end.
    Rect m3 = rule.onNodeWithTag("m3").bounds();
    std::vector<Rect> bars;
    std::vector<CornerRadii> corners;
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        if (canvas.rects[i].height == 16 && near(canvas.rects[i].y, m3.y + 16, 0.01f)) bars.push_back(canvas.rects[i]), corners.push_back(canvas.rectCorners[i]);
    CHECK(bars.size() == 2);
    if (bars.size() == 2) {
        CHECK(near(bars[0].x, m3.x + 2 + 108, 0.01f) && near(bars[0].right(), m3.x + 202, 0.01f));  // inactive
        CHECK(near(bars[1].x, m3.x + 2, 0.01f) && near(bars[1].right(), m3.x + 2 + 92, 0.01f));     // active
        CHECK(corners[0] == CornerRadii(2, 8, 8, 2) && corners[1] == CornerRadii(8, 2, 2, 8));
    }
    bool stop = std::ranges::any_of(canvas.rects, [&](const Rect& r) { return r.width == 4 && near(r.x + 2, m3.x + 202 - 8, 0.01f); });
    CHECK(stop);
    // The second: on its first step the thumb stands on its tick, held 8 dp in from the track's ends.
    Rect stepped = rule.onNodeWithTag("adımlı").bounds();
    bool redThumb = false;
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        if (canvas.rectColors[i] == Color{1, 0, 0, 1}) redThumb = near(canvas.rects[i].x + 4, stepped.x + 4 + 8 + (196 - 16) * 0.25f, 0.01f);
    CHECK(redThumb);
    // Standing up, the bar lies down.
    Rect upright = rule.onNodeWithTag("dikey").bounds();
    bool lying = std::ranges::any_of(canvas.rects, [&](const Rect& r) { return r.width == 44 && r.height == 4 && r.x >= upright.x - 0.5f; });
    CHECK(lying && upright.width == 48);
    // Held, the bar is half as thick.
    rule.host().pointerDown({m3.x + 150, m3.y + 22});
    rule.advanceFrame();
    rule.waitForIdle(0);
    testing::RecordingCanvas held;
    rule.host().draw(held);
    bool thin = std::ranges::any_of(held.rects, [&](const Rect& r) { return r.width == 2 && r.height == 44 && near(r.y, m3.y + 2, 0.01f); });
    CHECK(thin);
    rule.host().pointerUp({m3.x + 150, m3.y + 22});
}

TEST(range_slider_thumbs_and_track_are_slots) {
    auto range = mutableStateOf(std::pair{20.f, 60.f});
    std::optional<RangeSliderState> seen;
    std::vector<std::pair<float, bool>> thumbs;  // what each thumb was given: its value, held
    ComposeTestRule rule([&] {
        Column([&] {
            thumbs.clear();
            RangeSlider(range.get(), [range](std::pair<float, float> v) { range.set(v); }, Modifier().width(210).testTag("aralık"),
                        {.valueFrom = 0, .valueTo = 100,
                         .startThumb = [&](const SliderState& s) {
                             thumbs.push_back({s.value(), s.isPressed()});
                             Box(Modifier().size(10).testTag("baş"));
                         },
                         .endThumb = [&](const SliderState& s) {
                             thumbs.push_back({s.value(), s.isPressed()});
                             Box(Modifier().size(10).testTag("son"));
                         },
                         .rangeTrack = [&](const RangeSliderState& s) {
                             seen = s;
                             Box(Modifier().fillMaxWidth().height(6).testTag("iz"));
                         }});
            RangeSlider({1, 3}, [](std::pair<float, float>) {}, Modifier().width(210),
                        {.valueFrom = 0, .valueTo = 4, .thumb = [](const SliderState& s) { Box(Modifier().size(12).testTag(std::format("t{:.0f}", s.value()))); }});
        });
    });
    Rect slider = rule.onNodeWithTag("aralık").bounds(), track = rule.onNodeWithTag("iz").bounds();
    CHECK(track.x == slider.x + 5 && track.width == 200);  // half of each thumb off
    CHECK(near(rule.onNodeWithTag("baş").bounds().x, slider.x + 5 + 40 - 5, 0.01f) && near(rule.onNodeWithTag("son").bounds().x, slider.x + 5 + 120 - 5, 0.01f));
    CHECK(seen && seen->activeRangeStart() == 20 && seen->activeRangeEnd() == 60 && near(seen->startFraction(), 0.2f, 1e-4f) && seen->held() == -1);
    CHECK((thumbs == std::vector<std::pair<float, bool>>{{20, false}, {60, false}}));
    CHECK(rule.onNodeWithTag("t1").exists() && rule.onNodeWithTag("t3").exists());  // `thumb` for both when they have none of their own
    rule.host().pointerDown({slider.x + 5 + 150, slider.y + 22});  // nearer the end thumb: it moves, and is held
    rule.advanceFrame();
    rule.waitForIdle(0);
    CHECK(range.get().second == 75 && seen->held() == 1 && (thumbs == std::vector<std::pair<float, bool>>{{20, false}, {75, true}}));
    rule.host().pointerUp({slider.x + 5 + 150, slider.y + 22});
    rule.waitForIdle();
    CHECK(seen->held() == -1);
}

TEST(remembered_range_slider_state_and_its_material3_track) {
    int finished = 0;
    std::optional<RangeSliderState> kept;
    ComposeTestRule rule([&] {
        auto state = rememberRangeSliderState(1, 3, 3, 0, 4, [&] { ++finished; });
        kept = state;
        RangeSlider(state, Modifier().width(208).testTag("m3"),
                    {.thumb = [](const SliderState& s) { SliderDefaults::Thumb(s); },
                     .rangeTrack = [](const RangeSliderState& s) { SliderDefaults::Track(s); }});
    });
    // 4 dp bar thumbs: a 204 dp track from 2 dp in. On steps the values sit 8 dp in from its ends:
    // 1 at 8 + 188/4 = 55, 3 at 149; each stretch keeps 2 + 6 from a thumb.
    Rect b = rule.onNodeWithTag("m3").bounds();
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    std::vector<Rect> bars;
    std::vector<CornerRadii> corners;
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        if (canvas.rects[i].height == 16) bars.push_back(canvas.rects[i]), corners.push_back(canvas.rectCorners[i]);
    CHECK(bars.size() == 3);
    if (bars.size() == 3) {
        CHECK(near(bars[0].x, b.x + 2, 0.01f) && near(bars[0].right(), b.x + 2 + 55 - 8, 0.01f) && corners[0] == CornerRadii(8, 2, 2, 8));
        CHECK(near(bars[1].x, b.x + 2 + 149 + 8, 0.01f) && near(bars[1].right(), b.x + 206, 0.01f) && corners[1] == CornerRadii(2, 8, 8, 2));
        CHECK(near(bars[2].x, b.x + 2 + 55 + 8, 0.01f) && near(bars[2].right(), b.x + 2 + 149 - 8, 0.01f) && corners[2] == CornerRadii(2));
    }
    auto dotAt = [&](float x) { return std::ranges::any_of(canvas.rects, [&](const Rect& r) { return r.width == 4 && near(r.x + 2, x, 0.01f); }); };
    CHECK(dotAt(b.x + 2 + 8) && dotAt(b.x + 206 - 8) && dotAt(b.x + 2 + 102));  // a stop dot at each end, the middle step's tick
    auto barAt = [&](float x) { return std::ranges::any_of(canvas.rects, [&](const Rect& r) { return r.width == 4 && r.height == 44 && near(r.x + 2, x, 0.01f); }); };
    CHECK(barAt(b.x + 2 + 55) && barAt(b.x + 2 + 149));  // the thumbs on their steps' ticks
    tap(rule, {b.x + 2 + 5, b.y + 22});  // by the start: the start thumb goes to the first step
    rule.waitForIdle();
    CHECK(kept->activeRangeStart() == 0 && kept->activeRangeEnd() == 3 && finished == 1);
    kept->setActiveRange(3.6f, 2);  // from code: on steps, in order
    rule.waitForIdle();
    CHECK(kept->activeRangeStart() == 4 && kept->activeRangeEnd() == 4);
}

TEST(animate_bounds_glides_to_a_new_place_and_size) {
    auto right = mutableStateOf(false);
    auto wide = mutableStateOf(false);
    ScrollState scroll;
    std::vector<float> widths;  // what the content inside was told it is
    ComposeTestRule rule([&] {
        Column(Modifier().verticalScroll(scroll), [&] {
            LookaheadScope(Modifier().size(300, 200), [&] {
                Box(Modifier().fillMaxSize(), right.get() ? Alignment::BottomEnd : Alignment::TopStart, [&] {
                    Box(Modifier().animateBounds(tween(400, 0, LinearEasing)).size(wide.get() ? 100 : 40, 40).background(Color{1, 0, 0, 1}).testTag("kutu"),
                        [&] { Box(Modifier().fillMaxSize().onSizeChanged([&](Size s) { widths.push_back(s.width); })); });
                });
            });
            Box(Modifier().size(10, 1000));
        });
    });
    Rect red;
    auto frames = [&](int n) {  // drawn every frame, as an app is
        for (int k = 0; k < n; ++k) {
            rule.advanceFrame();
            testing::RecordingCanvas canvas;
            rule.host().draw(canvas);
            for (size_t i = 0; i < canvas.rects.size(); ++i)
                if (canvas.rectColors[i] == Color{1, 0, 0, 1}) red = canvas.rects[i];
        }
    };
    frames(1);
    CHECK(red.x == 0 && red.y == 0);
    right.set(true);  // to the bottom right corner: laid out there at once, drawn on the way
    frames(1);
    Rect laid = rule.onNodeWithTag("kutu").bounds();
    CHECK(laid.x == 260 && laid.y == 160 && red.x == 0 && red.y == 0 && rule.host().hasPendingWork());  // it asks for the frames
    frames(13);  // about half way (208 of 400 ms)
    CHECK(red.x > 100 && red.x < 160 && red.y > 60 && red.y < 100);
    frames(20);
    CHECK(red.x == 260 && red.y == 160 && !rule.host().hasPendingWork());
    wide.set(true);  // wider: the size grows along the way, the content laid out at it
    widths.clear();
    frames(13);
    CHECK(!widths.empty() && std::ranges::none_of(widths, [](float w) { return w >= 100; }));  // never told the size it goes to before it gets there
    CHECK(red.width > 55 && red.width < 85 && rule.onNodeWithTag("kutu").bounds().width == red.width);
    frames(20);
    CHECK(red.width == 100 && red.x == 200 && !rule.host().hasPendingWork());
    scroll.scrollTo(100);  // the scope scrolls with it: no animation
    frames(2);
    CHECK(red.y == 160 - 100 && !rule.host().hasPendingWork());
}

TEST(minimum_interactive_component_size_keeps_room_to_touch) {
    ComposeTestRule rule([&] {
        Column([&] {
            Box(Modifier().minimumInteractiveComponentSize().testTag("dış"), [] { Box(Modifier().size(20).testTag("iç")); });
            Box(Modifier().minimumInteractiveComponentSize().testTag("büyük"), [] { Box(Modifier().size(60, 30)); });
            CompositionLocalProvider({LocalMinimumInteractiveComponentSize.provides(0.f)}, [] {
                Box(Modifier().minimumInteractiveComponentSize().testTag("kapalı"), [] { Box(Modifier().size(20)); });
            });
        });
    });
    Rect outer = rule.onNodeWithTag("dış").bounds(), inner = rule.onNodeWithTag("iç").bounds();
    CHECK(outer.width == 48 && outer.height == 48 && inner.x == outer.x + 14 && inner.y == outer.y + 14);  // centered in it
    Rect big = rule.onNodeWithTag("büyük").bounds();
    CHECK(big.width == 60 && big.height == 48);  // only what is smaller grows
    CHECK(rule.onNodeWithTag("kapalı").bounds().width == 20);
}

TEST(controls_keep_48_dp_of_room_and_take_taps_anywhere_in_it) {
    auto clicks = std::make_shared<int>(0);
    auto checked = mutableStateOf(false), selected = mutableStateOf(false), on = mutableStateOf(false);
    auto room = mutableStateOf(48.f);
    MutableInteractionSource buttonSource;
    std::vector<Interaction::Type> log;
    ComposeTestRule rule([&] {
        LogInteractions(buttonSource, log);
        CompositionLocalProvider({LocalMinimumInteractiveComponentSize.provides(room.get())}, [&] {
            Column([&] {
                IconButton([clicks] { ++*clicks; }, Modifier().testTag("düğme"), {.interactionSource = buttonSource},
                           [] { Icon(Icons::Filled::Add, "Ekle"); });
                Checkbox(checked.get(), [checked](bool v) { checked.set(v); }, Modifier().testTag("kutu"));
                RadioButton(selected.get(), [selected] { selected.set(!selected.peek()); }, Modifier().testTag("radyo"));
                Switch(on.get(), [on](bool v) { on.set(v); }, Modifier().testTag("anahtar"));
                // Not taking taps themselves (a row around them would): just their own size.
                Checkbox(false, nullptr, Modifier().testTag("sade kutu"));
                RadioButton(false, nullptr, Modifier().testTag("sade radyo"));
                Switch(false, nullptr, Modifier().testTag("sade anahtar"));
            });
        });
    });
    auto bounds = [&](const char* tag) { return rule.onNodeWithTag(tag).bounds(); };
    CHECK(near(bounds("düğme").width, 48) && near(bounds("düğme").height, 48));
    CHECK(near(bounds("kutu").width, 48) && near(bounds("radyo").width, 48));
    CHECK(near(bounds("anahtar").width, 52) && near(bounds("anahtar").height, 48));
    CHECK(near(bounds("sade kutu").width, 24) && near(bounds("sade kutu").height, 24) && near(bounds("sade radyo").width, 24));
    CHECK(near(bounds("sade anahtar").height, 32));
    // A tap 2 dp from the edge, well off the 40 dp circle (or the 24 dp box), still lands.
    auto nearCorner = [&](const char* tag) { Rect b = bounds(tag); return Offset{b.x + 2, b.y + 2}; };
    tap(rule, nearCorner("düğme"));
    tap(rule, nearCorner("kutu"));
    tap(rule, nearCorner("radyo"));
    tap(rule, nearCorner("anahtar"));
    rule.waitForIdle();
    CHECK(*clicks == 1 && checked.peek() && selected.peek() && on.peek());
    rule.waitForIdle();
    // So does a press in the middle let go near the edge (a release); one let go past the room
    // doesn't click (a cancel).
    using T = Interaction::Type;
    Rect b = bounds("düğme");
    log.clear();
    rule.host().pointerDown(b.center());
    rule.advanceFrame();
    rule.host().pointerUp({b.right() - 2, b.center().y});
    rule.waitForIdle();
    CHECK(*clicks == 2 && (log == std::vector{T::Press, T::Release}));
    rule.host().pointerDown(b.center());
    rule.advanceFrame();
    rule.host().pointerUp({b.right() + 6, b.center().y});
    rule.waitForIdle();
    CHECK(*clicks == 2 && (log == std::vector{T::Press, T::Release, T::Press, T::Cancel}));
    // With no room asked for (0), they are as big as they look.
    room.set(0);
    rule.waitForIdle();
    CHECK(near(bounds("düğme").width, 40) && near(bounds("kutu").width, 24) && near(bounds("anahtar").height, 32));
    tap(rule, nearCorner("kutu"));  // the 24 dp box's own corner
    rule.waitForIdle();
    CHECK(!checked.peek());
}

TEST(buttons_and_chips_keep_48_dp_of_room_to_touch_them) {
    auto taps = std::make_shared<std::vector<std::string>>();
    auto room = mutableStateOf(48.f);
    auto on = mutableStateOf(false);
    ColorScheme cs = lightColorScheme();
    ComposeTestRule rule([&] {
        CompositionLocalProvider({LocalMinimumInteractiveComponentSize.provides(room.get())}, [&] {
            Column([&] {
                Button([taps] { taps->push_back("düğme"); }, Modifier().testTag("düğme"), [] { Text("Kaydet"); });
                TextButton([taps] { taps->push_back("metin"); }, Modifier().testTag("metin"), {}, [] { Text("İptal"); });
                ToggleButton(on.get(), [on](bool v) { on.set(v); }, Modifier().testTag("aç"), {}, [] { Text("Aç"); });
                AssistChip([taps] { taps->push_back("çip"); }, [] { Text("Yol"); }, {}, Modifier().testTag("çip"));
                SmallFloatingActionButton([taps] { taps->push_back("fab"); }, [] { Icon(Icons::Filled::Add, "Ekle"); },
                                          Modifier().testTag("fab"));
            });
        });
    });
    auto bounds = [&](const char* tag) { return rule.onNodeWithTag(tag).bounds(); };
    CHECK(near(bounds("düğme").height, 48) && near(bounds("metin").height, 48) && near(bounds("aç").height, 48));
    CHECK(near(bounds("çip").height, 48) && near(bounds("fab").width, 48) && near(bounds("fab").height, 48));
    // The button's container is 40 dp in the middle; a tap 2 dp from the top lands all the same.
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    Rect b = bounds("düğme");
    bool container = false;
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        container |= canvas.rectColors[i] == cs.primary && sameRect(canvas.rects[i], {b.x, b.y + 4, b.width, 40});
    CHECK(container);
    for (const char* tag : {"düğme", "metin", "aç", "çip", "fab"}) {
        Rect r = bounds(tag);
        tap(rule, {r.center().x, r.y + 2});
    }
    rule.waitForIdle();
    CHECK((*taps == std::vector<std::string>{"düğme", "metin", "çip", "fab"}) && on.peek());
    // No room asked for: as big as they look.
    room.set(0);
    rule.waitForIdle();
    CHECK(near(bounds("düğme").height, 40) && near(bounds("çip").height, 32) && near(bounds("fab").width, 40));
}

TEST(segmented_buttons_keep_48_dp_of_room_and_draw_40) {
    auto picked = mutableStateOf(0);
    auto room = mutableStateOf(48.f);
    ColorScheme cs = lightColorScheme();
    ComposeTestRule rule([&] {
        CompositionLocalProvider({LocalMinimumInteractiveComponentSize.provides(room.get())}, [&] {
            SingleChoiceSegmentedButtonRow(Modifier().width(300).testTag("satır"), [&] {
                for (int i = 0; i < 3; ++i)
                    SegmentedButton(picked.get() == i, [picked, i] { picked.set(i); }, [i] { Text("S" + std::to_string(i)); },
                                    Modifier().testTag("seg" + std::to_string(i)));
            });
        });
    });
    Rect row = rule.onNodeWithTag("satır").bounds(), seg = rule.onNodeWithTag("seg1").bounds();
    CHECK(near(row.height, 48) && near(seg.height, 48) && near(seg.width, 100));
    // Drawn on the 40 dp band in the middle: the outline, the rounded ends and the picked one's fill.
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    Rect band{row.x, row.y + 4, 300, 40};
    bool outline = false, ends = false, fill = false;
    for (size_t i = 0; i < canvas.strokes.size(); ++i)
        outline |= sameRect(canvas.strokes[i], band) && near(canvas.strokeCorners[i].topLeft, 20) && canvas.strokeColors[i] == cs.outline;
    for (size_t i = 0; i < canvas.layerBounds.size(); ++i) ends |= sameRect(canvas.layerBounds[i], band) && near(canvas.layerCorners[i].topLeft, 20);
    bool separator = false;  // between the first two
    for (size_t i = 0; i < canvas.rects.size(); ++i) {
        fill |= canvas.rectColors[i] == cs.secondaryContainer && sameRect(canvas.rects[i], {row.x, row.y + 4, 100, 40});
        separator |= canvas.rectColors[i] == cs.outline && sameRect(canvas.rects[i], {row.x + 99, row.y + 4, 1, 40});
    }
    CHECK(outline && ends && fill && separator);
    // A tap 2 dp from the top, above the band, picks the segment.
    tap(rule, {seg.center().x, seg.y + 2});
    rule.waitForIdle();
    CHECK(picked.peek() == 1);
    room.set(0);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("satır").bounds().height, 40));
}

TEST(top_app_bar_colors_heights_and_insets_can_be_set) {
    ColorScheme cs = lightColorScheme();
    const Color red = Color::hex(0xFF0000), green = Color::hex(0x00FF00), blue = Color::hex(0x0000FF), magenta = Color::hex(0xFF00FF);
    auto custom = mutableStateOf(false), centered = mutableStateOf(false);
    std::optional<TopAppBarState> state;
    ComposeTestRule rule([&, red, green, blue, magenta] {
        auto behavior = TopAppBarDefaults::exitUntilCollapsedScrollBehavior();
        state = behavior.state;
        Column([&] {
            TopAppBarSlots slots{.title = [] { Text("Başlık"); },
                                 .subtitle = [] { Text("Alt"); },
                                 .navigationIcon = [] { Icon(Icons::Filled::Menu, "Menü"); },
                                 .actions = [] { Icon(Icons::Filled::Search, "Ara"); }};
            if (custom.get()) {
                slots.navigationIconContentColor = red;
                slots.titleContentColor = green;
                slots.actionIconContentColor = blue;
                slots.subtitleContentColor = magenta;
                slots.expandedHeight = 80;
                slots.windowInsets = WindowInsets{0, 10, 0, 0};
            }
            if (centered.get())
                CenterAlignedTopAppBar(slots, Modifier().testTag("tek"));
            else
                TopAppBar(slots, Modifier().testTag("tek"));
            MediumTopAppBar({.title = [] { Text("Orta"); },
                             .expandedHeight = custom.get() ? std::optional(150.f) : std::nullopt,
                             .collapsedHeight = custom.get() ? std::optional(56.f) : std::nullopt,
                             .scrollBehavior = behavior},
                            Modifier().testTag("orta"));
        });
    }, {400, 800});
    auto colorsOf = [&] {
        testing::RecordingCanvas c;
        rule.host().draw(c);
        std::map<std::string, Color> out;
        for (size_t i = 0; i < c.texts.size(); ++i) out[c.texts[i]] = c.colors[i];
        out["menü"] = c.vectorColors.size() > 0 ? c.vectorColors[0] : Color{};
        out["ara"] = c.vectorColors.size() > 1 ? c.vectorColors[1] : Color{};
        return out;
    };
    // The theme's: the navigation icon and title in onSurface, actions and subtitle in onSurfaceVariant.
    auto plain = colorsOf();
    CHECK(plain["menü"] == cs.onSurface && plain["Başlık"] == cs.onSurface && plain["ara"] == cs.onSurfaceVariant && plain["Alt"] == cs.onSurfaceVariant);
    CHECK(near(rule.onNodeWithTag("tek").bounds().height, 64) && near(rule.onNodeWithTag("orta").bounds().height, 112));
    CHECK(near(state->heightOffsetLimit(), 64 - 112));
    // Each part in its own color; 80 dp tall under 10 dp of insets; the medium one from 150 down to 56.
    custom.set(true);
    rule.waitForIdle();
    auto set = colorsOf();
    CHECK(set["menü"] == red && set["Başlık"] == green && set["ara"] == blue && set["Alt"] == magenta);
    CHECK(near(rule.onNodeWithTag("tek").bounds().height, 90) && near(rule.onNodeWithText("Başlık").bounds().center().y, 10 + 40, 12));
    CHECK(near(rule.onNodeWithTag("orta").bounds().height, 150) && near(state->heightOffsetLimit(), 56 - 150));
    state->setHeightOffset(-94);  // collapsed
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("orta").bounds().height, 56));
    // The centered bar takes them all the same.
    centered.set(true);
    rule.waitForIdle();
    auto middle = colorsOf();
    CHECK(middle["menü"] == red && middle["Başlık"] == green && middle["ara"] == blue && middle["Alt"] == magenta);
    CHECK(near(rule.onNodeWithTag("tek").bounds().height, 90));
}

TEST(rows_and_columns_with_weights_that_dont_fill_are_as_big_as_their_children) {
    ComposeTestRule rule([&] {
        Box(Modifier().size(300, 500), [&] {
            Row([&] {
                // Not filling: each takes what it needs out of its share.
                Column(Modifier().testTag("sütun"), [&] {
                    Box(Modifier().size(40, 60));
                    Box(Modifier().weight(1, false).size(40, 50).testTag("ağır"));
                });
                // Filling: all of the room.
                Column(Modifier().testTag("dolu"), [&] {
                    Box(Modifier().size(40, 60));
                    Box(Modifier().weight(1).width(40).testTag("dolan"));
                });
                Row(Modifier().testTag("satır"), [&] { Box(Modifier().weight(1, false).size(30, 20)); });
            });
        });
    });
    CHECK(near(rule.onNodeWithTag("sütun").bounds().height, 110) && near(rule.onNodeWithTag("ağır").bounds().height, 50));
    CHECK(near(rule.onNodeWithTag("dolu").bounds().height, 500) && near(rule.onNodeWithTag("dolan").bounds().height, 440));
    CHECK(near(rule.onNodeWithTag("satır").bounds().width, 30));
}

