TEST(basic_alert_dialog_is_280_to_560_wide_and_can_skip_the_platform_margins) {
    auto wide = mutableStateOf(false), platform = mutableStateOf(true), fill = mutableStateOf(false);
    ComposeTestRule rule([&] {
        BasicAlertDialog([] {}, Modifier().testTag("diyalog"), [&] {
            Box(Modifier().then(fill.get() ? Modifier().fillMaxWidth() : Modifier().width(wide.get() ? 700.f : 100.f))
                    .height(60).testTag("içerik"));
        }, {.usePlatformDefaultWidth = platform.get()});
    }, {1000, 800});
    // Small content gets the least width (280), centered; large is held to 560.
    Rect content = rule.onNodeWithTag("içerik").bounds();
    CHECK(near(content.width, 280) && near(content.center().x, 500));
    wide.set(true);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("içerik").bounds().width, 560));
    // In a 400 dp window: the platform's 48 dp margins leave 304; without them, all 400.
    rule.host().setViewportSize({400, 800});
    fill.set(true);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("içerik").bounds().width, 304));
    platform.set(false);
    rule.waitForIdle();
    CHECK(near(rule.onNodeWithTag("içerik").bounds().width, 400));
}

TEST(alert_dialog_buttons_wrap_with_the_confirming_one_above) {
    auto longer = mutableStateOf(false);
    ColorScheme cs = lightColorScheme();
    ComposeTestRule rule([&] {
        AlertDialog([] {},
                    {.confirmButton = [&] { TextButton([] {}, Modifier().testTag("onay"), {}, [&] { Text(longer.get() ? "Şimdi güncelle ve yeniden başlat" : "Tamam"); }); },
                     .dismissButton = [&] {
                         TextButton([] {}, Modifier().testTag("ret"), {}, [] { Text("Sonra"); });
                         if (longer.get()) TextButton([] {}, Modifier().testTag("asla"), {}, [] { Text("Bir daha hiç sorma bana lütfen"); });
                     },
                     .icon = [] { Icon(Icons::Filled::Info, "Bilgi"); },
                     .title = [] { Text("Güncelleme"); },
                     .text = [] { Text("Yeni bir sürüm var."); },
                     .shape = RoundedCornerShape(8),
                     .containerColor = cs.primaryContainer,
                     .iconContentColor = cs.tertiary,
                     .titleContentColor = cs.onPrimaryContainer,
                     .textContentColor = cs.primary},
                    Modifier().testTag("diyalog"));
    }, {400, 800});
    // Side by side at the end, 8 dp apart.
    Rect dialog = rule.onNodeWithTag("diyalog").bounds(), ok = rule.onNodeWithTag("onay").bounds(), later = rule.onNodeWithTag("ret").bounds();
    CHECK(near(ok.right(), dialog.right() - 24) && near(ok.x - later.right(), 8) && near(ok.y, later.y));
    // Its own colors.
    testing::RecordingCanvas canvas;
    rule.host().draw(canvas);
    bool container = false;  // with its own shape
    for (size_t i = 0; i < canvas.rects.size(); ++i)
        container |= canvas.rectColors[i] == cs.primaryContainer && sameRect(canvas.rects[i], dialog) && near(canvas.rectRadii[i], 8);
    Color title{}, text{};
    for (size_t i = 0; i < canvas.texts.size(); ++i) {
        if (canvas.texts[i] == "Güncelleme") title = canvas.colors[i];
        if (canvas.texts[i] == "Yeni bir sürüm var.") text = canvas.colors[i];
    }
    CHECK(container && title == cs.onPrimaryContainer && text == cs.primary);
    CHECK(canvas.vectorColors.size() == 1 && canvas.vectorColors[0] == cs.tertiary);
    // Too long to share a row: each later one goes above the rows before, all at the end, 12 dp
    // apart (the confirming one on top).
    longer.set(true);
    rule.waitForIdle();
    dialog = rule.onNodeWithTag("diyalog").bounds(), ok = rule.onNodeWithTag("onay").bounds(), later = rule.onNodeWithTag("ret").bounds();
    Rect never = rule.onNodeWithTag("asla").bounds();
    CHECK(near(never.y - ok.bottom(), 12) && near(later.y - never.bottom(), 12));
    CHECK(near(ok.right(), dialog.right() - 24) && near(later.right(), dialog.right() - 24) && near(never.right(), dialog.right() - 24));
}

